def _merge_supplemental_product_qa_into_field_answer(
    agent_result: dict,
    *,
    supplemental: dict | None,
    supplemental_query: str,
) -> dict:
    """Attach a second semantic product-QA intent after formal-field repair.

    Both the primary result and the optional QA result have already passed
    their own entity/evidence contracts.  This function never chooses a
    product or derives a fact from wording: it only preserves a same-SKU QA
    answer, or makes the independently requested QA part safely missing.
    """
    result_skus = [
        str(sku or "").strip().upper()
        for sku in (agent_result.get("result_skus") or [])
        if str(sku or "").strip()
    ]
    query = str(supplemental_query or "").strip()
    if not query or len(result_skus) != 1:
        return agent_result
    metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    if supplemental and supplemental.get("result_skus") == result_skus:
        extra = str(supplemental.get("answer") or "").strip()
        if extra:
            agent_result["answer"] = str(agent_result.get("answer") or "").strip() + "\n" + extra
            metadata["supplemental_product_qa"] = supplemental.get("answer_metadata") or {}
            agent_result["answer_metadata"] = metadata
            return agent_result
    agent_result["answer"] = (
        str(agent_result.get("answer") or "").strip()
        + f"\n关于“{query}”：当前同 SKU 资料未找到可直接确认的依据，无法确认。"
    )
    metadata["supplemental_product_qa"] = {
        "contract_field_type": "product_qa",
        "evidence_status": "missing",
        "evidence_skus": [],
        "requested_query": query,
        "resolved_sku": result_skus[0],
    }
    agent_result["answer_metadata"] = metadata
    return agent_result


async def _try_same_sku_structured_best_effort_answer(
    db: Session,
    *,
    question: str,
    safe_missing: dict,
    semantic_preplan: dict | None,
) -> dict | None:
    """Answer an open product question from directly relevant structured facts.

    DeepSeek decides relevance and wording. Deterministic code only supplies
    customer-visible fields for the already sealed SKU and validates that the
    resulting answer cites those exact facts.
    """
    if str((semantic_preplan or {}).get("evidence_kind") or "") != "product_qa":
        return None
    sku = str(safe_missing.get("sku") or "").strip().upper()
    if not sku:
        sealed_skus = {
            str(item or "").strip().upper()
            for item in (safe_missing.get("result_skus") or [])
            if str(item or "").strip()
        }
        sealed_skus.update(
            str(row.get("sku") or "").strip().upper()
            for row in (safe_missing.get("results") or [])
            if isinstance(row, dict) and str(row.get("sku") or "").strip()
        )
        if len(sealed_skus) == 1:
            sku = next(iter(sealed_skus))
    if not sku:
        return None
    product, specs, business, content = _phase1_product_bundle_by_ref(db, sku)
    if product is None or str(product.sku or "").strip().upper() != sku:
        return None
    excluded_fields = {
        "sku", "barcode", "product_name_cn", "product_name_en",
        "content_title", "content_description", "bullet_points",
        "search_keywords", "manual", "inventory", "price",
    }
    raw_items: list[dict[str, Any]] = []
    for field in sorted(customer_field_contract.FORMAL_DETAIL_FIELDS):
        if field in excluded_fields or not customer_field_contract.is_supported_detail_field(field):
            continue
        value, source = _structured_product_field_evidence(
            field,
            db=db,
            product=product,
            specs=specs,
            business=business,
            content=content,
        )
        if not value or not source:
            continue
        raw_items.append({
            "evidence_id": customer_evidence_bundle.stable_customer_evidence_id(
                namespace="structured",
                sku=sku,
                value=f"{field}|{value}",
            ),
            "sku": sku,
            "source_type": "structured_field",
            "source": str(source),
            "field": field,
            "value": str(value)[:800],
            "visibility": customer_evidence_bundle.CUSTOMER_VISIBLE,
        })
    bundle = customer_evidence_bundle.build_customer_evidence_bundle(
        sku=sku,
        product_name=product.product_name_cn or product.product_name_en or sku,
        evidence_items=raw_items,
    )
    if not bundle.items:
        return None
    candidates = [
        {
            "evidence_id": item.evidence_id,
            "field": item.field,
            "field_label": customer_field_contract.product_detail_field_label(item.field) or item.field,
            "value": item.value,
        }
        for item in bundle.items
    ]
    runtime = customer_agent_planner_service._semantic_preplan_runtime_settings()
    try:
        raw = await customer_llm_service.chat_completion(
            db,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Return only JSON: {answer:string,evidence_ids:string[],evidence_quotes:string[]}. "
                        "Answer the complete customer question in concise, direct, friendly Chinese only when one or more supplied same-product "
                        "structured facts directly support it. You may combine multiple directly relevant "
                        "facts for a bounded suitability judgement, but never infer safety, durability, "
                        "compatibility, performance, ease of use, or a guarantee from merely adjacent facts. "
                        "Use NO_EVIDENCE when the facts are only related rather than sufficient. "
                        "Start with the customer's actual conclusion, without a greeting, preface, or phrases such as '请参考以下说明'. "
                        "For a safety or operating question, state both the permitted next action and the prohibited action when the supplied facts support them. "
                        "Use only supplied facts, keep uncertainty explicit, and copy one to three literal "
                        "evidence quotes of at most 60 characters."
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps(
                        {"question": question, "same_sku": sku, "candidates": candidates},
                        ensure_ascii=False,
                    ),
                },
            ],
            temperature=0,
            max_tokens=min(int(runtime["max_tokens"]), 360),
            purpose="same_sku_structured_best_effort_answer",
            api_model_override=runtime["model"],
            response_format=runtime["response_format"],
            thinking=runtime["thinking"],
        )
    except Exception:
        return None
    payload = customer_agent_planner_service._extract_json_object(str(raw or "")) or {}
    answer = str(payload.get("answer") or "").strip()
    evidence_ids = payload.get("evidence_ids")
    if not answer or answer == "NO_EVIDENCE" or not isinstance(evidence_ids, list) or not evidence_ids:
        return None
    selected_id_set = {str(item or "").strip() for item in evidence_ids if str(item or "").strip()}
    selected_items = [item for item in bundle.items if item.evidence_id in selected_id_set]
    if len(selected_items) != len(selected_id_set):
        return None
    evidence_content = "\n".join(item.value for item in selected_items)
    if (
        not _same_sku_rag_answer_has_selected_quotes(payload, evidence_content)
        or not await _same_sku_rag_answer_is_grounded_after_quote_validation(
            db, question, answer, payload, evidence_content
        )
    ):
        return None
    result = dict(safe_missing)
    result.update({
        "answer": answer,
        "confidence": "high",
        "uncertainty": "resolved",
        "evidence": [
            {
                "evidence_id": item.evidence_id,
                "sku": sku,
                "field_label": customer_field_contract.product_detail_field_label(item.field) or item.field,
                "value": item.value,
                "source_type": "structured_field",
                "source_layer": "structured",
                "matched_by": "semantic_same_sku_structured_evidence",
            }
            for item in selected_items
        ],
        "sources": [{"type": "product_field", "label": "同 SKU 商品资料", "sku": sku}],
        "answer_metadata": {
            "contract_field_type": "product_qa",
            "evidence_status": "matched",
            "evidence_sku": sku,
            "evidence_skus": [sku],
            "evidence_bundle_skus": [sku],
            "evidence_ids": [item.evidence_id for item in selected_items],
            "evidence_source": "same_sku_structured_best_effort",
        },
        # The bounded writer has already produced customer-facing prose and the
        # answer has passed an independent grounding check. Avoid a second LLM
        # pass that only adds a generic preface and extra latency.
        "skip_polish": True,
    })
    result.setdefault("debug", {})["agent_mode"] = "sealed_same_sku_structured_best_effort"
    return result


def _sealed_context_anchor_sku_conflict(question: str, anchor_sku: str, agent_result: dict) -> bool:
    """Reject a fallback that re-resolves a deictic turn outside its sealed SKU."""
    text = str(question or "").strip()
    if (
        _has_explicit_sku_text(text)
        or not re.search(r"(?:它|这个|这款|该商品|该产品|本产品)", text)
    ):
        return False
    expected = str(anchor_sku or "").strip().upper()
    returned = {
        str(sku or "").strip().upper()
        for sku in (agent_result.get("result_skus") or [])
        if str(sku or "").strip()
    }
    return bool(expected and returned and returned != {expected})


def _apply_sealed_context_anchor_cross_sku_guard(
    db: Session,
    *,
    user_id: str,
    question: str,
    conversation_id: str | None,
    agent_result: dict,
    semantic_preplan: dict | None = None,
) -> dict:
    """Keep a deictic single-product turn inside its persisted SKU boundary."""
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    semantic_plans = [
        semantic_preplan,
        debug.get("semantic_preplan"),
        (debug.get("plan") or {}).get("semantic_preplan")
        if isinstance(debug.get("plan"), dict)
        else None,
    ]
    # A semantic alternative recommendation is deliberately allowed to leave
    # the anchored SKU. The planner has already classified the turn as a new
    # catalogue search and the recommendation executor has sealed the selected
    # candidate separately; the single-product pronoun guard belongs only to
    # product-bound fact follow-ups.
    if any(
        isinstance(plan, dict)
        and str(plan.get("route_family") or "").strip() == "recommendation"
        and str(plan.get("recommendation_followup_action") or "").strip() == "alternative"
        for plan in semantic_plans
    ):
        return agent_result
    persisted_anchor_sku = _latest_persisted_agent_context_sku(db, conversation_id)
    saved_anchor_sku = persisted_anchor_sku
    if not saved_anchor_sku:
        saved_anchor_context = _latest_recommendation_context_for_sources(db, conversation_id)
        saved_anchor_sku = str((saved_anchor_context or {}).get("active_single_product_anchor") or "").strip().upper()
    anchor_skus = [saved_anchor_sku] if saved_anchor_sku else _latest_active_product_skus(db, conversation_id, user_id)
    latest_candidate_context = _latest_candidate_context_for_sources(db, conversation_id)
    has_ordered_multi_product_context = len(_ordered_context_skus(latest_candidate_context)) >= 2
    if (
        (has_ordered_multi_product_context and not persisted_anchor_sku)
        or len(anchor_skus) != 1
        or not _sealed_context_anchor_sku_conflict(question, anchor_skus[0], agent_result)
    ):
        return agent_result
    anchored_sku = anchor_skus[0]
    product = db.query(Product).filter(Product.sku == anchored_sku).first()
    if product is None:
        return agent_result
    decision = customer_entity_resolution_contract.SingleProductResolutionDecision(
        allowed=True,
        resolved_sku=anchored_sku,
        resolved_product_id=str(product.id),
        reason="sealed_context_anchor_rejected_cross_sku_result",
        match_level="sealed_context_anchor",
    )
    return _build_resolved_product_unknown_field_result(
        db,
        product,
        label="配件",
        source="sealed_context_anchor_cross_sku_guard",
        resolution_decision=decision,
    )


def _apply_request_sku_anchor_guard(
    db: Session,
    *,
    question: str,
    agent_result: dict,
    request_anchor_sku: str | None,
    phase1_plan: dict | None,
) -> dict:
    """Keep a product-page SKU from being lost by an earlier route.

    The API SKU identifies the product page, but does not classify the
    customer's field or turn a recommendation request into a product-detail
    request. This final boundary only rejects a conflicting or identity-losing
    detail response and replaces it with a same-SKU evidence-safe result.
    """
    anchor_sku = _resolve_exact_sku_variant(db, request_anchor_sku)
    if not anchor_sku or not isinstance(agent_result, dict):
        return agent_result
    if (
        (
            _looks_like_recommendation_request(question)
            and not _looks_like_page_current_item_availability_question(question)
        )
        or _looks_like_page_bundle_inclusion_question(question)
        or _looks_like_bundle_heat_source_question(question)
        or customer_agent_runtime_service._is_underspecified_recommendation_question(question)
    ):
        return agent_result

    product = db.query(Product).filter(Product.sku == anchor_sku).first()
    if product is None:
        return agent_result

    # A page SKU is only an identity anchor.  It must not overwrite a
    # category-level catalogue decision that was already scoped and composed
    # by the semantic catalogue route.  This matters for questions such as
    # "where can I buy a safe solid-alcohol stove?" while the customer happens
    # to be browsing a gas-stove page: the catalogue route may return verified
    # alcohol-stove candidates (or a bounded no-match conclusion), and the
    # final page guard must preserve that meaning instead of reclassifying it
    # as usage care for the page SKU.
    answer_type = str(agent_result.get("answer_type") or "").strip()
    answer_metadata = agent_result.get("answer_metadata")
    catalogue_source = ""
    if isinstance(answer_metadata, dict):
        catalogue_source = str(answer_metadata.get("source") or "").strip().lower()
    if (
        answer_type in {"recommendation", "comparison", "product_query"}
        and ("catalogue" in catalogue_source or "category" in catalogue_source)
        and not _looks_like_page_current_item_availability_question(question)
    ):
        return agent_result

    if _looks_like_page_current_item_availability_question(question):
        component = next(
            (
                term
                for term in ("炉头", "炉芯", "配件", "水壶", "锅", "炉具")
                if term in question
            ),
            "该配件",
        )
        page_name = str(product.product_name_cn or product.product_name_en or anchor_sku).strip()
        page_result = _build_bounded_clarification_result(
            answer=(
                f"{page_name}（{anchor_sku}）：当前同 SKU 资料未标注是否包含或单独提供“{component}”，"
                "不能把其他炉具或目录中的配件当作这款商品的随附部件。请按该 SKU 包装清单或配件说明核对。"
            ),
            source="page_current_item_availability_scope_guard",
        )
        page_result["sku"] = anchor_sku
        page_result["result_skus"] = []
        page_result["candidate_skus"] = []
        page_result["results"] = []
        page_debug = page_result.get("debug") if isinstance(page_result.get("debug"), dict) else {}
        page_debug["agent_mode"] = "page_current_item_availability_scope_guard"
        page_debug["request_sku_anchor"] = anchor_sku
        page_result["debug"] = page_debug
        return page_result

    usage_subtype = customer_agent_intent_service._detect_usage_care_subtype(question)
    if (
        _is_product_usage_care_question(question)
        and not _looks_like_recommendation_request(question)
        and not _looks_like_compatibility_usage_question(question)
        and usage_subtype in {"safety", "duration", "power_tradeoff", "installation", "full_unit_wash", "composition"}
    ):
        # A legacy/page-field route may have already produced a product-detail
        # card by the time this final identity boundary runs.  Recompose only
        # the bounded usage/safety subtype here; otherwise the page SKU would
        # turn an operational question such as “气罐能用多久” into a heat-source
        # or capacity field dump.
        if usage_subtype == "duration":
            bounded_answer = customer_agent_intent_service._compose_duration_usage_care_answer(question, [], [])
        elif usage_subtype == "power_tradeoff":
            bounded_answer = customer_agent_intent_service._compose_power_tradeoff_usage_care_answer(question, [], [])
        elif usage_subtype == "installation":
            bounded_answer = customer_agent_intent_service._compose_installation_usage_care_answer(question, [], [])
        elif usage_subtype == "full_unit_wash":
            bounded_answer = customer_agent_intent_service._compose_full_unit_wash_usage_care_answer(question)
        elif usage_subtype == "composition":
            bounded_answer = customer_agent_intent_service._compose_usage_care_composition_answer(question, [], [])
        else:
            bounded_answer = customer_agent_intent_service._compose_safety_usage_care_answer(question)
        if usage_subtype in {"duration", "power_tradeoff"}:
            bounded_answer = re.sub(
                r"请提供炉具型号或 SKU，我再按同款资料核对。?",
                "当前页面商品身份已明确；如能补充气罐规格、火力档位或实际负载，我再继续核对。",
                bounded_answer,
            )
        bounded_answer = re.sub(
            r"请提供炉具 SKU 与气罐型号，再核对接口和说明书。?",
            "当前页面商品已明确；请补充气罐型号，再核对接口和说明书。",
            bounded_answer,
        )
        if customer_agent_intent_service._looks_like_general_fuel_definition_question(question):
            bounded_answer = re.sub(
                r"如果要核对某款炉具能否使用液体酒精，请提供具体商品名或 SKU，我再按同款热源标注确认。?",
                "当前页面商品身份已明确；请按该商品说明书的热源标注核对，不能把医用酒精默认当作炉具燃料。",
                bounded_answer,
            )
        if anchor_sku:
            bounded_answer = re.sub(
                r"请提供具体炉具 SKU，并",
                "当前页面商品已明确；请",
                bounded_answer,
            )
            bounded_answer = re.sub(
                r"请提供具体炉具型号或 SKU，并",
                "当前页面商品已明确；请",
                bounded_answer,
            )
        bound_result = dict(agent_result)
        bound_result["intent"] = "product_usage_care"
        bound_result["answer_type"] = "product_usage_care"
        bound_result["answer"] = f"{product.product_name_cn or product.product_name_en or anchor_sku}（{anchor_sku}）\n{bounded_answer}"
        bound_result["sku"] = anchor_sku
        bound_result["result_skus"] = [anchor_sku]
        bound_result["candidate_skus"] = [anchor_sku]
        # Scope-guard clarifications retain the page identity in the answer,
        # but they are not catalogue results and must not render a product
        # card for the unrelated accessory being asked about.
        if catalogue_source.startswith("page_") and catalogue_source.endswith("_scope_guard"):
            bound_result["result_skus"] = []
            bound_result["candidate_skus"] = []
            bound_result["results"] = []
        bound_debug = bound_result.get("debug") if isinstance(bound_result.get("debug"), dict) else {}
        bound_debug["agent_mode"] = "request_sku_anchor_usage_care_recompose"
        bound_debug["request_sku_anchor"] = anchor_sku
        bound_debug["usage_care_subtype"] = usage_subtype
        bound_result["debug"] = bound_debug
        return bound_result

    if "气罐桌边夹" in question and str(agent_result.get("answer_type") or "") in {"clarification", "product_usage_care", "product_detail"}:
        bound_result = dict(agent_result)
        bound_result["sku"] = anchor_sku
        bound_result["result_skus"] = [anchor_sku]
        bound_result["candidate_skus"] = [anchor_sku]
        # A page scope guard is a bounded clarification, not a catalogue
        # result.  Keep the page SKU as identity in ``sku``/the answer, but
        # do not expose it as a recommendation/detail card for an unrelated
        # accessory question such as "有没有卖气罐".  This boundary is based
        # on route provenance, not on any product/SKU-specific rule.
        if catalogue_source.startswith("page_") and catalogue_source.endswith("_scope_guard"):
            bound_result["result_skus"] = []
            bound_result["candidate_skus"] = []
            bound_result["results"] = []
        answer_text = str(bound_result.get("answer") or "").strip()
        product_name = str(product.product_name_cn or product.product_name_en or anchor_sku).strip()
        if product_name not in answer_text and anchor_sku not in answer_text:
            bound_result["answer"] = f"{product_name}（{anchor_sku}）\n{answer_text}"
        bound_debug = bound_result.get("debug") if isinstance(bound_result.get("debug"), dict) else {}
        bound_debug["agent_mode"] = "request_sku_anchor_table_clip_scope"
        bound_debug["request_sku_anchor"] = anchor_sku
        bound_result["debug"] = bound_debug
        return bound_result

    # A page-bound compatibility question may deliberately have no retrieval
    # SKU: the page SKU is the identity, while the compatibility conclusion is
    # conservative because the field is unverified.  Do not replace that
    # customer-facing conclusion with a generic missing-field card; bind the
    # known page identity to the usage-care response instead.
    if (
        str(agent_result.get("answer_type") or "") == "product_usage_care"
        and (
            _looks_like_compatibility_usage_question(question)
            or customer_agent_intent_service._detect_usage_care_subtype(question)
            in {"duration", "power_tradeoff"}
            or _is_product_usage_care_question(question)
            or customer_agent_intent_service._looks_like_usage_care_question(question)
        )
    ):
        bound_result = dict(agent_result)
        bound_result["sku"] = anchor_sku
        bound_result["result_skus"] = [anchor_sku]
        bound_result["candidate_skus"] = [anchor_sku]
        # A page scope guard is a bounded clarification, not a catalogue
        # result. Keep the page SKU as identity in ``sku``/the answer, but do
        # not expose it as a recommendation/detail card for an unrelated
        # accessory question. This is route-provenance based, not SKU based.
        if catalogue_source.startswith("page_") and catalogue_source.endswith("_scope_guard"):
            bound_result["result_skus"] = []
            bound_result["candidate_skus"] = []
            bound_result["results"] = []
        answer_text = str(bound_result.get("answer") or "").strip()
        product_name = str(product.product_name_cn or product.product_name_en or anchor_sku).strip()
        if customer_agent_intent_service._detect_usage_care_subtype(question) in {"duration", "power_tradeoff"}:
            answer_text = re.sub(
                r"请提供炉具型号或 SKU，我再按同款资料核对。?",
                "当前页面商品身份已明确；如能补充气罐规格、火力档位或实际负载，我再继续核对。",
                answer_text,
            )
        if answer_text and product_name not in answer_text and anchor_sku not in answer_text:
            bound_result["answer"] = f"{product_name}（{anchor_sku}）\n{answer_text}"
        else:
            bound_result["answer"] = answer_text
        bound_debug = bound_result.get("debug") if isinstance(bound_result.get("debug"), dict) else {}
        bound_debug["agent_mode"] = "request_sku_anchor_usage_care_bind"
        bound_debug["request_sku_anchor"] = anchor_sku
        bound_result["debug"] = bound_debug
        return bound_result

    # A page SKU is context, not permission to reinterpret an explicitly
    # named different product subject.  For example, asking for a large pot,
    # windscreen, or teapot while browsing a stove page must not be converted
    # into a missing-field answer for the stove.
    explicit_target_category = _structured_target_category_from_question(question)
    if explicit_target_category and _product_category_domain(product.category) != _product_category_domain(explicit_target_category):
        return agent_result

    returned_skus = {
        str(value or "").strip().upper()
        for value in [
            *(agent_result.get("result_skus") or []),
            agent_result.get("sku"),
        ]
        if str(value or "").strip()
    }
    field_contract = resolve_requested_field_contract(question, phase1_plan)
    field_type = str(field_contract.get("field_type") or "").strip()
    asks_for_identity_again = bool(re.search(
        r"(?:\u63d0\u4f9b|\u8f93\u5165).{0,16}(?:SKU|\u5546\u54c1\u540d)|\u8bf7\u5148\u8bf4\u660e\u4f60\u6307\u7684\u54ea\u6b3e",
        str(agent_result.get("answer") or ""),
        flags=re.IGNORECASE,
    ))
    has_cross_sku = bool(returned_skus and anchor_sku.upper() not in returned_skus)
    # A valid page SKU already resolves identity. Even a capability question
    # outside the formal field ontology must never ask the customer to send
    # that identity again or return a generic answer that has no product
    # identity/evidence at all.
    answer_text = str(agent_result.get("answer") or "")
    product_name = str(product.product_name_cn or product.product_name_en or "").strip()
    names_current_product = bool(
        anchor_sku.upper() in answer_text.upper()
        or (product_name and product_name in answer_text)
    )
    has_lost_identity = bool(
        not returned_skus
        and (asks_for_identity_again or not names_current_product)
    )
    if not (has_cross_sku or has_lost_identity):
        return agent_result

    label = customer_field_contract.product_detail_field_label(field_type) or "相关"
    decision = customer_entity_resolution_contract.SingleProductResolutionDecision(
        allowed=True,
        resolved_sku=anchor_sku,
        resolved_product_id=str(product.id),
        reason="request_sku_anchor_guard",
        match_level="request_sku_anchor",
    )
    result = _build_resolved_product_unknown_field_result(
        db,
        product,
        label=label,
        source="request_sku_anchor_guard",
        resolution_decision=decision,
    )
    debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
    debug["agent_mode"] = "request_sku_anchor_guard"
    debug["request_sku_anchor"] = anchor_sku
    debug["rejected_result_skus"] = sorted(returned_skus)
    result["debug"] = debug
    return result


def _is_terminal_gifting_evidence_boundary(result: dict | None) -> bool:
    debug = result.get("debug") if isinstance(result, dict) and isinstance(result.get("debug"), dict) else {}
    return bool(
        str(debug.get("agent_mode") or "") == "sealed_product_qa_safe_missing"
        and debug.get("gifting_evidence_boundary") is True
    )


def _enforce_terminal_gifting_evidence_boundary(
    result: dict,
    *,
    bounded_answer: str,
) -> dict:
    """Keep an unsupported marketing judgement terminal through finalization."""
    result["answer"] = str(bounded_answer or result.get("answer") or "").strip()
    result["confidence"] = "medium"
    result["uncertainty"] = "missing_data"
    result["evidence"] = []
    result["sources"] = []
    metadata = result.get("answer_metadata") if isinstance(result.get("answer_metadata"), dict) else {}
    for key in (
        "evidence_source",
        "evidence_bundle_skus",
        "evidence_ids",
        "evidence_field",
        "field_evidence_match",
        "semantic_answer_coverage_complete",
    ):
        metadata.pop(key, None)
    metadata.update({
        "contract_field_type": "product_qa",
        "requested_field": "产品问答",
        "evidence_status": "missing",
        "field_evidence_missing": True,
        "evidence_skus": [],
        "answer_policy": "insufficient_evidence",
    })
    result["answer_metadata"] = metadata
    debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
    debug["agent_mode"] = "sealed_product_qa_safe_missing"
    debug["gifting_evidence_boundary"] = True
    result["debug"] = debug
    result["skip_polish"] = True
    return result


def _mark_semantic_executor_result(
    agent_result: dict | None,
    *,
    branch: str | None,
    semantic_preplan: dict | None,
) -> dict | None:
    """Persist semantic ownership as provenance, not as another intent rule.

    The semantic executor may return a useful answer or a bounded missing-data
    answer. In both cases historical post-processors must not reinterpret the
    turn. This marker records who already owned the turn without inspecting
    customer wording or adding another route classifier.
    """
    if not isinstance(agent_result, dict):
        return agent_result
    metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    result_skus = [
        str(item or "").strip().upper()
        for item in (agent_result.get("result_skus") or [])
        if str(item or "").strip()
    ]
    evidence_status = str(metadata.get("evidence_status") or "").strip().lower()
    result_state = (
        "matched"
        if result_skus
        or evidence_status in {"matched", "supported", "resolved", "structured"}
        else "missing"
    )
    branch_name = str(branch or "semantic_first_turn")
    metadata["semantic_owned"] = True
    metadata["semantic_executor_branch"] = branch_name
    metadata["semantic_result_state"] = result_state
    agent_result["answer_metadata"] = metadata
    debug["semantic_owned"] = True
    debug["semantic_pipeline_entry"] = {
        "branch": branch_name,
        "result_state": result_state,
        "answer_type": str(agent_result.get("answer_type") or ""),
        "intent": str(agent_result.get("intent") or ""),
        "result_skus": list(result_skus),
        "source": str(metadata.get("source") or ""),
        "answer_preview": str(agent_result.get("answer") or "")[:240],
        "route_family": str((semantic_preplan or {}).get("route_family") or ""),
    }
    agent_result["debug"] = debug
    return agent_result


def _is_semantic_owned_result(result: dict | None) -> bool:
    if not isinstance(result, dict):
        return False
    metadata = result.get("answer_metadata") if isinstance(result.get("answer_metadata"), dict) else {}
    debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
    return bool(metadata.get("semantic_owned") is True or debug.get("semantic_owned") is True)


async def _save_agent_result_and_return(
    db: Session,
    *,
    user_id: str,
    question: str,
    conversation_id: str | None,
    agent_result: dict,
    request_start: float,
    branch: str,
    semantic_preplan: dict | None = None,
) -> dict:
    stage_start = perf_counter()
    semantic_owned_at_entry = _is_semantic_owned_result(agent_result)
    semantic_entry_metadata = (
        dict(agent_result.get("answer_metadata"))
        if isinstance(agent_result.get("answer_metadata"), dict)
        else {}
    )
    semantic_entry_debug = (
        dict(agent_result.get("debug"))
        if isinstance(agent_result.get("debug"), dict)
        else {}
    )
    semantic_entry_snapshot = {
        "answer": str(agent_result.get("answer") or "")[:240],
        "result_skus": [
            str(item or "").strip().upper()
            for item in (agent_result.get("result_skus") or [])
            if str(item or "").strip()
        ],
        "answer_type": str(agent_result.get("answer_type") or ""),
        "agent_mode": str(semantic_entry_debug.get("agent_mode") or ""),
        "source": str(semantic_entry_metadata.get("source") or ""),
    } if semantic_owned_at_entry else None
    agent_result = _apply_sealed_context_anchor_cross_sku_guard(
        db,
        user_id=user_id,
        question=question,
        conversation_id=conversation_id,
        agent_result=agent_result,
        semantic_preplan=semantic_preplan,
    )
    original_debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    persisted_plan = original_debug.get("plan") if isinstance(original_debug.get("plan"), dict) else {}
    request_sku_anchor = str(
        persisted_plan.get("request_sku_anchor")
        or (semantic_preplan or {}).get("request_sku_anchor")
        or ""
    ).strip()
    agent_result = _apply_request_sku_anchor_guard(
        db,
        question=question,
        agent_result=agent_result,
        request_anchor_sku=request_sku_anchor,
        phase1_plan=persisted_plan,
    )
    original_debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    persisted_plan = original_debug.get("plan") if isinstance(original_debug.get("plan"), dict) else persisted_plan
    effective_semantic_preplan = semantic_preplan or persisted_plan.get("semantic_preplan") or {}
    if semantic_owned_at_entry:
        # A same-turn semantic result remains the source of truth through the
        # save boundary. Re-attach provenance if an identity guard returned a
        # shallow replacement object; this is bookkeeping, not a new route.
        metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
        metadata["semantic_owned"] = True
        agent_result["answer_metadata"] = metadata
        debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
        debug["semantic_owned"] = True
        agent_result["debug"] = debug
    terminal_gifting_boundary = _is_terminal_gifting_evidence_boundary(agent_result)
    terminal_gifting_answer = str(agent_result.get("answer") or "").strip() if terminal_gifting_boundary else ""
    if (
        str(original_debug.get("agent_mode") or "") == "sealed_product_qa_safe_missing"
        and not terminal_gifting_boundary
        and not semantic_owned_at_entry
    ):
        recovered = await _try_same_sku_structured_best_effort_answer(
            db,
            question=question,
            safe_missing=agent_result,
            semantic_preplan=effective_semantic_preplan,
        )
        if recovered is not None:
            agent_result = recovered
            original_debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
        else:
            rows = [row for row in (agent_result.get("results") or []) if isinstance(row, dict)]
            if rows:
                row = rows[0]
                sku = str(row.get("sku") or "").strip().upper()
                name = str(row.get("product_name_cn") or row.get("product_name_en") or sku).strip()
                agent_result["answer"] = _safe_missing_product_qa_answer(name, sku, question)
            agent_result["skip_polish"] = True
    supplemental_query = str((effective_semantic_preplan or {}).get("supplemental_qa_evidence_query") or "").strip()
    if not ((agent_result.get("debug") or {}).get("timing")) or not ((agent_result.get("answer_metadata") or {}).get("timing")):
        existing_debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
        existing_plan = existing_debug.get("plan") if isinstance(existing_debug.get("plan"), dict) else {}
        agent_result = _attach_phase1_plan_and_timing(
            agent_result,
            existing_plan,
            _phase1_timing(request_start=request_start),
        )
    agent_result = _ensure_debug_plan_raw_question(agent_result, question)
    agent_result = _finalize_answer(agent_result)
    agent_result = _attach_semantic_preplan_debug(
        agent_result,
        semantic_preplan,
        final_route=str(agent_result.get("answer_type") or agent_result.get("intent") or ""),
    )
    agent_result = _remove_redundant_identity_request(agent_result)
    # Explicit single-product field answers must not be completed with unrelated QA or selling points.
    agent_result = _enforce_field_evidence_policy(db, question, agent_result)
    agent_result = _complete_resolved_realtime_commercial_boundaries(question, agent_result)
    same_sku_rag_owned = bool(
        semantic_owned_at_entry
        and str((agent_result.get("answer_metadata") or {}).get("contract_field_type") or "").strip() == "product_qa"
        and str((agent_result.get("answer_metadata") or {}).get("evidence_source") or "").strip() == "same_sku_knowledge"
    )
    if not same_sku_rag_owned:
        agent_result = await _semantic_render_structured_usage_answer(
            db,
            question=question,
            agent_result=agent_result,
            semantic_preplan=effective_semantic_preplan,
        )
    if terminal_gifting_boundary:
        agent_result = _enforce_terminal_gifting_evidence_boundary(
            agent_result,
            bounded_answer=terminal_gifting_answer,
        )
    final_debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    final_entity_contract = (
        final_debug.get("entity_resolution_contract")
        if isinstance(final_debug.get("entity_resolution_contract"), dict)
        else {}
    )
    if (
        str(final_debug.get("agent_mode") or "") == "recommendation_context_product_field"
        and final_entity_contract.get("status") == "resolved"
        and str(final_entity_contract.get("resolved_sku") or "").strip()
    ):
        final_debug.setdefault("binding_provenance", "resolved_entity_contract")
        agent_result["debug"] = final_debug
    field_metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    if (
        str(field_metadata.get("contract_field_type") or "").strip() == "accessories"
        and field_metadata.get("field_evidence_missing") is True
        and len(agent_result.get("result_skus") or []) == 1
    ):
        accessory_preplan = dict(effective_semantic_preplan or {})
        accessory_preplan.update({
            "route_family": "product_bound_qa",
            "route_hint": "product_detail",
            "question_type": "field",
            "subject_text": str(agent_result.get("result_skus")[0]),
            "canonical_fields": [],
            "field_type": "",
            "field_hint": None,
            "evidence_required": True,
            "evidence_kind": "product_qa",
            "qa_evidence_query": question,
            "fallback_reason": "",
        })
        accessory_qa_result = await _try_product_qa_shortcut_with_semantic_selection(
            db,
            question,
            phase1_plan={"semantic_preplan": accessory_preplan},
        )
        if accessory_qa_result and accessory_qa_result.get("result_skus") == agent_result.get("result_skus"):
            accessory_qa_result.setdefault("answer_metadata", {}).update({
                "contract_field_type": "accessories",
                "evidence_field": "accessories",
                "field_evidence_match": True,
                "field_evidence_missing": False,
                "evidence_status": "matched",
            })
            agent_result = accessory_qa_result
    compound_queries = [] if terminal_gifting_boundary or same_sku_rag_owned else [
        str(item or "").strip()
        for item in ((effective_semantic_preplan or {}).get("qa_evidence_queries") or [])
        if str(item or "").strip()
    ]
    semantic_subject = customer_agent_service.normalize_search_text(
        str((effective_semantic_preplan or {}).get("subject_text") or "")
    ).lower()
    if (
        semantic_subject
        and len(compound_queries) > 1
        and all(semantic_subject in customer_agent_service.normalize_search_text(query).lower() for query in compound_queries)
    ):
        # Repeated subject-bearing rewrites are an overview decomposition, not
        # independently answerable product facts.
        compound_queries = []
    compound_metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    if (
        compound_queries
        and len(agent_result.get("result_skus") or []) == 1
        and str(compound_metadata.get("contract_field_type") or "").strip() == "product_qa"
    ):
        # The final save boundary is the last place before a safe-missing
        # response becomes user-visible. Re-run only the already semantic,
        # independently scoped queries under the same resolved SKU; never
        # reinterpret the question here.
        child_answers: list[dict] = []
        missing_child_queries: list[str] = []
        answered_child_requests: list[tuple[str, str]] = []
        child_evidence_ids: set[str] = set()
        for query in compound_queries:
            child_preplan = dict(effective_semantic_preplan)
            child_preplan.update({
                "qa_evidence_query": query,
                "qa_evidence_queries": [],
                "compound": False,
                "strict_compound_child_qa": True,
            })
            child_question = " ".join(item for item in (str(child_preplan.get("subject_text") or "").strip(), query) if item) or question
            child_result = await _try_product_qa_shortcut_with_semantic_selection(
                db, child_question, phase1_plan={"semantic_preplan": child_preplan},
            )
            if _is_sealed_product_qa_safe_missing(child_result):
                child_result = None
            if not child_result:
                child_result = await _try_sealed_same_sku_knowledge_answer(
                    db, child_question, {"semantic_preplan": child_preplan},
                )
            if child_result:
                child_meta = child_result.get("answer_metadata") if isinstance(child_result.get("answer_metadata"), dict) else {}
                child_evidence_id = str(child_meta.get("evidence_source") or "").strip()
                # A strict child selector must not reuse the sibling QA row.
                # Treat a duplicate evidence id as uncovered instead of
                # repeating an answer for a different sub-question.
                if child_evidence_id and child_evidence_id in child_evidence_ids:
                    missing_child_queries.append(query)
                else:
                    if child_evidence_id:
                        child_evidence_ids.add(child_evidence_id)
                    child_answers.append(child_result)
                    answered_child_requests.append((
                        query,
                        child_evidence_id
                        or str(child_meta.get("source") or "same_sku_child_evidence"),
                    ))
            else:
                missing_child_queries.append(query)
        if child_answers:
            if _is_sealed_product_qa_safe_missing(agent_result):
                agent_result = child_answers.pop(0)
            base_answer = str(agent_result.get("answer") or "").strip()
            extra_answers = []
            seen_answer_texts = {base_answer} if base_answer else set()
            for index, item in enumerate(child_answers):
                extra = str(item.get("answer") or "").strip()
                if extra and extra in seen_answer_texts:
                    if index + 1 < len(compound_queries):
                        missing_child_queries.append(compound_queries[index + 1])
                    continue
                if extra and extra not in base_answer and base_answer not in extra:
                    extra_answers.append(extra)
                    seen_answer_texts.add(extra)
            extra_answers.extend(
                f"关于“{query}”：当前同 SKU 资料未直接确认，无法确认。"
                for query in missing_child_queries
                if query
            )
            if extra_answers:
                agent_result["answer"] = "\n".join([base_answer, *extra_answers])
            compound_metadata = agent_result.setdefault("answer_metadata", {})
            compound_metadata["compound_product_qa_queries"] = compound_queries
            compound_metadata["compound_missing_child_queries"] = missing_child_queries
            compound_metadata["answer_coverage_contract"] = (
                customer_answer_coverage_contract.build_answer_coverage_contract(
                    compound_queries,
                    answered_requests=answered_child_requests,
                    unsupported_requests=missing_child_queries,
                ).to_dict()
            )
        elif len(compound_queries) > 1:
            # The parent answer may still be valid for the first child, but a
            # failed narrow retrieval must not make later semantic children
            # disappear from the customer-visible response.
            compound_metadata = agent_result.setdefault("answer_metadata", {})
            compound_metadata["compound_product_qa_queries"] = compound_queries
            compound_metadata["compound_missing_child_queries"] = compound_queries[1:]
            parent_evidence_id = str(
                compound_metadata.get("evidence_source")
                or compound_metadata.get("source")
                or "same_sku_parent_evidence"
            )
            compound_metadata["answer_coverage_contract"] = (
                customer_answer_coverage_contract.build_answer_coverage_contract(
                    compound_queries,
                    answered_requests=[(compound_queries[0], parent_evidence_id)],
                    unsupported_requests=compound_queries[1:],
                ).to_dict()
            )
    if (
        not terminal_gifting_boundary
        and not same_sku_rag_owned
        and supplemental_query
        and len(agent_result.get("result_skus") or []) == 1
        # The resolved compound executor may already have retrieved and merged
        # this same semantic supplement before entering the common save path.
        # Re-running it here duplicates a grounded fact and spends another LLM
        # round-trip, so the sealed metadata is the idempotency boundary.
        and not bool(
            (agent_result.get("answer_metadata") or {}).get("supplemental_product_qa")
            if isinstance(agent_result.get("answer_metadata"), dict)
            else False
        )
    ):
        supplemental, supplemental_query = await _resolve_sealed_supplemental_product_evidence(
            db,
            question=question,
            semantic_preplan=effective_semantic_preplan,
            base_plan={"semantic_preplan": effective_semantic_preplan},
        )
        agent_result = _merge_supplemental_product_qa_into_field_answer(
            agent_result,
            supplemental=supplemental,
            supplemental_query=supplemental_query,
        )
    result_skus = [
        str(item or "").strip().upper()
        for item in (agent_result.get("result_skus") or [])
        if str(item or "").strip()
    ]
    explicit_question_skus = [
        str(item or "").strip().upper()
        for item in customer_agent_service._extract_skus(question)
        if str(item or "").strip()
    ]
    if (
        not terminal_gifting_boundary
        and len(result_skus) == 1
        and explicit_question_skus == result_skus
        and str(agent_result.get("answer_type") or "") == "product_detail"
        and not supplemental_query
        # A sealed multi-field executor has already rendered every requested
        # field from same-SKU evidence.  Re-running the legacy phrase formatter
        # here can only discard fields it does not understand (for example
        # weight or fuel), so the formal contract remains authoritative.
        and not semantic_owned_at_entry
        and str((agent_result.get("answer_metadata") or {}).get("answer_policy") or "")
        != "sealed_same_sku_multi_field_evidence"
    ):
        compound_detail = product_service.get_product_detail(db, result_skus[0])
        if isinstance(compound_detail, dict):
            compound_answer = customer_agent_intent_service._compound_single_product_detail_answer(
                db,
                sku=result_skus[0],
                detail=compound_detail,
                question=question,
                supporting=None,
            )
            if compound_answer:
                agent_result["answer"] = compound_answer
                agent_result["skip_polish"] = True
                compound_metadata = agent_result.setdefault("answer_metadata", {})
                compound_metadata["answer_policy"] = "sealed_same_sku_compound_evidence"
                compound_metadata["evidence_skus"] = result_skus
    agent_result = _ensure_debug_plan_raw_question(agent_result, question)
    answer_metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    skip_polish = bool(agent_result.get("skip_polish"))
    if _should_skip_polish_for_agent_result(agent_result):
        skip_polish = True
    if answer_metadata.get("evidence_insufficient") is True or answer_metadata.get("answer_policy") == "insufficient_evidence":
        skip_polish = True
    if not skip_polish:
        agent_result["answer"] = await _polish_customer_answer(db, question, agent_result)
    # Preserve independently scoped child questions after customer polishing.
    # The polish model may shorten a safe-missing clause, but it must not erase
    # a requested sub-question that lacked same-SKU evidence.
    coverage_contract = customer_answer_coverage_contract.AnswerCoverageContract.from_dict(
        answer_metadata.get("answer_coverage_contract")
    )
    if coverage_contract is not None:
        agent_result = _apply_answer_coverage_contract(agent_result)
    else:
        missing_child_queries = [
            str(item or "").strip()
            for item in (answer_metadata.get("compound_missing_child_queries") or [])
            if str(item or "").strip()
        ]
        if missing_child_queries:
            answer_text = str(agent_result.get("answer") or "").strip()
            missing_lines = [f"关于“{query}”：当前同 SKU 资料未直接确认，无法确认。" for query in missing_child_queries]
            additions = [line for line in missing_lines if line not in answer_text]
            if additions:
                agent_result["answer"] = "\n".join([item for item in (answer_text, *additions) if item])
            compound_query_list = []
        else:
            compound_query_list = [
                str(item or "").strip()
                for item in (answer_metadata.get("compound_product_qa_queries") or [])
                if str(item or "").strip()
            ]
        # If a compound turn produced only one answer, do not silently drop
        # later independently requested children.  The child query itself is
        # the semantic source; absent an explicit answer for it, fail closed.
        answer_text = str(agent_result.get("answer") or "").strip()
        if len(compound_query_list) > 1:
            uncovered_queries = _uncovered_compound_queries_for_output(
                answer_text,
                compound_query_list,
                answer_metadata,
            )
            additions = [
                f"关于“{query}”：当前同 SKU 资料未直接确认，无法确认。"
                for query in uncovered_queries
            ]
            if additions:
                agent_result["answer"] = "\n".join([item for item in (answer_text, *additions) if item])
    agent_result = _shape_answer_for_output(agent_result)
    agent_result = _clear_unrelated_catalogue_cards(question, agent_result)
    final_debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    if semantic_entry_snapshot is not None:
        final_result_skus = [
            str(item or "").strip().upper()
            for item in (agent_result.get("result_skus") or [])
            if str(item or "").strip()
        ]
        final_debug["semantic_postprocess_snapshot"] = {
            "entry": semantic_entry_snapshot,
            "final": {
                "answer": str(agent_result.get("answer") or "")[:240],
                "result_skus": final_result_skus,
                "answer_type": str(agent_result.get("answer_type") or ""),
                "agent_mode": str(final_debug.get("agent_mode") or ""),
                "source": str(
                    (agent_result.get("answer_metadata") or {}).get("source") or ""
                ),
            },
        }
        final_debug["semantic_postprocess_changed"] = bool(
            semantic_entry_snapshot.get("answer") != str(agent_result.get("answer") or "")[:240]
            or semantic_entry_snapshot.get("result_skus") != final_result_skus
            or semantic_entry_snapshot.get("answer_type") != str(agent_result.get("answer_type") or "")
        )
    agent_result["debug"] = final_debug
    if (
        str(final_debug.get("agent_mode") or "") == "sealed_product_qa_safe_missing"
        and not terminal_gifting_boundary
    ):
        rows = [row for row in (agent_result.get("results") or []) if isinstance(row, dict)]
        if rows:
            row = rows[0]
            sku = str(row.get("sku") or "").strip().upper()
            name = str(row.get("product_name_cn") or row.get("product_name_en") or sku).strip()
            agent_result["answer"] = _safe_missing_product_qa_answer(name, sku, question)
        agent_result["skip_polish"] = True
    result_rows = [row for row in (agent_result.get("results") or []) if isinstance(row, dict)]
    saved_plan = ((agent_result.get("debug") or {}).get("plan") or {})
    comparison_recommendation = bool(
        agent_result.get("answer_type") == "recommendation"
        and isinstance(saved_plan, dict)
        and (
            saved_plan.get("must_compare_both_products")
            or str(saved_plan.get("primary_intent") or "") == "product_compare_recommendation"
        )
    )
    if comparison_recommendation and result_rows:
        top_sku = str(result_rows[0].get("sku") or "").strip().upper()
        lower_skus = {
            str(row.get("sku") or "").strip().upper()
            for row in result_rows[1:]
            if str(row.get("sku") or "").strip()
        }
        lines = str(agent_result.get("answer") or "").splitlines()
        top_line_index = next(
            (
                index
                for index, line in enumerate(lines)
                if top_sku in line.upper() and not any(sku in line.upper() for sku in lower_skus)
            ),
            None,
        )
        if top_line_index is not None:
            agent_result["answer"] = "\n".join(lines[top_line_index:]).strip()
    agent_result["skip_polish"] = skip_polish
    if terminal_gifting_boundary:
        agent_result = _enforce_terminal_gifting_evidence_boundary(
            agent_result,
            bounded_answer=terminal_gifting_answer,
        )
    agent_result = customer_final_answer_arbiter.arbitrate_final_answer(agent_result)
    agent_result = _remove_redundant_identity_request(agent_result)
    if terminal_gifting_boundary:
        agent_result = _enforce_terminal_gifting_evidence_boundary(
            agent_result,
            bounded_answer=terminal_gifting_answer,
        )
    # Environmental combustion safety is a universal hazard boundary. If the
    # semantic path degraded an unbound tent/room/vehicle question into a
    # knowledge-gap clarification, replace that gap with the conservative
    # safety guidance owned by the usage-care contract. This does not resolve
    # a product or add catalogue facts; an explicit SKU remains on its sealed
    # same-SKU path.
    agent_result = _apply_environmental_fuel_safety_boundary(question, agent_result)
    agent_result = _attach_agent_quality(agent_result, question)
    conversation = _get_or_create_conversation(db, user_id, question, agent_result.get("sku"), conversation_id)
    db.add(CustomerServiceMessage(
        conversation_id=conversation.id,
        role="user",
        content=question,
        sku=agent_result.get("sku"),
    ))
    assistant_turn_index = _assistant_turn_index(db, conversation.id)
    sources_with_context = _sources_with_result_context(
        agent_result,
        turn_index=assistant_turn_index,
        user_question=question,
        inherited_recommendation_context=_latest_recommendation_context_for_sources(db, conversation.id),
        inherited_candidate_context=_latest_candidate_context_for_sources(db, conversation.id),
    )
    assistant_message = CustomerServiceMessage(
        conversation_id=conversation.id,
        role="assistant",
        content=agent_result["answer"],
        sku=agent_result.get("sku"),
        sources_json=json.dumps(sources_with_context, ensure_ascii=False, default=str),
    )
    db.add(assistant_message)
    _touch_conversation(conversation, agent_result.get("sku"))
    db.flush()
    conversation_id_value = conversation.id
    message_id_value = assistant_message.id
    db.commit()
    customer_perf_service.log_stage("save_messages_and_commit", stage_start, branch=branch, skip_polish=bool(agent_result.get("skip_polish")))
    customer_perf_service.log_stage(
        "ask_customer_service.total",
        request_start,
        branch=branch,
        intent=agent_result.get("intent"),
        agent_mode=(agent_result.get("debug") or {}).get("agent_mode"),
    )
    customer_perf_service.summarize_request(
        final_answer=agent_result.get("answer"),
        intent=agent_result.get("intent"),
        agent_mode=(agent_result.get("debug") or {}).get("agent_mode"),
    )
    release_session_connection(db)
    agent_result = _attach_semantic_preplan_debug(
        agent_result,
        semantic_preplan,
        final_route=str(agent_result.get("answer_type") or agent_result.get("intent") or ""),
    )
    public_intent = _public_intent_name(agent_result.get("intent"), agent_result.get("answer_type"))
    return {
        "conversation_id": conversation_id_value,
        "message_id": message_id_value,
        "intent": public_intent,
        "answer_type": agent_result.get("answer_type"),
        "confidence": agent_result.get("confidence"),
        "uncertainty": agent_result.get("uncertainty"),
        "needs_clarification": agent_result.get("needs_clarification", False),
        "anomalies": agent_result.get("anomalies") or [],
        "suggested_followups": agent_result.get("suggested_followups") or [],
        "followups": agent_result.get("followups") or agent_result.get("suggested_followups") or [],
        "warnings": agent_result.get("warnings") or [],
        "evidence": agent_result.get("evidence") or [],
        "agent_quality": agent_result.get("agent_quality") or {},
        "answer_metadata": agent_result.get("answer_metadata") or {},
        "debug": agent_result.get("debug") or {},
        "sku": agent_result.get("sku"),
        "answer": agent_result["answer"],
        "sources": sources_with_context,
        "actions": agent_result.get("actions") or [],
        "results": agent_result.get("results") or [],
        "steps": agent_result.get("steps") or [],
        "result_skus": agent_result.get("result_skus") if "result_skus" in agent_result else [
            str(item.get("sku") or "").strip().upper()
            for item in (agent_result.get("results") or [])
            if isinstance(item, dict) and str(item.get("sku") or "").strip()
        ],
        "candidate_skus": agent_result.get("candidate_skus") if "candidate_skus" in agent_result else [
            str(item.get("sku") or "").strip().upper()
            for item in (agent_result.get("results") or [])
            if isinstance(item, dict) and str(item.get("sku") or "").strip()
        ],
        "agent_mode": (agent_result.get("debug") or {}).get("agent_mode"),
    }


def _phase1_timing(
    *,
    request_start: float,
    planner_duration_ms: float = 0,
    retrieval_duration_ms: float = 0,
    executor_duration_ms: float = 0,
    composer_duration_ms: float = 0,
    guard_duration_ms: float = 0,
    llm_duration_ms: float = 0,
    llm_call_count: int = 0,
) -> dict:
    return customer_agent_planner_service.merge_timing(
        None,
        {
            "total_duration_ms": round((perf_counter() - request_start) * 1000, 2),
            "planner_duration_ms": planner_duration_ms,
            "retrieval_duration_ms": retrieval_duration_ms,
            "executor_duration_ms": executor_duration_ms,
            "llm_duration_ms": llm_duration_ms,
            "llm_call_count": llm_call_count,
            "composer_duration_ms": composer_duration_ms,
            "guard_duration_ms": guard_duration_ms,
        },
    )


def _attach_phase1_plan_and_timing(agent_result: dict, plan: dict, timing: dict) -> dict:
    if not isinstance(agent_result, dict):
        return agent_result
    answer_metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    existing_plan = debug.get("plan") if isinstance(debug.get("plan"), dict) else {}
    merged_timing = customer_agent_planner_service.merge_timing(debug.get("timing"), timing)
    answer_metadata["timing"] = customer_agent_planner_service.merge_timing(answer_metadata.get("timing"), merged_timing)
    debug["timing"] = merged_timing
    # ``_db`` is a runtime-only dependency for the phase executors.  It must
    # never escape into the debug payload: HTTP debug responses are JSON and
    # a SQLAlchemy Session is neither customer evidence nor serializable.
    original_plan = {
        key: value
        for key, value in (plan.items() if isinstance(plan, dict) else [])
        if key != "_db"
    }
    debug_plan = {**original_plan, **existing_plan} if existing_plan else original_plan
    # A product-page SKU is request identity, not a route hint. An early
    # route may carry an older plan snapshot, but must never erase it.
    if original_plan.get("request_sku_anchor"):
        debug_plan["request_sku_anchor"] = original_plan["request_sku_anchor"]
    debug["plan"] = debug_plan
    if isinstance(plan, dict) and isinstance(plan.get("semantic_preplan"), dict):
        already_attached = bool((debug.get("semantic_preplan") or {}).get("called")) if isinstance(debug.get("semantic_preplan"), dict) else False
        preplan_debug = dict(plan["semantic_preplan"])
        if not preplan_debug.get("accepted_or_overridden"):
            final_route = str(agent_result.get("answer_type") or agent_result.get("intent") or "").strip()
            route_hint = str(preplan_debug.get("route_hint") or "").strip()
            accepted = bool(route_hint and final_route in _semantic_preplan_equivalent_routes(route_hint, final_route))
            preplan_debug["accepted_or_overridden"] = "accepted" if accepted else "overridden"
            if not accepted:
                preplan_debug["override_reason"] = preplan_debug.get("fallback_reason") or "deterministic_guard_final_route"
        plan["semantic_preplan"] = preplan_debug
        debug["semantic_preplan"] = preplan_debug
        if not already_attached and preplan_debug.get("called"):
            delta = int(preplan_debug.get("llm_call_count_delta") or preplan_debug.get("llm_call_count") or 0)
            if delta:
                debug["timing"]["llm_call_count"] = int(debug["timing"].get("llm_call_count") or 0) + delta
                answer_metadata["timing"]["llm_call_count"] = int(answer_metadata["timing"].get("llm_call_count") or 0) + delta
    agent_result["answer_metadata"] = answer_metadata
    agent_result["debug"] = debug
    return agent_result


def _ensure_debug_plan_raw_question(agent_result: dict, question: str) -> dict:
    """Keep the public audit trace complete without changing an effective plan."""
    if not isinstance(agent_result, dict):
        return agent_result
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    plan = debug.get("plan") if isinstance(debug.get("plan"), dict) else {}
    raw_question = str(question or "").strip()
    if raw_question and not str(plan.get("raw_question") or "").strip():
        plan["raw_question"] = raw_question
    debug["plan"] = plan
    agent_result["debug"] = debug
    return agent_result


def _semantic_preplan_equivalent_routes(route_hint: str, final_route: str) -> set[str]:
    route = str(route_hint or "").strip()
    final = str(final_route or "").strip()
    equivalents = {
        "comparison": {"comparison", "recommendation"},
        "query_products": {"query_products", "product_query"},
        "usage_care": {"knowledge_base_answer", "product_usage_care"},
        "unknown_field": {"product_detail", "knowledge_base_answer"},
        "product_detail": {"product_detail"},
    }
    return equivalents.get(route) or {route, final}


def _attach_semantic_preplan_debug(agent_result: dict | None, semantic_preplan: dict | None, *, final_route: str) -> dict | None:
    if not isinstance(agent_result, dict) or not isinstance(semantic_preplan, dict) or not semantic_preplan.get("called"):
        return agent_result
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    answer_metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    already_attached = bool((debug.get("semantic_preplan") or {}).get("called")) if isinstance(debug.get("semantic_preplan"), dict) else False
    final = str(final_route or agent_result.get("answer_type") or agent_result.get("intent") or "").strip()
    route_hint = str(semantic_preplan.get("route_hint") or "").strip()
    accepted = bool(route_hint and final in _semantic_preplan_equivalent_routes(route_hint, final))
    preplan_debug = dict(semantic_preplan)
    preplan_debug["accepted_or_overridden"] = "accepted" if accepted else "overridden"
    if not accepted:
        preplan_debug["override_reason"] = preplan_debug.get("fallback_reason") or "deterministic_guard_final_route"
    debug["semantic_preplan"] = preplan_debug
    if not already_attached:
        for container in (debug, answer_metadata):
            timing = container.get("timing") if isinstance(container.get("timing"), dict) else None
            if timing:
                timing["llm_call_count"] = int(timing.get("llm_call_count") or 0) + int(semantic_preplan.get("llm_call_count_delta") or semantic_preplan.get("llm_call_count") or 0)
                timing["llm_duration_ms"] = timing.get("llm_duration_ms") or 0
        trace = debug.get("trace") if isinstance(debug.get("trace"), dict) else None
        if trace is not None:
            trace["llm_call_count"] = int(trace.get("llm_call_count") or 0) + int(semantic_preplan.get("llm_call_count_delta") or semantic_preplan.get("llm_call_count") or 0)
    agent_result["debug"] = debug
    agent_result["answer_metadata"] = answer_metadata
    return agent_result


def _has_explicit_sku_text(question: str) -> bool:
    return bool(SKU_RE.search(str(question or "")))








def _looks_like_contents_accessories_contract_question(question: str) -> bool:
    text = str(question or "").strip()
    if not text:
        return False
    return bool(
        customer_agent_service.looks_like_contents_accessories_question(text)
        or customer_agent_intent_service._looks_like_contents_grounding_question(text)
    )


def _looks_like_ignition_capability_question(question: str) -> bool:
    """Recognize an ignition feature/capability ask, not an operation issue.

    The same ``点火`` vocabulary appears in setup and troubleshooting turns.
    Only the capability predicates stay on the formal product-detail contract;
    procedure/failure wording remains eligible for the usage-care route.
    """
    text = str(question or "").strip()
    if not text or not any(
        term in text
        for term in (
            "电子点火", "远程点火", "远程打火", "点火装置", "点火方式", "打火方式",
            "手动点火", "手动打火", "自动点火", "自动打火", "电池",
        )
    ):
        return False
    if any(term in text for term in ("怎么", "如何", "步骤", "操作", "点不着", "打不着", "点不起来")):
        return False
    return any(term in text for term in ("带", "有", "没有", "没带", "不带", "需要", "不用", "不是", "是否", "是不是", "吗", "吧"))




def _has_non_usage_care_field_contract(question: str) -> bool:
    """Keep non-usage product fields out of the usage/care fast path."""
    field_contract = customer_field_contract.detect_field_contract(question)
    # Any formal field must reach the central entity arbitration before a
    # scope guard or usage/care shortcut can decide the result.  Accessories
    # retains its additional generic-query exclusion below.
    if field_contract and field_contract.field_type != "accessories":
        # A product noun such as ``酒精炉`` can itself satisfy the heat-source
        # alias contract.  When the same sentence contains an operational,
        # failure, storage, or explicit fuel-compatibility signal, that field
        # alias is the subject—not the requested answer.  Preserve the
        # usage/safety route so a question such as “酒精炉怎么点不着” cannot
        # be downgraded to a bare heat-source listing.
        text = str(question or "").strip()
        if (
            field_contract.field_type == "usage_instruction"
            and _looks_like_ignition_capability_question(text)
        ):
            return True
        usage_signal = any(
            marker in text
            for marker in (
                "怎么", "如何", "点不着", "打不着", "点火", "点不起来", "安全", "危险",
                "存放", "保存", "收纳", "没用完", "用不完", "能用吗", "可以用吗",
                "支持", "适配", "兼容", "连接", "接上", "漏气", "泄漏", "会漏",
            )
        )
        if usage_signal and customer_agent_intent_service._looks_like_usage_care_question(text):
            return False
        return True
    if not field_contract or field_contract.field_type != "accessories":
        return _looks_like_contents_accessories_contract_question(question)

    # An explicit SKU is a sealed product-identity signal even when subject
    # span extraction also retains a shorter SKU-shaped search candidate.
    # Contents/accessories must therefore enter entity arbitration rather than
    # degrading into a generic catalogue query.
    if _has_explicit_sku_text(question):
        return True

    # Accessories only become product-bound when FieldContract left a concrete
    # subject. Category discovery and recommendation language keeps its
    # established query-products path even though it mentions accessories.
    selection = customer_field_contract.select_entity_subject_for_routing(raw_question=question)
    subject = str(selection.entity_subject or "").strip()
    if not subject or subject.startswith(("哪些", "有哪些", "什么", "推荐", "适合")):
        return False
    if _is_generic_contents_subject(subject):
        return False
    if any(term in str(question or "") for term in ("更偏", "推荐", "适合", "用于", "收纳")):
        return False
    return not _is_generic_category_phrase(subject) and not _is_generic_modifier_prefixed_product_scope(subject)








def _semantic_prior_result_context_semantics(
    recommendation_context: dict[str, Any] | None,
    candidate_context: dict[str, Any] | None,
) -> dict[str, Any]:
    """Describe prior-result discourse state without exposing product identity.

    The semantic planner receives opaque result positions for identity.  It
    also needs to know whether those positions came from a comparison or a
    recommendation, and whether the previous answer already recorded a
    choice.  Those are conversation-state facts, not product facts and not
    routing keywords.
    """
    contexts = [
        context
        for context in (recommendation_context, candidate_context)
        if isinstance(context, dict) and context
    ]
    if not contexts:
        return {}
    # Prefer a complete multi-product comparison ledger over a later/smaller
    # single-product anchor.  The latter is useful for a product-detail
    # pronoun, but if it wins here it hides the fact that the customer is still
    # choosing among the previous comparison participants.
    comparison_context = next(
        (
            context
            for context in contexts
            if str(context.get("source") or "").strip().lower() == "comparison"
            and len(_ordered_context_skus(context)) >= 2
        ),
        None,
    )
    context = comparison_context or contexts[0]
    source = str(context.get("source") or "").strip().lower()
    answer_type = str(context.get("answer_type") or "").strip().lower()
    if source not in {"comparison", "recommendation", "result"}:
        source = "comparison" if answer_type == "comparison" else "recommendation" if answer_type == "recommendation" else "result"
    ordered = _ordered_context_skus(*contexts)
    recorded_choice_sku = str(context.get("final_choice_sku") or "").strip().upper()
    recorded_choice_index = None
    if recorded_choice_sku and recorded_choice_sku in ordered:
        # Keep the choice as an opaque position.  The semantic planner may use
        # this discourse state to resolve a later reference, while SKU and
        # product facts remain server-owned and sealed below.
        recorded_choice_index = ordered.index(recorded_choice_sku) + 1
    has_choice = bool(recorded_choice_sku)
    return {
        "prior_answer_kind": source,
        "prior_result_count": len(ordered),
        "prior_result_is_multi_product": len(ordered) >= 2,
        "prior_has_recorded_choice": has_choice,
        "prior_recorded_choice_index": recorded_choice_index,
        "prior_selection_state": (
            "recorded_choice"
            if has_choice
            else "comparison_candidates"
            if source == "comparison" and len(ordered) >= 2
            else "candidate_results"
        ),
    }


async def _maybe_run_semantic_preplan(
    db: Session,
    question: str,
    phase1_plan: dict | None,
    *,
    conversation_id: str | None,
    request_sku_anchor: str | None = None,
) -> dict | None:
    # Every customer read turn is interpreted from the complete utterance.
    # Deterministic code below validates identity, permissions, structured
    # values and same-SKU evidence; it does not decide meaning from keywords.
    if not str(question or "").strip():
        return None
    recommendation_context = _latest_recommendation_context_for_sources(db, conversation_id) if conversation_id else {}
    candidate_context = _latest_candidate_context_for_sources(db, conversation_id) if conversation_id else {}
    prior_result_skus = _semantic_prior_result_context_skus(
        recommendation_context,
        candidate_context,
    )
    prior_customer_preference_texts: list[str] = []
    if isinstance(recommendation_context, dict) and isinstance(
        recommendation_context.get("effective_recommendation_contract")
        or recommendation_context.get("recommendation_request_contract"),
        dict,
    ):
        prior_question = str(recommendation_context.get("user_question") or "").strip()
        if prior_question:
            prior_customer_preference_texts.append(prior_question)
    active_anchor_sku = str(
        (recommendation_context or {}).get("active_single_product_anchor") or ""
    ).strip().upper()
    if not active_anchor_sku and isinstance(candidate_context, dict):
        # A pairwise choice is persisted in candidate_context even when the
        # public result accidentally contains both sealed participants.  The
        # recorded choice is still the only valid single-product anchor for a
        # later product-bound fact question.
        active_anchor_sku = str(
            candidate_context.get("final_choice_sku") or ""
        ).strip().upper()
    active_anchor = {}
    if active_anchor_sku:
        product = db.query(Product).filter(Product.sku == active_anchor_sku).first()
        if product is not None:
            active_anchor = {
                "sku": active_anchor_sku,
                "product_name": str(product.product_name_cn or product.product_name_en or "").strip(),
            }
    # This is identity provenance only, never a route decision: the semantic
    # planner still decides whether the complete turn requests a product fact.
    # Passing a boolean avoids leaking a SKU, catalogue value, or answer into
    # the semantic prompt while allowing it to distinguish a named-product
    # question from genuinely unscoped general guidance.
    current_turn_products = _products_named_in_question(db, question)
    unique_current_turn_catalog_product_name = bool(
        customer_entity_resolution_contract.unique_canonical_subject_in_question(
            question,
            current_turn_products,
        )
    )
    unique_current_turn_catalog_product_mention = (
        customer_entity_resolution_contract.unique_canonical_subject_in_question(
            question,
            current_turn_products,
        )
        if unique_current_turn_catalog_product_name
        else ""
    )
    prior_result_context_semantics = _semantic_prior_result_context_semantics(
        recommendation_context,
        candidate_context,
    )
    semantic_preplan = await customer_agent_planner_service.plan_customer_question_semantic(
        db,
        question,
        phase1_plan,
        context={
            "conversation_id": conversation_id,
            "has_recommendation_context": bool(prior_customer_preference_texts),
            "prior_customer_preference_texts": prior_customer_preference_texts,
            "active_product_anchor": active_anchor,
            "has_page_product_anchor": bool(request_sku_anchor),
            "has_unique_current_turn_catalog_product_name": unique_current_turn_catalog_product_name,
            # This text is already a literal span of the customer turn, not
            # a SKU or database fact. It lets the semantic model distinguish
            # a catalog name that happens to resemble a generic category.
            "unique_current_turn_catalog_product_mention": unique_current_turn_catalog_product_mention,
            # The planner sees only opaque positions.  The service resolves a
            # returned position back to this persisted SKU list after the plan
            # is validated; the model never chooses an identity.
            "prior_result_context_indexes": list(
                range(1, min(len(prior_result_skus), 12) + 1)
            ),
            # This is discourse state only. It contains no SKU, product name,
            # catalogue value, or answer text; identities remain opaque result
            # positions and are resolved by the service after planning.
            "prior_result_context_semantics": prior_result_context_semantics,
        },
    )
    semantic_preplan = _normalize_semantic_prior_result_context(
        semantic_preplan,
        ordered_result_skus=prior_result_skus,
        prior_result_context_semantics=prior_result_context_semantics,
    )
    return _normalize_recommendation_entity_scope(
        db,
        question,
        semantic_preplan,
    )


def _semantic_recommendation_followup_review_needed(
    semantic_preplan: dict | None,
    recommendation_context: dict | None,
) -> bool:
    if not isinstance(semantic_preplan, dict) or not isinstance(recommendation_context, dict):
        return False
    if not (
        recommendation_context.get("previous_result_skus")
        or recommendation_context.get("recommended_skus")
    ):
        return False
    if str(semantic_preplan.get("recommendation_followup_action") or "").strip() == "alternative":
        return False
    route = str(semantic_preplan.get("route_family") or "").strip()
    context_usage = str(semantic_preplan.get("context_usage") or "").strip()
    if (
        route == "recommendation"
        and context_usage in {"recommendation_context", "result_context"}
    ):
        return True
    return bool(
        route == "product_bound_qa"
        and context_usage == "result_context"
        and semantic_preplan.get("context_result_indexes")
    )


def _apply_semantic_recommendation_followup_action(
    semantic_preplan: dict | None,
    recommendation_context: dict | None,
    followup_decision: dict | None,
) -> dict | None:
    if not isinstance(semantic_preplan, dict) or not isinstance(recommendation_context, dict):
        return semantic_preplan
    if not isinstance(followup_decision, dict) or str(
        followup_decision.get("recommendation_followup_action") or ""
    ).strip().lower() != "alternative":
        return semantic_preplan
    normalized = dict(semantic_preplan)
    normalized.update({
        "route_family": "recommendation",
        "route_hint": "recommendation",
        "question_type": "recommendation",
        "subtype": "recommendation_change",
        "context_usage": "recommendation_context",
        "context_result_indexes": [],
        "decision_requested": True,
        "recommendation_followup_action": "alternative",
        "canonical_fields": [],
        "field_type": "",
        "field_hint": "",
        "evidence_kind": "",
        "evidence_required": True,
        "ambiguity": False,
        "fallback_reason": "",
        "accepted_or_overridden": "semantic_recommendation_followup_classifier",
        "override_reason": "flash_semantic_followup_classified_replacement_search",
    })
    # A product-bound plan may carry the anchored product name as its subject.
    # Replacement retrieval must reopen the persisted recommendation scope so
    # the sealed prior SKU can be excluded without narrowing the pool to itself.
    prior_scope = str(recommendation_context.get("product_scope") or "").strip()
    normalized["subject_text"] = prior_scope
    normalized["entity_scope"] = "category_scope" if prior_scope else ""
    relative_fields = {
        str(item or "").strip()
        for item in (followup_decision.get("relative_fields") or [])
        if str(item or "").strip()
    }
    if "weight" in relative_fields:
        preferences = [
            str(item or "").strip()
            for item in (normalized.get("recommendation_soft_preferences") or [])
            if str(item or "").strip()
        ]
        if not any("lighter than" in item.casefold() or "更轻" in item for item in preferences):
            preferences.append("lighter than the prior recommendation")
        normalized["recommendation_soft_preferences"] = list(dict.fromkeys(preferences))
    normalized["semantic_recommendation_followup_review"] = dict(followup_decision)
    return normalized


def _normalize_recommendation_entity_scope(
    db: Session,
    question: str,
    semantic_preplan: dict | None,
) -> dict | None:
    """Keep recommendation entities to catalogue products, not predicates.

    The semantic envelope allows product mentions as strings, so a provider
    can occasionally place a material or heat-source noun beside the actual
    recommendation subject in ``entities``.  Treating every string as a
    comparison participant is unsafe.  Validate the entity roles against the
    current catalogue identities already present in the turn; when fewer than
    two real products are present, preserve the recommendation route and let
    its normal contract execute.  No wording-specific intent route or product
    fact is inferred here.
    """
    value = semantic_preplan if isinstance(semantic_preplan, dict) else None
    if not value or str(value.get("route_family") or "").strip() != "recommendation":
        return semantic_preplan
    entities = [str(item or "").strip() for item in value.get("entities") or [] if str(item or "").strip()]
    if len(entities) < 2:
        return semantic_preplan
    named_products = _products_named_in_question(db, question) if db is not None else []
    named_skus = {
        str(product.sku or "").strip().upper()
        for product in named_products
        if str(product.sku or "").strip()
    }
    for candidate in customer_agent_service._extract_skus(question):
        resolved = _resolve_exact_sku_variant(db, candidate) if db is not None else None
        if resolved:
            named_skus.add(str(resolved).strip().upper())
    if len(named_skus) >= 2:
        return semantic_preplan
    normalized_named_labels = {
        customer_agent_service.normalize_search_text(label).lower()
        for product in named_products
        for label in (product.product_name_cn, product.product_name_en, product.sku)
        if str(label or "").strip()
    }
    product_entities = [
        entity
        for entity in entities
        if customer_agent_service.normalize_search_text(entity).lower() in normalized_named_labels
        or str(entity or "").strip().upper() in named_skus
    ]
    normalized = dict(value)
    normalized["entities"] = list(dict.fromkeys(product_entities))
    normalized["entity_scope"] = "resolved_product" if product_entities else "category_scope"
    normalized["semantic_adapter_source"] = "validated_recommendation_entity_scope"
    if str(normalized.get("fallback_reason") or "").strip() in {
        "pairwise_recommendation_requires_comparison_contract",
        "pairwise_factual_requires_comparison_contract",
    }:
        if product_entities:
            # Genuine named products keep the pairwise comparison contract.
            # Predicate-like entities (people, capacity, coating, and the
            # requested product kind) are not participants; they must not turn
            # a recommendation into an unsealed comparison or erase the
            # recommendation's own semantic fields.
            normalized["fallback_reason"] = ""
            normalized["accepted_or_overridden"] = "validated_recommendation_entity_scope"
            normalized["route_hint"] = "recommendation"
            normalized["question_type"] = "recommendation"
            normalized["subtype"] = str(normalized.get("subtype") or "recommendation")
            normalized["ambiguity"] = False
            normalized["evidence_required"] = True
            normalized["confidence"] = max(float(normalized.get("confidence") or 0.0), 0.65)
            normalized["confidence_label"] = "medium" if normalized["confidence"] < 0.9 else "high"
        else:
            # The validator's comparison error was caused only by polluted
            # entity slots. Keep the model's original recommendation shape and
            # allow the executor to use its typed constraints/free-text context.
            normalized["fallback_reason"] = "missing_recommendation_semantic_context"
            normalized["accepted_or_overridden"] = "validated_recommendation_entity_scope"
            normalized["override_reason"] = "non_product_entities_removed_from_recommendation_scope"
            normalized["route_hint"] = "recommendation"
            normalized["question_type"] = "recommendation"
            normalized["subtype"] = str(normalized.get("subtype") or "recommendation")
            normalized["ambiguity"] = False
            normalized["evidence_required"] = True
            normalized["confidence"] = max(float(normalized.get("confidence") or 0.0), 0.65)
            normalized["confidence_label"] = "medium" if normalized["confidence"] < 0.9 else "high"
    return normalized


def _normalize_semantic_prior_result_context(
    semantic_preplan: dict | None,
    *,
    ordered_result_skus: list[str] | None,
    prior_result_context_semantics: dict[str, Any] | None,
) -> dict | None:
    """Bind a semantic prior-result scope to server-owned opaque positions.

    Flash can understand that a turn operates on the previous answer while
    omitting the companion ``context_result_indexes`` field or using a
    descriptive scope such as ``prior_context``.  The planner validator keeps
    that meaning as ``entity_scope=prior_results``; this adapter supplies only
    the positions already persisted by the server.  It never resolves a SKU
    from customer wording and never creates a new product participant.
    """
    value = semantic_preplan if isinstance(semantic_preplan, dict) else None
    if not value:
        return semantic_preplan
    ordered = list(dict.fromkeys(
        str(sku or "").strip().upper()
        for sku in (ordered_result_skus or [])
        if str(sku or "").strip()
    ))[:12]
    if not ordered:
        return semantic_preplan

    raw_indexes = value.get("context_result_indexes") or []
    indexes = [
        item
        for item in raw_indexes
        if type(item) is int and 1 <= item <= len(ordered)
    ]
    entity_scope = str(value.get("entity_scope") or "").strip().lower()
    prior_scope = entity_scope == "prior_results" or entity_scope.startswith(("prior_", "previous_"))
    if not prior_scope and not indexes:
        return semantic_preplan

    semantics = (
        prior_result_context_semantics
        if isinstance(prior_result_context_semantics, dict)
        else {}
    )
    try:
        recorded_index = int(semantics.get("prior_recorded_choice_index"))
    except (TypeError, ValueError):
        recorded_index = 0

    if not indexes and prior_scope:
        prior_kind = str(semantics.get("prior_answer_kind") or "").strip().lower()
        # A previous comparison is still a pairwise evidence set even if its
        # answer already named a preferred item: a follow-up asking to choose
        # needs both sealed participants available to justify that choice.
        if prior_kind == "comparison" and len(ordered) >= 2:
            indexes = list(range(1, len(ordered) + 1))
        elif 1 <= recorded_index <= len(ordered):
            indexes = [recorded_index]
        else:
            indexes = list(range(1, len(ordered) + 1))

    # A comparison can have two persisted participants and still record one
    # evidence-backed choice.  If the next semantic turn is product-bound QA,
    # that route means the customer is asking a fact about one product, not
    # asking us to answer for the whole comparison again.  Prefer the
    # server-owned recorded choice in that case.  This is discourse-state
    # binding, not a Chinese wording matcher: a genuinely multi-product fact
    # request remains a comparison plan and keeps all opaque positions.
    if (
        str(value.get("route_family") or "").strip() == "product_bound_qa"
        and str(value.get("context_usage") or "").strip() == "result_context"
        and len(indexes) > 1
        and isinstance(prior_result_context_semantics, dict)
        and prior_result_context_semantics.get("prior_has_recorded_choice")
        and isinstance(recorded_index, int)
        and 1 <= recorded_index <= len(ordered)
    ):
        indexes = [recorded_index]

    if not indexes:
        return semantic_preplan
    normalized = dict(value)
    normalized["entity_scope"] = "prior_results"
    normalized["context_usage"] = "result_context"
    normalized["context_result_indexes"] = list(dict.fromkeys(indexes))
    normalized["accepted_or_overridden"] = "server_prior_result_context_binding"
    normalized["override_reason"] = "semantic_prior_result_scope_bound_to_opaque_handles"
    return normalized


def _semantic_preplan_route_family(preplan: dict | None) -> str:
    if not isinstance(preplan, dict) or not preplan.get("called"):
        return ""
    family = str(preplan.get("route_family") or "").strip()
    if family:
        return family
    route_hint = str(preplan.get("route_hint") or "").strip()
    subtype = str(preplan.get("subtype") or "").strip()
    question_type = str(preplan.get("question_type") or "").strip()
    if subtype == "structured_query" or (route_hint == "query_products" and question_type in {"filter", "count"}):
        return "structured_query" if subtype == "structured_query" else "generic_query"
    if route_hint == "recommendation" or subtype == "recommendation":
        return "recommendation"
    if route_hint == "unknown_field" or subtype in {"unknown_realtime", "commercial_realtime"}:
        return "unknown_realtime"
    if question_type == "contents_accessories" or subtype in {"contents_accessories", "composition"}:
        return "contents_accessories"
    if route_hint in {"product_detail", "usage_care", "knowledge_base_answer"}:
        return "product_bound_qa"
    if route_hint == "clarification" or subtype == "no_match":
        return "clarification"
    return ""


def _apply_semantic_single_field_route_precedence(
    phase1_plan: dict | None,
    semantic_preplan: dict | None,
) -> None:
    """Remove parser-only collection state after a sealed singular field plan.

    The semantic planner owns the whole-turn meaning.  A legacy parser can
    still expose a short SKU prefix as a second participant (for example a
    compact token embedded in a longer SKU); that diagnostic extraction must
    never turn a high-confidence, one-product field request into comparison
    work.  This helper changes no field, entity, SKU, or evidence: Phase 2
    will independently validate the semantic subject into its contract.
    """
    plan = phase1_plan if isinstance(phase1_plan, dict) else None
    preplan = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    fields = [
        str(field or "").strip()
        for field in (preplan.get("canonical_fields") or [])
        if str(field or "").strip() in customer_field_contract.FORMAL_DETAIL_FIELDS
    ]
    if not (
        plan is not None
        and preplan.get("called")
        and _semantic_preplan_confident(preplan, minimum=0.9)
        and _semantic_preplan_route_family(preplan) == "product_bound_qa"
        and len(fields) == 1
    ):
        return
    plan["primary_intent"] = "product_detail"
    plan["answer_type"] = "product_detail"
    plan["product_refs"] = []
    plan["must_compare_both_products"] = False
    plan["must_make_choice"] = False
    plan["tasks"] = []




def _semantic_preplan_confident(preplan: dict | None, *, minimum: float = 0.5) -> bool:
    if not isinstance(preplan, dict) or not preplan.get("called"):
        return False
    label = str(preplan.get("confidence_label") or "").strip()
    if label == "high":
        return True
    if label == "medium":
        return minimum <= 0.65
    try:
        confidence = float(preplan.get("confidence") or 0)
    except (TypeError, ValueError):
        confidence = 0.0
    if confidence >= minimum:
        return True
    # A fail-closed semantic parser clears its public confidence, but the
    # catalogue adapter may safely consume the independently retained route
    # confidence only to select an exact value from the live DB closed set.
    if (
        str(preplan.get("semantic_route_family_hint") or "") == "structured_query"
        and str(preplan.get("fallback_reason") or "") in {
            "incomplete_structured_query_scope",
            "catalogue_value_requires_structured_query",
            "unbound_catalogue_browse_requires_structured_query",
        }
    ):
        try:
            return float(preplan.get("semantic_confidence_hint") or 0) >= minimum
        except (TypeError, ValueError):
            return False
    return False




def _semantic_pairwise_contract_candidate(preplan: dict | None) -> bool:
    """Whether a semantic plan requires sealed handling of multiple named products.

    A user can request a choice between two named products using either the
    ``comparison`` or ``recommendation`` route family.  The latter is still a
    pairwise decision, not permission for the legacy recommendation renderer
    to invent a preference.  Semantic planning owns that distinction; this
    helper only decides whether every supplied participant must be sealed.
    """
    value = preplan if isinstance(preplan, dict) else {}
    route_family = str(value.get("route_family") or "").strip()
    if route_family == "comparison":
        return True
    # A request to choose from the catalogue is a recommendation, not a
    # pairwise comparison.  But once semantic planning has supplied two or
    # more named product spans, a catalogue-wide recommendation must never
    # replace them.  ``decision_requested`` is useful answer-shaping context,
    # not a safe prerequisite for preserving those identities: model output
    # can omit that boolean while still understanding a natural “怎么选” ask.
    participants = [str(item).strip() for item in (value.get("entities") or []) if str(item or "").strip()]
    context_indexes = [item for item in (value.get("context_result_indexes") or []) if isinstance(item, int)]
    return route_family == "recommendation" and len(participants) + len(context_indexes) >= 2


def _semantic_context_result_skus(
    semantic_preplan: dict | None,
    ordered_result_skus: list[str] | None,
) -> list[str]:
    """Resolve semantic result handles against the persisted result ledger.

    The planner may understand an anaphoric reference, but it is never allowed
    to manufacture an identity.  Only one-based positions returned by the
    planner and the server-owned ordered SKU ledger participate here.
    """
    preplan = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    raw_indexes = preplan.get("context_result_indexes") or []
    if not raw_indexes:
        return []
    ordered = [
        str(sku or "").strip().upper()
        for sku in (ordered_result_skus or [])
        if str(sku or "").strip()
    ]
    resolved: list[str] = []
    for raw_index in raw_indexes:
        if isinstance(raw_index, bool) or not isinstance(raw_index, int):
            return []
        position = raw_index - 1
        if position < 0 or position >= len(ordered):
            return []
        sku = ordered[position]
        if sku in resolved:
            return []
        resolved.append(sku)
    return resolved


def _semantic_structured_comparison_overview_contract(preplan: dict | None) -> bool:
    """Recognize an intentional fieldless semantic comparison overview.

    The semantic plan, not a legacy field alias in words such as "features",
    decides whether a named comparison asks for one field or for a bounded
    overview of recorded differences.  A relation-comparison plan with no
    requested field is also an overview: the semantic planner has already
    identified the user's broad "what is the difference" intent, and the
    executor can now present the sealed participants' common, differing facts.
    """
    value = preplan if isinstance(preplan, dict) else {}
    route_family = str(value.get("route_family") or "").strip()
    subtype = str(value.get("subtype") or "").strip()
    fieldless = (
        not list(value.get("canonical_fields") or [])
        and not str(value.get("field_type") or value.get("field_hint") or "").strip()
    )
    if (
        route_family == "comparison"
        and subtype == "relation_comparison"
        and fieldless
        and not bool(value.get("decision_requested"))
        and not str(value.get("supplemental_qa_evidence_query") or "").strip()
        and not list(value.get("comparison_qa_concepts") or [])
    ):
        return True
    return bool(
        route_family == "comparison"
        and str(value.get("subtype") or "").strip() == "comparison_overview"
        and str(value.get("evidence_kind") or "").strip() == "structured_field"
        and fieldless
        and not bool(value.get("decision_requested"))
    )


def _explicit_product_identity_question(text: str) -> bool:
    """Whether the customer explicitly asks if products share one identity.

    This does not resolve either product or choose a route.  It only preserves
    the obligation to answer the customer's yes/no identity question after
    both participants have independently been sealed to catalogue records.
    """
    value = str(text or "")
    return any(term in value for term in ("同一款", "同款", "同一个产品"))


def _should_execute_semantic_catalog_recommendation(preplan: dict | None) -> bool:
    """Allow the catalogue executor only for an unbound semantic recommendation.

    Named multi-product requests are sealed comparison work, even when the
    semantic route label is ``recommendation``.  This guard is intentionally
    based on the structured semantic plan, rather than lexical heuristics.
    """
    context_result_selection = bool(
        isinstance(preplan, dict)
        and str(preplan.get("route_family") or "").strip() == "recommendation"
        and str(preplan.get("context_usage") or "").strip() == "result_context"
        and bool(preplan.get("context_result_indexes"))
        and not any(str(item or "").strip() for item in (preplan.get("entities") or []))
        and bool(preplan.get("decision_requested"))
    )
    if not isinstance(preplan, dict) or (
        _semantic_pairwise_contract_candidate(preplan)
        and not context_result_selection
    ):
        return False
    constraints = preplan.get("recommendation_constraints")
    constraints = constraints if isinstance(constraints, dict) else {}
    # ``subject_text`` is the model's meaning-level description of what the
    # customer wants.  It is often a whole natural purpose rather than a
    # catalogue category (for example, "a practical gift for a beginner").
    # Treating that field as a reason to refuse catalogue execution made a
    # healthy recommendation plan fall through to the same generic
    # clarification.  The planner has already owned the route; the executor
    # can search the catalogue and let same-SKU evidence decide what it can
    # say.  The context check below only prevents a completely empty plan from
    # becoming an arbitrary catalogue recommendation.
    has_semantic_selection_context = bool(
        constraints
        or str(preplan.get("subject_text") or "").strip()
        or preplan.get("recommendation_evidence_requirements")
        or preplan.get("recommendation_soft_preferences")
        or preplan.get("unrepresented_recommendation_requirements")
        or context_result_selection
    )
    return (
        str(preplan.get("route_family") or "") == "recommendation"
        and not preplan.get("fallback_reason")
        # A grounded medium-confidence recommendation still belongs to the
        # semantic contract.  Confidence controls whether the model may claim
        # certainty about wording; it must not reopen the legacy lexical
        # ``query_products`` router.  The shared verifier below either proves
        # every candidate from same-SKU evidence or returns a safe
        # clarification, so accepting the semantic route at the medium floor
        # does not relax the evidence boundary.
        and _semantic_preplan_confident(preplan, minimum=0.65)
        and isinstance(preplan.get("recommendation_constraints"), dict)
        # A model-owned item-selection request may intentionally omit a
        # category (for example choosing one practical gift for a beginner).
        # In that case the catalogue is the scope and the semantic priorities
        # drive retrieval/ranking; no deterministic category is guessed.
        and has_semantic_selection_context
    )






def _one_edit_apart(left: str, right: str) -> bool:
    """Return whether two compact strings differ by exactly one edit."""
    if left == right or abs(len(left) - len(right)) > 1:
        return False
    if len(left) > len(right):
        left, right = right, left
    if len(left) == len(right):
        return sum(a != b for a, b in zip(left, right)) == 1
    index_left = index_right = differences = 0
    while index_left < len(left) and index_right < len(right):
        if left[index_left] == right[index_right]:
            index_left += 1
            index_right += 1
            continue
        differences += 1
        index_right += 1
        if differences > 1:
            return False
    return True


def _semantic_unique_typo_near_catalog_subject(
    entity: str,
    products: list[Product],
) -> str:
    """Recover a one-character shopper typo only when the catalogue is unique.

    Semantic planning must already have identified a product mention.  This
    helper supplies no SKU or facts: it merely maps that literal mention to a
    canonical display name when exactly one catalogue row is one edit away.
    Ambiguous near matches continue to fail closed.
    """
    raw_entity = str(entity or "").strip()
    normalized = customer_agent_service.normalize_search_text(raw_entity).lower()
    normalized = re.sub(
        r"(?:这个|那个|这款|那款)?(?:产品|商品|炉子|炉具|锅具|水壶)$",
        "",
        normalized,
    ).strip()
    compact_entity = re.sub(r"[\s\-_()（）]+", "", normalized)
    if len(compact_entity) < 3 or len(re.findall(r"[\u4e00-\u9fff]", compact_entity)) < 2:
        return ""

    owners: dict[str, str] = {}
    exact_owner_found = False
    for product in products:
        sku = str(product.sku or "").strip().upper()
        display_name = str(product.product_name_cn or product.product_name_en or "").strip()
        if not sku or not display_name:
            continue
        aliases = {
            str(alias or "").strip()
            for source in (product.product_name_cn, product.product_name_en)
            for alias in customer_agent_service.product_name_aliases(str(source or ""))
            if str(alias or "").strip()
        }
        for alias in aliases:
            compact_alias = re.sub(
                r"[\s\-_()（）]+",
                "",
                customer_agent_service.normalize_search_text(alias).lower(),
            )
            if len(compact_alias) < 3:
                continue
            if compact_alias == compact_entity:
                exact_owner_found = True
                continue
            if _one_edit_apart(compact_entity, compact_alias):
                owners[sku] = display_name
                break
    if exact_owner_found:
        return ""
    return next(iter(owners.values())) if len(owners) == 1 else ""




def _semantic_comparison_entity_contracts(
    question: str,
    semantic_preplan: dict | None,
    products: list[Product],
    *,
    context_anchor_sku: str | None = None,
    context_result_skus: list[str] | None = None,
) -> list[customer_entity_resolution_contract.EntityResolutionContract]:
    """Validate semantic comparison participants without accepting an LLM SKU decision."""
    preplan = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    if (
        not _semantic_pairwise_contract_candidate(preplan)
        or not _semantic_preplan_confident(preplan, minimum=0.65)
    ):
        return []
    normalized_question = customer_agent_service.normalize_search_text(question)
    canonical_anchor_sku = str(context_anchor_sku or "").strip().upper()
    anchor_product = next(
        (
            product
            for product in products
            if str(product.sku or "").strip().upper() == canonical_anchor_sku
        ),
        None,
    )
    allow_context_anchor = bool(
        anchor_product is not None
        and str(preplan.get("context_usage") or "").strip() == "entity_anchor"
    )
    context_participant_skus = _semantic_context_result_skus(
        preplan,
        context_result_skus,
    )
    if preplan.get("context_result_indexes") and not context_participant_skus:
        return []
    product_by_sku = {
        str(product.sku or "").strip().upper(): product
        for product in products
        if str(product.sku or "").strip()
    }
    participants: list[str] = []
    context_anchor_participants: set[str] = set()
    coordinated_ellipsis_participants: set[str] = set()
    for raw_participant in preplan.get("entities") or []:
        participant = str(raw_participant or "").strip()
        normalized_participant = customer_agent_service.normalize_search_text(participant)
        if not normalized_participant or participant in participants:
            return []
        if normalized_participant not in normalized_question:
            anchor_identity_values = {
                customer_agent_service.normalize_search_text(value)
                for value in (
                    canonical_anchor_sku,
                    getattr(anchor_product, "product_name_cn", "") if anchor_product else "",
                    getattr(anchor_product, "product_name_en", "") if anchor_product else "",
                )
                if str(value or "").strip()
            }
            if allow_context_anchor and normalized_participant in anchor_identity_values:
                context_anchor_participants.add(participant)
            elif _is_coordinated_entity_ellipsis(
                normalized_question,
                normalized_participant,
                participants,
            ):
                coordinated_ellipsis_participants.add(participant)
            else:
                return []
        participants.append(participant)
    if len(participants) + len(context_participant_skus) < 2:
        return []
    # Entity sealing proves identity only.  For a single formal comparison
    # criterion, preserve that already-validated field on every contract so
    # downstream evidence can be audited against the same canonical request.
    # Multiple criteria intentionally stay unbound here: a missing value must
    # produce a same-SKU evidence gap, never make a uniquely named product
    # disappear or let identity arbitration choose among criteria.
    canonical_fields = [
        customer_field_contract.semantic_preplan_field_type(item)
        for item in (preplan.get("canonical_fields") or [])
    ]
    canonical_fields = list(dict.fromkeys(field for field in canonical_fields if field))
    field_type = canonical_fields[0] if len(canonical_fields) == 1 else None
    contracts: list[customer_entity_resolution_contract.EntityResolutionContract] = []
    resolved_skus: set[str] = set()
    for participant_index, participant in enumerate(participants):
        if participant in context_anchor_participants and anchor_product is not None:
            normalized_participant = customer_agent_service.normalize_search_text(participant)
            matched_by = (
                "sku_exact"
                if normalized_participant
                == customer_agent_service.normalize_search_text(canonical_anchor_sku)
                else "canonical_name_exact"
            )
            contract = customer_entity_resolution_contract.EntityResolutionContract(
                entity_text=participant,
                normalized_entity_text=normalized_participant,
                status="resolved",
                resolved_sku=canonical_anchor_sku,
                resolver_candidate_skus=[canonical_anchor_sku],
                diagnostic_candidate_skus=[],
                candidate_skus=[canonical_anchor_sku],
                matched_by=matched_by,
                confidence="high",
                is_unique=True,
                matched_span=None,
                field_type=field_type,
                status_reason="trusted_context_anchor_exact",
            )
        else:
            contract_subject = participant
            if (
                customer_agent_service.normalize_search_text(participant)
                in normalized_question
                or participant in coordinated_ellipsis_participants
            ):
                contract_subject = (
                    _semantic_unique_typo_near_catalog_subject(participant, products)
                    or participant
                )
            contract = customer_entity_resolution_contract.build_entity_resolution_contract(
                question,
                products,
                entity_text_override=contract_subject,
                field_type_override=field_type,
                participant_local_identity=True,
            )
        decision = customer_entity_resolution_contract.can_resolve_single_product(contract, products)
        if (
            not decision.allowed
            and customer_agent_service.normalize_search_text(participant) in normalized_question
            and participant_index > 0
        ):
            expanded_contracts: dict[str, customer_entity_resolution_contract.EntityResolutionContract] = {}
            participant_start = normalized_question.find(
                customer_agent_service.normalize_search_text(participant)
            )
            for prior_participant in participants[:participant_index]:
                normalized_prior = customer_agent_service.normalize_search_text(prior_participant)
                prior_start = normalized_question.find(normalized_prior)
                prior_end = prior_start + len(normalized_prior)
                between = (
                    normalized_question[prior_end:participant_start]
                    if prior_start >= 0 and participant_start >= prior_end
                    else ""
                )
                if not any(joiner in between for joiner in ("和", "与", "跟", "及", "、", "/")):
                    continue
                # Chinese coordination may omit the shared family in the
                # second literal mention ("Family A 和 B"). Try only prefixes
                # from the already literal first participant; catalogue exact
                # or unique one-edit sealing remains mandatory.
                for cut in range(2, len(normalized_prior)):
                    expanded = f"{normalized_prior[:cut]}{participant}"
                    canonical = _semantic_unique_typo_near_catalog_subject(expanded, products) or expanded
                    expanded_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
                        question,
                        products,
                        entity_text_override=canonical,
                        field_type_override=field_type,
                        participant_local_identity=True,
                    )
                    expanded_decision = customer_entity_resolution_contract.can_resolve_single_product(
                        expanded_contract,
                        products,
                    )
                    if expanded_decision.allowed and expanded_decision.resolved_sku:
                        expanded_contracts[expanded_decision.resolved_sku] = expanded_contract
            if len(expanded_contracts) == 1:
                contract = next(iter(expanded_contracts.values()))
                decision = customer_entity_resolution_contract.can_resolve_single_product(contract, products)
        if not decision.allowed or not decision.resolved_sku or decision.resolved_sku in resolved_skus:
            return []
        if (
            participant in coordinated_ellipsis_participants
            and contract.matched_by not in {"canonical_name_exact", "normalized_alias_exact"}
        ):
            # Ellipsis completion may recover only an identity that the
            # catalogue itself seals exactly. Fuzzy recall is never enough.
            return []
        resolved_skus.add(decision.resolved_sku)
        contracts.append(contract)
    for context_index, context_sku in enumerate(context_participant_skus, start=1):
        product = product_by_sku.get(context_sku)
        if product is None or context_sku in resolved_skus:
            return []
        entity_text = str(
            product.product_name_cn
            or product.product_name_en
            or context_sku
        ).strip()
        normalized_entity_text = customer_agent_service.normalize_search_text(entity_text)
        contracts.append(customer_entity_resolution_contract.EntityResolutionContract(
            entity_text=entity_text,
            normalized_entity_text=normalized_entity_text,
            status="resolved",
            resolved_sku=context_sku,
            resolver_candidate_skus=[context_sku],
            diagnostic_candidate_skus=[],
            candidate_skus=[context_sku],
            matched_by="result_context_index",
            confidence="high",
            is_unique=True,
            matched_span=None,
            field_type=field_type,
            status_reason=f"trusted_result_context_index_{context_index}",
        ))
        resolved_skus.add(context_sku)
    return contracts


def _is_coordinated_entity_ellipsis(
    normalized_question: str,
    normalized_participant: str,
    literal_participants: list[str],
) -> bool:
    """Recognize a model-expanded participant in a coordinated product phrase.

    Chinese shoppers commonly state a shared family only once, e.g.
    ``天鹅壶4杯黑色和9杯黑色``.  The semantic planner may expand the second
    participant to its complete catalogue name.  Accept that expansion only
    when a meaningful shared prefix belongs to an already literal participant
    and the entire distinguishing suffix is present in the current question;
    the caller still requires an exact, unique catalogue identity.
    """
    if not normalized_question or not normalized_participant:
        return False
    for literal in literal_participants:
        normalized_literal = customer_agent_service.normalize_search_text(literal)
        if not normalized_literal or normalized_literal not in normalized_question:
            continue
        shared = 0
        for left, right in zip(normalized_literal, normalized_participant):
            if left != right:
                break
            shared += 1
        suffix = normalized_participant[shared:]
        if shared >= 2 and len(suffix) >= 2 and suffix in normalized_question:
            return True
    return False


def _apply_semantic_comparison_plan(
    question: str,
    phase1_plan: dict[str, Any],
    semantic_preplan: dict | None,
    products: list[Product],
    *,
    context_anchor_sku: str | None = None,
    context_result_skus: list[str] | None = None,
) -> list[customer_entity_resolution_contract.EntityResolutionContract]:
    """Adapt one validated semantic comparison into sealed multi-entity execution."""
    contracts = _semantic_comparison_entity_contracts(
        question,
        semantic_preplan,
        products,
        context_anchor_sku=context_anchor_sku,
        context_result_skus=context_result_skus,
    )
    if not contracts:
        return []
    resolved_skus = [str(contract.resolved_sku or "").strip().upper() for contract in contracts]
    if len(resolved_skus) < 2 or any(not sku for sku in resolved_skus):
        return []
    phase1_plan.update(
        {
            "primary_intent": "comparison",
            "answer_type": "comparison",
            "product_refs": resolved_skus,
            "must_compare_both_products": True,
            # The semantic plan owns whether the customer asked for a winner.
            # Do not let a second lexical comparator reinterpret the same turn
            # after Flash has already classified it.
            "must_make_choice": bool((semantic_preplan or {}).get("decision_requested")),
            "semantic_comparison_entity_contracts": [contract.to_dict() for contract in contracts],
        }
    )
    return contracts






def _semantic_comparison_fail_closed_result(semantic_preplan: dict | None) -> dict | None:
    """Keep an unsealed semantic comparison out of legacy free-form execution."""
    preplan = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    if not preplan.get("called") or not _semantic_pairwise_contract_candidate(preplan):
        return None
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": (
            "我能看出你想比较两款商品，但其中至少一款名称还不能唯一对应具体型号。"
            "请补充两款的完整商品名或 SKU，我再按各自已核对的信息公平比较。"
        ),
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "needs_clarification": True,
        "answer_metadata": {
            "source": "semantic_comparison_unsealed_clarification",
            "evidence_status": "entity_unsealed",
        },
        "debug": {
            "agent_mode": "semantic_comparison_unsealed_clarification",
            "semantic_comparison_entities": list(preplan.get("entities") or []),
        },
        "skip_polish": True,
    }


def _semantic_pairwise_missing_criterion_result(
    rows: list[dict[str, Any]],
    entity_contracts: list[dict[str, Any]],
) -> dict[str, Any]:
    """Clarify a sealed pairwise purchase decision that lacks a criterion.

    The semantic plan has already established that the user wants one of two
    named products, but has not supplied a product field or suitability
    criterion.  Choosing from broad row text here would recreate the legacy
    rule-based comparator.  Keep both identities auditable and ask for the
    customer's actual priority instead.
    """
    candidate_skus = [
        str(row.get("sku") or "").strip().upper()
        for row in rows
        if str(row.get("sku") or "").strip()
    ]
    labels = [
        f"{str(row.get('product_name_cn') or row.get('product_name_en') or row.get('sku') or '').strip()}（{sku}）"
        for row, sku in zip(rows, candidate_skus)
    ]
    products_text = "、".join(label for label in labels if label) or "这两款商品"
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": (
            f"我已锁定你在比较的{products_text}，但还不知道你最在意的选择依据。"
            "请告诉我更看重容量、重量、使用场景或预算中的哪一项，我会只按各自同 SKU 的已标注资料帮你比较。"
        ),
        # The evidence may be insufficient for a winner, but the two sealed
        # participants are still valid conversation state.  Dropping them
        # here made the next turn lose the comparison context and ask the
        # customer to name the products again.
        "results": rows,
        "result_skus": candidate_skus,
        "candidate_skus": candidate_skus,
        "needs_clarification": True,
        "answer_metadata": {
            "source": "semantic_pairwise_missing_criterion_clarification",
            "evidence_status": "criterion_missing",
            "final_choice_sku": None,
        },
        "debug": {
            "agent_mode": "semantic_pairwise_missing_criterion_clarification",
            "entity_resolution_contracts": entity_contracts,
        },
        "skip_polish": True,
    }


def _semantic_pairwise_realtime_fields_result(
    rows: list[dict[str, Any]],
    entity_contracts: list[dict[str, Any]],
    field_types: list[str],
) -> dict[str, Any]:
    """Preserve a sealed realtime comparison instead of choosing on unrelated data."""
    canonical_fields = list(dict.fromkeys(
        str(field or "").strip()
        for field in field_types
        if str(field or "").strip()
    ))
    candidate_skus = [
        str(row.get("sku") or "").strip().upper()
        for row in rows
        if str(row.get("sku") or "").strip()
    ]
    labels = [
        f"{str(row.get('product_name_cn') or row.get('product_name_en') or row.get('sku') or '').strip()}（{sku}）"
        for row, sku in zip(rows, candidate_skus)
    ]
    products_text = "、".join(label for label in labels if label) or "这两款商品"
    if canonical_fields == ["price"]:
        answer = (
            f"我已锁定你在比较的{products_text}，但当前资料没有维护这两款的实时价格，"
            "因此不能判断哪款更便宜。请以同一平台、同一时间的实际售价和优惠为准。"
        )
    elif canonical_fields == ["inventory"]:
        answer = (
            f"我已锁定你在比较的{products_text}，但当前资料没有维护这两款的实时库存，"
            "因此不能判断哪款现货更充足。请以平台或店铺页面为准。"
        )
    else:
        field_labels = [
            customer_field_contract.product_detail_field_label(field) or field
            for field in canonical_fields
        ]
        answer = (
            f"我已锁定你在比较的{products_text}，但当前资料没有维护可核验的"
            f"{'、'.join(field_labels)}，因此不能据此指定其中一款。"
        )
    return {
        "intent": "compare_products",
        "answer_type": "comparison",
        "answer": answer,
        "results": rows,
        "result_skus": candidate_skus,
        "candidate_skus": candidate_skus,
        "sources": [],
        "answer_metadata": {
            "source": "semantic_pairwise_realtime_field_boundary",
            "contract_field_types": canonical_fields,
            "evidence_status": "realtime_source_unavailable",
            "final_choice_sku": None,
        },
        "debug": {
            "agent_mode": "semantic_pairwise_realtime_field_boundary",
            "field_contract": {
                "field_type": canonical_fields[0] if len(canonical_fields) == 1 else "",
                "canonical_fields": canonical_fields,
                "source": "validated_semantic_preplan",
            },
            "entity_resolution_contracts": entity_contracts,
        },
        "skip_polish": True,
    }




def _semantic_product_navigation_contract_result(
    db: Session,
    question: str,
    semantic_preplan: dict | None,
) -> dict | None:
    """Seal an LLM-identified product-navigation turn before storing an anchor."""
    preplan = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    # A semantic product_bound_qa with no requested field or evidence is a
    # conservative representation of navigation, not permission for legacy
    # generic retrieval.  The catalogue still seals the subject below.
    if str(preplan.get("route_family") or "") not in {"product_navigation", "product_bound_qa"}:
        return None
    if not _semantic_preplan_confident(preplan, minimum=0.9):
        return None
    if preplan.get("ambiguity") or preplan.get("evidence_required"):
        return None
    if preplan.get("canonical_fields") or preplan.get("field_type"):
        return None
    subject = str(preplan.get("subject_text") or "").strip()
    normalized_subject = customer_agent_service.normalize_search_text(subject)
    normalized_question = customer_agent_service.normalize_search_text(question)
    if not normalized_subject or normalized_subject not in normalized_question:
        return None
    products = db.query(Product).order_by(Product.sku.asc()).all()
    entity_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
        question,
        products,
        entity_text_override=subject,
    )
    decision = customer_entity_resolution_contract.can_resolve_single_product(entity_contract, products)
    if not decision.allowed or not decision.resolved_sku:
        candidate_skus = [str(item or "").strip().upper() for item in entity_contract.candidate_skus if str(item or "").strip()]
        candidate_rows = [
            item for item in products
            if str(item.sku or "").strip().upper() in candidate_skus
        ]
        if candidate_rows:
            labels = "、".join(
                f"{str(item.product_name_cn or item.product_name_en or item.sku).strip()}（{str(item.sku or '').strip().upper()}）"
                for item in candidate_rows[:6]
            )
            return {
                "answer": f"“{subject}”当前能对应多款商品：{labels}。请告诉我想看哪一款，我再继续介绍具体资料。",
                "intent": "clarification",
                "answer_type": "clarification",
                "confidence": "high",
                "uncertainty": "ambiguous_product",
                "needs_clarification": True,
                "sources": [{"type": "product", "label": "语义导航候选", "sku": str(item.sku or "").strip().upper()} for item in candidate_rows],
                "actions": [],
                "results": [{"sku": item.sku, "product_name_cn": item.product_name_cn, "category": item.category} for item in candidate_rows],
                "result_skus": [str(item.sku or "").strip().upper() for item in candidate_rows],
                "candidate_skus": [str(item.sku or "").strip().upper() for item in candidate_rows],
                "steps": [{"type": "entity_navigation_contract", "label": "请求选择商品", "detail": "语义主体对应多个真实候选", "ok": True}],
                "warnings": [],
                "evidence": [],
                "answer_metadata": {"source": "semantic_product_navigation_contract", "evidence_status": "ambiguous_navigation_identity"},
                "debug": {"agent_mode": "semantic_product_navigation_clarification", "entity_resolution_contract": entity_contract.to_dict()},
                "sku": None,
                "skip_polish": True,
            }
        return None
    product = next(
        (item for item in products if str(item.sku or "").strip().upper() == decision.resolved_sku),
        None,
    )
    if product is None:
        return None
    sku = str(product.sku or "").strip().upper()
    name = str(product.product_name_cn or product.product_name_en or sku).strip()
    return {
        "answer": f"已切换到{name}（{sku}）。你可以继续问它的材质、尺寸、重量、配件或使用方式。",
        "intent": "product_detail",
        "answer_type": "product_detail",
        "confidence": "high",
        "uncertainty": "confirmed",
        "needs_clarification": False,
        "sources": [{"type": "product", "label": "语义导航实体合同", "sku": sku}],
        "actions": [],
        "results": [{"sku": sku, "product_name_cn": product.product_name_cn, "category": product.category}],
        "result_skus": [sku],
        "candidate_skus": [sku],
        "steps": [{"type": "entity_navigation_contract", "label": "建立当前商品上下文", "detail": f"语义主体经实体合同解析为 {sku}", "ok": True}],
        "warnings": [],
        "evidence": [],
        "answer_metadata": {
            "source": "semantic_product_navigation_contract",
            "evidence_status": "sealed_navigation_identity",
            "evidence_sku": sku,
            "evidence_skus": [sku],
        },
        "debug": {
            "agent_mode": "semantic_product_navigation_contract",
            "entity_resolution_contract": entity_contract.to_dict(),
        },
        "sku": sku,
        "skip_polish": True,
    }




def _product_row_from_model(product: Product, specs: ProductSpecs | None = None, business: ProductBusiness | None = None, content: ProductContent | None = None) -> dict:
    raw_capacity = getattr(specs, "capacity", "") if specs else ""
    capacity_consistent = _capacity_evidence_is_internally_consistent(
        raw_capacity,
        " ".join(
            str(value or "")
            for value in (
                product.product_name_cn or product.product_name_en,
                getattr(specs, "technical_advantages", "") if specs else "",
                getattr(content, "long_description_cn", "") if content else "",
            )
        ),
    ) if raw_capacity else True
    return {
        "sku": product.sku,
        "barcode": product.barcode,
        "product_name_cn": product.product_name_cn,
        "product_name_en": product.product_name_en,
        "brand": product.brand,
        "series": product.series,
        "category": product.category,
        "sub_category": product.sub_category,
        "product_level": product.product_level,
        "launch_date": str(product.launch_date) if product.launch_date else "",
        "lifecycle_status": product.lifecycle_status,
        "capacity": raw_capacity if capacity_consistent else "",
        "capacity_evidence_conflict": not capacity_consistent,
        "size_info": getattr(specs, "size_info", "") if specs else "",
        "power": getattr(specs, "power", "") if specs else "",
        "heat_source": getattr(specs, "heat_source", "") if specs else "",
        "body_material": getattr(specs, "body_material", "") if specs else "",
        "surface_finish": getattr(specs, "surface_finish", "") if specs else "",
        "color": getattr(specs, "color", "") if specs else "",
        "usage_instruction": getattr(specs, "usage_instruction", "") if specs else "",
        "gross_weight_g": getattr(specs, "gross_weight_g", 0) if specs else 0,
        "features": getattr(specs, "technical_advantages", "") if specs else "",
        "usage_scenarios": getattr(business, "usage_scenarios", "") if business else "",
        "target_audience": getattr(business, "target_audience", "") if business else "",
        "positioning": getattr(business, "positioning", "") if business else "",
        "top_selling_points": getattr(business, "top_selling_points", "") if business else "",
        "price_positioning": getattr(business, "price_positioning", "") if business else "",
        # These customer-facing content columns are not independently used as
        # catalogue predicates.  They let the value-scope executor prove that
        # a customer-provided multilingual collection name occurs on the same
        # product row as one formal catalogue value.
        "title_cn": getattr(content, "title_cn", "") if content else "",
        "title_en": getattr(content, "title_en", "") if content else "",
        "website_title": getattr(content, "website_title", "") if content else "",
        "amazon_title": getattr(content, "amazon_title", "") if content else "",
        "long_description_en": getattr(content, "long_description_en", "") if content else "",
        "long_description_cn": getattr(content, "long_description_cn", "") if content else "",
    }


def _phase1_product_bundle_by_ref(db: Session, product_ref: str) -> tuple[Product | None, ProductSpecs | None, ProductBusiness | None, ProductContent | None]:
    ref = str(product_ref or "").strip()
    if not ref:
        return None, None, None, None
    exact_sku_value = _resolve_exact_sku_variant(db, ref) or ref.upper()
    exact_sku = db.query(Product).filter(Product.sku == exact_sku_value).first()
    if exact_sku:
        specs = db.query(ProductSpecs).filter(ProductSpecs.product_id == exact_sku.id).first()
        business = db.query(ProductBusiness).filter(ProductBusiness.product_id == exact_sku.id).first()
        content = db.query(ProductContent).filter(ProductContent.product_id == exact_sku.id).first()
        return exact_sku, specs, business, content
    product = (
        db.query(Product)
        .filter(
            (Product.product_name_cn == ref)
            | (Product.product_name_cn.contains(ref))
            | (Product.product_name_en.contains(ref))
            | (Product.sku == ref.upper())
        )
        .order_by(Product.sku.asc())
        .first()
    )
    if not product:
        return None, None, None, None
    specs = db.query(ProductSpecs).filter(ProductSpecs.product_id == product.id).first()
    business = db.query(ProductBusiness).filter(ProductBusiness.product_id == product.id).first()
    content = db.query(ProductContent).filter(ProductContent.product_id == product.id).first()
    return product, specs, business, content


def _field_display_value(requested_field: str, value: Any) -> str:
    """Remove a duplicated leading label without rewriting evidence content."""
    display = str(value or "").strip().rstrip("。.!！?？：:")
    label = str(requested_field or "").strip()
    if not display or not label:
        return display
    return re.sub(
        rf"^{re.escape(label)}(?:包括|有|是)?\s*[：:]\s*",
        "",
        display,
        count=1,
    ).strip()


def _dimension_missing_display_label(dimension_subtype: str | None, requested_field: str) -> str:
    """Keep a missing dimension answer scoped to the customer's component noun."""
    return {
        "expanded": "展开尺寸",
        "storage": "收纳尺寸",
        "package": "包装尺寸",
        "fuel_holder": "装酒精/木炭的燃料仓尺寸",
    }.get(dimension_subtype, requested_field)


def _phase1_product_field_result(db: Session, plan: dict) -> dict | None:
    product_ref = str(plan.get("product_ref") or "").strip()
    explicit_sku = str(plan.get("sku") or "").strip().upper()
    requested_field = str(plan.get("requested_field") or "").strip()
    raw_question = str(plan.get("raw_question") or "").strip()
    # Duration and fuel-efficiency questions are product QA, not heat-source
    # field reads.  A semantic/legacy planner may label a gas-related sentence
    # as ``热源``; defer it so the bounded duration path can answer (or state
    # that no duration evidence exists) instead of returning an unrelated
    # missing heat-source field.
    if customer_agent_intent_service._detect_usage_care_subtype(raw_question) in {"duration", "power_tradeoff"}:
        return None
    field_contract = customer_field_contract.detect_field_contract(raw_question)
    # “推荐哪种” without a field is still an underspecified catalogue
    # recommendation, but a formal field phrase such as “推荐用什么燃料” is a
    # product-bound fact request when the caller already sealed the SKU.
    if customer_agent_runtime_service._is_underspecified_recommendation_question(raw_question) and not field_contract:
        return None
    explicit_field_override = str(plan.get("field_type_override") or "").strip()
    # The question's deterministic FieldContract is authoritative over a
    # compatibility planner label.  Otherwise a broad legacy label such as
    # dimensions can turn a formal specification request into a different
    # safe-missing answer.
    canonical_field = (
        explicit_field_override
        if customer_field_contract.is_supported_detail_field(explicit_field_override)
        else field_contract.field_type if field_contract else
        customer_field_contract.field_type_from_detail_label(requested_field)
    )
    canonical_label = customer_field_contract.product_detail_field_label(canonical_field)
    if canonical_label:
        requested_field = canonical_label
        plan["requested_field"] = requested_field
    if requested_field == "适用场景":
        canonical_field = "usage_scene"
    resolved_ref = (
        _resolve_exact_sku_variant(db, explicit_sku or product_ref or raw_question)
        or explicit_sku
        or _resolve_sku(db, raw_question or product_ref, product_ref or None)
        or _resolve_sku(db, product_ref, None)
        or product_ref
    )
    if resolved_ref:
        plan["product_ref"] = resolved_ref
        plan["sku"] = resolved_ref
    product, specs, business, content = _phase1_product_bundle_by_ref(db, resolved_ref)
    identity_source = str(plan.get("product_identity_source") or "").strip() or None
    sealed_entity_contract = None
    initial_identity_decision = (
        customer_entity_resolution_contract.can_trust_bound_product_identity(
            product=product,
            sku=resolved_ref,
            identity_source=identity_source,
        )
        if product
        else None
    )
    # A weak planner reference may be repaired by a direct canonical name in
    # the question. Once a trusted upstream identity contract has sealed a
    # SKU, however, this evidence provider must consume that SKU and must not
    # independently re-resolve the raw question to another product.
    if (
        canonical_field
        and raw_question
        and not bool(initial_identity_decision and initial_identity_decision.allowed)
    ):
        # The legacy field executor may receive only a weak planner reference.
        # Repair it through the same sealed EntityResolutionContract used by
        # Phase 2, never by a first fuzzy database row.  This also permits a
        # field-specific safe-missing answer for an exact named product whose
        # requested column has no valid value.
        all_products = db.query(Product).order_by(Product.sku.asc()).all()
        question_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
            raw_question,
            all_products,
            field_type_override=canonical_field,
        )
        resolution = customer_entity_resolution_contract.can_resolve_single_product(
            question_contract,
            all_products,
        )
        if resolution.allowed and resolution.resolved_sku:
            sealed_entity_contract = question_contract
            product, specs, business, content = _phase1_product_bundle_by_ref(db, resolution.resolved_sku)
            resolved_ref = resolution.resolved_sku
            plan["product_ref"] = resolved_ref
            plan["sku"] = resolved_ref
            plan["entity_resolution_contract"] = question_contract.to_dict()
    if product:
        identity_decision = customer_entity_resolution_contract.can_trust_bound_product_identity(
            product=product,
            sku=resolved_ref,
            entity_contract=sealed_entity_contract,
            identity_source=identity_source,
        )
        if not identity_decision.allowed:
            return {
                "intent": "clarify",
                "answer_type": "clarification",
                "answer": f"我还不能把“{product_ref}”稳定定位到唯一商品。请补充 SKU 或更完整的商品名。",
                "results": [],
                "result_skus": [],
                "candidate_skus": [],
                "needs_clarification": True,
                "answer_metadata": {"source": "entity_strength_gate_clarification"},
                "debug": {
                    "agent_mode": "entity_strength_gate_clarification",
                    "bound_product_identity_decision": identity_decision.to_dict(),
                },
                "skip_polish": True,
            }
    if not product:
        return {
            "intent": "product_detail",
            "answer_type": "product_detail",
            "answer": f"当前资料中暂未标注{resolved_ref}的{requested_field}。",
            "results": [],
            "result_skus": [],
            "answer_metadata": {"answer_policy": "field_only_missing"},
            "debug": {"agent_mode": "planner_product_field"},
            "skip_polish": True,
        }
    # Structured product fields are authoritative.  Same-SKU QA remains a
    # field-compatible fallback below when the validated database provider is
    # empty; an exact wording match alone must not replace a formal field.
    value = ""
    evidence_source = None
    evidence_scope = "subject"
    dimension_evidence = None
    dimension_subtype = (
        customer_field_contract.requested_dimension_subtype(raw_question)
        if canonical_field == "dimensions"
        else None
    )
    cleaning_subtype = (
        customer_field_contract.requested_cleaning_subtype(raw_question)
        if canonical_field == "cleaning"
        else None
    )
    usage_instruction_subtype = (
        customer_field_contract.requested_usage_instruction_subtype(raw_question)
        if canonical_field == "usage_instruction"
        else None
    )
    content_subtype = _content_field_evidence_subtype(raw_question, canonical_field)
    if canonical_field == "accessories":
        accessories_qa = _best_product_qa_match(
            db,
            product,
            raw_question or requested_field,
            requested_field_type="accessories",
        )
        value = str(getattr(accessories_qa, "answer", "") or "").strip()
        evidence_source = f"product_qa:{accessories_qa.id}" if accessories_qa and value else None
    elif requested_field == "SKU":
        value = str(product.sku or "").strip().upper()
        evidence_source = "product.sku"
    elif requested_field == "尺寸":
        dimension_evidence = customer_field_contract.select_dimension_evidence(
            getattr(specs, "size_info", "") if specs else "",
            requested_scope=customer_field_contract.requested_evidence_scope(raw_question, "dimensions"),
            requested_subtype=customer_field_contract.requested_dimension_subtype(raw_question),
        )
        value = dimension_evidence.value if dimension_evidence else ""
        evidence_source = "specs.size_info" if dimension_evidence else None
        evidence_scope = dimension_evidence.scope if dimension_evidence else customer_field_contract.requested_evidence_scope(raw_question, "dimensions")
        if value in {"", "[]", "/"}:
            value = ""
    elif requested_field == "容量":
        value = _capacity_field_evidence(getattr(specs, "capacity", "") if specs else "")
        evidence_source = "specs.capacity" if value else None
    elif requested_field == "重量":
        weight = getattr(specs, "gross_weight_g", None)
        # Keep this older phase-one path on the same validated formatter as
        # the central structured-evidence provider.  A database float such as
        # 150.0 is a gram value, not a customer-facing precision claim.
        value = _weight_field_evidence(weight, capacity=getattr(specs, "capacity", "") if specs else "")
        evidence_source = "specs.gross_weight_g" if value else None
    elif requested_field == "材质":
        value = str(getattr(specs, "body_material", "") or "").strip()
        evidence_source = "specs.body_material" if value else None
        if value in {"", "[]", "/"}:
            value = ""
    elif requested_field == "颜色":
        value = _color_field_evidence(getattr(specs, "color", "") if specs else "")
        evidence_source = "specs.color" if value else None
    elif canonical_field == "usage_scene":
        value = _compound_display_value(getattr(business, "usage_scenarios", "") if business else "")
        evidence_source = "business.usage_scenarios" if value else None
    # Structured product fields are authoritative. A same-SKU QA entry that
    # passes the canonical field policy is only a fallback when the structured
    # provider is missing or fails its semantic validation.
    if not value and canonical_field in {"usage_instruction", "cleaning", "care"}:
        value, evidence_source = _structured_product_field_evidence(
            canonical_field,
            db=db,
            product=product,
            specs=specs,
            business=business,
            content=content,
            requested_subtype=content_subtype or usage_instruction_subtype or cleaning_subtype,
        )
    if not value and canonical_field and canonical_field not in {
        "dimensions",
        "people",
        "dishwasher",
        "heat_source",
        "accessories",
    }:
        value, evidence_source = _structured_product_field_evidence(
            canonical_field,
            db=db,
            product=product,
            specs=specs,
            business=business,
            content=content,
            requested_subtype=content_subtype or usage_instruction_subtype or cleaning_subtype,
        )
    if not value and canonical_field:
        qa_evidence = _best_product_qa_match(
            db,
            product,
            raw_question or requested_field,
            requested_field_type=canonical_field,
            # The FieldContract already fixed the customer field and the
            # EntityResolutionContract already fixed this SKU.  Restrict the
            # fallback to request-side QA text (question/tags), so natural
            # wording such as a platform-purchase question can use a
            # field-compatible same-SKU QA without answer-body keyword drift.
            semantic_query=raw_question or requested_field,
        )
        qa_value = str(getattr(qa_evidence, "answer", "") or "").strip()
        if canonical_field == "dimensions" and qa_value and dimension_subtype:
            qa_subtype = customer_field_contract.requested_dimension_subtype(
                " ".join((
                    str(getattr(qa_evidence, "question", "") or ""),
                    str(getattr(qa_evidence, "tags", "") or ""),
                ))
            )
            if qa_subtype != dimension_subtype:
                qa_value = ""
        if canonical_field in {"usage_instruction", "cleaning", "care"} and qa_value:
            if not _usage_instruction_matches_product(product, qa_value):
                qa_value = ""
            elif canonical_field == "cleaning" and cleaning_subtype == "machine_wash":
                qa_value = _machine_wash_specific_evidence(qa_value)
            elif canonical_field == "usage_instruction" and usage_instruction_subtype == "liquid_temperature_capability":
                qa_value = _liquid_temperature_capability_evidence(qa_value)
        if qa_value:
            value = qa_value
            evidence_source = f"product_qa:{qa_evidence.id}"
            evidence_scope = "subject"
    if not value and canonical_field and canonical_field not in {
        "dimensions",
        "people",
        "dishwasher",
        "heat_source",
        "accessories",
    }:
        value, evidence_source = _structured_product_field_evidence(
            canonical_field,
            db=db,
            product=product,
            specs=specs,
            business=business,
            content=content,
            requested_subtype=content_subtype or usage_instruction_subtype or cleaning_subtype,
        )
    row = _product_row_from_model(product, specs, business, content)
    evidence_value = value
    capacity_conflict = (
        _capacity_evidence_conflict(product.product_name_cn, value)
        if requested_field == "容量" and value
        else None
    )
    color_conflict = (
        _color_evidence_conflict(product.product_name_cn, value)
        if requested_field == "颜色" and value
        else None
    )
    # Product-detail callers may provide either the display label ("热源")
    # or the canonical FieldContract type ("heat_source").  Evidence routing
    # must follow the contract, not the incidental display representation;
    # otherwise a sealed EntityResolutionContract skips its own same-SKU
    # structured heat-source evidence and falsely reports it as missing.
    if canonical_field == "heat_source":
        if not str(row.get("heat_source") or "").strip():
            merged_detail = product_service.get_product_detail(db, product.sku)
            merged_specs = merged_detail.get("specs") if isinstance(merged_detail, dict) else {}
            merged_heat_source = str((merged_specs or {}).get("heat_source") or "").strip()
            if merged_heat_source:
                row["heat_source"] = merged_heat_source
        if str(row.get("heat_source") or "").strip():
            evidence_source = "specs.heat_source"
        heat_source_evidence: dict[str, Any] = {}
        answer, evidence_status = _phase1_heat_source_capability_answer(
            db,
            row,
            raw_question or requested_field,
            evidence_metadata=heat_source_evidence,
        )
        evidence_value = str(heat_source_evidence.get("evidence_value") or "").strip()
        evidence_source = heat_source_evidence.get("evidence_source") or evidence_source
        evidence_scope = heat_source_evidence.get("evidence_scope") or evidence_scope
        if str(evidence_source or "").startswith("product_qa:"):
            evidence_source = "product_qa"
    elif requested_field == "适用人数":
        people_evidence: dict[str, Any] = {}
        answer = _phase1_people_capacity_answer(row, evidence_metadata=people_evidence)
        evidence_value = str(people_evidence.get("evidence_value") or "").strip()
        evidence_source = people_evidence.get("evidence_source")
        evidence_scope = people_evidence.get("evidence_scope") or evidence_scope
        evidence_status = "structured" if evidence_value else "missing"
    elif requested_field == "洗碗机适配":
        instruction = str(getattr(specs, "usage_instruction", "") or "").strip()
        dishwasher_evidence = (
            value
            if value and str(evidence_source or "").startswith("product_qa:")
            else _dishwasher_specific_evidence(instruction)
        )
        if dishwasher_evidence:
            evidence_value = dishwasher_evidence
            evidence_source = evidence_source or "specs.usage_instruction"
            answer = f"{product.product_name_cn}（{product.sku}）的洗碗机适配资料：{dishwasher_evidence}。"
            evidence_status = "structured"
        else:
            evidence_value = ""
            evidence_source = None
            answer = f"{product.product_name_cn}（{product.sku}）当前资料未标注，未明确说明是否可放入洗碗机。"
            evidence_status = "missing"
    elif capacity_conflict:
        name_capacity, structured_capacity = capacity_conflict
        answer = (
            f"{product.product_name_cn}（{product.sku}）的容量资料存在冲突："
            f"商品名称标注{name_capacity}，规格字段记录{structured_capacity}；"
            "当前无法确认准确容量，请以官方页面或人工核实结果为准。"
        )
        evidence_value = ""
        evidence_source = None
        evidence_status = "conflict"
    elif color_conflict:
        name_color, structured_color = color_conflict
        answer = (
            f"{product.product_name_cn}（{product.sku}）的颜色资料存在冲突："
            f"商品名称标注{name_color}，规格字段记录{structured_color}；"
            "当前无法确认准确颜色，请以官方页面或人工核实结果为准。"
        )
        evidence_value = ""
        evidence_source = None
        evidence_status = "conflict"
    elif value:
        if requested_field == "尺寸" and dimension_evidence is not None:
            display_value = dimension_evidence.value.replace("*", "×")
            display_unit = f" {dimension_evidence.unit}" if dimension_evidence.unit else ""
            if dimension_evidence.is_generic_fallback and dimension_subtype not in {"expanded", "storage", "package"}:
                answer = (
                    f"当前资料未单独维护{product.product_name_cn}（{product.sku}）的产品本体尺寸；"
                    f"仅记录了{dimension_evidence.label}：{display_value}{display_unit}。"
                )
            else:
                answer = (
                    f"{product.product_name_cn}（{product.sku}）的{dimension_evidence.label or requested_field}："
                    f"{display_value}{display_unit}。"
                )
        else:
            display_value = _field_display_value(requested_field, value)
            if requested_field == "核心卖点":
                display_value = re.sub(
                    rf"^(?:{re.escape(str(product.product_name_cn or '').strip())}的)?核心卖点(?:包括|有|是)?[：:]\s*",
                    "",
                    display_value,
                ).strip()
            answer = f"{product.product_name_cn}（{product.sku}）的{requested_field}：{display_value}。"
        evidence_status = "structured"
    else:
        dimension_missing_label = _dimension_missing_display_label(dimension_subtype, requested_field)
        if canonical_field == "cleaning" and cleaning_subtype == "machine_wash":
            answer = f"当前资料未明确标注{product.product_name_cn}（{product.sku}）是否可以用洗衣机机洗。"
        elif canonical_field == "cleaning":
            answer = (
                f"当前同 SKU 资料中暂未找到{product.product_name_cn}（{product.sku}）的具体清洁说明，"
                "暂时无法确认清洁步骤；建议以产品说明书或人工客服核对结果为准。"
            )
        elif canonical_field == "usage_instruction" and usage_instruction_subtype == "liquid_temperature_capability":
            answer = f"{product.product_name_cn}（{product.sku}）：当前资料未直接标明是否可以装热水、冷水或开水。"
        elif canonical_field == "accessories":
            answer = (
                f"{product.product_name_cn}（{product.sku}）：当前资料未标注套装包含内容、"
                "包装清单或具体配件，无法确认具体清单。"
            )
        else:
            answer = (
                f"\u5f53\u524d\u8d44\u6599\u4e2d\u6682\u672a\u627e\u5230"
                f"{product.product_name_cn}\uff08{product.sku}\uff09\u7684{dimension_missing_label}\u3002"
            )
        evidence_status = "missing"
    return {
        "intent": "product_detail",
        "answer_type": "product_detail",
        "sku": product.sku,
        "answer": answer,
        "results": [row],
        "result_skus": [product.sku],
        "candidate_skus": [product.sku],
        "answer_metadata": {
            "answer_policy": "field_only",
            "requested_field": canonical_field or requested_field,
            "requested_field_label": requested_field,
            "evidence_status": evidence_status,
            "evidence_field": canonical_field if evidence_value else None,
            "evidence_source": evidence_source,
            "evidence_value": evidence_value,
            "evidence_scope": evidence_scope if evidence_value else None,
            "evidence_sku": product.sku if evidence_value else None,
            "evidence_label": dimension_evidence.label if dimension_evidence else None,
            "evidence_unit": dimension_evidence.unit if dimension_evidence else None,
            "evidence_subtype": dimension_evidence.subtype if dimension_evidence else dimension_subtype or cleaning_subtype,
            "dimension_generic_fallback": dimension_evidence.is_generic_fallback if dimension_evidence else False,
            "field_evidence_match": bool(canonical_field and evidence_value),
            "field_evidence_missing": bool(canonical_field and not evidence_value),
        },
        "debug": {
            "agent_mode": "planner_product_compatibility" if requested_field == "heat_source" else "planner_product_field",
            "plan": {
                "primary_intent": "product_field",
                "product_ref": product.sku,
                "requested_field": requested_field,
                "raw_question": raw_question or requested_field,
            },
            "raw_results": [row],
            "candidate_skus": [product.sku],
        },
        "skip_polish": True,
    }


def _phase1_alcohol_stove_compatibility_answer(
    db: Session,
    row: dict,
    *,
    evidence_metadata: dict[str, Any] | None = None,
) -> tuple[str, str]:
    name = str(row.get("product_name_cn") or row.get("product_name_en") or row.get("sku") or "该产品").strip()
    sku = str(row.get("sku") or "").strip().upper()
    category = str(row.get("category") or "").strip()
    heat_source = _heat_source_field_evidence(row.get("heat_source"))
    normalized_heat_source = "" if heat_source in {"", "/", "[]"} else heat_source
    if not normalized_heat_source and not any(term in category for term in ("锅", "炉", "壶", "酒具", "咖啡")):
        return f"{name}（{sku}）不是炉具或炊具，当前资料也未标注适用酒精炉；不建议按酒精炉适配产品理解。", "not_applicable"
    def _capability_evidence_status(value: str) -> str | None:
        text_value = str(value or "").strip().lower()
        if not text_value:
            return None
        if re.search(r"(?:未(?:标注|显示|找到)|没有|暂无).{0,20}(?:支持|适用|可用).{0,8}(酒精炉|alcohol stove)", text_value):
            return "not_listed"
        if re.search(r"(不支持|不适合|不建议|不能|不可).{0,8}(酒精炉|alcohol stove)", text_value):
            return "unsupported"
        if any(term in text_value for term in ("液体酒精", "工业酒精", "alcohol fuel")):
            return "supported"
        verdict = customer_agent_intent_service._alcohol_stove_support_verdict(text_value)
        if verdict is True:
            return "supported"
        if verdict is False:
            return "unsupported"
        return None

    evidence_status = _capability_evidence_status(normalized_heat_source)
    evidence = ""
    if normalized_heat_source and evidence_metadata is not None:
        evidence_metadata.update({
            "evidence_value": normalized_heat_source,
            "evidence_source": "specs.heat_source",
            "evidence_scope": "subject",
            "evidence_sku": sku,
        })
    if evidence_status is None and sku:
        evidence = str(customer_agent_intent_service._best_same_sku_evidence_text(
            db,
            sku=sku,
            supporting=None,
            term_groups=[("酒精炉", "alcohol stove")],
        ) or "").strip()
        evidence_status = _capability_evidence_status(evidence)
        if evidence and evidence_metadata is not None:
            evidence_metadata.update({
                "evidence_value": evidence,
                "evidence_source": "product_qa",
                "evidence_scope": "subject",
                "evidence_sku": sku,
            })
    if evidence_status == "supported":
        source_text = evidence or normalized_heat_source
        return f"{name}（{sku}）当前资料显示支持酒精炉；适用热源/同 SKU 证据为：{source_text}。", "supported"
    if evidence_status == "unsupported":
        return f"{name}（{sku}）当前资料显示不支持酒精炉；相关证据为：{evidence or normalized_heat_source}。", "unsupported"
    if normalized_heat_source or evidence_status == "not_listed":
        return f"{name}（{sku}）当前资料显示适用热源为：{normalized_heat_source}；当前资料未显示支持酒精炉。", "not_listed"
    return f"当前资料里没有找到{name}（{sku}）是否支持酒精炉的明确说明。", "missing"


def _same_sku_usage_instruction_heat_source_boundary(
    usage_instruction: Any,
    *,
    asked_capability: str,
    asks_direct_heating: bool,
) -> str:
    """Return an explicit negative heat-source boundary from same-SKU instructions.

    ``usage_instruction`` is not a general heat-source provider.  It is used
    here only when one complete source sentence directly negates the specific
    heat source or direct-heating operation in the customer's question.
    """
    text = str(usage_instruction or "").strip()
    if not text or text in {"[]", "/", "暂无", "未标注"}:
        return ""
    capability_terms = {
        "卡式炉": ("卡式炉",),
        "燃气炉": ("燃气炉", "气炉", "卡式炉"),
        "气炉": ("气炉", "燃气炉", "卡式炉"),
        "明火直烧": ("明火直烧", "明火"),
        "明火": ("明火", "明火直烧"),
        "分体炉": ("分体炉",),
        "一体炉": ("一体炉",),
        "电磁炉": ("电磁炉",),
        "电陶炉": ("电陶炉",),
        "电热炉": ("电热炉",),
        "电炉": ("电炉", "电磁炉", "电陶炉", "电热炉"),
    }.get(asked_capability, ())
    negative_markers = ("不可", "不能", "不建议", "严禁", "禁止")
    for sentence in re.split(r"(?<=[。！？!?；;])\s*", text):
        for clause in re.split(r"(?<=[，,])\s*", sentence):
            candidate = re.sub(r"\s+", " ", clause).strip()
            if not candidate or not any(marker in candidate for marker in negative_markers):
                continue
            directly_names_capability = bool(capability_terms and any(term in candidate for term in capability_terms))
            directly_names_operation = asks_direct_heating and any(
                term in candidate for term in ("直接加热", "直接置于", "直接放", "明火上加热")
            )
            if directly_names_capability or directly_names_operation:
                return candidate.rstrip("。；; ")
    return ""


def _requested_fuel_capabilities(text: str) -> list[str]:
    """Extract all explicit fuel/heat-source alternatives from one turn.

    This is a small ontology for fuel *wording*, not a product/SKU rule.  It
    keeps a choice such as ``液体还是固体`` from being truncated to the first
    token and deliberately ignores a bare ``酒精炉`` category noun.
    """
    value = str(text or "").strip()
    if not value:
        return []
    action_markers = (
        "能烧", "可以烧", "能用", "可以用", "支持", "适配", "兼容", "能否", "可不可以",
        "可以吗", "能吗", "适合吗", "只能用", "用什么", "使用", "还是", "推荐用", "选择",
    )
    if not any(marker in value for marker in action_markers):
        return []
    requested: list[str] = []

    def add(label: str) -> None:
        if label not in requested:
            requested.append(label)

    electric_aliases = (
        ("电磁炉", ("电磁炉", "电池炉")),
        ("电陶炉", ("电陶炉",)),
        ("电热炉", ("电热炉",)),
        ("电炉", ("电炉",)),
    )
    for label, aliases in electric_aliases:
        if any(alias in value for alias in aliases):
            add(label)
    canister_subtypes = (
        ("液化气罐", ("液化气罐", "液化气瓶")),
        ("高山气罐", ("高山气罐", "高山罐")),
        ("卡式气罐", ("卡式气罐", "卡式罐", "长罐")),
        ("扁罐", ("扁罐",)),
    )
    for label, aliases in canister_subtypes:
        if any(alias in value for alias in aliases):
            add(label)
    if any(term in value for term in ("固体酒精", "固态酒精", "酒精块", "固体燃料")) or (
        "固体" in value and "酒精" in value
    ):
        add("固体酒精")
    if "液体酒精" in value or ("液体" in value and "酒精" in value):
        add("液体酒精")
    if any(term in value for term in ("木炭", "炭火", "炭烧", "烧炭", "碳火", "碳烧", "速燃碳")):
        add("木炭")
    if "柴火" in value:
        add("柴火")
    if "煤炭" in value:
        add("煤炭")
    if not requested and "酒精" in value and "酒精炉" not in value:
        add("酒精")
    return requested


def _looks_like_fuel_choice_question(text: str) -> bool:
    """Whether the customer explicitly asks to choose between fuel types."""
    value = str(text or "").strip()
    requested = _requested_fuel_capabilities(value)
    return len(requested) >= 2 and any(term in value for term in ("还是", "选择", "哪个", "推荐", "怎么选"))


def _requested_fuel_capability(text: str) -> str:
    """Extract the first explicit fuel subtype without treating heat words as proof."""
    value = str(text or "").strip()
    requested = _requested_fuel_capabilities(value)
    if requested:
        return requested[0]
    action_markers = ("能烧", "可以烧", "能用", "可以用", "支持", "适配", "兼容", "能否", "可不可以", "使用")
    if "酒精炉" in value and any(marker in value for marker in action_markers):
        return "酒精炉"
    if "酒精" in value and any(marker in value for marker in action_markers):
        return "酒精"
    return ""


def _phase1_fuel_capability_answer(
    row: dict,
    question: str,
    *,
    asked_fuel: str,
    evidence_metadata: dict[str, Any] | None = None,
) -> tuple[str, str]:
    """Answer an explicit fuel-subtype question from the same-SKU heat field."""
    name = str(row.get("product_name_cn") or row.get("product_name_en") or row.get("sku") or "该产品").strip()
    sku = str(row.get("sku") or "").strip().upper()
    prefix = f"{name}（{sku}）" if name else sku
    heat_source = _heat_source_field_evidence(row.get("heat_source"))
    normalized_heat_source = "" if heat_source in {"", "/", "[]", "暂无", "未标注"} else heat_source
    if normalized_heat_source and evidence_metadata is not None:
        evidence_metadata.update({
            "evidence_value": normalized_heat_source,
            "evidence_source": "specs.heat_source",
            "evidence_scope": "subject",
            "evidence_sku": sku,
        })
    if not normalized_heat_source:
        return f"{prefix}：当前资料未标注适用热源；是否支持{asked_fuel}，不能仅凭现有资料确认。", "missing"

    source_lower = normalized_heat_source.lower()
    fuel_aliases = {
        "固体酒精": ("固体酒精", "固态酒精", "酒精块", "固体燃料"),
        "液体酒精": ("液体酒精",),
        "木炭": ("木炭", "炭火", "炭烧", "烧炭", "碳火", "碳烧", "速燃碳"),
        "柴火": ("柴火",),
        "煤炭": ("煤炭",),
        "酒精": ("酒精", "alcohol"),
        "电磁炉": ("电磁炉", "电池炉"),
        "电陶炉": ("电陶炉",),
        "电热炉": ("电热炉",),
        "电炉": ("电炉", "电磁炉", "电陶炉", "电热炉", "电池炉"),
        "液化气罐": ("液化气罐", "液化气瓶"),
        "高山气罐": ("高山气罐", "高山罐"),
        "卡式气罐": ("卡式气罐", "卡式罐", "长罐"),
        "扁罐": ("扁罐",),
    }
    canister_labels = {"液化气罐", "高山气罐", "卡式气罐", "扁罐"}
    if asked_fuel in canister_labels:
        supported = any(term in normalized_heat_source for term in fuel_aliases[asked_fuel])
        if supported:
            return (
                f"{prefix}：兼容性结论：当前资料明确标注支持{asked_fuel}；适用热源为{normalized_heat_source}。",
                "supported",
            )
        return (
            f"{prefix}：兼容性结论：当前资料只标注适用热源为{normalized_heat_source}，"
            f"未标注{asked_fuel}的接口或具体罐型，无法确认{asked_fuel}也可以用。",
            "missing",
        )
    if asked_fuel == "酒精":
        supported = any(term in normalized_heat_source or term in source_lower for term in fuel_aliases["酒精"])
    elif asked_fuel in {"固体酒精", "液体酒精"}:
        # A generic “酒精炉” label does not establish whether the fuel is
        # solid or liquid.  Require the requested subtype itself.
        supported = any(term in normalized_heat_source for term in fuel_aliases[asked_fuel])
    else:
        # Charcoal/wood are not synonyms for the broad “明火” label.  Require
        # the explicit fuel wording to avoid silently substituting heat sources.
        supported = any(term in normalized_heat_source for term in fuel_aliases.get(asked_fuel, (asked_fuel,)))
    if supported:
        return f"{prefix}：当前资料显示支持{asked_fuel}；适用热源为{normalized_heat_source}。", "supported"
    return f"{prefix}：当前资料未显示支持{asked_fuel}；当前资料显示适用热源为{normalized_heat_source}。", "not_listed"


def _phase1_multi_fuel_capability_answer(
    row: dict,
    question: str,
    *,
    asked_fuels: list[str],
    evidence_metadata: dict[str, Any] | None = None,
) -> tuple[str, str]:
    """Answer every explicitly named fuel alternative from the same SKU."""
    name = str(row.get("product_name_cn") or row.get("product_name_en") or row.get("sku") or "该产品").strip()
    sku = str(row.get("sku") or "").strip().upper()
    prefix = f"{name}（{sku}）" if name else sku
    electric_labels = {"电磁炉", "电陶炉", "电热炉", "电炉"}
    conclusion_label = "热源选择结论" if any(fuel in electric_labels for fuel in asked_fuels) else "燃料选择结论"
    lines = [f"{prefix}：{conclusion_label}："]
    statuses: list[str] = []
    for fuel in asked_fuels:
        one, status = _phase1_fuel_capability_answer(
            row,
            question,
            asked_fuel=fuel,
            evidence_metadata=evidence_metadata,
        )
        body = one[len(prefix):].lstrip("：: ") if prefix and one.startswith(prefix) else one
        lines.append(f"- {fuel}：{body}")
        statuses.append(status)
    if any(status == "supported" for status in statuses) and any(status != "supported" for status in statuses):
        lines.append("按当前同 SKU 资料，只能把明确标注支持的燃料作为已核验选项；未标注或未显示支持的燃料不能直接当作替代。")
        supported_labels = [fuel for fuel, status in zip(asked_fuels, statuses) if status == "supported"]
        lines.append(f"结论：当前只建议选择资料明确标注支持的{'、'.join(supported_labels)}；其他选项不建议替代。")
    elif not any(status == "supported" for status in statuses):
        lines.append("当前资料没有把这些燃料都核验为可用，不能仅凭明火或酒精炉类别替代判断。")
        lines.append("结论：当前没有核验出其中任何一种可用，不建议仅凭现有资料任选其一；请按说明书或提供 SKU 再确认。")
    else:
        lines.append("结论：当前资料明确核验支持这些选项；实际选择仍应以对应燃料说明书和使用环境为准。")
    return "\n".join(lines), ("supported" if all(status == "supported" for status in statuses) else "not_listed")


def _phase1_heat_source_capability_answer(
    db: Session,
    row: dict,
    question: str,
    *,
    evidence_metadata: dict[str, Any] | None = None,
) -> tuple[str, str]:
    text = str(question or "").strip()
    identity_free_text = text
    for identity in (
        row.get("product_name_cn"),
        row.get("product_name_en"),
        row.get("sku"),
    ):
        identity_text = str(identity or "").strip()
        if identity_text:
            identity_free_text = re.sub(re.escape(identity_text), "", identity_free_text, flags=re.IGNORECASE)
    asked_fuels = _requested_fuel_capabilities(identity_free_text)
    if len(asked_fuels) >= 2:
        return _phase1_multi_fuel_capability_answer(
            row,
            text,
            asked_fuels=asked_fuels,
            evidence_metadata=evidence_metadata,
        )
    asked_fuel = asked_fuels[0] if asked_fuels else _requested_fuel_capability(identity_free_text)
    if asked_fuel == "酒精炉":
        return _phase1_alcohol_stove_compatibility_answer(
            db,
            row,
            evidence_metadata=evidence_metadata,
        )
    if asked_fuel:
        return _phase1_fuel_capability_answer(
            row,
            text,
            asked_fuel=asked_fuel,
            evidence_metadata=evidence_metadata,
        )
    if any(term in identity_free_text for term in ("酒精炉", "酒精")):
        return _phase1_alcohol_stove_compatibility_answer(db, row, evidence_metadata=evidence_metadata)

    name = str(row.get("product_name_cn") or row.get("product_name_en") or row.get("sku") or "该产品").strip()
    sku = str(row.get("sku") or "").strip().upper()
    prefix = f"{name}（{sku}）" if name else sku
    heat_source = _heat_source_field_evidence(row.get("heat_source"))
    normalized_heat_source = "" if heat_source in {"", "/", "[]", "暂无", "未标注"} else heat_source
    asks_direct_heating = any(term in identity_free_text for term in (
        "直接加热", "明火加热", "上火加热", "直接放", "直接置于",
    ))
    asks_heat_source = any(term in identity_free_text for term in ("热源", "燃料", "适用什么热源", "适用热源"))
    capability_aliases = {
        "卡式炉": ("卡式炉",),
        "燃气炉": ("燃气炉", "气炉", "卡式炉"),
        "气炉": ("气炉", "燃气炉", "卡式炉"),
        "明火直烧": ("明火直烧", "明火"),
        "明火": ("明火", "明火直烧"),
        "分体炉": ("分体炉",),
        "一体炉": ("一体炉",),
        "电磁炉": ("电磁炉",),
        "电陶炉": ("电陶炉",),
        "电热炉": ("电热炉",),
        "电炉": ("电炉", "电磁炉", "电陶炉", "电热炉"),
    }
    asked_capability = next((label for label in capability_aliases if label in identity_free_text), "")

    if normalized_heat_source:
        if evidence_metadata is not None:
            evidence_metadata.update({
                "evidence_value": normalized_heat_source,
                "evidence_source": "specs.heat_source",
                "evidence_scope": "subject",
                "evidence_sku": sku,
            })
        if asks_direct_heating:
            return f"{prefix}：可以按直接加热理解，当前资料显示适用热源为{normalized_heat_source}。", "supported"
        if asked_capability:
            aliases = capability_aliases.get(asked_capability, ())
            if any(alias and alias in normalized_heat_source for alias in aliases):
                return f"{prefix}：支持{asked_capability}，当前资料显示适用热源为{normalized_heat_source}。", "supported"
            return f"{prefix}：当前资料未显示支持{asked_capability}，当前资料显示适用热源为{normalized_heat_source}。", "not_listed"
        if "燃料" in text:
            return f"{prefix}：当前资料显示适用燃料/气源为{normalized_heat_source}。", "structured"
        if asks_heat_source:
            return f"{prefix}：当前资料显示适用热源为{normalized_heat_source}。", "structured"
        return f"{prefix}：当前资料显示适用热源为{normalized_heat_source}。", "structured"

    instruction_boundary = _same_sku_usage_instruction_heat_source_boundary(
        row.get("usage_instruction"),
        asked_capability=asked_capability,
        asks_direct_heating=asks_direct_heating,
    )
    if instruction_boundary:
        if evidence_metadata is not None:
            evidence_metadata.update({
                "evidence_value": instruction_boundary,
                "evidence_source": "specs.usage_instruction",
                "evidence_scope": "subject",
                "evidence_sku": sku,
            })
        return f"{prefix}：{instruction_boundary}。", "unsupported"

    if asks_direct_heating:
        return f"{prefix}：当前资料未标注适用热源；是否可以直接加热，不能仅凭现有资料确认。", "missing"
    if asked_capability:
        return f"{prefix}：当前资料未标注适用热源；是否支持{asked_capability}，不能仅凭现有资料确认。", "missing"
    return f"{prefix}：当前资料未标注适用热源，不能仅凭现有资料确认。", "missing"










def _phase1_catalog_rows(db: Session, product_ref: str) -> list[dict]:
    ref = str(product_ref or "").strip()
    category_scope_config = {
        "配件": {
            "categories": {"配件"},
            "sub_categories": ("收纳包具", "餐厨配件", "附件"),
            "fallback_terms": ("配件", "附件"),
        },
        "炉具": {
            "categories": {"炉具"},
            "sub_categories": ("炉具", "炉子", "酒精炉", "气炉", "卡式炉"),
            "fallback_terms": ("炉具", "炉子", "酒精炉", "卡式炉", "气炉"),
        },
        "餐具": {
            "categories": {"餐具"},
            "sub_categories": ("餐具",),
            "fallback_terms": ("餐具",),
        },
        "水具": {
            # A cookware row may mention “水杯” in a sub-category or sales
            # copy (for example a pot set that includes a cup).  That is not
            # enough to make it a waterware candidate.  Category scope is the
            # catalogue identity boundary, so keep this scope at the stored
            # category level and let semantic/RAG ranking work within it.
            "categories": {"水具", "水壶", "水杯", "杯具"},
            "sub_categories": (),
            "fallback_terms": (),
        },
        "桌椅": {
            "categories": {"桌椅"},
            "sub_categories": ("桌椅",),
            "fallback_terms": ("桌椅",),
        },
        "咖啡器具": {
            "categories": {"咖啡器具"},
            "sub_categories": ("咖啡器具",),
            "fallback_terms": ("咖啡器具",),
        },
        "茶具": {
            "categories": {"茶具"},
            "sub_categories": ("茶具",),
            "fallback_terms": ("茶具",),
        },
        "天幕/地垫/帐篷": {
            "categories": {"天幕", "地垫", "帐篷", "天幕/地垫/帐篷", "天幕、地垫、帐篷"},
            "sub_categories": ("天幕", "地垫", "帐篷"),
            "fallback_terms": ("天幕", "地垫", "帐篷"),
        },
    }

    def _matches_category_scope(row: dict, scope: dict[str, Any]) -> bool:
        category = str(row.get("category") or "").strip()
        sub_category = str(row.get("sub_category") or "").strip()
        if category in (scope.get("categories") or set()):
            return True
        if sub_category and any(term in sub_category for term in (scope.get("sub_categories") or ())):
            return True
        if category or sub_category:
            return False
        name_text = " ".join(str(row.get(key) or "") for key in ("product_name_cn", "product_name_en"))
        return any(term and term in name_text for term in (scope.get("fallback_terms") or ()))

    query = (
        db.query(Product, ProductSpecs, ProductBusiness, ProductContent)
        .outerjoin(ProductSpecs, ProductSpecs.product_id == Product.id)
        .outerjoin(ProductBusiness, ProductBusiness.product_id == Product.id)
        .outerjoin(ProductContent, ProductContent.product_id == Product.id)
    )
    rows: list[dict] = []
    for product, specs, business, content in query.all():
        row = _product_row_from_model(product, specs, business, content)
        haystack = " ".join(str(row.get(key) or "") for key in (
            "product_name_cn",
            "product_name_en",
            "category",
            "capacity",
            "features",
            "usage_scenarios",
            "positioning",
            "long_description_cn",
        ))
        if ref == "产品":
            matched = True
        elif ref == "水壶":
            category_text = " ".join(str(row.get(key) or "") for key in ("category", "sub_category", "product_name_cn", "product_name_en"))
            matched = "水壶" in category_text
        elif ref == "气罐":
            # A canister is a consumable/accessory subject, not a stove
            # category.  Match its own product identity fields and exclude
            # stove rows whose heat-source field merely mentions a canister.
            category = str(row.get("category") or "").strip()
            canister_name = " ".join(
                str(row.get(key) or "")
                for key in ("product_name_cn", "product_name_en")
            )
            adapter_markers = ("转接头", "转换头", "适配头", "配件")
            matched = (
                category in {"燃料", "气罐", "燃气"}
                or (
                    category not in {"炉具", "锅具", "酒精炉", "配件"}
                    and any(term in canister_name for term in ("气罐", "气瓶", "高山气罐", "卡式气罐", "液化气罐"))
                )
            ) and not any(term in canister_name for term in adapter_markers)
        elif ref == "锅具":
            # The catalogue label "锅具" includes product-family records that
            # are actually griddles or accessory components.  Count only
            # standalone pots and cookware sets, using the same canonical
            # candidate boundary as recommendation and structured filtering.
            matched = (
                customer_structured_query_contract.resolve_material_subject_scope(row, "\u9505\u5177")["eligible"]
                and _is_service_pot_or_cookware_set_candidate(row)
            )
        elif ref == "烤盘":
            category = str(row.get("category") or "").strip()
            griddle_text = " ".join(
                str(row.get(key) or "")
                for key in ("product_name_cn", "product_name_en", "sub_category", "features")
            )
            matched = category != "炉具" and any(term in griddle_text for term in ("烤盘", "煎盘", "煎烤盘"))
        elif ref in category_scope_config:
            matched = _matches_category_scope(row, category_scope_config[ref])
        elif ref == "套锅":
            matched = "套锅" in haystack or "锅" in str(row.get("category") or "") and "套" in haystack
        else:
            matched = bool(ref and ref in haystack)
        if matched:
            rows.append(row)
    return rows


def _database_category_scope_ref(rows: list[dict], semantic_subject: str) -> str:
    """Resolve a semantic category subject to an existing DB category label.

    This is a bounded catalogue-identity adapter, not a field-intent router:
    the semantic preplan has already chosen ``structured_query/category``.
    We only accept a subject that maps to a real category value (including a
    segment of a stored composite category) so product-name recall cannot
    broaden a category count.
    """
    subject = customer_agent_service.normalize_search_text(semantic_subject)
    if not subject:
        return ""
    normalized_categories = {
        customer_agent_service.normalize_search_text(str(row.get("category") or "")): str(row.get("category") or "").strip()
        for row in rows
        if str(row.get("category") or "").strip()
    }
    # Resolve maintained semantic aliases before returning a raw category
    # label.  In particular, “水杯” and “水壶” are customer-facing forms of
    # the live 水具 scope; returning the raw word would call the loose text
    # search branch and allow a cookware row whose copy happens to mention a
    # cup to enter the recommendation pool.
    category_aliases = {
        "配件": ("配件", "附件"),
        "炉具": ("炉具", "炉子", "酒精炉", "气炉", "卡式炉"),
        "餐具": ("餐具",),
        "水具": ("水具", "水壶", "水杯", "杯具"),
        "桌椅": ("桌椅",),
        "咖啡器具": ("咖啡器具",),
        "茶具": ("茶具",),
    }
    for canonical, aliases in category_aliases.items():
        normalized_aliases = {
            customer_agent_service.normalize_search_text(alias).strip().lower()
            for alias in aliases
        }
        if subject not in normalized_aliases:
            continue
        if any(
            customer_agent_service.normalize_search_text(str(row.get("category") or "")).strip().lower()
            in normalized_aliases
            for row in rows
            if isinstance(row, dict) and str(row.get("category") or "").strip()
        ):
            return canonical
    if subject in normalized_categories:
        return normalized_categories[subject]
    # A one-character head noun is a common customer shorthand for a stored
    # category label (锅 -> 锅具, 炉 -> 炉具).  Match only an actual category
    # label, never a product name or selling-point field.
    if len(subject) == 1:
        matches = [
            label for normalized, label in normalized_categories.items()
            if normalized.startswith(subject) and normalized.endswith("具")
        ]
        if len(matches) == 1:
            return matches[0]
    # The planner may preserve the customer's concrete category noun while
    # the catalogue stores a broader canonical category (for example
    # ``水杯`` under ``水具``). Resolve only against the maintained category
    # vocabulary and an existing category population; do not turn a product
    # name or a selling-point word into a scope.
    for canonical, aliases in category_aliases.items():
        normalized_aliases = {
            customer_agent_service.normalize_search_text(alias).strip().lower()
            for alias in aliases
        }
        if subject not in normalized_aliases:
            continue
        if any(
            str(row.get("category") or "").strip() == canonical
            or canonical == "水具"
            and str(row.get("category") or "").strip() in {"水具", "水壶"}
            for row in rows
            if isinstance(row, dict)
        ):
            return canonical
    composite_matches = [
        label for normalized, label in normalized_categories.items()
        if subject and subject in normalized and any(separator in normalized for separator in ("/", "、", "，", ","))
    ]
    return composite_matches[0] if len(composite_matches) == 1 else ""


def _database_product_family_scope_rows(rows: list[dict], semantic_subject: str) -> list[dict]:
    """Resolve a semantic family subject only against product identity fields."""
    subject = customer_agent_service.normalize_search_text(semantic_subject)
    if not subject:
        return []
    family_rows = []
    for row in rows:
        identity_values = (
            row.get("sku"),
            row.get("product_name_cn"),
            row.get("product_name_en"),
        )
        if any(
            subject in customer_agent_service.normalize_search_text(str(value or ""))
            for value in identity_values
        ):
            family_rows.append(row)
    return family_rows


def _database_question_product_family_scope_rows(rows: list[dict], question: str) -> list[dict]:
    """Find a repeated product-name span shared with the full question.

    This is used only when semantic planning is unavailable.  It examines
    product identity fields, never descriptions, scenarios, selling points or
    requested attributes, and therefore cannot turn a broad recommendation
    match into a product-family answer.
    """
    normalized_question = customer_agent_service.normalize_search_text(question).lower()
    segments = re.findall(r"[a-z0-9]+|[\u4e00-\u9fff]+", normalized_question)
    best_rows: list[dict] = []
    best_span_length = 0
    for segment in segments:
        upper_length = min(len(segment), 24)
        for span_length in range(upper_length, 2, -1):
            if span_length < best_span_length:
                break
            for index in range(0, len(segment) - span_length + 1):
                span = segment[index:index + span_length]
                matching_rows = [
                    row
                    for row in rows
                    if any(
                        span in customer_agent_service.normalize_search_text(str(row.get(field) or "")).lower()
                        for field in ("sku", "product_name_cn", "product_name_en")
                    )
                ]
                if len(matching_rows) > 1 and (
                    span_length > best_span_length
                    or (span_length == best_span_length and len(matching_rows) > len(best_rows))
                ):
                    best_span_length = span_length
                    best_rows = matching_rows
    return best_rows


def _phase1_catalog_count_rows(db: Session, product_ref: str, question: str) -> tuple[list[dict], str | None]:
    """Return the authoritative category-membership population for count questions.

    Product discovery can deliberately use a narrower functional domain (for
    example, excluding a standalone griddle from cookware recommendations).
    A customer asking how many products are in a catalogue category needs the
    database category membership instead, including a product assigned to a
    composite category.  Keep that distinction at the aggregate boundary.
    """
    ref = str(product_ref or "").strip()
    text = str(question or "")
    is_count = any(token in text for token in ("多少", "几款", "几种", "几个"))
    if ref != "锅具" or not is_count:
        return _phase1_catalog_rows(db, ref), None

    rows = _phase1_catalog_rows(db, "产品")
    category_rows = [row for row in rows if "锅具" in str(row.get("category") or "")]
    pure_count = sum(str(row.get("category") or "").strip() == "锅具" for row in category_rows)
    composite_count = len(category_rows) - pure_count
    scope_note = f"其中类目为“锅具”{pure_count} 款"
    if composite_count:
        scope_note += f"，复合类目中包含“锅具”{composite_count} 款"
    return category_rows, scope_note


def _phase1_catalog_count_result(db: Session, plan: dict) -> dict:
    product_ref = str(plan.get("product_ref") or "").strip() or "产品"
    rows, scope_note = _phase1_catalog_count_rows(db, product_ref, str(plan.get("raw_question") or ""))
    display_ref = _phase1_catalog_display_label(product_ref)
    skus = [str(row.get("sku") or "") for row in rows if row.get("sku")]
    display_rows = _phase1_rank_catalog_display_rows(product_ref, rows)[:10]
    display_skus = [str(row.get("sku") or "") for row in display_rows if row.get("sku")]
    samples = "、".join(
        f"{row.get('sku')} {row.get('product_name_cn')}".strip()
        for row in display_rows
        if row.get("sku")
    )
    scope_label = f"【{display_ref}】" if product_ref != "产品" else "【产品】"
    if not rows:
        answer = f"当前产品库里暂未维护明确的{scope_label}类产品。"
        if product_ref != "产品":
            answer += " 如果你愿意，我可以改按相近类目或具体用途继续帮你找。"
    else:
        if samples and len(rows) > len(display_rows):
            suffix = f"先列前 {len(display_rows)} 款：{samples}。"
        elif samples:
            suffix = f"分别是：{samples}。"
        else:
            suffix = ""
        if product_ref == "配件" and samples:
            suffix = f"先按更像明确配件的小件/附件口径列前 {len(display_rows)} 款：{samples}。"
        elif product_ref == "水具" and samples:
            suffix = f"先按通用饮水/补水口径列前 {len(display_rows)} 款：{samples}。"
        answer = f"当前匹配到{scope_label}类产品共有 {len(rows)} 款。{suffix}"
        if scope_note:
            answer += f" 统计口径：{scope_note}。"
        if product_ref != "产品":
            answer += " 如果你想继续缩小范围，我可以再按用途、人数、容量、重量或收纳继续筛。"
    return {
        "intent": "query_products",
        "answer_type": "product_query" if product_ref == "天幕/地垫/帐篷" else "query_products",
        "answer": answer,
        "results": display_rows,
        "result_skus": display_skus,
        "candidate_skus": display_skus,
        "answer_metadata": {
            "source": "product_catalog_structured_query",
            "catalog_count": len(rows),
            "display_count": len(display_rows),
            "product_ref": product_ref,
        },
        "debug": {"agent_mode": "structured_catalog_count"},
        "skip_polish": True,
    }


def _phase1_catalog_display_label(product_ref: str) -> str:
    ref = str(product_ref or "").strip()
    if ref == "all_products":
        return "全部产品"
    if ref == "天幕/地垫/帐篷":
        return "天幕、地垫、帐篷"
    return ref


def _phase1_rank_catalog_display_rows(product_ref: str, rows: list[dict]) -> list[dict]:
    ref = str(product_ref or "").strip()
    if ref not in {"配件", "水具"}:
        return list(rows or [])

    def _score(row: dict) -> tuple[int, str]:
        text = " ".join(
            str(row.get(key) or "").strip()
            for key in ("product_name_cn", "product_name_en", "category", "sub_category", "features", "usage_scenarios", "positioning")
        )
        score = 0
        if ref == "配件":
            if any(term in text for term in ("配件", "附件", "替换件", "维修件", "炉芯", "防风板", "提手", "手夹", "刀板", "收纳件", "小配件")):
                score += 10
            if any(term in text for term in ("锅具配件", "餐厨配件", "炉具配件", "替换配件", "备用配件")):
                score += 5
            if any(term in text for term in ("收纳包", "折叠箱", "保温包", "围裙", "堆堆车", "炊雪盘", "水袋", "雪拉碗", "喷枪")):
                score -= 8
        elif ref == "水具":
            if any(term in text for term in ("水具", "水壶", "水杯", "杯", "饮水", "补水", "便携水具", "保温壶", "冷水壶")):
                score += 8
            if any(term in text for term in ("便携", "随身", "公园野餐", "徒步补水", "户外补水", "饮水")):
                score += 4
            if any(term in text for term in ("咖啡", "手冲", "细口壶", "煮茶")):
                score -= 6
            if any(term in text for term in ("烧水", "加热", "套装礼盒", "礼盒")):
                score -= 3
        sku = str(row.get("sku") or "")
        return (-score, sku)

    return sorted(list(rows or []), key=_score)


def _looks_like_standalone_burner_head_accessory_request(question: str) -> bool:
    """Keep a bare burner-head target in the accessory ontology.

    ``炉头`` can be used colloquially for a complete small stove, so this
    boundary only applies when it is the standalone selection target.  A
    complete-stove noun (炉具/炉子/卡式炉/酒精炉等) or the compound ``小炉头``
    keeps the broader stove route.  The decision is based on the customer's
    semantic noun and selection predicate, never on a SKU or exact utterance.
    """
    text = str(question or "").strip()
    if "炉头" not in text or "小炉头" in text:
        return False
    if any(term in text for term in ("炉具", "炉子", "酒精炉", "燃气炉", "卡式炉", "气炉")):
        return False
    selection_terms = ("推荐", "哪款", "哪个", "哪种", "用什么样", "有没有", "有卖", "卖吗", "找")
    return any(term in text for term in selection_terms)


def _semantic_catalog_product_ref(question: str) -> str:
    text = str(question or "").strip()
    # Explicit accessory/storage nouns define the catalogue subject even when
    # the same turn also mentions cookware or tableware.  This keeps a bag or
    # attachment request from falling through to the broad product/category
    # fallback; it does not identify or promote any SKU.
    if any(term in text for term in ("收纳包", "收纳袋", "装备包", "野炊包", "餐具包", "厨具包", "配件", "附件")):
        return "配件"
    if (
        any(term in text for term in ("高山气罐", "卡式气罐", "液化气罐", "通用气罐", "气罐", "气瓶"))
        and any(term in text for term in ("品牌", "型号", "推荐", "哪款", "哪个", "买", "选"))
        # A canister noun can be a supporting condition for a burner request
        # (for example “装气罐的小炉头”), not the product category being
        # selected.  Let the explicit stove subject win before the generic
        # fuel catalogue boundary; this is an intent-precedence rule, not a
        # SKU or utterance-specific exception.
        and not any(term in text for term in ("炉头", "炉具", "炉子", "酒精炉", "燃气炉", "卡式炉", "分体炉", "一体炉", "气炉"))
        and not any(term in text for term in ("能不能", "能否", "能用", "适配", "兼容", "接口", "用什么燃料"))
    ):
        return "气罐"
    if any(term in text for term in ("咖啡器具", "手冲", "手冲壶")):
        return "咖啡器具"
    if "茶具" in text:
        return "茶具"
    if any(term in text for term in ("烤盘", "煎盘")):
        return "烤盘"
    if "水壶" in text:
        return "水壶"
    if "水具" in text:
        return "水具"
    # A heat-source noun can be a constraint on cookware rather than the
    # catalogue subject being selected (for example, "支持酒精炉的锅具").
    # Resolve the requested object first when the sentence expresses a
    # compatibility relation; an unqualified "推荐酒精炉" still falls
    # through to the stove category below.
    if (
        any(term in text for term in ("锅具", "套锅", "单锅", "锅"))
        and any(term in text for term in ("酒精炉", "燃气炉", "卡式炉", "分体炉", "一体炉", "气炉"))
        and any(term in text for term in ("支持", "适合", "兼容", "能用", "能配", "搭配", "配合", "能不能", "能否", "是否"))
    ):
        return "锅具"
    if _looks_like_standalone_burner_head_accessory_request(text):
        return "配件"
    if any(term in text for term in ("炉具", "炉子", "炉头", "酒精炉", "燃气炉", "卡式炉", "分体炉", "一体炉", "气炉", "stove", "burner")):
        return "炉具"
    if any(term in text for term in ("锅具", "套锅", "单锅", "锅", "套装", "组合", "套餐")):
        return "锅具"
    if "配件" in text:
        return "配件"
    if "餐具" in text:
        return "餐具"
    if "桌椅" in text:
        return "桌椅"
    if any(term in text for term in ("天幕", "地垫", "帐篷")):
        return "天幕/地垫/帐篷"
    return "产品"


