def _structured_target_category_from_question(question: str) -> str:
    text = str(question or "").strip()
    if not text:
        return ""
    aliases = "|".join(re.escape(alias) for alias, _ in _STRUCTURED_TARGET_CATEGORY_ALIASES)
    for pattern in (
        rf"(?:哪些|哪一些|有哪些)\s*({aliases})",
        rf"(?:有没有|有无|推荐(?:一下|一个|一款|几个|几款)?|找(?:一个|一款)?|想买|买(?:一个|一款)?|卖不卖|有卖)\s*(?:一个|一款|几个|几款)?\s*({aliases})",
        rf"(?:推荐|找|想买|买)[^？?。！!，,；;]{{0,40}}?({aliases})",
        rf"({aliases})\s*(?:推荐|卖吗|有卖|有没有|要一个)",
        rf"(?:这个|这款|那款|该|我说的)\s*({aliases})",
        rf"的\s*({aliases})\s*[？?。！!，,；;]*$",
    ):
        match = re.search(pattern, text)
        if match is not None:
            alias = match.group(1)
            return next(category for candidate, category in _STRUCTURED_TARGET_CATEGORY_ALIASES if candidate == alias)
    return ""


def _product_category_domain(category: str | None) -> str:
    value = str(category or "").strip()
    if any(term in value for term in ("锅具", "烤盘", "煎盘")):
        return "cookware"
    if any(term in value for term in ("水壶", "水具", "水杯")):
        return "waterware"
    if "炉具" in value or "酒精炉" in value:
        return "stove"
    if "配件" in value:
        return "accessory"
    if "餐具" in value:
        return "tableware"
    if "咖啡器具" in value:
        return "coffee"
    if "茶具" in value:
        return "tea"
    if "桌椅" in value:
        return "furniture"
    return value


def _looks_like_semantic_catalog_query(question: str) -> bool:
    text = str(question or "").strip()
    if not text:
        return False
    generic_category_listing = bool(re.match(
        r"^\s*(?:有)?\s*(?:哪些|多少款|多少个|多少种|多少|几款|几种)\s*"
        r"(?:锅具|套锅|单锅|锅|炉具|炉子|炉|水具|水壶|配件|附件|餐具|桌椅|咖啡器具|咖啡|茶具|烤盘|煎盘|天幕|地垫|帐篷)"
        r"(?:产品|商品)?\s*[？?！!]?$",
        text,
    ))
    # A formal field predicate (shipping, price, material, etc.) outweighs a
    # coincidental count token such as "多少" inside a product question.
    if customer_field_contract.detect_field_contract(text) is not None and not generic_category_listing:
        return False
    count_or_list_terms = ("多少款", "多少个", "多少种", "多少", "几款", "几种", "有哪些", "列出")
    scope_terms = ("锅具", "套锅", "单锅", "锅", "炉具", "炉子", "炉", "水具", "水壶", "配件", "餐具", "桌椅", "咖啡器具", "咖啡", "茶具", "烤盘", "煎盘", "天幕", "地垫", "帐篷")
    if any(term in text for term in ("适合", "更偏", "能配", "搭配", "随身补水", "冷水", "热水", "手冲", "泡茶")):
        return False
    return any(term in text for term in count_or_list_terms) and any(term in text for term in scope_terms)


def _has_resolved_entity_contents_accessories_question(db: Session, question: str) -> bool:
    text = str(question or "").strip()
    if not text:
        return False
    if not customer_agent_intent_service._looks_like_contents_grounding_question(text):
        return False
    if _resolve_sku(db, text, None):
        return True
    return bool(_products_named_in_question(db, text))


def _structured_query_row_text(row: dict[str, Any]) -> str:
    return " ".join(
        str(row.get(key) or "").strip()
        for key in (
            "sku",
            "product_name_cn",
            "product_name_en",
            "category",
            "sub_category",
            "capacity",
            "body_material",
            "material",
            "heat_source",
            "applicable_heat_source",
            "target_audience",
            "gross_weight_g",
            "specification",
            "size",
            "features",
            "usage_scenarios",
            "positioning",
            "long_description_cn",
        )
    )


def _structured_row_matches_category_value(row: dict[str, Any], value: str) -> bool:
    text = _structured_query_row_text(row)
    normalized = str(value or "").strip()
    if not normalized:
        return True
    if normalized == "水杯":
        has_cup_signal = any(token in text for token in ("水杯", "杯", "杯子", "随行杯", "保温杯", "钛杯", "马克杯"))
        has_kettle_signal = any(token in text for token in ("水壶", "茶壶", "烧水壶", "细口壶", "冷水壶", "保温壶"))
        return has_cup_signal and not has_kettle_signal
    if normalized == "水具":
        return any(token in text for token in ("水具", "水壶", "杯", "杯子", "水杯", "壶"))
    if normalized == "水壶":
        has_kettle_signal = any(token in text for token in ("水壶", "茶壶", "烧水壶", "细口壶", "冷水壶", "保温壶"))
        has_cup_signal = any(token in text for token in ("水杯", "杯", "杯子", "随行杯", "保温杯", "钛杯", "马克杯"))
        return has_kettle_signal and not has_cup_signal
    if normalized == "锅具":
        return "锅" in text
    if normalized == "炉具":
        return "炉" in text
    if normalized == "配件":
        return "配件" in text
    if normalized == "咖啡器具":
        return "咖啡" in text
    return normalized in text




def _structured_row_matches_heat_value(row: dict[str, Any], value: str) -> bool:
    text = " ".join(
        str(row.get(key) or "").strip()
        for key in ("heat_source", "applicable_heat_source", "features", "long_description_cn")
    )
    normalized = str(value or "").strip()
    if not normalized:
        return True
    if normalized == "明火直烧":
        return "明火" in text
    if normalized == "明火":
        return any(token in text for token in ("明火", "直接加热", "烧水"))
    if normalized == "卡式炉":
        return "卡式炉" in text or "卡式气罐" in text
    if normalized == "酒精炉":
        return "酒精炉" in text or "酒精" in text
    return normalized in text


def _structured_row_matches_usage_value(row: dict[str, Any], value: str) -> bool:
    text = " ".join(
        str(row.get(key) or "").strip()
        for key in ("usage_scenarios", "features", "positioning", "long_description_cn", "target_audience")
    )
    normalized = str(value or "").strip()
    if not normalized:
        return True
    if normalized == "徒步":
        return any(token in text for token in ("徒步", "轻量", "便携"))
    if normalized == "咖啡":
        return any(token in text for token in ("咖啡", "手冲", "滤杯", "分享壶", "细口壶"))
    if "徒步" in normalized:
        return any(token in text for token in ("徒步", "轻量", "便携"))
    if "新手" in normalized:
        return any(token in text for token in ("新手", "入门", "基础", "性价比"))
    return normalized in text


def _structured_product_query_result(
    *,
    question: str,
    product_ref: str,
    rows: list[dict[str, Any]],
    source: str,
    reason_label: str,
    answer_type: str = "product_query",
    metadata_source: str | None = None,
    membership_field: str | None = None,
) -> dict | None:
    display_rows = rows[:10]
    if not display_rows:
        return None
    result_skus = [str(row.get("sku") or "").strip().upper() for row in display_rows if str(row.get("sku") or "").strip()]
    sample_text = "、".join(
        f"{row.get('sku')} {row.get('product_name_cn')}".strip()
        for row in display_rows
        if row.get("sku")
    )
    if source == "semantic_catalog_family_scope":
        rows_by_category: dict[str, list[dict[str, Any]]] = {}
        for row in display_rows:
            category = str(row.get("category") or "未分类").strip() or "未分类"
            rows_by_category.setdefault(category, []).append(row)
        category_parts = []
        for category, category_rows in rows_by_category.items():
            category_samples = "、".join(
                f"{row.get('sku')} {row.get('product_name_cn')}".strip()
                for row in category_rows
                if row.get("sku")
            )
            category_parts.append(f"{category} {len(category_rows)} 款：{category_samples}")
        answer = (
            f"【{product_ref}】相关商品共 {len(rows)} 款，按产品库类目区分为："
            f"{'；'.join(category_parts)}。"
            "如果你想选炉具本体或配件，我可以在对应类目里继续比较。"
        )
    else:
        answer = (
            f"当前按{reason_label}在【{product_ref}】里筛到 {len(rows)} 款候选。"
            f"{'先列前 %d 款：%s。' % (len(display_rows), sample_text) if sample_text else ''}"
            "如果你要继续缩小范围，我可以再按容量、重量、材质或人数继续筛。"
        )
    membership_evidence = []
    if membership_field:
        membership_label = customer_field_contract.product_detail_field_label(membership_field) or membership_field
        for row in display_rows:
            sku = str(row.get("sku") or "").strip().upper()
            value = row.get(membership_field)
            if sku and value is not None and str(value).strip():
                membership_evidence.append({
                    "type": "catalogue_membership",
                    "sku": sku,
                    "field": membership_field,
                    "field_label": membership_label,
                    "value": value,
                    "source_type": "product_db",
                    "source_label": "product_db",
                    "evidence_text": f"{membership_label} {value}",
                })
    return {
        "intent": "query_products",
        "answer_type": answer_type,
        "answer": answer,
        "results": display_rows,
        "result_skus": result_skus,
        "candidate_skus": result_skus,
        "evidence": membership_evidence,
        "answer_metadata": {
            "source": metadata_source or source,
            "product_ref": product_ref,
            "matched_count": len(rows),
            "membership_evidence_field": membership_field or "",
        },
        "debug": {"agent_mode": source, "raw_results": display_rows, "candidate_skus": result_skus},
        "skip_polish": True,
    }


def _detect_unknown_product_fact_label(question: str) -> str | None:
    text = str(question or "").strip()
    if not text:
        return None
    for label, terms in _STRUCTURED_UNKNOWN_FACT_TERMS.items():
        if any(term in text for term in terms):
            return label
    return None


def _detect_resolved_entity_unknown_fact_label(question: str) -> str | None:
    text = str(question or "").strip()
    if not text:
        return None
    field_contract = customer_field_contract.detect_field_contract(text)
    if field_contract and field_contract.field_type == "shipping":
        return "发货时效"
    if field_contract:
        contract_label = customer_field_contract.product_detail_field_label(field_contract.field_type)
        if contract_label in _RESOLVED_ENTITY_UNKNOWN_FACT_TERMS:
            return contract_label
    for label, terms in _RESOLVED_ENTITY_UNKNOWN_FACT_TERMS.items():
        if any(term in text for term in terms):
            return label
    return None


def _resolved_entity_unknown_field_guard_label(question: str) -> str | None:
    text = str(question or "").strip()
    if not text:
        return None
    label = _detect_resolved_entity_unknown_fact_label(text)
    if label in _RESOLVED_ENTITY_REALTIME_COMMERCIAL_LABELS:
        return label
    if customer_agent_intent_service._looks_like_usage_care_question(text):
        return None
    if customer_agent_intent_service._looks_like_contents_grounding_question(text):
        return None
    if customer_agent_intent_service._is_compare_question(text):
        return None
    if _looks_like_recommendation_request(text):
        return None
    return label


def _resolved_entity_realtime_commercial_field_guard_label(question: str) -> str | None:
    label = _resolved_entity_unknown_field_guard_label(question)
    if label in _RESOLVED_ENTITY_REALTIME_COMMERCIAL_LABELS:
        return label
    return None


def _semantic_preplan_unknown_realtime_subtype(preplan: dict | None, question: str) -> str:
    subtype = str((preplan or {}).get("subtype") or "").strip()
    if subtype in _SEMANTIC_UNKNOWN_REALTIME_SUBTYPES:
        return subtype
    route_hint = str((preplan or {}).get("route_hint") or "").strip()
    question_type = str((preplan or {}).get("question_type") or "").strip()
    label = _resolved_entity_realtime_commercial_field_guard_label(question) or _detect_unknown_product_fact_label(question)
    if label and (route_hint == "unknown_field" or question_type == "unknown_field" or (preplan or {}).get("unknown_field")):
        return "commercial_realtime"
    return ""


def _resolved_entity_unknown_fact_answer(prefix: str, label: str) -> str:
    special = {
        "库存": f"{prefix}\n当前资料未标注库存，也不能仅凭现有资料确认实时库存；请以平台或店铺页面为准，或联系人工客服确认。",
        "在售状态": f"{prefix}\n当前资料未维护可确认的实时在售状态或库存，不能仅凭静态产品资料判断；请以平台或店铺页面为准，或联系人工客服确认。",
        "销量": f"{prefix}\n当前资料未标注销量，也不能仅凭现有资料判断实时销量；请以平台或店铺页面为准。",
        "评价": f"{prefix}\n当前资料未标注评价或好评率，也不能仅凭现有资料确认实时评价信息；请以平台或店铺页面为准。",
        "价格": f"{prefix}\n当前资料未标注实时价格，也不能仅凭现有资料确认当前售价；请以平台或店铺页面为准。",
        "保修": f"{prefix}\n当前资料未标注保修信息，也无法仅凭现有资料确认具体质保政策；请以平台或店铺页面或人工客服说明为准。",
        "认证": f"{prefix}\n当前资料未标注对应认证或检测信息，不能仅凭现有资料确认。",
        "官方说明书": f"{prefix}\n当前资料未维护官方说明书信息，如需确认建议联系人工客服。",
        "售后电话": f"{prefix}\n当前资料未维护正式售后电话号码，无法提供可核验的联系电话；请通过购买平台的官方客服入口确认。",
        "安装视频": f"{prefix}\n当前资料未维护安装视频信息，如需确认建议联系人工客服。",
        "优惠活动": f"{prefix}\n当前资料未标注该商品的优惠、活动、券、会员价或到手价信息，也无法确认实时促销；请以平台或店铺页面为准。",
        # ``shipping`` is one safely-unsupported commercial field, but it
        # covers several customer meanings (carrier, dispatch/delivery timing,
        # postage, and delivery promises).  Do not fabricate an ETA premise
        # for a carrier question merely because both meanings share this
        # formal contract.  The semantic plan determines the field; this copy
        # is only the evidence-safe boundary when no matching same-SKU QA or
        # structured source exists.
        "发货时效": f"{prefix}\n当前资料未标注该商品的承运快递、发货或配送时效、运费及配送承诺等具体安排，无法确认；请以平台或店铺页面为准。",
        "赠品": f"{prefix}\n当前资料未标注该商品是否附赠赠品，也无法确认实时活动赠品；请以平台或店铺页面为准。",
        "包邮": f"{prefix}\n当前资料未标注该商品的包邮或运费规则，也无法确认实时包邮活动；请以平台或店铺页面为准。",
        "售后": f"{prefix}\n当前资料未标注该商品的售后政策或服务细则，也无法确认实时售后安排；请以平台或店铺页面或人工客服说明为准。",
    }
    # Non-realtime unsupported fields (for example a manufacturer model
    # number) must keep their own field boundary.  Do not borrow the generic
    # realtime-commercial disclaimer merely because this function also serves
    # price, inventory and delivery guards above.
    return special.get(label) or f"{prefix}\n当前资料未标注{label}信息，无法确认。"


def _build_resolved_product_unknown_field_result(
    db: Session,
    product: Product,
    *,
    label: str,
    source: str,
    resolution_decision: customer_entity_resolution_contract.SingleProductResolutionDecision,
    entity_contract: customer_entity_resolution_contract.EntityResolutionContract | None = None,
) -> dict:
    row = _product_row_from_model(product)
    name = str(product.product_name_cn or product.product_name_en or product.sku or "").strip()
    sku = str(product.sku or "").strip().upper()
    if not resolution_decision.allowed or resolution_decision.resolved_sku != sku:
        raise ValueError("resolved unknown-field answer requires an allowed exact entity decision")
    prefix = f"{name}（{sku}）" if name else sku
    manual_document = None
    if label == "官方说明书":
        manual_document = (
            db.query(KnowledgeDocument)
            .filter(
                KnowledgeDocument.sku == sku,
                KnowledgeDocument.source_type == "manual",
                KnowledgeDocument.is_active.is_(True),
            )
            .order_by(KnowledgeDocument.updated_at.desc())
            .first()
        )
    manual_value = ""
    if manual_document is not None:
        manual_value = str(manual_document.file_name or manual_document.title or "").strip()
    if manual_value:
        answer = f"{prefix}\n当前资料已维护官方说明书：{manual_value}。"
    else:
        answer = _resolved_entity_unknown_fact_answer(prefix, label)
    evidence_field = "manual" if manual_value else None
    evidence_source = "knowledge_documents.manual" if manual_value else None
    evidence_value = manual_value
    if entity_contract is None:
        entity_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
            sku,
            [product],
            resolver_candidates=[product],
            entity_text_override=sku,
            field_type_override=customer_field_contract.field_type_from_detail_label(label),
        )
    return {
        "intent": "product_detail",
        "answer_type": "product_detail",
        "answer": answer,
        "results": [row],
        "result_skus": [sku],
        "candidate_skus": [sku],
        "sku": sku,
        "answer_metadata": {
            "source": source,
            "requested_field": label,
            "contract_field_type": customer_field_contract.field_type_from_detail_label(label),
            "evidence_status": "structured" if evidence_value else "missing",
            "evidence_field": evidence_field,
            "evidence_source": evidence_source,
            "evidence_value": evidence_value,
            "evidence_sku": sku if evidence_value else None,
            "evidence_scope": "subject" if evidence_value else None,
            "field_evidence_match": bool(evidence_value),
            "field_evidence_missing": not bool(evidence_value),
            "entity_resolution_contract": entity_contract.to_dict(),
        },
        "debug": {
            "agent_mode": source,
            "entity_resolution_contract": entity_contract.to_dict(),
            "single_product_resolution_decision": resolution_decision.to_dict(),
            "plan": {"primary_intent": "product_field", "product_ref": sku, "requested_field": label},
            "raw_results": [row],
            "candidate_skus": [sku],
        },
        "skip_polish": True,
    }


def _clarification_compatible_products(question: str, products: list[Product]) -> list[Product]:
    explicit_colors = [term for term in customer_agent_service.PRODUCT_COLOR_TERMS if term in str(question or "")]
    if not explicit_colors:
        return list(products)
    return [
        product
        for product in products
        if any(color in str(product.product_name_cn or product.product_name_en or "") for color in explicit_colors)
    ]


def _build_ambiguous_named_product_unknown_field_result(
    products: list[Product],
    *,
    label: str,
    question: str = "",
) -> dict:
    display_products = _clarification_compatible_products(question, products)[:5]
    rows = [_product_row_from_model(product) for product in display_products]
    options = "；".join(
        f"{str(product.product_name_cn or product.product_name_en or product.sku).strip()}（{str(product.sku or '').strip().upper()}）"
        for product in display_products
    )
    answer = (
        f"匹配到多个相关商品：{options}。请先指定 SKU 或具体款式；"
        f"另外，当前资料也未标注该类实时{label}信息，不能直接确认。"
        if options
        else f"没有找到与当前显式条件一致的明确商品。请提供 SKU 或更完整型号，再确认{label}信息。"
    )
    resolver_candidate_skus = [str(product.sku or "").strip().upper() for product in products[:5] if str(product.sku or "").strip()]
    clarification_candidate_skus = [str(product.sku or "").strip().upper() for product in display_products if str(product.sku or "").strip()]
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": answer,
        "results": [],
        "result_skus": [],
        "candidate_skus": resolver_candidate_skus,
        "clarification_candidate_skus": clarification_candidate_skus,
        "sku": None,
        "needs_clarification": True,
        "suggested_followups": ["请直接提供 SKU 或完整产品名。"],
        "followups": ["请直接提供 SKU 或完整产品名。"],
        "answer_metadata": {"source": "named_product_unknown_field_clarification", "requested_field": label, "evidence_status": "ambiguous_product"},
        "debug": {
            "agent_mode": "named_product_unknown_field_clarification",
            "plan": {"primary_intent": "clarify", "requested_field": label},
            "raw_results": rows,
            "candidate_skus": resolver_candidate_skus,
            "clarification_candidate_skus": clarification_candidate_skus,
        },
        "skip_polish": True,
    }


def _content_field_evidence_subtype(question: str, canonical_field: str | None) -> str | None:
    """Choose a content column only after the FieldContract has fixed its type."""
    text = str(question or "").casefold()
    field = str(canonical_field or "").strip()
    if field == "content_title":
        if "amazon" in text:
            return "content_title_amazon"
        if "官网" in text or "网站" in text:
            return "content_title_website"
        return "content_title_en" if "英文" in text or "english" in text else "content_title_cn"
    if field == "content_description":
        listing = "刊登" in text or "listing" in text
        english = "英文" in text or "english" in text
        if listing:
            return "content_description_listing_en" if english else "content_description_listing_cn"
        return "content_description_en" if english else "content_description_cn"
    return None


def _structured_product_field_evidence(
    canonical_field: str | None,
    *,
    db: Session,
    product: Product,
    specs: ProductSpecs | None,
    business: ProductBusiness | None,
    content: ProductContent | None,
    requested_subtype: str | None = None,
) -> tuple[str, str | None]:
    """Read the first non-empty value allowed by the canonical evidence policy."""
    policy = customer_field_contract.field_evidence_policy(canonical_field)
    if policy is None:
        return "", None
    if canonical_field == "specification":
        value = _specification_field_evidence(product=product, specs=specs)
        return (value, "specification.summary") if value else ("", None)
    if canonical_field in {"content_title", "content_description"}:
        if content is None:
            return "", None
        subtype = str(requested_subtype or "").strip()
        field_map = {
            "content_title_cn": "title_cn",
            "content_title_en": "title_en",
            "content_title_website": "website_title",
            "content_title_amazon": "amazon_title",
            "content_description_cn": "long_description_cn",
            "content_description_en": "long_description_en",
            "content_description_listing_cn": "listing_cn",
            "content_description_listing_en": "listing_en",
        }
        attribute = field_map.get(subtype)
        if not attribute:
            attribute = "title_cn" if canonical_field == "content_title" else "long_description_cn"
        value = _compound_display_value(getattr(content, attribute, ""))
        return (value, f"content.{attribute}") if _is_valid_structured_field_value(canonical_field, value) else ("", None)
    layers = {
        "product": product,
        "specs": specs,
        "business": business,
        "content": content,
    }
    for field_path in policy.structured_fields:
        if field_path.startswith("associations."):
            association = field_path.partition(".")[2]
            if association == "channels":
                values = [
                    str(row.channel_name or "").strip()
                    for row in (
                        db.query(ListingChannel)
                        .join(ProductListingChannel, ProductListingChannel.channel_id == ListingChannel.id)
                        .filter(ProductListingChannel.product_id == product.id)
                        .order_by(ListingChannel.channel_name.asc())
                        .all()
                    )
                ]
                source = "product_listing_channels->listing_channels"
            elif association == "regions":
                values = [
                    str(row.region_name or "").strip()
                    for row in (
                        db.query(SalesRegion)
                        .join(ProductSalesRegion, ProductSalesRegion.region_id == SalesRegion.id)
                        .filter(ProductSalesRegion.product_id == product.id)
                        .order_by(SalesRegion.region_name.asc())
                        .all()
                    )
                ]
                source = "product_sales_regions->sales_regions"
            elif association == "certifications":
                values = [
                    _certification_association_evidence(row)
                    for row in (
                        db.query(Certification)
                        .join(ProductCertification, ProductCertification.certification_id == Certification.id)
                        .filter(ProductCertification.product_id == product.id)
                        .order_by(Certification.certification_name.asc())
                        .all()
                    )
                ]
                source = "product_certifications->certifications"
            else:
                values, source = [], ""
            values = [item for item in values if _is_valid_structured_field_value(canonical_field, item)]
            if values:
                return "、".join(values), source
            continue
        layer_name, separator, attribute = str(field_path or "").partition(".")
        source = layers.get(layer_name)
        if not separator or source is None or not attribute:
            continue
        raw_value = getattr(source, attribute, None)
        value = (
            _weight_field_evidence(
                raw_value,
                capacity=getattr(specs, "capacity", "") if specs is not None else "",
            )
            if canonical_field == "weight" and field_path in {"specs.gross_weight_g", "specs.net_weight_g"}
            else
            _capacity_field_evidence(raw_value)
            if canonical_field == "capacity" and field_path == "specs.capacity"
            else _people_count_field_evidence(raw_value)
            if canonical_field == "people" and field_path in {"business.target_audience", "business.top_selling_points"}
            else _color_field_evidence(raw_value)
            if canonical_field == "color" and field_path == "specs.color"
            else _heat_source_field_evidence(raw_value)
            if canonical_field == "heat_source" and field_path == "specs.heat_source"
            else _selling_point_heat_source_evidence(raw_value)
            if canonical_field == "heat_source" and field_path == "business.top_selling_points"
            else _dishwasher_specific_evidence(raw_value)
            if canonical_field == "dishwasher"
            else _compound_display_value(raw_value)
        )
        if not _is_valid_structured_field_value(canonical_field, value):
            continue
        if field_path == "specs.usage_instruction" and canonical_field in {
            "usage_instruction",
            "cleaning",
            "care",
        }:
            if not _usage_instruction_matches_product(product, raw_value):
                continue
            value = (
                _machine_wash_specific_evidence(value)
                if canonical_field == "cleaning" and requested_subtype == "machine_wash"
                else _liquid_temperature_capability_evidence(value)
                if canonical_field == "usage_instruction" and requested_subtype == "liquid_temperature_capability"
                else _usage_instruction_field_evidence(
                    value,
                    canonical_field,
                    requested_subtype=requested_subtype,
                )
            )
            if not value:
                continue
        return value, field_path
    return "", None


def _weight_field_evidence(value: Any, *, capacity: Any = None) -> str:
    """Render a valid gram-column value without guessing an inconsistent unit."""
    try:
        grams = float(value)
    except (TypeError, ValueError):
        return ""
    if grams <= 0:
        return ""
    capacity_text = _capacity_field_evidence(capacity)
    capacity_liters = [
        float(match.group(1))
        for match in re.finditer(r"(\d+(?:\.\d+)?)\s*(?:L|l|升)", capacity_text)
    ]
    # ``gross_weight_g`` is explicitly a grams column.  A sub-five-gram value
    # alongside a 10L-or-larger capacity is an incompatible source-unit shape;
    # do not guess that the number means kilograms.  Fail closed until the
    # source data is corrected.
    if grams < 5 and any(liters >= 10 for liters in capacity_liters):
        return ""
    display = f"{grams:g}"
    return f"{display}g"


def _specification_field_evidence(
    *,
    product: Product,
    specs: ProductSpecs | None,
) -> str:
    """Build a field-scoped specification summary from validated SKU columns."""
    if specs is None:
        return ""
    parts: list[str] = []
    dimension = customer_field_contract.select_dimension_evidence(
        getattr(specs, "size_info", ""),
        requested_scope="subject",
    )
    if dimension and dimension.value:
        unit = f" {dimension.unit}" if dimension.unit else ""
        parts.append(f"尺寸：{dimension.value.replace('*', '×')}{unit}")
    def _without_own_label(value: Any, label: str) -> str:
        return re.sub(rf"^\s*{re.escape(label)}\s*[：:]\s*", "", str(value or "").strip())

    capacity = _without_own_label(_capacity_field_evidence(getattr(specs, "capacity", "")), "容量")
    if _is_valid_structured_field_value("capacity", capacity):
        parts.append(f"容量：{capacity}")
    weight = getattr(specs, "gross_weight_g", None)
    weight_display = _weight_field_evidence(weight, capacity=getattr(specs, "capacity", ""))
    if weight_display:
        parts.append(f"重量：{weight_display}")
    material = _without_own_label(_compound_display_value(getattr(specs, "body_material", "")), "材质")
    if _is_valid_structured_field_value("material", material):
        parts.append(f"材质：{material}")
    color = _without_own_label(_color_field_evidence(getattr(specs, "color", "")), "颜色")
    if _is_valid_structured_field_value("color", color):
        parts.append(f"颜色：{color}")
    power = _without_own_label(_compound_display_value(getattr(specs, "power", "")), "功率")
    if _is_valid_structured_field_value("power", power):
        parts.append(f"功率：{power}")
    return "；".join(parts)


def _certification_association_evidence(certification: Certification) -> str:
    """Preserve the dictionary explanation for a certification or standard label."""
    name = str(getattr(certification, "certification_name", "") or "").strip()
    description = str(getattr(certification, "description", "") or "").strip()
    if not description or description == name or description in name:
        return name
    return f"{name}（{description}）" if name else ""


def _is_valid_structured_field_value(canonical_field: str | None, value: Any) -> bool:
    """Reject placeholders before they become customer evidence."""
    text = _compound_display_value(value).strip()
    if not text or text.lower() in {"[]", "/", "null", "none", "n/a", "na", "unknown", "未分类", "未知", "暂无"}:
        return False
    if canonical_field == "barcode":
        return bool(re.fullmatch(r"\d{8,14}", text.replace(" ", "")))
    if canonical_field == "people":
        return bool(_people_count_field_evidence(text))
    return True


def _people_count_field_evidence(value: Any) -> str:
    """Return only an explicit serving headcount, never capacity or audience prose."""
    text = _compound_display_value(value).strip()
    match = re.search(
        r"(?:单人|双人|(?:(?:\d+\s*[-~至]\s*\d+)|(?:\d+)|[一二两三四五六七八九十]+)\s*(?:个)?人)",
        text,
    )
    return match.group(0) if match else ""








def _build_generic_ambiguous_unknown_field_clarification_result(
    question: str,
    *,
    label: str,
    products: list[Product] | None = None,
    subject_override: str | None = None,
) -> dict:
    resolver_products = list(products or [])[:5]
    display_products = _clarification_compatible_products(question, resolver_products)
    rows = [_product_row_from_model(product) for product in display_products]
    subject = subject_override or customer_agent_intent_service._detail_subject_from_question(question) or "这款商品"
    if rows:
        options = "；".join(
            f"{str(row.get('product_name_cn') or row.get('product_name_en') or row.get('sku') or '').strip()}（{str(row.get('sku') or '').strip().upper()}）"
            for row in rows
            if str(row.get("sku") or "").strip()
        )
        answer = (
            f"“{subject}”这个叫法可能对应多个相关商品：{options}。"
            f"请先指定 SKU 或更完整的款式名；另外，当前资料也未标注该类实时{label}信息，不能直接确认。"
        )
    else:
        answer = (
            f"“{subject}”这个叫法可能对应多个相关商品。"
            f"请先提供 SKU 或更完整的商品名；另外，当前资料也未标注该类实时{label}信息，不能直接确认。"
        )
    candidate_skus = [str(product.sku or "").strip().upper() for product in resolver_products if str(product.sku or "").strip()]
    clarification_candidate_skus = [str(row.get("sku") or "").strip().upper() for row in rows if str(row.get("sku") or "").strip()]
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": answer,
        "results": [],
        "result_skus": [],
        "candidate_skus": candidate_skus,
        "clarification_candidate_skus": clarification_candidate_skus,
        "sku": None,
        "needs_clarification": True,
        "suggested_followups": ["请直接提供 SKU 或完整产品名。"],
        "followups": ["请直接提供 SKU 或完整产品名。"],
        "answer_metadata": {"source": "named_product_unknown_field_clarification", "requested_field": label, "evidence_status": "ambiguous_product"},
        "debug": {
            "agent_mode": "named_product_unknown_field_clarification",
            "plan": {"primary_intent": "clarify", "requested_field": label},
            "raw_results": rows,
            "candidate_skus": candidate_skus,
            "clarification_candidate_skus": clarification_candidate_skus,
        },
        "skip_polish": True,
    }


def _enforce_field_evidence_policy(db: Session, question: str, agent_result: dict) -> dict:
    """Replace unsafe explicit-field answers with the deterministic same-SKU field result.

    This is deliberately narrow: only one explicit field, a single result SKU, and an
    exact canonical-name/SKU product mention can enter the guard. It cannot select a
    product for category, recommendation, comparison, or fuzzy entity requests.
    """
    if not isinstance(agent_result, dict):
        return agent_result
    navigation_metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    if navigation_metadata.get("source") == "semantic_product_navigation_contract":
        # This turn intentionally established only a sealed identity anchor.
        # Tokens in the product name must not be retrofitted into an
        # unrequested field answer by the evidence-repair layer.
        return agent_result
    # Reuse the formal field decision already attached by the central route.
    # Re-parsing only the raw wording here can turn an incidental lexical word
    # (such as ``brand`` in a price-tier question) into a different field and
    # overwrite a correct Phase-2 answer.  Semantic classification remains
    # allowlisted and is still incapable of supplying identity or evidence.
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    debug_plan = debug.get("plan") if isinstance(debug.get("plan"), dict) else {}
    attached_field_request = (
        debug.get("field_contract")
        if isinstance(debug.get("field_contract"), dict)
        else debug_plan.get("field_contract")
        if isinstance(debug_plan.get("field_contract"), dict)
        else None
    )
    # A generic QA contract is already sealed by exact entity resolution and
    # same-SKU QA evidence. Do not reinterpret it through an unrelated
    # semantic formal field during evidence-repair formatting.
    if str((attached_field_request or {}).get("field_type") or "").strip() == "product_qa":
        # A sealed semantic QA request may legitimately have no matching
        # same-SKU QA.  Its safe-missing response is still owned by the QA
        # contract; reparsing lexical fragments here must not relabel it as
        # an unrelated formal field (for example return policy -> heat source).
        return agent_result
    sealed_multi_fields = [
        str(field or "").strip()
        for field in (attached_field_request or {}).get("canonical_fields") or []
        if str(field or "").strip()
    ]
    sealed_evidence_skus = {
        str(sku or "").strip().upper()
        for sku in navigation_metadata.get("evidence_skus") or []
        if str(sku or "").strip()
    }
    result_skus = {
        str(sku or "").strip().upper()
        for sku in agent_result.get("result_skus") or []
        if str(sku or "").strip()
    }
    if (
        len(sealed_multi_fields) > 1
        and str((attached_field_request or {}).get("source") or "") == "validated_semantic_preplan"
        and len(result_skus) == 1
    ):
        # A resolved compound contract remains valid even when every requested
        # field is missing.  Requiring an evidence SKU here used to collapse
        # an all-missing answer to the first field during repair, silently
        # dropping the remaining customer request.
        return agent_result
    trusted_attached_field_sources = {
        "validated_semantic_preplan",
        "deterministic_full_predicate",
        "deterministic_alias",
    }
    attached_formal_field_type = (
        str(attached_field_request.get("field_type") or "").strip()
        if isinstance(attached_field_request, dict)
        and attached_field_request.get("source") in trusted_attached_field_sources
        and customer_field_contract.is_supported_detail_field(attached_field_request.get("field_type"))
        else None
    )
    semantic_preplan = debug.get("semantic_preplan") if isinstance(debug.get("semantic_preplan"), dict) else None
    formal_field_request = customer_field_contract.resolve_requested_field_contract(
        question,
        {"semantic_preplan": semantic_preplan} if semantic_preplan else None,
    )
    formal_field_type = (
        formal_field_request.get("field_type")
        if formal_field_request.get("source") == "validated_semantic_preplan"
        else None
    )
    field_contract = (
        customer_field_contract.field_contract_for_type(attached_formal_field_type or formal_field_type)
        if attached_formal_field_type or formal_field_type
        else customer_field_contract.detect_field_contract(question)
    )
    detected_field_types = customer_field_contract.detect_field_types(question)
    # A validated attached contract has already adjudicated the user's field.
    # Product names and parenthetical descriptors may contain another field
    # word (for example “赠品”), which must not exempt a mismatched QA answer
    # from same-field evidence enforcement.  Without that formal attachment,
    # preserve the existing fail-closed multi-field behavior.
    if not field_contract or (
        not attached_formal_field_type
        and not formal_field_type
        and len(detected_field_types) != 1
    ):
        return agent_result
    if str(agent_result.get("answer_type") or "") != "product_detail":
        return agent_result
    plan = debug.get("plan") if isinstance(debug.get("plan"), dict) else {}
    tasks = [task for task in (plan.get("tasks") or []) if isinstance(task, dict)]
    if (
        plan.get("routing_conflict")
        or plan.get("must_compare_both_products")
        or plan.get("must_make_choice")
        or len(tasks) > 1
    ):
        return agent_result
    result_skus = [str(sku or "").strip().upper() for sku in (agent_result.get("result_skus") or []) if str(sku or "").strip()]
    if len(result_skus) != 1:
        return agent_result
    product = _explicit_product_from_question(db, question)
    if not product or str(product.sku or "").strip().upper() != result_skus[0]:
        return agent_result
    requested_label = customer_field_contract.product_detail_field_label(field_contract.field_type)
    if not requested_label:
        return agent_result
    # Material components (body, lid, handle) have independent evidence scopes.
    # A generic material replacement would collapse them to body material and
    # can therefore invent a lid/handle fact from an otherwise valid response.
    if (
        field_contract.field_type == "material"
        and customer_field_contract.material_component_detail_requests(question)
    ):
        return agent_result
    metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    # Shipping is safely unsupported as a structured database field, but an
    # explicit same-SKU ProductQa record is an allowed evidence source under
    # the shipping FieldEvidencePolicy.  Preserve that sealed result instead
    # of rebuilding it as a generic real-time shipping safe-missing answer.
    # The metadata is created only after the QA helper has sealed both the
    # EntityResolutionContract and the field-compatible QA evidence.
    has_same_sku_shipping_qa_evidence = bool(
        field_contract.field_type == "shipping"
        and metadata.get("contract_field_type") == "shipping"
        and metadata.get("field_evidence_match") is True
        and str(metadata.get("evidence_field") or "") == "product_qa"
        and str(metadata.get("evidence_sku") or "").strip().upper() == result_skus[0]
        and str(metadata.get("evidence_source") or "").startswith("product_qa:")
    )
    if has_same_sku_shipping_qa_evidence:
        return agent_result
    # Warranty has no customer-facing structured column, but a sealed same-SKU
    # QA/RAG record may state the limited static fact that official warranty is
    # available. Preserve only that evidence-bound result; missing duration or
    # terms remain absent rather than becoming an invented policy.
    has_same_sku_warranty_evidence = bool(
        field_contract.field_type == "warranty"
        and metadata.get("contract_field_type") == "warranty"
        and metadata.get("field_evidence_match") is True
        and str(metadata.get("evidence_field") or "") == "warranty"
        and result_skus[0] in {
            str(metadata.get("evidence_sku") or "").strip().upper(),
            *(
                str(sku or "").strip().upper()
                for sku in metadata.get("evidence_skus") or []
            ),
        }
    )
    if has_same_sku_warranty_evidence:
        return agent_result
    if not customer_field_contract.is_supported_detail_field(field_contract.field_type):
        existing_entity_contract = (
            metadata.get("entity_resolution_contract")
            if isinstance(metadata.get("entity_resolution_contract"), dict)
            else debug.get("entity_resolution_contract")
            if isinstance(debug.get("entity_resolution_contract"), dict)
            else {}
        )
        if (
            metadata.get("contract_field_type") == field_contract.field_type
            and metadata.get("field_evidence_missing") is True
            and str(existing_entity_contract.get("resolved_sku") or "").strip().upper() == result_skus[0]
        ):
            return agent_result
        # Safely unsupported fields are never repaired from a different
        # structured field. Rebuild their answer through the exact-entity safe
        # boundary so a product-name token cannot replace (for example) a gift
        # request with heat-source evidence.
        entity_debug = debug.get("entity_resolution_contract") if isinstance(debug.get("entity_resolution_contract"), dict) else {}
        resolution_decision = customer_entity_resolution_contract.SingleProductResolutionDecision(
            allowed=True,
            resolved_sku=result_skus[0],
            resolved_product_id=str(product.id),
            reason="field_evidence_guard_exact_identity",
            match_level=str(entity_debug.get("matched_by") or "canonical_name_exact"),
        )
        route_source = str(debug.get("agent_mode") or metadata.get("source") or "resolved_entity_unknown_field_fallback")
        if route_source not in {"resolved_entity_detail_contract", "resolved_entity_unknown_field_fallback"}:
            route_source = "resolved_entity_unknown_field_fallback"
        replacement = _build_resolved_product_unknown_field_result(
            db,
            product,
            label=requested_label,
            source=route_source,
            resolution_decision=resolution_decision,
        )
        replacement_debug = replacement.get("debug") if isinstance(replacement.get("debug"), dict) else {}
        replacement_debug["field_contract"] = dict(attached_field_request or formal_field_request)
        if entity_debug:
            replacement_debug["entity_resolution_contract"] = dict(entity_debug)
        if isinstance(semantic_preplan, dict):
            replacement_debug["semantic_preplan"] = dict(semantic_preplan)
        replacement_debug["binding_provenance"] = "resolved_entity_contract"
        replacement_debug["field_evidence_guard_applied"] = True
        replacement["debug"] = replacement_debug
        return replacement
    evidence_field = str(metadata.get("evidence_field") or "").strip()
    evidence_sku = str(metadata.get("evidence_sku") or "").strip().upper()
    if evidence_field == field_contract.field_type and evidence_sku == result_skus[0]:
        return agent_result
    replacement = _phase1_product_field_result(db, {
        "primary_intent": "product_field",
        "answer_type": "product_detail",
        "product_ref": result_skus[0],
        "sku": result_skus[0],
        "requested_field": requested_label,
        "field_type_override": field_contract.field_type,
        "field_only": True,
        "product_identity_source": "field_evidence_repair",
        "raw_question": question,
    })
    if not replacement:
        return agent_result
    replacement_metadata = replacement.get("answer_metadata") if isinstance(replacement.get("answer_metadata"), dict) else {}
    if not evidence_field:
        evidence_value = str(replacement_metadata.get("evidence_value") or "").strip()
        normalized_answer = re.sub(r"[\s，,。；;：:（）()]", "", str(agent_result.get("answer") or ""))
        normalized_evidence = re.sub(r"[\s，,。；;：:（）()]", "", evidence_value)
        # A compound answer can legitimately combine the requested structured
        # field with another same-SKU QA/KB-supported intent. Preserve it when
        # the structured evidence is already visible in the answer; attach the
        # formal evidence metadata instead of collapsing the second intent.
        if normalized_evidence and normalized_evidence in normalized_answer:
            metadata.update({
                key: replacement_metadata.get(key)
                for key in (
                    "evidence_status",
                    "evidence_field",
                    "evidence_source",
                    "evidence_value",
                    "evidence_scope",
                    "evidence_sku",
                    "evidence_label",
                    "evidence_unit",
                    "evidence_subtype",
                    "field_evidence_match",
                    "field_evidence_missing",
                )
            })
            metadata["field_evidence_metadata_repaired"] = True
            agent_result["answer_metadata"] = metadata
            debug["field_evidence_guard_applied"] = True
            agent_result["debug"] = debug
            return agent_result
        requested_label = customer_field_contract.product_detail_field_label(field_contract.field_type) or ""
        safe_missing_markers = ("暂未", "未找到", "未维护", "未标注", "无法确认", "没有")
        if (
            replacement_metadata.get("field_evidence_missing") is True
            and requested_label
            and requested_label in str(agent_result.get("answer") or "")
            and any(marker in str(agent_result.get("answer") or "") for marker in safe_missing_markers)
        ):
            metadata.update({
                key: replacement_metadata.get(key)
                for key in (
                    "evidence_status",
                    "evidence_field",
                    "evidence_source",
                    "evidence_value",
                    "evidence_scope",
                    "evidence_sku",
                    "evidence_label",
                    "evidence_unit",
                    "evidence_subtype",
                    "field_evidence_match",
                    "field_evidence_missing",
                )
            })
            metadata["field_evidence_metadata_repaired"] = True
            agent_result["answer_metadata"] = metadata
            debug["field_evidence_guard_applied"] = True
            agent_result["debug"] = debug
            return agent_result
    replacement_debug = replacement.get("debug") if isinstance(replacement.get("debug"), dict) else {}
    replacement_debug["field_evidence_guard_applied"] = True
    # Evidence repair may change formatter provenance, never the already
    # sealed identity or formal field decision that caused the repair.
    if isinstance(attached_field_request, dict):
        replacement_debug["field_contract"] = dict(attached_field_request)
        replacement_plan = replacement_debug.get("plan") if isinstance(replacement_debug.get("plan"), dict) else {}
        replacement_plan["field_contract"] = dict(attached_field_request)
        if isinstance(debug_plan, dict):
            for key in ("primary_intent", "requested_field", "requested_fields", "product_ref"):
                if key in debug_plan:
                    replacement_plan[key] = debug_plan[key]
        replacement_debug["plan"] = replacement_plan
    if isinstance(debug.get("entity_resolution_contract"), dict):
        replacement_debug["entity_resolution_contract"] = dict(debug["entity_resolution_contract"])
    if isinstance(semantic_preplan, dict):
        replacement_debug["semantic_preplan"] = dict(semantic_preplan)
    replacement_debug["agent_mode"] = str(debug.get("agent_mode") or "resolved_entity_detail_contract")
    replacement["debug"] = replacement_debug
    replacement_metadata["qa_shortcut_rejected_reason"] = (
        "field_evidence_missing"
        if not evidence_field
        else "field_evidence_mismatch"
    )
    replacement_metadata["contract_field_type"] = field_contract.field_type
    if isinstance(metadata.get("timing"), dict):
        replacement_metadata["timing"] = dict(metadata["timing"])
    replacement["answer_metadata"] = replacement_metadata
    return replacement


def _build_unresolved_product_like_unknown_field_clarification_result(
    question: str,
    *,
    label: str,
    subject_override: str | None = None,
) -> dict | None:
    subject = subject_override or customer_agent_intent_service._detail_subject_from_question(question)
    if not subject:
        return None
    if not _looks_like_product_like_scope_subject(subject):
        return None
    if _is_generic_contents_subject(subject):
        return None
    product_like_suffixes = ("壶", "水壶", "锅", "套锅", "炉", "炉具", "烤盘", "盘", "杯", "茶具", "咖啡壶", " kettle")
    normalized_subject = customer_agent_service.normalize_search_text(subject).strip()
    if (
        not any(normalized_subject.endswith(suffix.strip()) for suffix in product_like_suffixes if suffix.strip())
        and not _looks_like_product_like_scope_subject(subject)
    ):
        return None
    answer = (
        f"我没能在当前商品资料里明确找到“{subject}”对应的具体 SKU。"
        f"你可以提供 SKU，或确认是哪一款商品，我再帮你判断这款商品的实时{label}类信息该去哪里确认。"
    )
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": answer,
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "needs_clarification": True,
        "answer_metadata": {
            "source": "unresolved_product_like_unknown_field_clarification",
            "requested_field": label,
            "evidence_status": "unresolved_product_like_subject",
        },
        "debug": {"agent_mode": "unresolved_product_like_unknown_field_clarification"},
        "skip_polish": True,
    }


def _generic_unresolved_product_like_unknown_field_clarification_result(
    question: str,
    *,
    label: str,
    subject_override: str | None = None,
) -> dict:
    subject = subject_override or customer_agent_intent_service._detail_subject_from_question(question) or "这款商品"
    answer = (
        f"我还没法把“{subject}”稳定对应到具体 SKU。"
        f"你可以提供 SKU 或更完整的商品名，我再帮你判断这款商品的实时{label}类信息该去哪里确认。"
    )
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": answer,
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "needs_clarification": True,
        "answer_metadata": {
            "source": "unresolved_product_like_unknown_field_clarification",
            "requested_field": label,
            "evidence_status": "unresolved_product_like_subject",
        },
        "debug": {"agent_mode": "unresolved_product_like_unknown_field_clarification"},
        "skip_polish": True,
    }


def _build_unknown_field_product_not_found_result(
    question: str,
    *,
    label: str,
    subject_override: str | None = None,
) -> dict:
    extracted_skus = [str(item or "").strip().upper() for item in customer_agent_service._extract_skus(question) if str(item or "").strip()]
    subject = subject_override or customer_agent_intent_service._detail_subject_from_question(question) or question
    target = extracted_skus[0] if extracted_skus else str(subject or "").strip()
    answer = f"没有找到“{target}”对应的产品资料，当前无法确认它的{label}信息。请确认 SKU 或产品名是否正确。"
    return {
        "intent": "product_detail",
        "answer_type": "product_detail",
        "answer": answer,
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "answer_metadata": {
            "source": "unknown_field_product_not_found",
            "requested_field": label,
            "evidence_status": "product_not_found",
        },
        "debug": {"agent_mode": "unknown_field_product_not_found"},
        "skip_polish": True,
    }




def _pre_route_high_risk_contract_result(
    db: Session,
    question: str,
    semantic_preplan: dict | None,
) -> dict | None:
    text = str(question or "").strip()
    if not text:
        return None
    field_contract = customer_field_contract.detect_field_contract(text)
    # A semantic recommendation that asks the catalogue to choose a product
    # owns the whole turn, including natural budget/price preferences.  The
    # legacy field detector can still see a negated word such as “价格” inside
    # that sentence; allowing it to run first would turn a recommendation into
    # a realtime-price clarification.  This is a semantic ownership veto only:
    # candidate facts and any live-price claim remain downstream contracts.
    semantic_recommendation_owned = bool(
        _semantic_preplan_route_family(semantic_preplan) == "recommendation"
        and (semantic_preplan or {}).get("decision_requested") is True
        and not bool((semantic_preplan or {}).get("fallback_reason"))
        and _semantic_preplan_confident(semantic_preplan, minimum=0.65)
    )
    if semantic_recommendation_owned:
        return None
    # A current-availability contract is not a live sales feed.  A question
    # phrased as "still sold?" is therefore a current availability request
    # even if the semantic provider mistakenly calls it product QA.  This is
    # a safety veto only: it supplies neither a route answer nor a product
    # fact and lets the existing safe-missing contract retain the resolved
    # identity.
    current_availability_request = bool(
        field_contract and field_contract.field_type in {"inventory", "lifecycle_status"}
    )
    # A validated product-QA turn has its own sealed identity and same-SKU
    # evidence path. This guard protects realtime and legacy unknown fields;
    # it must not reinterpret a product-QA subject before that contract can
    # resolve the entity and retrieve bounded QA/KB evidence.
    if (
        _semantic_prefers_sealed_product_qa({"semantic_preplan": semantic_preplan})
        and not current_availability_request
    ):
        return None
    generic_scope = customer_field_contract.select_entity_subject_for_routing(raw_question=text)
    if _is_generic_company_product_scope(generic_scope.entity_subject):
        # “你们产品” / “本店商品” denotes the merchant catalogue, never a
        # single product identity.  Let the generic business/FAQ route answer
        # it instead of converting a formal field signal into an unresolved
        # product clarification.
        return None
    if field_contract and field_contract.field_type in {"accessories", "warranty", "gift", "manual", "lifecycle_status"}:
        return None
    high_risk_field_types = {
        "after_sales_contact",
        "inventory",
        "price",
        "warranty",
        "shipping",
        "manual",
        "lifecycle_status",
    }
    # This early guard exists only for realtime/commercial or legacy unknown
    # facts. A different formal database field may contain a high-risk-looking
    # word (for example price_positioning contains "price"); it must continue
    # to the central FieldContract/EntityResolutionContract detail path.
    semantic_unknown_realtime = _semantic_preplan_unknown_realtime_subtype(semantic_preplan, text)
    if (
        field_contract
        and field_contract.field_type not in high_risk_field_types
        and not semantic_unknown_realtime
    ):
        return None
    semantic_field = str((semantic_preplan or {}).get("field_type") or "").strip()
    if (
        semantic_field
        and semantic_field in customer_field_contract.FORMAL_DETAIL_FIELDS
        and not bool((semantic_preplan or {}).get("fallback_reason"))
        and not bool((semantic_preplan or {}).get("ambiguity"))
        and _semantic_preplan_confident(semantic_preplan, minimum=0.9)
    ):
        # A schema-validated semantic detail field must reach Phase 2 before
        # broad legacy words such as "认证" or "价格" can trigger an
        # unknown-fact guard. This remains true when a weaker lexical parser
        # found a conflicting field such as price inside price positioning.
        # The semantic layer still supplies no identity or evidence.
        return None
    semantic_requested_fields = list(dict.fromkeys(
        customer_field_contract.semantic_preplan_field_type(field)
        for field in ((semantic_preplan or {}).get("canonical_fields") or [])
        if customer_field_contract.semantic_preplan_field_type(field)
        in customer_field_contract.FORMAL_DETAIL_FIELDS
    ))
    if (
        len(semantic_requested_fields) > 1
        and not bool((semantic_preplan or {}).get("fallback_reason"))
        and not bool((semantic_preplan or {}).get("ambiguity"))
        and _semantic_preplan_confident(semantic_preplan, minimum=0.9)
    ):
        # The central sealed multi-field executor renders each requested field
        # independently, including evidence-safe missing copy for realtime
        # inventory/price.  Consuming the turn here would keep only the first
        # legacy label and silently drop the rest of the customer's question.
        return None
    has_semantic_preplan = isinstance(semantic_preplan, dict) and semantic_preplan.get("called")
    deterministic_unknown_fields = {"manual", "after_sales_contact"}
    if not has_semantic_preplan and not (
        field_contract and field_contract.field_type in deterministic_unknown_fields
    ):
        return None
    if _looks_like_semantic_waterware_capability_query(text):
        return None
    # The semantic provider owns meaning for natural current-purchasability
    # wording.  Once it has emitted the validated unknown-realtime contract,
    # this layer supplies only the safe display label and sealed identity; it
    # must not require a second lexical alias before refusing an unverifiable
    # live-sales claim.
    label = (
        "在售状态"
        if current_availability_request or semantic_unknown_realtime
        else (_resolved_entity_realtime_commercial_field_guard_label(text) or _detect_unknown_product_fact_label(text))
    )
    if not label and field_contract and field_contract.field_type in deterministic_unknown_fields:
        label = customer_field_contract.product_detail_field_label(field_contract.field_type)
    if not label:
        return None
    supported_detail_field = customer_field_contract.is_supported_detail_field(
        field_contract.field_type if field_contract else None
    )
    subject_selection = customer_field_contract.select_entity_subject_for_routing(
        raw_question=text,
        fallback_product_like_subject=_product_like_scope_subject(text),
        fallback_named_subject=customer_agent_intent_service._detail_subject_from_question(text).strip(),
    )
    subject = subject_selection.entity_subject
    contract_products: list[Product] = []
    try:
        contract_products = db.query(Product).order_by(Product.sku.asc()).all()
        # Prefer a unique full catalogue mention contained in the current
        # turn over a field-adjacent subject polluted by a trailing discourse
        # pronoun (for example, "<product> it still sold?").  This is only
        # identity normalization: it neither chooses a field nor turns a
        # generic request into a product question.
        canonical_subject = customer_entity_resolution_contract.unique_canonical_subject_in_question(
            text,
            contract_products,
        )
        entity_selection = _choose_effective_entity_contract(
            text,
            contract_products,
            override_subject=canonical_subject or subject or None,
        )
        entity_contract = entity_selection.contract
    except Exception:
        entity_contract = None
    resolution_decision = customer_entity_resolution_contract.can_resolve_single_product(
        entity_contract,
        contract_products,
    )
    displayable_ambiguity_skus = _displayable_phase2_clarification_candidate_skus(entity_contract)
    if displayable_ambiguity_skus:
        displayable_set = set(displayable_ambiguity_skus)
        result = _build_ambiguous_named_product_unknown_field_result(
            [
                product
                for product in contract_products
                if str(product.sku or "").strip().upper() in displayable_set
            ],
            label=label,
            question=text,
        )
        debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
        debug["entity_resolution_contract"] = entity_contract.to_dict()
        result["debug"] = debug
        return result
    # A semantic ambiguity verdict is authoritative for identity safety. It
    # must be handled before a permissive lexical resolver can turn one of the
    # candidate names into a resolved product and answer a high-risk field.
    entity_scope_hint = str((semantic_preplan or {}).get("entity_scope") or "").strip()
    if entity_scope_hint == "ambiguous_product_name":
        named_products = _products_named_in_question(db, text)
        if len(named_products) > 1:
            return _build_ambiguous_named_product_unknown_field_result(named_products, label=label, question=text)
        return _build_generic_ambiguous_unknown_field_clarification_result(
            text,
            label=label,
            products=named_products,
            subject_override=str(((semantic_preplan or {}).get("entities") or [""])[0] or ""),
        )
    if resolution_decision.allowed:
        product = next(
            (
                item
                for item in contract_products
                if str(item.sku or "").strip().upper() == resolution_decision.resolved_sku
            ),
            None,
        )
        if product:
            field_type = str(field_contract.field_type or "").strip() if field_contract else ""
            if field_type and _best_product_qa_match(
                db,
                product,
                text,
                requested_field_type=field_type,
            ) is not None:
                # A same-SKU QA compatible with the already recognised formal
                # field is evidence for the central detail executor, not a
                # reason to emit a generic realtime-safe fallback early.
                return None
            result = _build_resolved_product_unknown_field_result(
                db,
                product,
                label=label,
                source="resolved_entity_unknown_field_fallback",
                resolution_decision=resolution_decision,
            )
            debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
            debug["entity_resolution_contract"] = entity_contract.to_dict()
            result["debug"] = debug
            return result
    subtype = str((semantic_preplan or {}).get("subtype") or "").strip()
    entity_scope_hint = str((semantic_preplan or {}).get("entity_scope") or "").strip()
    entity_texts = [
        str(item or "").strip()
        for item in ((semantic_preplan or {}).get("entities") or [])
        if str(item or "").strip()
    ]
    primary_entity = entity_texts[0] if entity_texts else ""

    named_products = _products_named_in_question(db, text)
    if primary_entity:
        entity_named_products = customer_agent_service.resolve_named_product_candidates(
            primary_entity,
            db.query(Product).all(),
            subject=primary_entity,
        )
        if len(entity_named_products) > len(named_products):
            named_products = entity_named_products
    if entity_scope_hint == "ambiguous_product_name":
        if len(named_products) > 1:
            return _build_ambiguous_named_product_unknown_field_result(named_products, label=label, question=text)
        return _build_generic_ambiguous_unknown_field_clarification_result(
            text,
            label=label,
            products=named_products,
            subject_override=primary_entity,
        )
    if len(named_products) > 1:
        return _build_ambiguous_named_product_unknown_field_result(named_products, label=label, question=text)
    if subtype == "no_match":
        return _build_unknown_field_product_not_found_result(text, label=label, subject_override=primary_entity)
    unresolved_clarification = _build_unresolved_product_like_unknown_field_clarification_result(
        text,
        label=label,
        subject_override=primary_entity,
    )
    if unresolved_clarification:
        return unresolved_clarification
    if entity_scope_hint == "unresolved_product_like":
        return _generic_unresolved_product_like_unknown_field_clarification_result(
            text,
            label=label,
            subject_override=primary_entity,
        )
    if customer_agent_service._extract_skus(text):
        return _build_unknown_field_product_not_found_result(text, label=label, subject_override=primary_entity)
    if subtype in _SEMANTIC_UNKNOWN_REALTIME_SUBTYPES:
        if unresolved_clarification:
            return unresolved_clarification
        if not primary_entity and not _has_unresolved_product_like_scope(db, text):
            return _unknown_product_fact_result(text, semantic_authorized=True)
        return None
    if label == "价格" and _looks_like_generic_constraint_category_query(text):
        return None
    if (
        not _contains_explicit_negative_product_marker(text)
        and not _looks_like_recommendation_request(text)
        and not customer_agent_intent_service._looks_like_contents_grounding_question(text)
        and (
            customer_agent_intent_service._looks_like_usage_care_question(text)
            or _looks_like_product_detail_field_question(text)
            or (
                supported_detail_field
                and str((semantic_preplan or {}).get("route_hint") or "").strip() == "product_detail"
            )
        )
    ):
        return {
            "intent": "clarify",
            "answer_type": "clarification",
            "answer": f"我还不能把“{primary_entity or subject or '该商品'}”稳定定位到唯一商品。请补充 SKU 或更完整的商品名，我再继续确认这个问题。",
            "results": [],
            "result_skus": [],
            "candidate_skus": [],
            "needs_clarification": True,
            "answer_metadata": {"source": "entity_scope_ambiguous_clarification", "evidence_status": "ambiguous_product"},
            "debug": {"agent_mode": "entity_scope_ambiguous_clarification"},
            "skip_polish": True,
        }
    if not primary_entity and not _has_unresolved_product_like_scope(db, text):
        return _unknown_product_fact_result(text)
    return None


def _semantic_missing_condition_label(
    question: str,
    semantic_preplan: dict | None,
    *,
    resolved_sku: str = "",
    product_name: str = "",
) -> str:
    """Keep a missing-evidence reply anchored to the customer's own condition.

    This is presentation support after identity is already sealed. It does
    not classify a route or authorize a fact. The label is derived from the
    semantic retrieval phrase when useful, then from the original question,
    with product identity and generic question grammar removed.
    """
    value = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    sources = [
        str(value.get("qa_evidence_query") or "").strip(),
        str(value.get("supplemental_qa_evidence_query") or "").strip(),
        str(question or "").strip(),
    ]
    removable_identities = [str(resolved_sku or "").strip(), str(product_name or "").strip()]
    removable_identities.extend(
        str(item or "").strip()
        for item in (value.get("entities") or [])
        if str(item or "").strip()
    )
    grammar = (
        "请问", "是否", "能不能", "能否", "可不可以", "可以不可以", "有没有", "有无",
        "怎么", "如何", "什么", "哪项", "哪种", "这款", "这件", "这个", "它的",
        "商品", "产品", "信息", "资料", "查询", "了解", "确认", "兼容", "适配",
        "支持", "使用", "能用", "可以用", "用", "能", "吗", "呢", "么", "呀", "啊",
    )
    for source in sources:
        if not source:
            continue
        cleaned = source
        asks_adjustability = bool(
            re.search(
                r"(?:是否|能不能|能否|可不可以|可以不可以|能|可以|可)?(?:调整|调节|调)(?:吗|呢|么)?[？?]?$",
                source,
            )
        )
        for identity in removable_identities:
            if identity:
                cleaned = re.sub(re.escape(identity), "", cleaned, flags=re.IGNORECASE)
        cleaned = re.sub(
            r"(?:是否|能不能|能否|可不可以|可以不可以|能|可以|可)?(?:调整|调节|调)(?:吗|呢|么)?[？?]?$",
            "",
            cleaned,
        )
        cleaned = re.sub(r"[，,。；;：:（）()【】\[\]“”‘’！!？?]", " ", cleaned)
        for term in grammar:
            cleaned = cleaned.replace(term, " ")
        cleaned = re.sub(r"\s+", " ", cleaned).strip()
        # Keep a short phrase that still contains a concrete customer noun;
        # discard pure leftovers such as "具体" or a lone question fragment.
        pieces = [item for item in re.findall(r"[\u4e00-\u9fffA-Za-z0-9_-]{2,}", cleaned) if item]
        pieces = [item for item in pieces if item not in {"具体", "当前", "还有", "相关", "是否"}]
        if pieces:
            label = max(pieces, key=len)[:24]
            if asks_adjustability and not label.endswith("是否可调"):
                return f"{label}是否可调"
            return label
    return ""






def _unknown_product_fact_result(question: str, *, semantic_authorized: bool = False) -> dict | None:
    # This legacy guard predates FieldContract/EntityResolutionContract.  It
    # may provide a safe generic answer only when the question has no formal
    # customer field signal.  Otherwise it would consume a field before the
    # conversation anchor can bind the product and before same-SKU evidence is
    # considered.
    formal_contract = customer_field_contract.detect_field_contract(question)
    if not semantic_authorized and formal_contract is not None and formal_contract.field_type != "price":
        return None
    label = _detect_unknown_product_fact_label(question)
    if not label:
        return None
    text = str(question or "").strip()
    scope = _semantic_catalog_product_ref(text)
    if label == "库存":
        answer = "当前资料未标注库存，也不能仅凭现有数据库确认实时库存；如需确认现货情况，建议联系人工客服或后台查询。"
    elif label == "销量":
        answer = "当前资料未标注销量，不能仅凭现有资料判断哪款销量最高。"
    elif label == "评价":
        answer = "当前资料未标注客户评价或好评率，不能仅凭现有资料判断评价高低。"
    elif label == "价格":
        answer = "当前资料未标注实时价格，不能仅凭现有资料确认当前售价；如需价格请联系人工客服或后台查询。"
    elif label == "保修":
        answer = "当前资料未标注保修信息，不能仅凭现有资料确认质保范围；建议联系人工客服确认。"
    elif label == "认证":
        answer = "当前资料未标注对应认证或检测信息，不能仅凭现有资料确认。"
    elif label == "官方说明书":
        answer = "当前资料未维护官方说明书信息，如需确认建议联系人工客服。"
    elif label == "售后电话":
        answer = "当前资料未维护正式售后电话号码，无法提供可核验的联系电话；请通过购买平台的官方客服入口确认。"
    elif label == "安装视频":
        answer = "当前资料未维护安装视频信息，如需确认建议联系人工客服。"
    elif label == "发货时效":
        answer = (
            "目前无法承诺今天下单后明天发货或送达，实际时效会受库存、下单时间、仓库和收货地区影响，"
            "请以下单页显示的预计发货/送达时间为准；如果时间很紧，建议下单前通过店铺客服确认库存和最晚发出时间。"
        )
    else:
        return None
    if scope != "产品" and scope not in {"烤盘", "锅具", "炉具", "水具", "水壶", "咖啡器具", "茶具", "桌椅", "餐具", "配件", "天幕/地垫/帐篷"}:
        scope = "产品"
    if scope != "产品" and not SKU_RE.search(text):
        answer = f"关于【{scope}】类产品，{answer}"
    return {
        "intent": "product_detail",
        "answer_type": "product_detail",
        "answer": answer,
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "answer_metadata": {"source": "structured_unknown_field_guard", "requested_field": label},
        "debug": {
            "agent_mode": "structured_unknown_field_guard",
            "plan": {"primary_intent": "product_field", "requested_field": label, "product_ref": ""},
            "raw_results": [],
        },
        "skip_polish": True,
    }


def _structured_filter_field_and_value(question: str) -> tuple[str, str] | None:
    text = str(question or "").strip()
    if not text:
        return None
    field_aliases = {
        "材质": ("材质", "材料"),
        "热源": ("热源", "燃气炉", "卡式炉", "明火", "酒精炉"),
    }
    value_aliases = {
        "不锈钢": ("不锈钢", "304", "316"),
        "铝合金": ("铝合金", "铝"),
        "燃气炉": ("燃气炉", "卡式炉", "明火"),
    }
    matched_field = None
    for field_name, aliases in field_aliases.items():
        if any(alias in text for alias in aliases):
            matched_field = field_name
            break
    matched_value = None
    for value_name, aliases in value_aliases.items():
        if any(alias in text for alias in aliases):
            matched_value = value_name
            break
    if matched_field is None and matched_value in {"不锈钢", "铝合金"}:
        material_shortcuts = (
            f"是{matched_value}的",
            f"要{matched_value}的",
            f"选{matched_value}的",
        )
        if any(pattern in text for pattern in material_shortcuts):
            matched_field = "材质"
    if matched_field == "热源" and matched_value == "燃气炉":
        return matched_field, matched_value
    if matched_field == "材质" and matched_value in {"不锈钢", "铝合金"}:
        return matched_field, matched_value
    return None


def _phase1_structured_field_filter_intent(question: str):
    text = str(question or "").strip()
    if _looks_like_semantic_waterware_capability_query(text):
        return None
    if "咖啡器具" in text and "手冲" in text and "配件" not in text:
        return None
    if customer_agent_intent_service._looks_like_alcohol_stove_cookware_recommendation_question(text):
        return None
    if _looks_like_multi_condition_cookware_recommendation(text):
        return None
    if not any(term in text for term in ("哪些", "有哪些", "哪一些", "列出")):
        return None
    intent = customer_agent_intent_service.parse_intent(text, previous_result_skus=[])
    if not intent or intent.intent != "query_products":
        return None
    filters = intent.filters or {}
    if not str(filters.get("product.category") or "").strip():
        return None
    if str(filters.get("specs.body_material") or "").strip():
        return intent
    if str(filters.get("specs.heat_source") or "").strip():
        return intent
    if str(filters.get("business.usage_scenarios") or "").strip():
        return intent
    if str(filters.get("specs.capacity") or "").strip():
        return intent
    if str(filters.get("specs.gross_weight_g") or "").strip():
        return intent
    if str(filters.get("business.target_audience") or "").strip():
        return intent
    if str(filters.get("business.price_positioning") or "").strip():
        return intent
    if intent.negative_filters:
        return intent
    return None


def _structured_hard_filter_contract(question: str) -> dict[str, Any]:
    text = str(question or "").strip()
    if not text or SKU_RE.search(text):
        return {}
    target_category = _structured_target_category_from_question(text)
    if not target_category:
        semantic_category = _semantic_catalog_product_ref(text)
        if semantic_category != "产品":
            target_category = semantic_category
    # This is deliberately a narrow execution adapter, rather than an
    # alternate intent router.  A customer can ask to select a generic
    # catalogue category by one formally supported, evidence-backed property.
    # The category plus formal field are the executable contract; no wording
    # list decides whether a customer is "really" selecting products.
    # Named products are excluded above by the entity contract before this
    # function is allowed to execute.
    explicit_dishwasher_catalog_selection = bool(target_category and "洗碗机" in text)
    targeted_heat_recommendation = bool(
        target_category
        and "推荐" in text
        and any(term in text for term in ("燃气炉", "卡式炉", "电磁炉", "电陶炉", "酒精炉", "明火"))
    )
    if (
        not any(term in text for term in ("哪些", "有哪些", "哪一些", "列出"))
        and not targeted_heat_recommendation
        and not explicit_dishwasher_catalog_selection
    ):
        return {}
    if _looks_like_semantic_waterware_capability_query(text):
        return {}
    if "咖啡器具" in text and "手冲" in text and "配件" not in text:
        return {}
    if customer_agent_intent_service._looks_like_alcohol_stove_cookware_recommendation_question(text):
        return {}
    if _looks_like_multi_condition_cookware_recommendation(text):
        return {}
    soft_preference_count = sum(
        1
        for matched in (
            any(term in text for term in ("两个人", "两人", "2人", "双人")),
            any(term in text for term in ("轻量", "轻便", "别太重")),
            any(term in text for term in ("预算低", "预算不高", "预算低一点", "便宜点", "性价比")),
            "新手" in text,
        )
        if matched
    )
    if soft_preference_count >= 2 and any(term in text for term in ("锅具", "锅", "炉具", "炉")):
        return {}

    intent = customer_agent_intent_service.parse_intent(text, previous_result_skus=[])
    filters = dict((intent.filters or {}) if intent else {})
    negative_filters = dict((intent.negative_filters or {}) if intent else {})
    requested_fields = list((intent.requested_fields or []) if intent else [])

    lowered = text.lower()
    product_ref = str(filters.get("product.category") or "").strip()
    if target_category:
        product_ref = target_category
        filters["product.category"] = target_category
    elif "水壶" in text or ("哪些壶" in text and "咖啡壶" not in text and "茶壶" not in text):
        product_ref = "水壶"
        filters["product.category"] = "水壶"
    elif any(term in text for term in ("水杯", "杯子", "钛杯", "杯")):
        product_ref = "水具"
        filters["product.category"] = "水杯"
    elif any(term in text for term in ("锅具", "套锅", "单锅")) or ("锅" in text and "火锅" not in text):
        product_ref = "锅具"
        filters["product.category"] = "锅具"
    elif any(term in text for term in ("炉具", "炉子", "卡式炉", "酒精炉")):
        product_ref = "炉具"
        filters["product.category"] = "炉具"
    elif "配件" in text:
        product_ref = "配件"
        filters["product.category"] = "配件"
    elif "咖啡器具" in text:
        product_ref = "咖啡器具"
        filters["product.category"] = "咖啡器具"
    elif "水具" in text:
        product_ref = "水具"
        filters["product.category"] = "水具"

    if not str(filters.get("specs.body_material") or "").strip():
        for raw_value in ("硬质氧化铝合金", "硬质氧化铝", "铝合金", "不锈钢", "钛"):
            if raw_value in text:
                normalized = customer_agent_intent_service._normalize_structured_filter_value("specs.body_material", raw_value)
                if normalized:
                    filters["specs.body_material"] = normalized
                    if "材质" not in requested_fields:
                        requested_fields.append("材质")
                    break

    if not str(filters.get("specs.heat_source") or "").strip():
        if "酒精炉" in text:
            filters["specs.heat_source"] = "酒精炉"
        elif "卡式炉" in text:
            filters["specs.heat_source"] = "卡式炉"
        elif "电磁炉" in text:
            filters["specs.heat_source"] = "电磁炉"
        elif "电陶炉" in text:
            filters["specs.heat_source"] = "电陶炉"
        elif "明火直烧" in text:
            filters["specs.heat_source"] = "明火直烧"
        elif "明火" in text or "直接加热" in text:
            filters["specs.heat_source"] = "明火"
        if str(filters.get("specs.heat_source") or "").strip() and "热源" not in requested_fields:
            requested_fields.append("热源")

    usage_filter = str(filters.get("business.usage_scenarios") or "").strip()
    heat_source_filter = str(filters.get("specs.heat_source") or "").strip()
    if target_category and heat_source_filter and heat_source_filter in usage_filter:
        filters.pop("business.usage_scenarios", None)
        requested_fields = [field for field in requested_fields if field != "适用场景"]

    if not str(filters.get("business.usage_scenarios") or "").strip():
        if "徒步" in text:
            filters["business.usage_scenarios"] = "徒步"
        elif "咖啡相关配件" in text:
            filters["business.usage_scenarios"] = "咖啡"
        if str(filters.get("business.usage_scenarios") or "").strip() and "适用场景" not in requested_fields:
            requested_fields.append("适用场景")

    dishwasher_field_requested = explicit_dishwasher_catalog_selection or _structured_contract_requests_dishwasher_field(
        text=text,
        requested_fields=requested_fields,
        filters=filters,
        negative_filters=negative_filters,
    )
    if dishwasher_field_requested:
        filters["_contract.dishwasher"] = "洗碗机"
    if "不能进洗碗机" in text or "不能放洗碗机" in text or "不可进洗碗机" in text or "不适合洗碗机" in text:
        negative_filters["_contract.dishwasher"] = "洗碗机"
        filters.pop("_contract.dishwasher", None)
    if "轻量" in text or "轻便" in text or "别太重" in text or "比较轻" in text:
        filters["_contract.lightweight"] = "true"
    if "徒步" in text:
        filters["_contract.hiking"] = "true"
    if "两个人" in text or "两人" in text or "2人" in text or "双人" in text:
        filters["_contract.two_person"] = "true"
    if "新手" in text:
        filters["_contract.beginner"] = "true"
    # Budget is a semantic ranking preference backed by the catalogue's
    # price_positioning field.  It is deliberately not serialized into this
    # legacy structured-filter adapter: doing so turns a natural hint into a
    # hard lexical eligibility test and can discard valid candidates.
    if "咖啡相关配件" in text:
        filters["_contract.coffee_accessory"] = "true"

    if not product_ref:
        product_ref = _semantic_catalog_product_ref(text)
    if product_ref == "产品":
        product_ref = ""

    hard_filter_keys = {
        key
        for key in filters.keys()
        if key != "product.category"
    }
    hard_filter_keys.update(negative_filters.keys())
    if not product_ref or not hard_filter_keys:
        return {}
    return {
        "intent": intent,
        "product_ref": product_ref,
        "filters": filters,
        "negative_filters": negative_filters,
        "requested_fields": requested_fields,
    }




def _structured_contract_requests_dishwasher_field(
    *,
    text: str,
    requested_fields: list[str],
    filters: dict[str, Any],
    negative_filters: dict[str, Any],
) -> bool:
    if str(negative_filters.get("_contract.dishwasher") or "").strip():
        return False
    if str(filters.get("_contract.dishwasher") or "").strip():
        return True
    requested_field_paths = {
        str(customer_agent_intent_service._resolve_query_field(field) or "").strip()
        for field in requested_fields
        if field
    }
    if "specs.usage_instruction" not in requested_field_paths:
        return False
    dishwasher_signals = {"洗碗机"}
    if any(signal in str(text or "") for signal in dishwasher_signals):
        return True
    return False


def _structured_row_matches_contract(row: dict[str, Any], contract: dict[str, Any]) -> bool:
    filters = dict(contract.get("filters") or {})
    negative_filters = dict(contract.get("negative_filters") or {})
    row_text = _structured_query_row_text(row)
    row_text_lower = row_text.lower()
    weight_raw = row.get("gross_weight_g")
    try:
        weight_value = float(weight_raw or 0)
    except (TypeError, ValueError):
        weight_value = 0.0
    capacity_text = str(row.get("capacity") or "")

    dishwasher_required = bool(filters.pop("_contract.dishwasher", ""))
    dishwasher_required_negative = bool(negative_filters.pop("_contract.dishwasher", ""))
    lightweight_required = bool(filters.pop("_contract.lightweight", ""))
    hiking_required = bool(filters.pop("_contract.hiking", ""))
    two_person_required = bool(filters.pop("_contract.two_person", ""))
    beginner_required = bool(filters.pop("_contract.beginner", ""))
    # Backward-compatible cleanup for callers that still carry the old flag.
    # It must never reach the generic lexical filter below as an eligibility
    # condition.
    filters.pop("_contract.budget", None)
    coffee_accessory_required = bool(filters.pop("_contract.coffee_accessory", ""))

    category_value = str(filters.pop("product.category", "") or "").strip()
    body_material_value = str(filters.pop("specs.body_material", "") or "").strip()
    heat_source_value = str(filters.pop("specs.heat_source", "") or "").strip()
    usage_value = str(filters.pop("business.usage_scenarios", "") or "").strip()

    if body_material_value:
        material_contract = customer_structured_query_contract.StructuredQueryContract(
            subject_category=category_value or "all_products",
            field="material",
            operator="contains",
            value=body_material_value,
            status="resolved",
        )
        if not customer_structured_query_contract.match_material_condition(
            contract=material_contract,
            row=row,
        )["matched"]:
            return False
    elif category_value and not _structured_row_matches_category_value(row, category_value):
        return False
    if heat_source_value and not _structured_row_matches_heat_value(row, heat_source_value):
        return False
    if usage_value and not _structured_row_matches_usage_value(row, usage_value):
        return False
    if filters and not customer_agent_intent_service._filter_rows([row], filters=filters, negative_filters={}, term=""):
        return False
    if negative_filters and not customer_agent_intent_service._filter_rows([row], filters={}, negative_filters=negative_filters, term=""):
        return False

    if coffee_accessory_required and not any(term in row_text for term in ("咖啡", "手冲", "滤杯", "细口壶", "分享壶")):
        return False
    if dishwasher_required and not any(
        term in row_text
        for term in ("洗碗机", "可放入洗碗机", "可进洗碗机", "适合洗碗机", "可洗碗机清洗")
    ):
        return False
    if dishwasher_required_negative and not any(
        term in row_text
        for term in ("不适合洗碗机", "不可放入洗碗机", "不能放进洗碗机", "不能进洗碗机", "勿入洗碗机")
    ):
        return False
    if lightweight_required and not (
        any(term in row_text for term in ("轻量", "轻便", "便携"))
        or (0 < weight_value <= 350)
    ):
        return False
    if hiking_required and not any(term in row_text for term in ("徒步", "轻量", "便携")):
        return False
    if two_person_required and not (
        any(term in row_text for term in ("两人", "两个人", "2人", "双人", "1-2人"))
        or any(term in capacity_text for term in ("1-2人", "2人"))
    ):
        return False
    if beginner_required and not any(term in row_text for term in ("新手", "入门", "基础", "性价比")):
        return False
    return True


def _looks_like_structured_field_filter_query(question: str) -> bool:
    text = str(question or "").strip()
    if not text or SKU_RE.search(text):
        return False
    if customer_agent_intent_service._looks_like_alcohol_stove_cookware_recommendation_question(text):
        return False
    if _looks_like_multi_condition_cookware_recommendation(text):
        return False
    # The shared structured-query contract already understands natural
    # predicates such as “容量不小于 1 升”.  Do not make a second lexical gate
    # rediscover that predicate: if the contract resolved an explicit
    # condition, the structured executor is the correct owner of it.
    try:
        resolved_contract = customer_structured_query_contract.build_structured_query_contract(text)
    except Exception:
        resolved_contract = None
    if (
        resolved_contract is not None
        and resolved_contract.status == "resolved"
        and bool(resolved_contract.conditions)
    ):
        return True
    if _structured_hard_filter_contract(text):
        return True
    if _phase1_structured_field_filter_intent(text):
        return True
    if not any(term in text for term in ("有哪些", "哪些", "哪一些", "推荐", "找")):
        return False
    if _semantic_catalog_product_ref(text) == "产品":
        return False
    return _structured_filter_field_and_value(text) is not None


def _looks_like_semantic_waterware_capability_query(question: str) -> bool:
    text = str(question or "").strip()
    if not text or SKU_RE.search(text):
        return False
    if any(term in text for term in ("怎么选", "推荐", "想买", "买个", "买一", "选哪", "哪款", "哪种")):
        return False
    if not any(term in text for term in ("有哪些", "哪一些", "找", "列出")):
        return False
    if not any(term in text for term in ("水具", "水壶", "水杯")):
        return False
    return any(term in text for term in ("冷水", "补水", "饮水", "热水", "装热水", "喝热水"))


def _structured_field_filter_result(db: Session, question: str) -> dict | None:
    text = str(question or "").strip()
    if not text or _is_internal_catalogue_filter_query(text):
        return None
    # This executor is entered only after Flash has classified the turn as a
    # structured query and the typed contract has resolved.  Do not run a
    # second Chinese keyword parser here: it used to turn natural selection
    # requests into a legacy field-filter route and was a frequent source of
    # route theft.
    resolved_contract = customer_structured_query_contract.build_structured_query_contract(text)
    if resolved_contract.status != "resolved" or not resolved_contract.conditions:
        return None
    product_ref = str(resolved_contract.subject_category or "").strip()
    if not product_ref or product_ref == "产品":
        return None
    source_rows = _phase1_catalog_rows(db, product_ref)
    rows = [
        row
        for row in source_rows
        if customer_structured_query_contract.evaluate_structured_row(row, resolved_contract).get("matched")
    ]
    if not rows:
        # A local parser miss must not become a customer-facing canned
        # conclusion.  The semantic executor decides whether the turn is a
        # true no-match, needs a broader RAG explanation, or should ask a
        # follow-up; returning None keeps that ownership intact.
        return None
    return _structured_product_query_result(
        question=text,
        product_ref=product_ref,
        rows=rows,
        source="structured_category_field_filter_query",
        reason_label=f"{product_ref} / 结构化硬筛选条件",
    )






def _looks_like_multi_condition_cookware_recommendation(question: str) -> bool:
    text = str(question or "").strip()
    if not text or SKU_RE.search(text):
        return False
    if not any(term in text for term in ("锅具", "锅", "套锅", "炊具")):
        return False
    if any(term in text for term in ("水壶", "水具", "水杯", "壶")):
        return False
    has_group_or_scene = any(term in text for term in ("4人以上", "4人", "四口", "多人", "家庭", "露营", "户外", "新手"))
    has_constraints = any(term in text for term in ("容量大", "容量要大", "大容量", "燃气炉", "卡式炉", "明火", "别太重", "轻", "轻量", "轻便"))
    has_budget_preference = any(term in text for term in ("价格别太高", "别太贵", "不要太贵", "预算不高", "预算有限", "便宜点", "性价比"))
    has_selection = any(term in text for term in ("推荐", "怎么选", "买什么", "买锅具", "有哪些", "用什么"))
    return has_group_or_scene and (has_constraints or has_budget_preference) and (has_selection or "。" in text)






def _normalize_recommendation_scope_label(value: str) -> str:
    ref = _semantic_catalog_product_ref(str(value or "").strip())
    return {
        "燃气炉": "炉具",
        "酒精炉": "炉具",
        "炉具": "炉具",
        "水壶": "水具",
        "烧水壶": "水具",
        "水具": "水具",
        "锅具": "锅具",
        "煮面锅": "锅具",
        "烤盘": "锅具",
        "煎盘": "锅具",
        "配件": "配件",
    }.get(ref, ref if ref != "产品" else str(value or "").strip())


def _normalized_recommendation_scope_skus(value: Any) -> dict[str, list[str]]:
    if not isinstance(value, dict):
        return {}
    normalized: dict[str, list[str]] = {}
    for raw_label, raw_skus in value.items():
        label = _normalize_recommendation_scope_label(str(raw_label or ""))
        if not label:
            continue
        for raw_sku in raw_skus if isinstance(raw_skus, (list, tuple)) else []:
            sku = str(raw_sku or "").strip().upper()
            if sku and sku not in normalized.setdefault(label, []):
                normalized[label].append(sku)
    return normalized


def _multi_category_recommendation_row_is_sellable(row: dict[str, Any]) -> bool:
    lifecycle = str(row.get("lifecycle_status") or "").strip()
    return not any(
        term in lifecycle
        for term in ("禁用", "老款无货", "下架", "停售", "未上市", "暂停开发")
    )







def _semantic_structured_query_result(
    db: Session,
    question: str,
    *,
    candidate_context: dict[str, Any] | None = None,
    semantic_preplan: dict[str, Any] | None = None,
) -> dict | None:
    text = str(question or "").strip()
    if not text:
        return None
    # Internal catalogue predicates such as owner/lifecycle are parsed by the
    # deterministic query contract. This semantic category adapter only
    # understands public catalogue scope and would otherwise widen
    # "负责人 Max 的锅具" to every cookware row.
    if _is_internal_catalogue_filter_query(text):
        return None
    # A high-confidence semantic product-QA decision owns the whole-turn
    # meaning.  This catalogue executor is only a fallback for genuine
    # category/filter/recommendation requests, so it must yield before any
    # deterministic cookware or category heuristic can reinterpret the
    # named product as a set of alternatives. Entity and same-SKU evidence
    # validation continue in the later sealed product-QA path.
    if _semantic_product_qa_preempts_legacy_shortcuts(semantic_preplan):
        return None
    # A semantic recommendation is a choice among products, not an exhaustive
    # catalogue listing.  This prevents a formal predicate embedded in a
    # recommendation sentence from being consumed by the catalogue executor.
    # The recommendation executor will apply the same typed predicate to each
    # candidate and then let RAG explain the choice.
    if (
        _semantic_preplan_route_family(semantic_preplan) == "recommendation"
        and bool((semantic_preplan or {}).get("decision_requested"))
        and not bool((semantic_preplan or {}).get("ambiguity"))
    ):
        return None
    if _should_keep_preruntime_for_scoped_heat_source_followup(
        text,
        candidate_context=candidate_context,
    ):
        return None
    if _has_resolved_entity_contents_accessories_question(db, text):
        return None
    # A generic catalogue recommendation cannot consume a product-like
    # subject that EntityResolutionContract cannot bind.  Otherwise an
    # unrecognised name followed by “推荐” silently becomes a recommendation
    # for a different catalogue product.
    if _has_unresolved_product_like_scope(db, text):
        return None
    # Let the shared typed predicate own an explicit field condition before a
    # semantic category/family scope can widen it into an unfiltered listing.
    # This is especially important for natural numeric forms such as
    # “容量不小于 1 升的水壶”.
    try:
        resolved_contract = customer_structured_query_contract.build_structured_query_contract(text)
    except Exception:
        resolved_contract = None
    if (
        resolved_contract is not None
        and resolved_contract.status == "resolved"
        and bool(resolved_contract.conditions)
    ):
        # Once a typed condition is present, this executor must not widen a
        # zero-match result into an unfiltered category listing.  The adapter
        # may return a bounded row set or None; either way the semantic owner
        # handles the customer-facing explanation.
        return _structured_field_filter_result(db, text)
    semantic_subject = str((semantic_preplan or {}).get("subject_text") or "").strip()
    all_catalog_rows = _phase1_catalog_rows(db, "产品")
    category_ref = _database_category_scope_ref(all_catalog_rows, semantic_subject)
    semantic_scope_rows = (
        _database_product_family_scope_rows(all_catalog_rows, semantic_subject)
        if semantic_subject and not category_ref
        else []
    )
    if (
        len(semantic_scope_rows) <= 1
        and str((semantic_preplan or {}).get("field_type") or "").strip() == "series"
    ):
        semantic_scope_rows = _database_question_product_family_scope_rows(
            all_catalog_rows,
            text,
        )
    if (
        _semantic_preplan_confident(semantic_preplan, minimum=0.9)
        and _semantic_preplan_route_family(semantic_preplan) in {"structured_query", "recommendation"}
        and semantic_subject
        and not category_ref
        and len(semantic_scope_rows) > 1
        and not customer_agent_service._extract_skus(text)
    ):
        return _structured_product_query_result(
            question=text,
            product_ref=semantic_subject,
            rows=semantic_scope_rows,
            source="semantic_catalog_family_scope",
            reason_label="已验证商品族范围",
            answer_type="query_products",
            metadata_source="product_catalog_family_query",
        )
    # A structured catalogue query never owns the field meaning of an already
    # resolved product. A loose name recall is not enough here: a generic
    # attribute phrase such as "轻量锅具" may overlap an unrelated product name
    # (for example "轻量保温杯"). Only a sealed EntityResolutionContract may
    # defer this catalogue query to product detail.
    if _has_resolved_named_product_contract(db, text):
        return None
    # For a high-confidence catalogue request, semantic planning has already
    # interpreted the whole utterance and supplied only a generic catalogue
    # scope.  Resolve that scope through the database search provider instead
    # of requiring a second lexical recognizer to rediscover the same term.
    # The plan cannot supply products, SKUs, or facts: all candidates remain
    # bounded by the actual database result set.
    semantic_fields = list((semantic_preplan or {}).get("canonical_fields") or [])
    if (
        _semantic_preplan_confident(semantic_preplan, minimum=0.9)
        and _semantic_preplan_route_family(semantic_preplan) == "structured_query"
        and semantic_fields == ["category"]
        and semantic_subject
    ):
        # Semantic planning owns the meaning "this is a catalogue category
        # request"; this adapter only resolves that abstract subject against
        # the categories actually present in the database.  A lexical product
        # search is deliberately not an acceptable substitute: "锅" may
        # occur in a kettle or stove name while the customer asks for the
        # database's cookware category.
        category_rows = _phase1_catalog_rows(db, "产品")
        category_ref = _database_category_scope_ref(category_rows, semantic_subject)
        if category_ref:
            # Counting is a semantic operation, not something this executor
            # should rediscover from Chinese count words.  Flash may mark the
            # structured plan as ``question_type=count``; otherwise the same
            # category scope is returned as a catalogue listing.
            if str((semantic_preplan or {}).get("question_type") or "").strip() == "count":
                return _phase1_catalog_count_result(
                    db,
                    {"product_ref": category_ref, "raw_question": text},
                )
            rows = _phase1_catalog_rows(db, category_ref)
            return _structured_product_query_result(
                question=text,
                product_ref=category_ref,
                rows=rows,
                source="structured_catalog_semantic_category_scope",
                reason_label="语义目录范围",
                answer_type="query_products",
                metadata_source="product_catalog_structured_query",
            )
        rows = customer_agent_service.search_products(db, semantic_subject, limit=50)
        return _structured_product_query_result(
            question=text,
            product_ref=semantic_subject,
            rows=rows,
            source="structured_catalog_count",
            reason_label="语义目录范围",
            answer_type="query_products",
            metadata_source="product_catalog_structured_query",
        )
    # No lexical category/capability branch follows this point.  If Flash did
    # not provide a verified structured scope or typed condition, let the
    # semantic owner/RAG fallback explain the limitation or ask a useful
    # follow-up.  Re-parsing the same sentence here is how the old rule tree
    # used to steal turns from the semantic plan.
    return None


def _semantic_prefers_sealed_product_qa(phase1_plan: dict[str, Any]) -> bool:
    """Reserve generic product facts for the sealed same-SKU QA path.

    The semantic preplan owns the meaning of an utterance.  This guard only
    recognizes its schema-validated decision that a named product asks for a
    product-specific fact outside the formal field taxonomy; it never derives
    a field, product, or answer from wording.  Entity resolution and exact
    same-SKU QA matching remain mandatory in ``_try_product_qa_shortcut``.
    """
    plan = phase1_plan if isinstance(phase1_plan, dict) else {}
    preplan = plan.get("semantic_preplan") if isinstance(plan.get("semantic_preplan"), dict) else {}
    adapter_source = str(preplan.get("semantic_adapter_source") or "").strip()
    confidence_floor = 0.65 if adapter_source in {
        "semantic_care_fields_to_same_sku_rag",
        "semantic_subfield_to_same_sku_rag",
    } else 0.9
    if not _semantic_preplan_confident(preplan, minimum=confidence_floor):
        return False
    if str(preplan.get("route_family") or "").strip() != "product_bound_qa":
        return False
    if str(preplan.get("evidence_kind") or "").strip() != "product_qa":
        return False
    if preplan.get("ambiguity") or (preplan.get("canonical_fields") or []):
        return False
    if str(preplan.get("field_type") or preplan.get("field_hint") or "").strip():
        return False
    # The family itself is schema-validated.  Providers may omit the legacy
    # route_hint compatibility mirror, so it must not reopen an old usage/care
    # shortcut after the model has explicitly selected sealed product QA.
    return str(preplan.get("route_hint") or "").strip() in {"", "product_detail"}






def _semantic_product_qa_preempts_legacy_shortcuts(preplan: dict[str, Any] | None) -> bool:
    """Keep an explicit semantic QA decision ahead of legacy shortcut routers.

    This is another veto only. It has no lexical interpretation and does not
    choose a QA record; it preserves the model's schema-validated decision so
    the later same-SKU EntityResolution/QA contract can run or fail closed.
    """
    value = preplan if isinstance(preplan, dict) else {}
    adapter_source = str(value.get("semantic_adapter_source") or "").strip()
    confidence_floor = 0.65 if adapter_source in {
        "semantic_care_fields_to_same_sku_rag",
        "semantic_subfield_to_same_sku_rag",
    } else 0.9
    return bool(
        _semantic_preplan_confident(value, minimum=confidence_floor)
        and not value.get("fallback_reason")
        and not value.get("ambiguity")
        and str(value.get("route_family") or "").strip() == "product_bound_qa"
        and str(value.get("evidence_kind") or "").strip() == "product_qa"
        and not (value.get("canonical_fields") or [])
        and not str(value.get("field_type") or value.get("field_hint") or "").strip()
    )






















def _phase1_people_capacity_answer(
    row: dict[str, Any],
    *,
    evidence_metadata: dict[str, Any] | None = None,
) -> str:
    name = str(row.get("product_name_cn") or row.get("product_name_en") or row.get("sku") or "该产品").strip()
    audience = str(row.get("target_audience") or "").strip()
    people_evidence = _people_count_field_evidence(audience)
    if people_evidence:
        if evidence_metadata is not None:
            evidence_metadata.update({
                "evidence_value": people_evidence,
                "evidence_source": "business.target_audience",
                "evidence_scope": "subject",
            })
        sku = str(row.get("sku") or "").strip().upper()
        identity = f"{name}（{sku}）" if sku else name
        return f"{identity}的适合人群资料明确标注“{people_evidence}”，适用人数可按{people_evidence}理解。"
    if evidence_metadata is not None:
        evidence_metadata.clear()
    return f"当前产品资料中未维护{name}的明确适用人数，无法确认适合几个人。"




def _phase1_comparison_evidence_value(canonical_field: str, value: Any) -> str:
    """Normalize legacy comparison evidence through the central value guard."""
    if canonical_field == "capacity":
        return _capacity_field_evidence(value)
    if value in (None, "", 0):
        return ""
    display = _compound_display_value(value).strip()
    if canonical_field == "weight" and re.fullmatch(r"\d+(?:\.0+)?", display):
        display = f"{display.split('.', 1)[0]}g"
    if display.startswith("{") and display.endswith("}"):
        try:
            display = _display_value(json.loads(display)).strip()
        except (TypeError, ValueError, json.JSONDecodeError):
            pass
    return display if _is_valid_structured_field_value(canonical_field, display) else ""


def _phase1_product_evidence_text(row: dict, *, max_fields: int | None = None) -> str:
    fields = (
        ("capacity", "capacity"),
        ("body_material", "material"),
        ("gross_weight_g", "weight"),
        ("features", "technical_advantages"),
        ("usage_scenarios", "usage_scene"),
        ("positioning", "positioning"),
        ("long_description_cn", "long_description_cn"),
    )
    if max_fields is not None:
        # The decision fallback is a concise comparison aid, not a product
        # payload renderer. Long descriptions remain available to dedicated
        # content-field requests and cannot crowd out comparable evidence.
        fields = tuple(item for item in fields if item[0] != "long_description_cn")
    values = [
        f"{customer_field_contract.product_detail_field_label(canonical_field) or canonical_field}：{evidence}"
        for key, canonical_field in fields
        if (evidence := _phase1_comparison_evidence_value(canonical_field, row.get(key)))
    ]
    return "；".join(values[:max_fields] if max_fields is not None else values)


def _validate_semantic_comparison_adjudication(
    data: dict[str, Any] | None,
    *,
    participant_count: int,
    allowed_evidence_fields: set[str],
) -> dict[str, Any] | None:
    """Accept an LLM comparison choice only as a sealed index-plus-evidence contract.

    The semantic model may interpret suitability, but it never supplies an SKU,
    product identity, database value, or customer-facing answer.  This validator
    only maps a bounded participant index back onto already sealed entities and
    accepts field keys that the executor actually supplied as same-SKU evidence.
    """
    if not isinstance(data, dict) or participant_count < 2:
        return None
    forbidden = {
        "sku", "selected_sku", "product", "product_name", "selected_product",
        "answer", "final_answer", "facts", "evidence_values", "raw_evidence",
    }
    if forbidden.intersection(data):
        return None
    selected_index = data.get("selected_index")
    if isinstance(selected_index, bool):
        return None
    if selected_index is not None and (
        not isinstance(selected_index, int) or selected_index < 0 or selected_index >= participant_count
    ):
        return None
    raw_fields = data.get("evidence_fields")
    if not isinstance(raw_fields, list):
        return None
    evidence_fields = list(dict.fromkeys(str(field or "").strip() for field in raw_fields))
    if selected_index is None and not evidence_fields:
        reasoning_summary = str(data.get("reasoning_summary") or "").strip()[:300]
        return {
            "selected_index": None,
            "evidence_fields": [],
            "reasoning_summary": reasoning_summary,
        }
    if not evidence_fields or any(field not in allowed_evidence_fields for field in evidence_fields):
        return None
    reasoning_summary = str(data.get("reasoning_summary") or "").strip()[:300]
    return {
        "selected_index": selected_index,
        "evidence_fields": evidence_fields,
        "reasoning_summary": reasoning_summary,
    }


def _comparison_adjudication_evidence(
    *,
    db: Session,
    bundles: list[tuple[Product | None, ProductSpecs | None, ProductBusiness | None, ProductContent | None]],
    include_partial: bool = False,
) -> dict[str, list[dict[str, Any]]]:
    """Build an opaque, same-SKU evidence packet for semantic comparison.

    Product identities never enter this packet. By default a field is present
    only when every sealed participant has a validated value. A decision
    adjudicator may explicitly request partial fields so an observed hard
    contradiction is not discarded; absent participant rows remain unknown
    and never become positive evidence.
    """
    candidates = sorted(
        field
        for field in customer_field_contract.FORMAL_DETAIL_FIELDS
        if customer_field_contract.is_supported_detail_field(field)
        and field not in {"sku", "barcode", "product_name", "product_name_en", "category"}
    )
    packet: dict[str, list[dict[str, Any]]] = {}
    for field in candidates:
        rows: list[dict[str, Any]] = []
        for index, (product, specs, business, content) in enumerate(bundles):
            if product is None:
                rows = []
                break
            value, source = _structured_product_field_evidence(
                field,
                db=db,
                product=product,
                specs=specs,
                business=business,
                content=content,
            )
            if not value:
                if include_partial:
                    continue
                rows = []
                break
            rows.append(
                {
                    "participant_index": index,
                    "sku": str(product.sku or "").strip().upper(),
                    "value": str(value).strip()[:600],
                    "source": str(source or "").strip(),
                }
            )
        if len(rows) == len(bundles) or (include_partial and rows):
            packet[field] = rows
    return packet


def _comparison_supporting_structured_evidence(
    canonical_field: str,
    *,
    requested_subtype: str | None,
    db: Session,
    product: Product,
    specs: ProductSpecs | None,
    business: ProductBusiness | None,
    content: ProductContent | None,
) -> tuple[str, str | None]:
    """Read a model-selected supporting field without turning it into a route.

    A semantic comparison can ask for a concept that has no catalogue column
    of its own (for example packing burden).  Flash may identify a formal
    field that can help ground that concept.  Keep that decision in the
    semantic plan, while this helper only reads the already sealed SKU's
    structured evidence.  Dimensions need the shared dimension-scope parser;
    all other fields use the normal field evidence policy.
    """
    field = str(canonical_field or "").strip()
    if field == "dimensions":
        raw_value = getattr(specs, "size_info", "") if specs is not None else ""
        subtype = str(requested_subtype or "").strip().lower() or None
        dimension = customer_field_contract.select_dimension_evidence(
            raw_value,
            requested_scope="subject",
            requested_subtype=subtype,
        )
        # Some imports contain a single unlabelled product dimension.  If the
        # semantic concept is storage/packing but the source has no subtype
        # label, retain that concrete dimension as supporting evidence rather
        # than treating the absence of a label as absence of the value.
        if dimension is None and subtype:
            dimension = customer_field_contract.select_dimension_evidence(
                raw_value,
                requested_scope="subject",
            )
        return (
            str(dimension.value or "").strip() if dimension is not None else "",
            "specs.size_info" if dimension is not None and dimension.value else None,
        )
    return _structured_product_field_evidence(
        field,
        db=db,
        product=product,
        specs=specs,
        business=business,
        content=content,
        requested_subtype=requested_subtype or None,
    )


def _parse_semantic_json_object(content: str) -> dict[str, Any] | None:
    text = str(content or "").strip()
    if text.startswith("```"):
        text = re.sub(r"^```(?:json)?\s*", "", text, flags=re.I)
        text = re.sub(r"\s*```$", "", text)
    try:
        data = json.loads(text)
    except (TypeError, json.JSONDecodeError):
        return None
    return data if isinstance(data, dict) else None


def _capacity_evidence_is_internally_consistent(value: Any, identity_text: str = "") -> bool:
    """Reject only capacity text whose own size labels contradict each other."""
    text = str(value or "").strip()
    if not text:
        return False

    def normalized_capacities(source: str) -> list[float]:
        values: list[float] = []
        for match in re.finditer(r"(?<![\d.])(\d+(?:\.\d+)?)\s*(ml|毫升|l|升)(?![a-z])", source, flags=re.I):
            amount = float(match.group(1))
            values.append(amount * (1000 if match.group(2).casefold() in {"l", "升"} else 1))
        return values

    identity_capacities = set(normalized_capacities(str(identity_text or "")))
    field_capacities = normalized_capacities(text)
    if len(identity_capacities) == 1 and field_capacities and next(iter(identity_capacities)) not in field_capacities:
        return False

    labelled_values: dict[str, list[float]] = {"大锅": [], "小锅": []}
    patterns = (
        r"(\d+(?:\.\d+)?)\s*(ml|毫升|l|升)\s*(大锅|小锅)",
        r"(大锅|小锅)\s*(\d+(?:\.\d+)?)\s*(ml|毫升|l|升)",
    )
    for pattern_index, pattern in enumerate(patterns):
        for match in re.finditer(pattern, text, flags=re.IGNORECASE):
            if pattern_index == 0:
                raw_value, unit, label = match.group(1), match.group(2), match.group(3)
            else:
                label, raw_value, unit = match.group(1), match.group(2), match.group(3)
            normalized = float(raw_value) * (1000 if unit.casefold() in {"l", "升"} else 1)
            labelled_values[label].append(normalized)
    if labelled_values["大锅"] and labelled_values["小锅"]:
        return max(labelled_values["大锅"]) >= max(labelled_values["小锅"])
    return True


def _validate_semantic_recommendation_narrative(
    data: dict[str, Any] | None,
    *,
    candidate_count: int,
    verified_fields_by_index: dict[int, set[str]],
    candidate_identity_tokens_by_index: dict[int, set[str]] | None = None,
    expected_ranked_count: int | None = None,
) -> dict[str, Any] | None:
    """Accept a narrative only when it cites the sealed candidate evidence."""
    if not isinstance(data, dict) or set(data) != {"ranked_candidate_indexes", "evidence_usage", "answer"}:
        return None
    ranked = data.get("ranked_candidate_indexes")
    usages = data.get("evidence_usage")
    answer = str(data.get("answer") or "").strip()
    if not isinstance(ranked, list) or not ranked or len(ranked) > min(candidate_count, 5):
        return None
    if expected_ranked_count is not None and len(ranked) != expected_ranked_count:
        return None
    if any(type(index) is not int or not (0 <= index < candidate_count) for index in ranked):
        return None
    if len(set(ranked)) != len(ranked) or not isinstance(usages, list) or len(usages) != len(ranked):
        return None
    if not (20 <= len(answer) <= 1200) or "http://" in answer.lower() or "https://" in answer.lower():
        return None
    # Candidate indices are schema-only handles, never customer-facing language.
    if re.search(r"(?:候选\s*(?:索引)?|索引)\s*[#：:]?\s*\d+", answer, flags=re.IGNORECASE):
        return None
    # The model is free to choose a natural explanation, but it cannot name a
    # sealed product which its own ranked/evidence handles did not select.
    # Without this check a later result reordering can bind the prose for one
    # product to another product's evidence.  Identity tokens are supplied
    # from the sealed catalogue rows; this is contract validation, never a
    # product-name routing rule.
    if candidate_identity_tokens_by_index:
        normalized_answer = re.sub(r"\s+", "", answer).casefold()
        for index in ranked:
            selected_tokens = {
                re.sub(r"\s+", "", str(token or "")).casefold()
                for token in candidate_identity_tokens_by_index.get(index, set())
                if len(re.sub(r"\s+", "", str(token or ""))) >= 3
            }
            if selected_tokens and not any(token in normalized_answer for token in selected_tokens):
                # A customer-facing recommendation must identify every
                # product it ranks. Otherwise a later verifier cannot safely
                # bind pronouns such as “这款” to the visible result SKU and
                # may replace good semantic prose with an internal template.
                return None
        ranked_tokens = {
            re.sub(r"\s+", "", str(token or "")).casefold()
            for index in ranked
            for token in candidate_identity_tokens_by_index.get(index, set())
            if len(re.sub(r"\s+", "", str(token or ""))) >= 3
        }
        for index, tokens in candidate_identity_tokens_by_index.items():
            if index in ranked:
                continue
            for token in tokens:
                normalized_token = re.sub(r"\s+", "", str(token or "")).casefold()
                if (
                    len(normalized_token) >= 3
                    and normalized_token not in ranked_tokens
                    and normalized_token in normalized_answer
                ):
                    # A family/base identity can be a literal prefix of the
                    # selected variant's canonical name or SKU (for example
                    # ``城市出逃套锅`` inside ``城市出逃套锅大锅``).  The answer
                    # has not named an outside product in that case; it has
                    # named the selected identity.  Reject only a token that
                    # is not contained by any selected identity token.
                    if any(normalized_token in ranked_token for ranked_token in ranked_tokens):
                        continue
                    return None
    used_indexes: set[int] = set()
    normalized_usage: list[dict[str, Any]] = []
    for item in usages:
        if not isinstance(item, dict) or set(item) != {"candidate_index", "fields"}:
            return None
        index, fields = item.get("candidate_index"), item.get("fields")
        if type(index) is not int or index not in ranked or index in used_indexes:
            return None
        if not isinstance(fields, list) or not fields or len(fields) > 8:
            return None
        # Models occasionally cite one unavailable alias alongside several
        # valid keys (for example a weight key on one selected variant). The
        # unavailable key grants no evidence, so drop it and let the factual
        # editor remove the associated claim. Reject only when the candidate
        # has no valid same-SKU citation left.
        verified_fields = verified_fields_by_index.get(index, set())
        valid_fields = [
            field
            for field in fields
            if isinstance(field, str) and field in verified_fields
        ]
        if not valid_fields:
            return None
        used_indexes.add(index)
        normalized_usage.append({"candidate_index": index, "fields": list(dict.fromkeys(valid_fields))})
    if used_indexes != set(ranked):
        return None
    # Meaning and numerical equivalence belong to the semantic evidence audit.
    # Local validation deliberately stops at immutable structure: selected
    # catalogue identity and cited fields must belong to the same candidate.
    # It must not reject natural variants such as 一升/1L/1000ml or force one
    # catalogue column name to stand in for another semantically equivalent one.
    return {"ranked_candidate_indexes": ranked, "evidence_usage": normalized_usage, "answer": answer}


def _recommendation_candidate_identity_tokens(candidate: dict[str, Any]) -> set[str]:
    """Return exact catalogue identities that belong to one sealed candidate.

    Identity validation protects same-SKU binding; it must not become a
    language classifier.  Older code generated every two-to-eight character
    substring of product and marketplace titles.  Common prose such as
    ``露营锅具`` could then match an unselected title and reject an otherwise
    grounded answer.  Exact canonical names and SKUs provide the integrity
    boundary without imposing wording rules on the model.
    """
    values = [
        candidate.get("product_name"),
        candidate.get("sku"),
    ]
    return {
        str(value or "").strip()
        for value in values
        if len(re.sub(r"\s+", "", str(value or "").strip())) >= 2
    }


_RECOMMENDATION_PRODUCT_FORM_TERMS = (
    "锅具套装", "炊具套装", "套锅", "套装", "单锅", "烤盘", "煎盘",
    "水壶", "水杯", "餐具", "炉具",
)


def _recommendation_product_form(candidate: dict[str, Any]) -> str:
    """Describe the product form carried by one sealed catalogue row.

    This is not a selection rule.  It is a small identity label passed to the
    prose writers so that a single pot is not casually rewritten as a cookware
    set (or another neighbouring product form).  The canonical product name is
    always the primary source; category fields only help when the name is
    abbreviated.
    """
    declared_form = str(candidate.get("product_form") or "").strip()
    if declared_form:
        return declared_form
    primary_text = " ".join(
        str(candidate.get(field) or "")
        for field in (
            "product_name", "product_name_cn", "product_name_en", "category", "sub_category",
        )
    ).casefold()
    if "单锅" in primary_text:
        return "single_cookware"
    if any(term in primary_text for term in ("锅具套装", "炊具套装", "套锅", "套装")):
        return "cookware_set"
    if any(term in primary_text for term in ("烤盘", "煎盘")):
        return "griddle"
    if "水壶" in primary_text:
        return "kettle"
    if "水杯" in primary_text:
        return "cup"
    if "炉具" in primary_text:
        return "stove"
    if "餐具" in primary_text:
        return "tableware"
    # A shortened canonical name may omit the form while a marketplace title
    # still carries it.  Use that marketing text only when the primary identity
    # is otherwise generic; contradictory title text must not override it.
    title_text = " ".join(
        str(candidate.get(field) or "")
        for field in ("title_cn", "website_title")
    ).casefold()
    if "单锅" in title_text:
        return "single_cookware"
    if any(term in title_text for term in ("锅具套装", "炊具套装", "套锅", "套装")):
        return "cookware_set"
    if any(term in title_text for term in ("烤盘", "煎盘")):
        return "griddle"
    if "水壶" in title_text:
        return "kettle"
    if "水杯" in title_text:
        return "cup"
    if "炉具" in title_text:
        return "stove"
    if "餐具" in title_text:
        return "tableware"
    return "catalogue_product"


def _recommendation_identity_aliases(candidate: dict[str, Any]) -> list[str]:
    """Keep same-SKU aliases, excluding aliases with a contradictory form."""
    primary = dict(candidate or {})
    primary.update({"title_cn": "", "website_title": "", "identity_aliases": []})
    primary_form = _recommendation_product_form(primary)
    aliases: list[str] = []
    for field in ("product_name_en", "title_cn", "website_title"):
        alias = str(candidate.get(field) or "").strip()
        if not alias:
            continue
        alias_form = _recommendation_product_form({"product_name": alias})
        if (
            primary_form == "single_cookware" and alias_form == "cookware_set"
        ) or (
            primary_form == "cookware_set" and alias_form == "single_cookware"
        ):
            continue
        aliases.append(alias)
    return list(dict.fromkeys(aliases))


def _recommendation_product_identity_spans(
    answer: str,
    products: list[dict[str, Any]],
) -> list[tuple[int, int]]:
    """Return spans occupied by supplied product identities in customer prose."""
    value = str(answer or "")
    spans: list[tuple[int, int]] = []
    for product in products:
        identity_values = [
            product.get("product_name"),
            product.get("product_name_cn"),
            product.get("sku"),
            *(product.get("identity_aliases") or []),
        ]
        for identity in identity_values:
            token = str(identity or "").strip()
            if len(re.sub(r"\s+", "", token)) < 2:
                continue
            for match in re.finditer(re.escape(token), value, flags=re.IGNORECASE):
                spans.append((match.start(), match.end()))
    return spans


def _recommendation_form_wording_conflict(
    answer: str,
    products: list[dict[str, Any]],
) -> bool:
    """Detect a product-form noun attached to the wrong selected SKU."""
    value = str(answer or "")
    if not value:
        return False
    identity_spans = _recommendation_product_identity_spans(value, products)

    def protected(start: int, end: int) -> bool:
        return any(start >= left and end <= right for left, right in identity_spans)

    # A collective phrase such as “这两款……套锅” is wrong when the selected
    # set mixes a single pot and a set.  The exact product names themselves are
    # protected, so “享野套锅” remains valid while the collective noun is not.
    forms = {_recommendation_product_form(product) for product in products}
    if "single_cookware" in forms and "cookware_set" in forms:
        for match in re.finditer(r"套(?:锅|装)", value):
            if protected(match.start(), match.end()):
                continue
            prefix = value[max(0, match.start() - 18):match.start()]
            if any(term in prefix for term in ("这两款", "两款", "这几款", "几款", "这些")):
                return True

    # Within a product's local segment, a single-pot identity must not be
    # described as a set.  Restricting this to the segment avoids interpreting
    # the customer's original request as a product fact.
    identity_positions: list[tuple[int, int, str]] = []
    for product in products:
        form = _recommendation_product_form(product)
        for identity in (product.get("product_name"), product.get("product_name_cn"), product.get("sku")):
            token = str(identity or "").strip()
            if len(re.sub(r"\s+", "", token)) < 2:
                continue
            for match in re.finditer(re.escape(token), value, flags=re.IGNORECASE):
                identity_positions.append((match.start(), match.end(), form))
    identity_positions.sort(key=lambda item: (item[0], item[1]))
    for index, (start, end, form) in enumerate(identity_positions):
        if form != "single_cookware":
            continue
        next_start = next(
            (other_start for other_start, _other_end, _other_form in identity_positions[index + 1:] if other_start > end),
            len(value),
        )
        segment = value[end:next_start]
        for match in re.finditer(r"锅具套装|炊具套装|套锅|套装", segment):
            absolute_start = end + match.start()
            if not protected(absolute_start, end + match.end()):
                return True
    return False








_RECOMMENDATION_MEASUREMENT_RE = re.compile(
    r"(?<![\d.])(\d+(?:\.\d+)?)\s*(ml|毫升|l|升|kg|千克|公斤|g|克|cm|厘米|mm|毫米|英寸|寸)(?![a-z])",
    flags=re.IGNORECASE,
)
_RECOMMENDATION_UNSUPPORTED_SAFETY_RE = re.compile(
    r"放心(?:使用)?|可以放心|完全没问题|绝对安全|安全可靠|无风险|零风险|保证安全|不会出问题|不会有问题|"
    r"食品级|食用级|无毒|不含有害物|不含重金属",
    flags=re.IGNORECASE,
)


def _recommendation_measurements(value: Any) -> set[tuple[str, float]]:
    unit_groups = {
        "ml": ("volume", 1.0), "毫升": ("volume", 1.0),
        "l": ("volume", 1000.0), "升": ("volume", 1000.0),
        "g": ("mass", 1.0), "克": ("mass", 1.0),
        "kg": ("mass", 1000.0), "千克": ("mass", 1000.0), "公斤": ("mass", 1000.0),
        "cm": ("length", 10.0), "厘米": ("length", 10.0),
        "mm": ("length", 1.0), "毫米": ("length", 1.0),
        "英寸": ("length_in", 1.0), "寸": ("length_in", 1.0),
    }
    result: set[tuple[str, float]] = set()
    for match in _RECOMMENDATION_MEASUREMENT_RE.finditer(str(value or "")):
        group = unit_groups.get(str(match.group(2) or "").casefold())
        if not group:
            continue
        result.add((group[0], round(float(match.group(1)) * group[1], 6)))
    return result


def _recommendation_content_conflicts_with_structured_specs(
    value: Any,
    *,
    capacity: Any,
    gross_weight_g: Any,
) -> bool:
    """Reject prose measurements that contradict authoritative SKU specs.

    Imported listing copy sometimes describes an older marketplace variant
    while ``product_specs`` carries the maintained SKU values. Long prose may
    still supply use-purpose evidence, but once it states a different capacity
    or weight it is unsafe as an indivisible citation: the final writer can
    quote the conflicting number along with the valid purpose. This is a
    source-precedence check within one SKU, not a customer-language rule.
    """
    prose_measurements = _recommendation_measurements(value)
    if not prose_measurements:
        return False
    structured_capacity = {
        measurement for measurement in _recommendation_measurements(capacity)
        if measurement[0] == "volume"
    }
    try:
        weight_value = float(gross_weight_g or 0)
    except (TypeError, ValueError):
        weight_value = 0
    structured_weight = {("mass", round(weight_value, 6))} if weight_value > 0 else set()
    prose_capacity = {measurement for measurement in prose_measurements if measurement[0] == "volume"}
    prose_weight = {measurement for measurement in prose_measurements if measurement[0] == "mass"}
    return bool(
        (structured_capacity and prose_capacity and not prose_capacity.issubset(structured_capacity))
        or (structured_weight and prose_weight and not prose_weight.issubset(structured_weight))
    )


def _recommendation_unsealed_measurement_claims(
    answer: str,
    question: str,
    selected_rows: list[dict[str, Any]],
) -> list[str]:
    """Catch newly calculated product measurements in prose.

    A product record may contain several component measurements, but a model
    must not silently add them into a new product total.  Customer thresholds
    remain allowed because they belong to the question, not the catalogue.
    """
    allowed = _recommendation_measurements(question)
    evidence_text = " ".join(
        str(row.get(field) or "")
        for row in (selected_rows or [])
        if isinstance(row, dict)
        for field in (
            "capacity", "gross_weight_g", "weight", "size_info", "power",
            "features", "positioning", "top_selling_points", "long_description_cn",
            "long_description_en",
        )
    )
    # ``gross_weight_g`` is stored as a numeric structured value, while the
    # customer-facing answer naturally renders it with ``g``.  Add that
    # unit-bearing representation to the same sealed evidence packet so a
    # direct restatement such as ``300g`` is not mistaken for a newly derived
    # measurement.  This is source-shape normalization, not a question rule.
    structured_weight_evidence: list[str] = []
    for row in (selected_rows or []):
        if not isinstance(row, dict):
            continue
        raw_weight = row.get("gross_weight_g")
        try:
            weight = float(raw_weight)
        except (TypeError, ValueError):
            continue
        if weight > 0:
            structured_weight_evidence.append(f"{weight:g}g")
    if structured_weight_evidence:
        evidence_text += " " + " ".join(structured_weight_evidence)
    evidence_text += " " + " ".join(
        str(value or "")
        for row in (selected_rows or [])
        if isinstance(row, dict)
        for value in (
            (row.get("same_sku_evidence") or {}).values()
            if isinstance(row.get("same_sku_evidence"), dict)
            else (
                (row.get("sealed_evidence") or {}).values()
                if isinstance(row.get("sealed_evidence"), dict)
                else []
            )
        )
    )
    allowed.update(_recommendation_measurements(evidence_text))
    claims: list[str] = []
    for match in _RECOMMENDATION_MEASUREMENT_RE.finditer(str(answer or "")):
        token = match.group(0)
        unit = str(match.group(2) or "").casefold()
        group = {
            "ml": "volume", "毫升": "volume", "l": "volume", "升": "volume",
            "g": "mass", "克": "mass", "kg": "mass", "千克": "mass", "公斤": "mass",
            "cm": "length", "厘米": "length", "mm": "length", "毫米": "length",
            "英寸": "length_in", "寸": "length_in",
        }.get(unit)
        if not group:
            continue
        normalized = (group, round(float(match.group(1)) * {
            "volume": 1000.0 if unit in {"l", "升"} else 1.0,
            "mass": 1000.0 if unit in {"kg", "千克", "公斤"} else 1.0,
            "length": 10.0 if unit in {"cm", "厘米"} else 1.0,
            "length_in": 1.0,
        }[group], 6))
        if normalized not in allowed:
            claims.append(token)
    return list(dict.fromkeys(claims))


def _recommendation_row_measurements(row: dict[str, Any]) -> set[tuple[str, float]]:
    """Collect measurements that belong to one selected catalogue row."""
    if not isinstance(row, dict):
        return set()
    evidence_text = " ".join(
        str(row.get(field) or "")
        for field in (
            "capacity", "gross_weight_g", "weight", "size_info", "power",
            "features", "positioning", "top_selling_points", "long_description_cn",
            "long_description_en",
        )
    )
    for value in (
        (row.get("same_sku_evidence") or {}).values()
        if isinstance(row.get("same_sku_evidence"), dict)
        else (
            (row.get("sealed_evidence") or {}).values()
            if isinstance(row.get("sealed_evidence"), dict)
            else []
        )
    ):
        evidence_text += " " + str(value or "")
    try:
        weight = float(row.get("gross_weight_g"))
    except (TypeError, ValueError):
        weight = 0
    if weight > 0:
        evidence_text += f" {weight:g}g"
    return _recommendation_measurements(evidence_text)


def _recommendation_cross_sku_measurement_claims(
    answer: str,
    question: str,
    selected_rows: list[dict[str, Any]],
) -> list[str]:
    """Reject a concrete measurement attached to another selected SKU.

    The general measurement check protects the answer from invented numbers.
    This narrower association check only runs when multiple selected products
    are explicitly named in the prose; it prevents a value from SKU A being
    stated in SKU B's sentence without imposing a wording route on a single
    recommendation.
    """
    if len(selected_rows or []) < 2 or not str(answer or "").strip():
        return []
    answer_text = str(answer)
    allowed_from_question = _recommendation_measurements(question)
    occurrences: list[tuple[int, int, str]] = []
    for index, row in enumerate(selected_rows):
        identities = list(dict.fromkeys(
            str(row.get(field) or "").strip()
            for field in ("product_name_cn", "product_name_en", "product_name", "sku")
            if str(row.get(field) or "").strip()
        ))
        for identity in identities:
            position = answer_text.find(identity)
            if position >= 0:
                occurrences.append((position, index, identity))
                break
    if len({index for _position, index, _identity in occurrences}) < 2:
        return []
    occurrences.sort(key=lambda item: item[0])
    claims: list[str] = []
    for occurrence_index, (start, row_index, identity) in enumerate(occurrences):
        end = len(answer_text)
        for next_start, next_row_index, _next_identity in occurrences[occurrence_index + 1:]:
            if next_row_index != row_index and next_start > start:
                end = next_start
                break
        segment = answer_text[start:end]
        unbound = _recommendation_measurements(segment) - allowed_from_question - _recommendation_row_measurements(selected_rows[row_index])
        claims.extend(f"{identity}:{value[0]}={value[1]:g}" for value in sorted(unbound))
    return list(dict.fromkeys(claims))


def _recommendation_unsupported_safety_claims(
    answer: str,
    selected_rows: list[dict[str, Any]],
) -> list[str]:
    evidence_text = " ".join(
        str(row.get(field) or "")
        for row in (selected_rows or [])
        if isinstance(row, dict)
        for field in (
            "features", "surface_finish", "usage_instruction", "long_description_cn",
            "long_description_en", "top_selling_points", "positioning",
        )
    )
    evidence_text += " " + " ".join(
        str(value or "")
        for row in (selected_rows or [])
        if isinstance(row, dict)
        for value in (
            (row.get("same_sku_evidence") or {}).values()
            if isinstance(row.get("same_sku_evidence"), dict)
            else []
        )
    )
    normalized_evidence = re.sub(r"\s+", "", evidence_text).casefold()
    return list(dict.fromkeys(
        match.group(0)
        for match in _RECOMMENDATION_UNSUPPORTED_SAFETY_RE.finditer(str(answer or ""))
        if re.sub(r"\s+", "", match.group(0)).casefold() not in normalized_evidence
    ))


_RECOMMENDATION_UNSUPPORTED_RELATIVE_RE = re.compile(
    r"不如|不及",
    flags=re.IGNORECASE,
)
_RECOMMENDATION_UNSUPPORTED_PRICE_RELATIVE_RE = re.compile(
    r"(?:最|更|较)\s*(?:便宜|贵)"
    r"|(?:价格|价位)\s*(?:上|方面|层面|定位)?\s*(?:可能|应该|通常|大概)?\s*(?:比较|相对|很|挺)?\s*"
    r"(?:不算\s*)?(?:最\s*)?"
    r"(?:不\s*)?(?:便宜|贵|高|低|实惠|友好|亲民|划算|合理|合适)"
    r"|(?:比较|相对|很|挺|更|最)?\s*(?:实惠|划算|亲民|性价比(?:高|好|不错)?|价格友好)",
    flags=re.IGNORECASE,
)


def _recommendation_unsupported_relative_claims(
    answer: str,
    selected_rows: list[dict[str, Any]],
) -> list[str]:
    """Catch unsupported cross-candidate comparisons in recommendation prose.

    A semantic writer may correctly notice that one selected candidate has a
    requested property, then overreach by declaring that another finish is
    worse at that property.  The latter is not licensed by merely seeing two
    different source values.  Keep this check deliberately narrow: ordinary
    bounded recommendations such as ``更适合`` remain model-owned, while the
    explicit ``不如/不及`` construction is rejected unless the source itself
    states that relationship.  The same boundary applies to a catalogue
    price tier: ``中端`` is usable as a recorded positioning, but it cannot
    be rewritten as an actual-price comparison such as ``最便宜`` or
    ``价格更高``.
    """
    evidence_text = " ".join(
        str(row.get(field) or "")
        for row in (selected_rows or [])
        if isinstance(row, dict)
        for field in (
            "features", "surface_finish", "usage_scenarios", "target_audience",
            "positioning", "top_selling_points", "long_description_cn",
            "long_description_en", "heat_source", "capacity", "gross_weight_g",
            "size_info",
        )
    )
    evidence_text += " " + " ".join(
        str(value or "")
        for row in (selected_rows or [])
        if isinstance(row, dict)
        for value in (
            (row.get("same_sku_evidence") or {}).values()
            if isinstance(row.get("same_sku_evidence"), dict)
            else []
        )
    )
    normalized_evidence = re.sub(r"\s+", "", evidence_text).casefold()
    conflicts: list[str] = []
    for pattern in (_RECOMMENDATION_UNSUPPORTED_RELATIVE_RE, _RECOMMENDATION_UNSUPPORTED_PRICE_RELATIVE_RE):
        conflicts.extend(
            match.group(0)
            for match in pattern.finditer(str(answer or ""))
            if re.sub(r"\s+", "", match.group(0)).casefold() not in normalized_evidence
        )
    return list(dict.fromkeys(conflicts))


_RECOMMENDATION_AGGREGATE_CAPACITY_RE = re.compile(
    r"总(?:体|计|可用)?(?:容量|容积)|合计(?:容量|容积)?|"
    r"容量合计|整体(?:容量|容积)|总和(?:容量|容积)?|"
    r"容量(?:加起来|相加)"
)
_RECOMMENDATION_STORAGE_TERMS = (
    "收纳", "存放", "打包", "好装", "装得下", "套娃式", "折叠收纳",
)
_RECOMMENDATION_STORAGE_REQUEST_TERMS = (
    "收纳", "存放", "打包", "好装", "装得下", "便携", "携带", "轻便",
    "体积", "放进行李", "送人", "礼物", "送礼",
)


def _recommendation_aggregate_capacity_claims(
    answer: str,
    selected_rows: list[dict[str, Any]],
) -> list[str]:
    """Reject an unlabeled total made by combining component capacities.

    Individual component values remain valid same-SKU facts.  The check only
    catches prose that presents their sum as a product-level total unless the
    catalogue itself labels such a total.  It is an output-fidelity check, not
    a recommendation predicate or a route decision.
    """
    text = str(answer or "")
    if not text or not _RECOMMENDATION_AGGREGATE_CAPACITY_RE.search(text):
        return []
    evidence_text = " ".join(
        str(row.get(field) or "")
        for row in (selected_rows or [])
        if isinstance(row, dict)
        for field in (
            "capacity", "features", "positioning", "top_selling_points",
            "long_description_cn", "long_description_en",
        )
    )
    if re.search(r"总容量|合计容量|容量合计|整体容量|总容积", evidence_text):
        return []
    return list(dict.fromkeys(match.group(0) for match in _RECOMMENDATION_AGGREGATE_CAPACITY_RE.finditer(text)))


_RECOMMENDATION_UNBOUNDED_GROUP_OUTCOME_RE = re.compile(
    r"(?:基本|完全|足够|绰绰有余|刚好|正好|能|可以)?\s*"
    r"(?:够用|吃饱|吃得下|满足(?:你们|多人|两人|三人)?(?:的)?(?:用餐|吃饭|煮面|需求))"
    r"|(?:能|可以)\s*满足[^，。；;!?！？]{0,16}(?:用餐|吃饭|煮面|食量|需求)",
    flags=re.IGNORECASE,
)


def _recommendation_unbounded_group_outcome_claims(
    answer: str,
    selected_rows: list[dict[str, Any]],
) -> list[str]:
    """Reject serving/outcome guarantees that exceed a recorded range.

    Capacity and audience fields can support a conditional reference, but they
    do not prove that a group will eat full or that a portion will be enough.
    This is a final prose-integrity check; it does not decide retrieval or
    candidate eligibility.
    """
    text = str(answer or "")
    if not text:
        return []
    evidence_text = " ".join(
        str(row.get(field) or "")
        for row in (selected_rows or [])
        if isinstance(row, dict)
        for field in ("capacity", "features", "usage_scenarios", "target_audience", "positioning")
    )
    normalized_evidence = re.sub(r"\s+", "", evidence_text).casefold()

    # A customer-facing recommendation is allowed to discuss the requested
    # outcome even when the catalogue does not literally promise it.  What is
    # unsafe is an unqualified guarantee.  The previous implementation looked
    # at the matched words in isolation, so even a sentence such as “实际能否
    # 吃饱还要结合食量” was rejected and the whole recommendation was replaced
    # by a no-match answer.  Inspect the containing sentence instead: a
    # general conditional/boundary phrase keeps the model's useful judgement
    # while making the uncertainty explicit.  This is deliberately language
    # level and product-agnostic; it is not a list of product or intent routes.
    conditional_markers = (
        "是否", "能否", "取决于", "要看", "还要看", "视", "因人而异",
        "不一定", "不能保证", "无法保证", "未明确", "未直接确认", "资料未",
        "资料没有", "仅供参考", "作为参考", "实际", "具体", "不代表",
        "不宜据此判断", "无法直接判断", "需要结合", "结合实际",
        # A same-SKU catalogue statement may describe a customer-relevant
        # outcome in bounded terms (for example, a recorded 3--4 person
        # capacity or an audience/positioning sentence).  Attribution keeps
        # that useful evidence-bound wording distinct from an unqualified
        # guarantee such as “这款一定够用”.
        "资料显示", "资料标注", "产品资料", "资料记录", "标注", "记录",
        "定位", "面向",
    )

    def _sentence_for_match(match: re.Match[str]) -> str:
        start = max(
            text.rfind(mark, 0, match.start()) + len(mark)
            for mark in ("。", "！", "？", "；", ";", "\n")
        )
        end_candidates = [text.find(mark, match.end()) for mark in ("。", "！", "？", "；", ";", "\n")]
        end_candidates = [position for position in end_candidates if position >= 0]
        end = min(end_candidates) if end_candidates else len(text)
        return text[start:end]

    conflicts: list[str] = []
    for match in _RECOMMENDATION_UNBOUNDED_GROUP_OUTCOME_RE.finditer(text):
        matched = match.group(0).strip()
        if not matched:
            continue
        if re.sub(r"\s+", "", matched).casefold() in normalized_evidence:
            continue
        sentence = _sentence_for_match(match)
        if any(marker in sentence for marker in conditional_markers):
            continue
        conflicts.append(matched)
    return list(dict.fromkeys(conflicts))




def _recommendation_unverified_practical_outcome_claims(
    answer: str,
    coverage: dict[str, Any] | None,
    selected_indexes: list[int] | None,
) -> list[str]:
    """Find positive customer-outcome wording that coverage left unverified.

    This is a post-generation integrity check, not an eligibility gate. The
    semantic coverage decision remains the owner of meaning; this boundary
    only prevents a prose writer from turning an explicitly unverified
    required practical condition into a product promise. Preferred or
    subjective-outcome factors are deliberately not literal evidence gates:
    they may shape a natural recommendation and should be bounded in prose by
    the writer when the catalogue does not state them directly. Conditional
    wording such as “资料未直接说明” is allowed for required factors too.
    """
    if not str(answer or "").strip() or not isinstance(coverage, dict):
        return []
    selected = {
        index
        for index in (selected_indexes or [])
        if type(index) is int
    }
    if not selected:
        return []
    conditional_markers = (
        "是否", "能否", "取决于", "要看", "还要看", "不一定", "不能保证",
        "无法保证", "未明确", "未直接", "资料未", "资料没有", "没有直接",
        "没有说明", "不代表", "仅供参考", "作为参考", "需要结合", "因人而异",
    )
    factor_concepts = (
        (("gift", "gift-worthy", "礼物", "送礼", "礼赠"), ("礼物", "送礼", "送人", "礼赠"), ("礼物", "送礼", "礼赠", "gift")),
        (("beginner", "beginner-friendly", "suitable for beginners", "新手", "初学"), ("适合新手", "适合初学者", "适合入门", "新手友好", "beginner-friendly"), ("新手", "初学", "入门", "beginner")),
        (("choose wrong", "low regret", "hard to choose", "不容易选错", "选错", "踩雷"), ("不容易选错", "不易选错", "不容易踩雷", "不易踩雷", "选择风险低", "风险较低", "风险相对较低", "低风险", "容错率高"), ("选错", "容错", "low regret")),
        (("easy to store", "storage", "收纳", "存放"), ("好收纳", "易收纳", "方便收纳", "收纳方便", "易于收纳"), ("收纳", "存放", "storage")),
        (("easy operation", "simple operation", "easy to use", "operation", "操作", "复杂", "简单", "易用", "操作简单", "不复杂", "易操作", "好操作"), ("操作简单", "操作简便", "不复杂", "不会太复杂", "容易操作", "易操作", "好操作", "使用方便", "易用"), ("操作简单", "简单易用", "易操作", "好操作", "易用", "easy to use")),
        (("practical", "实用"), ("实用", "方便实用"), ("实用", "易用", "好用", "方便", "practical")),
    )
    text = str(answer)

    def _sentence_for_position(position: int) -> str:
        start = max(
            text.rfind(mark, 0, position) + len(mark)
            for mark in ("。", "！", "？", "；", ";", "，", ",", "\n")
        )
        ends = [
            text.find(mark, position)
            for mark in ("。", "！", "？", "；", ";", "，", ",", "\n")
        ]
        ends = [end for end in ends if end >= 0]
        return text[start:min(ends) if ends else len(text)]

    conflicts: list[str] = []
    for factor in coverage.get("decision_factors") or []:
        if not isinstance(factor, dict):
            continue
        factor_text = str(factor.get("factor") or "").strip().casefold()
        if not factor_text:
            continue
        # A preferred or subjective-outcome factor is a semantic ranking
        # preference, not a catalogue capability that must be proven word for
        # word. Keeping this boundary for required factors protects concrete
        # fit without reviving the old natural-language evidence valve.
        if str(factor.get("importance") or "").strip() != "required":
            continue
        supported = {
            index
            for field in (
                "supported_candidate_indexes",
                "bounded_candidate_indexes",
            )
            for index in (factor.get(field) or [])
            if type(index) is int
        }
        concept_terms: tuple[str, ...] | None = None
        direct_evidence_terms: tuple[str, ...] | None = None
        for labels, terms, evidence_terms in factor_concepts:
            if any(label.casefold() in factor_text for label in labels):
                concept_terms = terms
                direct_evidence_terms = evidence_terms
                break
        if not concept_terms:
            continue
        supported_evidence_by_index: dict[int, list[str]] = {}
        for usage in factor.get("evidence_usage") or []:
            if not isinstance(usage, dict) or type(usage.get("candidate_index")) is not int:
                continue
            excerpts = [
                str(item.get("excerpt") or "").strip()
                for item in (usage.get("evidence") or [])
                if isinstance(item, dict) and str(item.get("excerpt") or "").strip()
            ]
            if excerpts:
                supported_evidence_by_index[usage["candidate_index"]] = excerpts
        direct_supported = {
            index
            for index in selected & supported
            if direct_evidence_terms
            and any(
                term.casefold() in " ".join(supported_evidence_by_index.get(index, [])).casefold()
                for term in direct_evidence_terms
            )
        }
        # A model status cannot authorize an outcome from a nearby trait. If
        # the selected same-SKU citation does not contain a directly relevant
        # outcome, inspect the prose for an unsupported positive claim even
        # when coverage labelled the candidate supported.
        if selected and selected.issubset(direct_supported):
            continue
        for term in concept_terms:
            for match in re.finditer(re.escape(term), text, flags=re.IGNORECASE):
                sentence = _sentence_for_position(match.start())
                if any(marker in sentence for marker in conditional_markers):
                    continue
                if (
                    any(label.casefold() in factor_text for label in (
                        "beginner",
                        "beginner-friendly",
                        "suitable for beginners",
                        "新手",
                        "初学",
                    ))
                    and re.search(
                        r"(?:面向|目标用户|定位为|使用场景(?:包括)?|适用人群).{0,24}(?:入门|新手|初学)",
                        sentence,
                        flags=re.IGNORECASE,
                    )
                ):
                    # A recorded audience/scene label may be repeated as a
                    # narrower fact; it must not be mistaken for the stronger
                    # outcome claim “适合新手”.
                    continue
                conflicts.append(f"{factor.get('factor')}:{term}")
    return list(dict.fromkeys(conflicts))


def _recommendation_unbounded_budget_claims(answer: str) -> list[str]:
    """Reject affordability promises that exceed a catalogue price tier."""
    text = str(answer or "")
    if not text:
        return []
    positive_terms = (
        "符合预算",
        "预算友好",
        "预算合适",
        "适合预算",
        "实惠",
        "便宜",
        "高性价比",
        "性价比高",
        "性价比很高",
        "很高性价比",
        "不贵",
        "价格不高",
        "价格不会太高",
        "价格应该不会太高",
        "价位不高",
        "不会太贵",
        "应该不贵",
        "价格亲民",
        "价格友好",
    )
    conditional_markers = (
        "未明确", "没有明确", "需要确认", "还需确认", "实际价格",
        "不能据此", "无法据此", "不代表", "仅供参考", "资料没有直接",
    )
    attribution_markers = ("资料记录", "资料中", "记录中", "产品资料")
    conflicts: list[str] = []
    for term in positive_terms:
        for match in re.finditer(re.escape(term), text, flags=re.IGNORECASE):
            start = max(
                text.rfind(mark, 0, match.start()) + len(mark)
                for mark in ("。", "！", "？", "；", ";", "\n")
            )
            ends = [
                text.find(mark, match.end())
                for mark in ("。", "！", "？", "；", ";", "\n")
            ]
            ends = [end for end in ends if end >= 0]
            sentence = text[start:min(ends) if ends else len(text)]
            if any(marker in sentence for marker in conditional_markers):
                continue
            if term in {"高性价比", "性价比高"} and any(
                marker in sentence for marker in attribution_markers
            ):
                continue
            conflicts.append(term)
    return list(dict.fromkeys(conflicts))


def _recommendation_fact_integrity_conflicts(
    answer: str,
    question: str,
    selected_rows: list[dict[str, Any]],
    *,
    context_text: str | None = None,
) -> dict[str, list[str]]:
    return {
        "product_form": ["product_form"]
        if _recommendation_form_wording_conflict(answer, selected_rows)
        else [],
        "unsealed_measurements": _recommendation_unsealed_measurement_claims(
            answer,
            question,
            selected_rows,
        ),
        "cross_sku_measurements": _recommendation_cross_sku_measurement_claims(
            answer,
            question,
            selected_rows,
        ),
        "unsupported_safety": _recommendation_unsupported_safety_claims(
            answer,
            selected_rows,
        ),
        "unsupported_relative": _recommendation_unsupported_relative_claims(
            answer,
            selected_rows,
        ),
        "group_outcome": _recommendation_unbounded_group_outcome_claims(
            answer,
            selected_rows,
        ),
        "unbounded_budget": _recommendation_unbounded_budget_claims(answer),
        "aggregate_capacity": _recommendation_aggregate_capacity_claims(
            answer,
            selected_rows,
        ),
        # Storage is a relevance/presentation choice, not a same-SKU factual
        # contradiction.  The semantic writer is already told not to volunteer
        # it when the customer did not ask; do not turn an occasional tangent
        # into the rigid field-dump fallback.
        "unasked_storage": [],
    }










def _model_selected_recommendation_seed(
    data: dict[str, Any] | None,
    *,
    candidate_count: int,
    expected_ranked_count: int | None = None,
) -> dict[str, Any] | None:
    """Recover only a model-authored candidate choice from malformed prose JSON.

    Selection remains entirely model-owned.  This adapter accepts no product
    facts or answer text; it merely validates that the model's candidate
    handles are in range so the independent Flash evidence renderer can write
    a fresh answer from the sealed packet.
    """
    if not isinstance(data, dict):
        return None
    ranked = data.get("ranked_candidate_indexes")
    if not isinstance(ranked, list) or not ranked or len(ranked) > min(candidate_count, 3):
        return None
    if expected_ranked_count is not None and len(ranked) != expected_ranked_count:
        return None
    if any(type(index) is not int or not (0 <= index < candidate_count) for index in ranked):
        return None
    if len(set(ranked)) != len(ranked):
        return None
    return {
        "ranked_candidate_indexes": list(ranked),
        "evidence_usage": [],
        "answer": "",
        "selection_only": True,
    }


def _semantic_customer_factor_basis_sources(
    *,
    question: str,
    semantic_requirements: list[str] | None = None,
    soft_preferences: list[str] | None = None,
    predicate_constraints: list[dict[str, Any]] | None = None,
    requested_catalogue_subject: str | None = None,
    recommendation_context_text: str | None = None,
) -> list[str]:
    """Return only customer-derived inputs that may authorize a decision factor.

    Candidate evidence is intentionally absent. Seeing a price tier, material,
    or feature in recalled rows must not cause the coverage model to invent a
    customer priority that was never expressed or carried from conversation.
    """

    sources: list[str] = []

    def _add(value: Any) -> None:
        if isinstance(value, dict):
            for nested in value.values():
                _add(nested)
            return
        if isinstance(value, (list, tuple, set)):
            for nested in value:
                _add(nested)
            return
        text = str(value or "").strip()
        if text:
            sources.append(text)

    # Planner summaries and typed predicates are deliberately not provenance:
    # they are useful semantic hints but may themselves contain a paraphrase or
    # an inferred preference. The coverage model must point back to customer
    # language from the current turn or carried conversation context.
    _add(question)
    _add(recommendation_context_text)
    return list(dict.fromkeys(sources))


def _semantic_customer_factor_basis_is_grounded(
    basis: Any,
    sources: list[str] | None,
) -> bool:
    """Validate factor provenance without comparing customer and product words."""

    normalized_basis = re.sub(r"\s+", "", str(basis or "")).casefold()
    if len(normalized_basis) < 2:
        return False
    return any(
        normalized_basis in re.sub(r"\s+", "", str(source or "")).casefold()
        for source in (sources or [])
        if str(source or "").strip()
    )


def _semantic_price_positioning_rank(value: Any) -> int | None:
    """Map a maintained catalogue price tier to a coarse preference rank.

    This is deliberately a field-level tie-breaker for an already semantic
    recommendation pool. It is not a customer-wording route, a live-price
    lookup, or a hard product eligibility check.
    """
    text = re.sub(r"\s+", " ", str(value or "")).strip().casefold()
    if not text:
        return None
    if any(term in text for term in ("高端", "premium", "high-end", "high end")):
        return 2
    if any(term in text for term in ("中端", "mid-range", "mid range", "mid")):
        return 1
    if any(
        term in text
        for term in (
            "入门",
            "基础",
            "亲民",
            "affordable",
            "entry",
            "value",
            "性价比",
        )
    ):
        return 0
    return None


def _semantic_budget_priority_alternatives(
    candidates: list[dict[str, Any]],
    eligible_candidate_indexes: list[int] | None,
    selected_candidate_indexes: list[int] | None,
    *,
    premium_requested: bool = False,
) -> list[int]:
    """Return lower-tier alternatives when Flash picked only premium rows.

    Budget remains a soft semantic preference: a premium row is retained when
    it is the only evidenced fit, when the customer explicitly asks for a
    premium tier, or when the selected set already contains a lower tier. The
    helper only narrows a second semantic ranking call to already eligible
    same-SKU candidates; it never admits a new row or rejects a product on its
    own.
    """
    if premium_requested:
        return []
    eligible = [
        index
        for index in (eligible_candidate_indexes or [])
        if type(index) is int and 0 <= index < len(candidates)
    ]
    selected = [
        index
        for index in (selected_candidate_indexes or [])
        if type(index) is int and 0 <= index < len(candidates)
    ]
    selected_tiers = [
        _semantic_price_positioning_rank(
            (candidates[index].get("sealed_evidence") or {}).get(
                "business.price_positioning"
            )
        )
        for index in selected
    ]
    if not selected_tiers or any(tier != 2 for tier in selected_tiers):
        return []
    return [
        index
        for index in eligible
        if _semantic_price_positioning_rank(
            (candidates[index].get("sealed_evidence") or {}).get(
                "business.price_positioning"
            )
        )
        in {0, 1}
    ]


async def _semantic_recommendation_candidate_selection(
    db: Session,
    *,
    question: str,
    candidates: list[dict[str, Any]],
    soft_preferences: list[str] | None,
    semantic_requirements: list[str] | None = None,
    predicate_constraints: list[dict[str, Any]] | None = None,
    eligible_candidate_indexes: list[int] | None = None,
    decision_factors: list[dict[str, Any]] | None = None,
    expected_ranked_count: int | None = None,
    recommendation_context_text: str | None = None,
) -> dict[str, Any] | None:
    """Let Flash rank eligible same-SKU candidates by the customer's meaning."""
    runtime = customer_agent_planner_service._semantic_preplan_runtime_settings()
    messages = [
        {
            "role": "system",
            "content": (
                "Return JSON only. Rank the eligible sealed candidates for the customer's complete request. "
                "The question is authoritative: consider all of its needs together, including natural qualitative wording, "
                "instead of defaulting to catalogue order or the candidate with the most populated fields. Base every match "
                "on that candidate's own sealed_evidence. Missing evidence is uncertainty, not support, and a nearby property "
                "must not be treated as the requested property. A requested measurable threshold is covered only by evidence "
                "for that measurement; an audience, serving, or marketing label cannot establish a different measurement. "
                "Prefer the candidate that directly covers more of what the "
                "customer actually cares about. For a preferred formal predicate, use its verified same-SKU evidence to order candidates, "
                "but do not reject or hide a candidate solely because that preference is unverified. For a practical_fit factor, prefer complementary concrete specifications plus a "
                "directly relevant usage or audience context over a single broad marketing sentence. Do not rank a more weakly "
                "supported candidate first merely because its description sounds more persuasive. "
                 "When the customer wants a low-regret choice but has not stated a hobby, group size, cooking style, or other special "
                 "preference, prefer a broadly useful candidate with fewer unstated prerequisites. Do not rank a tea, coffee, cooking, "
                 "group-oriented, fuel-dependent, or safety-critical item ahead merely by assuming that unknown preference. A stove, "
                 "burner, or fuel appliance normally carries more recipient-specific setup and safe-operation prerequisites than a simple "
                 "general-use item, so it should not lead a low-choice-risk gift request unless the customer actually asks for that form. "
                 "Respect product_form: prefer a complete requested item over a component whose supporting prose actually describes a "
                 "family or bundle, and never use bundle-wide prose to rank that component. When the customer asks for one physical "
                 "item in singular terms such as a single pot, do not silently choose a set or bundle unless the question also makes "
                 "a set acceptable. "
                "When none covers everything, choose the strongest evidenced fit and leave the "
                 "gap for the answer to explain. formal_predicates, soft_customer_preferences, semantic_requirements, and prior context clarify "
                 "the customer's intent but are not product facts. For each formal_predicate, compare its field and meaning only with the same candidate's sealed_evidence; numeric predicates have already been checked structurally, while text predicates such as surface_finish are semantic and must not be matched by substring alone. selection_context may be used only to avoid an unavailable "
                 "or explicitly restricted product. If eligible_candidate_indexes is supplied, select only from those "
                 "indexes; they are the candidates already admitted by same-SKU adjudication. Required factual factors must be supported. "
                 "Treat a generic budget or affordability preference as a soft ranking signal. When decision_factor_evidence marks a "
                 "factor dimension as budget, use the candidate's business.price_positioning as the primary signal even if another "
                 "marketing field says high value or high cost performance. If a candidate's sealed_evidence contains "
                 "business.price_positioning, an 入门/中端 tier may rank ahead of a 高端 tier for a budget-conscious customer, while a "
                 "高端 tier may rank ahead when the customer explicitly wants premium positioning. This field is a catalogue tier, not a "
                 "current price; missing or conflicting price positioning lowers preference confidence but never rejects an otherwise useful "
                 "candidate. When budget is explicitly part of the request, do not let a merely lighter candidate with no price evidence "
                 "automatically outrank a same-SKU candidate whose recorded tier aligns with the budget, unless the lighter candidate is "
                 "materially better on an explicit hard requirement. Do not invent a price or call a tier affordable as a guaranteed fact. "
                 "When neither the complete question nor decision_factor_evidence expresses budget, price, affordability, value, or "
                 "premium positioning, ignore business.price_positioning completely and do not use it to rank candidates. "
                 "A required practical_fit factor may be supported, bounded, or partial: prefer supported or bounded candidates when the "
                "overall fit is otherwise comparable, but do not discard a partial candidate when it is the strongest useful choice; the "
                "writer must describe that choice conditionally and name the missing part rather than turning it into a guarantee. Do not "
                "write customer prose. "
                + (
                    "The customer requested exactly one recommendation, so return exactly one index. "
                    if expected_ranked_count == 1
                    else "Return at most three focused indexes. "
                )
                + "Schema exactly: {\"ranked_candidate_indexes\":[integer]}."
            ),
        },
        {
            "role": "user",
            "content": json.dumps({
                "question": question,
                "formal_predicates": list(predicate_constraints or []),
                "soft_customer_preferences": list(soft_preferences or []),
                "semantic_requirements": list(semantic_requirements or []),
                "decision_factor_evidence": list(decision_factors or []),
                "eligible_candidate_indexes": list(eligible_candidate_indexes or []),
                "prior_recommendation_context": str(recommendation_context_text or "").strip(),
                "sealed_candidates": candidates,
            }, ensure_ascii=False),
        },
    ]
    try:
        content = await customer_llm_service.chat_completion(
            db,
            messages=messages,
            temperature=0,
            max_tokens=120,
            purpose="semantic_recommendation_candidate_selection",
            api_model_override=runtime["model"],
            response_format={"type": "json_object"} if settings.SEMANTIC_PREPLAN_JSON_MODE else None,
            thinking={"type": "disabled"} if settings.SEMANTIC_PREPLAN_THINKING_DISABLED else None,
        )
    except Exception:
        return None
    parsed = _parse_semantic_json_object(content)
    if not isinstance(parsed, dict) or set(parsed) != {"ranked_candidate_indexes"}:
        return None
    selected = _model_selected_recommendation_seed(
        parsed,
        candidate_count=len(candidates),
        expected_ranked_count=expected_ranked_count,
    )
    if selected is None:
        return None
    eligible = {
        index for index in (eligible_candidate_indexes or []) if type(index) is int
    }
    if eligible and not set(selected["ranked_candidate_indexes"]).issubset(eligible):
        return None
    return selected


async def _semantic_recommendation_decision_factor_contract(
    db: Session,
    *,
    question: str,
    semantic_requirements: list[str] | None = None,
    soft_preferences: list[str] | None = None,
    predicate_constraints: list[dict[str, Any]] | None = None,
    requested_catalogue_subject: str | None = None,
    recommendation_context_text: str | None = None,
) -> list[dict[str, Any]] | None:
    """Extract customer-owned decision factors before any candidate is shown."""

    customer_basis_sources = _semantic_customer_factor_basis_sources(
        question=question,
        semantic_requirements=semantic_requirements,
        soft_preferences=soft_preferences,
        predicate_constraints=predicate_constraints,
        requested_catalogue_subject=requested_catalogue_subject,
        recommendation_context_text=recommendation_context_text,
    )
    if not customer_basis_sources:
        return None
    runtime = customer_agent_planner_service._semantic_preplan_runtime_settings()
    system = (
        "Return only JSON. Extract the complete set of independent customer decision factors for a product recommendation. "
        "You are not routing, retrieving, ranking, choosing a product, or judging evidence, and no candidate data is supplied. "
        "Use only meanings expressed in customer_basis_sources. semantic_hints are non-authoritative paraphrases and may be wrong; "
        "they cannot authorize a factor. Every factor must include customer_basis as the shortest verbatim excerpt from "
        "customer_basis_sources that expresses it. Split independent meanings instead of merging them. A requested physical product "
        "form is handled separately by requested_catalogue_subject; do not duplicate a plain form as a factor. A non-usage assignment "
        "role belongs in requested_role_factor: set it for a distinct role such as a gift, emergency backup, or work tool, and use null "
        "when no such assignment role is expressed. An ordinary use scene, task, group, or audience—such as camping, hiking, cooking, "
        "drinking, two-person use, or beginner use—is not requested_role_factor; preserve it as an independent scenario_fit or "
        "subjective_outcome decision_factors item as appropriate. Choosing "
        "an item as a gift must therefore produce a gift-suitability requested_role_factor, separately from recipient fit, "
        "practicality, storage, low choice risk, appearance, or packaging. Never infer appearance, packaging, prestige, price, storage, "
        "ease, audience, or another preference merely because it is plausible for the product or role. "
        "factor_type=factual for a concrete product fact/capability and practical_fit for person, group, use, role, scenario, or outcome. "
        "decision_kind is concrete_capability, scenario_fit, or subjective_outcome. Use subjective_outcome for ease, simplicity, "
        "beginner friendliness, practicality, gift suitability, low choice risk, appearance, and storage convenience; use scenario_fit "
        "for a concrete group/use/scene fit. When one customer phrase combines a group and an ordinary task, such as "
        "‘一个人喝水用’ or ‘两个人煮面’, preserve the group fit and the task/scene fit as separate factors so the "
        "candidate's own usage evidence can be judged for both meanings. importance is required only for a must-have; otherwise preferred. An explicit request that an item be truly or really suitable, dedicated, explicitly supported, or required for a named method, role, or use is a must-have even when expressed conversationally; preserve the named method/role/use as a required practical_fit/concrete_capability factor. For example, ‘真正适合手冲’ is not a soft preference for any coffee-related item: a kettle, moka pot, French press, or grinder is not a substitute unless the same-SKU evidence establishes the requested pour-over form or capability. Ordinary ‘用于/适合’ context without this stronger fit meaning may remain a preferred scenario. A generic affordability "
        "direction is preferred with dimension=budget; every other dimension is empty. Return at most eight factors in customer-meaning "
        "order. In a recommendation, an ordinary intended task such as boiling water, cooking noodles, or drinking is a practical_fit "
        "scenario_fit unless the customer explicitly asks to verify a recorded compatibility or specification. Before returning, account "
        "for every independent meaning in customer_basis_sources exactly once; do not rely on a later completeness pass. An unconstrained "
        "request may return an empty list and a null requested_role_factor. Schema exactly: "
        "{\"requested_role_factor\":{\"factor\":\"suitability for the requested role\",\"customer_basis\":\"verbatim role text\"},\"decision_factors\":[{\"factor\":\"concise semantic label\",\"customer_basis\":\"verbatim customer text\","
        "\"dimension\":\"\",\"factor_type\":\"practical_fit\",\"decision_kind\":\"subjective_outcome\",\"importance\":\"preferred\"}]}"
    )
    payload = {
        "customer_basis_sources": customer_basis_sources,
        "requested_catalogue_subject": str(requested_catalogue_subject or "").strip(),
        "semantic_hints": {
            "requirements": [str(item or "").strip() for item in (semantic_requirements or []) if str(item or "").strip()],
            "soft_preferences": [str(item or "").strip() for item in (soft_preferences or []) if str(item or "").strip()],
            "formal_predicates": [item for item in (predicate_constraints or []) if isinstance(item, dict)],
        },
    }
    for attempt in range(2):
        messages = [
            {
                "role": "system",
                "content": system + (
                    " The previous payload was invalid or ungrounded. Re-read only customer_basis_sources, preserve every independent "
                    "meaning, and omit anything that lacks a verbatim customer basis."
                    if attempt
                    else ""
                ),
            },
            {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
        ]
        try:
            raw = await customer_llm_service.chat_completion(
                db,
                messages=messages,
                temperature=0,
                max_tokens=min(1400, max(520, len(str(question or "")) * 8)),
                purpose=(
                    "semantic_recommendation_factor_completeness"
                    if attempt
                    else "semantic_recommendation_factor_extraction"
                ),
                api_model_override=runtime["model"],
                response_format=runtime["response_format"],
                thinking=runtime["thinking"],
            )
        except Exception:
            continue
        parsed = _parse_semantic_json_object(raw)
        raw_factors = parsed.get("decision_factors") if isinstance(parsed, dict) else None
        if (
            not isinstance(parsed, dict)
            or "requested_role_factor" not in parsed
            or not isinstance(raw_factors, list)
            or len(raw_factors) > 8
        ):
            continue
        raw_role_factor = parsed.get("requested_role_factor")
        role_factor: dict[str, Any] | None = None
        if raw_role_factor is not None:
            if not isinstance(raw_role_factor, dict):
                continue
            role_label = str(raw_role_factor.get("factor") or "").strip()
            role_basis = str(raw_role_factor.get("customer_basis") or "").strip()
            if (
                not role_label
                or len(role_label) > 80
                or len(role_basis) > 160
                or not _semantic_customer_factor_basis_is_grounded(
                    role_basis,
                    customer_basis_sources,
                )
            ):
                continue
            role_factor = {
                "factor": role_label,
                "customer_basis": role_basis,
                "dimension": "",
                "factor_type": "practical_fit",
                "decision_kind": "subjective_outcome",
                "importance": "preferred",
                "requested_role_factor": True,
            }
        factors: list[dict[str, Any]] = []
        seen: set[tuple[str, str]] = set()
        valid = True
        for item in raw_factors:
            if not isinstance(item, dict):
                valid = False
                break
            factor = str(item.get("factor") or "").strip()
            customer_basis = str(item.get("customer_basis") or "").strip()
            if not customer_basis and _semantic_customer_factor_basis_is_grounded(
                factor,
                customer_basis_sources,
            ):
                customer_basis = factor
            dimension = str(item.get("dimension") or "").strip()
            factor_type = str(item.get("factor_type") or "").strip()
            decision_kind = str(item.get("decision_kind") or "").strip()
            importance = str(item.get("importance") or "").strip()
            key = (factor.casefold(), customer_basis.casefold())
            if (
                not factor
                or len(factor) > 80
                or len(customer_basis) > 160
                or not _semantic_customer_factor_basis_is_grounded(customer_basis, customer_basis_sources)
                # ``dimension`` is descriptive semantic metadata.  Budget is
                # the only dimension with a typed catalogue-side adapter; a
                # natural factor such as “更轻” may validly arrive as
                # ``weight`` and must not invalidate the whole RAG coverage
                # packet merely because it is not a routing/filter token.
                or len(dimension) > 40
                or factor_type not in {"factual", "practical_fit"}
                or decision_kind not in {"concrete_capability", "scenario_fit", "subjective_outcome"}
                or importance not in {"required", "preferred"}
                or key in seen
            ):
                valid = False
                break
            if dimension == "budget":
                importance = "preferred"
            seen.add(key)
            factors.append({
                "factor": factor,
                "customer_basis": customer_basis,
                "dimension": dimension,
                "factor_type": factor_type,
                "decision_kind": decision_kind,
                "importance": importance,
            })
        if valid:
            if role_factor is not None:
                role_key = (
                    role_factor["factor"].casefold(),
                    role_factor["customer_basis"].casefold(),
                )
                if role_key not in seen:
                    factors.insert(0, role_factor)
            if len(factors) > 8:
                continue
            return factors
    return None


async def _semantic_recommendation_requirement_coverage_once(
    db: Session,
    *,
    question: str,
    candidates: list[dict[str, Any]],
    semantic_requirements: list[str],
    soft_preferences: list[str] | None = None,
    predicate_constraints: list[dict[str, Any]] | None = None,
    requested_catalogue_subject: str | None = None,
    recommendation_context_text: str | None = None,
    decision_factor_contract: list[dict[str, Any]] | None = None,
    validation_diagnostic: dict[str, Any] | None = None,
    consistency_repair: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    """Ask Flash which sealed candidates actually cover the requested meanings.

    Candidate selection and prose rendering are separate provider calls.  A
    presentation fallback must not turn a selected row into a recommendation
    merely because the JSON writer failed.  This adjudicator is deliberately
    semantic: it judges each request against the same-SKU sealed evidence and
    returns a small coverage map, rather than adding another phrase or intent
    router in Python.
    """
    requirements = [
        str(item or "").strip()
        for item in (semantic_requirements or [])
        if str(item or "").strip()
    ]

    def _reject_coverage(reason: str, detail: Any | None = None) -> None:
        if validation_diagnostic is not None:
            validation_diagnostic["failure"] = reason
            if detail is not None:
                validation_diagnostic["failure_detail"] = detail

    if not candidates:
        _reject_coverage("no_candidates")
        return None
    # Keep the planner's canonical soft dimensions as a typed side channel.
    # This lets the adjudicator return a natural factor label without making
    # Python rediscover its meaning from Chinese wording.  In particular,
    # budget is a ranking preference even when the model's prose label says
    # ``required`` by mistake.
    soft_preference_dimensions = {
        str(item or "").strip()
        for item in (soft_preferences or [])
        if str(item or "").strip() in {"budget"}
    }
