def _compound_display_value(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    if text.startswith("[") and text.endswith("]"):
        try:
            return _display_value(json.loads(text))
        except (TypeError, ValueError, json.JSONDecodeError):
            items = [item.strip().strip("'\"") for item in text[1:-1].split(",")]
            return "，".join(item for item in items if item)
    # Imported catalogue text occasionally stores line breaks as the two
    # literal characters ``\n``. They are separators, not part of the product
    # value a customer should see.
    text = text.replace("\\n", "、")
    return re.sub(r"[、；;]{2,}", "、", text).strip("、；; ")


def _normalize_customer_answer_text(value: Any) -> str:
    """Hide escaped catalogue separators without changing customer facts."""
    text = str(value or "")
    text = text.replace("\\r\\n", "、").replace("\\n", "、").replace("\\r", "、")
    return re.sub(r"、{2,}", "、", text)








def _heat_source_field_evidence(value: Any) -> str:
    """Normalize a structured heat-source cell into one readable list."""
    display = _compound_display_value(value)
    if not display:
        return ""
    items = [
        item.strip()
        for item in re.split(r"[、,，;；\r\n]+", display)
        if item.strip()
    ]
    return "、".join(dict.fromkeys(items))


def _selling_point_heat_source_evidence(value: Any) -> str:
    """Use a selling-point fallback only when it explicitly names a heat source."""
    text = _compound_display_value(value).strip()
    if not text:
        return ""
    markers = (
        "电陶炉", "电磁炉", "卡式炉", "酒精炉", "柴火炉", "燃气炉",
        "明火", "直火", "炭火", "固体燃料", "气罐",
    )
    clauses = [
        clause.strip()
        for clause in re.split(r"[\r\n]+|(?<=[。！？!?；;])", text)
        if clause.strip() and any(marker in clause for marker in markers)
    ]
    return " ".join(dict.fromkeys(clauses)).strip()


_CAPACITY_VALUE_PATTERN = re.compile(
    r"(?<![\d.])\d+(?:\.\d+)?\s*(?:ml|毫升|l|升)(?![A-Za-z])",
    re.IGNORECASE,
)

_LABELED_COMPONENT_SIZE_PATTERN = re.compile(
    r"^\S.{0,20}(?:\s+|[：:])\s*\d+(?:\.\d+)?\s*寸$",
    re.IGNORECASE,
)


def _capacity_field_evidence(value: Any) -> str:
    """Return only values that are structurally valid capacity evidence.

    The imported catalogue uses a JSON list for ``specs.capacity`` but also
    contains explicit placeholders and a few values copied from unrelated
    columns.  Same-SKU provenance alone is therefore insufficient: a capacity
    provider must also prove capacity-unit semantics before it can be exposed.
    """
    if value in (None, ""):
        return ""
    parsed: Any = value
    if isinstance(value, str):
        text = value.strip()
        if not text or text in {"[]", "/", "null", "None"}:
            return ""
        if text.startswith(("[", "{")):
            try:
                parsed = json.loads(text)
            except (TypeError, ValueError, json.JSONDecodeError):
                parsed = text

    items = parsed if isinstance(parsed, list) else [parsed]
    accepted: list[str] = []
    for item in items:
        display = _display_value(item).strip()
        if not display or not (
            _CAPACITY_VALUE_PATTERN.search(display)
            or _LABELED_COMPONENT_SIZE_PATTERN.search(display)
        ):
            continue
        accepted.append(display)
    display = "，".join(dict.fromkeys(accepted))
    # A malformed labelled capacity is not customer-facing evidence.  Keep
    # the whole cell sealed rather than silently exposing a value whose own
    # component labels contradict one another.
    return display if _capacity_evidence_is_internally_consistent(display) else ""


def _color_field_evidence(value: Any) -> str:
    """Keep only explicit color tokens from the structured color column."""
    display = _compound_display_value(value)
    if not display:
        return ""
    items = [item.strip() for item in re.split(r"[、,，;；\r\n]+", display) if item.strip()]
    accepted = [
        item
        for item in items
        if "色" in item or any(char in _COLOR_FAMILY_CHARACTERS for char in item)
    ]
    return "、".join(dict.fromkeys(accepted))


def _dishwasher_specific_evidence(value: Any) -> str:
    """Return only clauses that explicitly state dishwasher compatibility."""
    text = str(value or "").strip()
    if not text or text in {"[]", "/"} or "洗碗机" not in text:
        return ""
    clauses = [
        clause.strip()
        for clause in re.split(r"[\r\n]+|(?<=[。！？!?；;])", text)
        if clause.strip() and "洗碗机" in clause
    ]
    return " ".join(dict.fromkeys(clauses)).strip()


def _machine_wash_specific_evidence(value: Any) -> str:
    """Return only clauses that explicitly discuss laundry-machine washing."""
    text = str(value or "").strip()
    if not text or text in {"[]", "/"} or not any(term in text for term in ("洗衣机", "机洗")):
        return ""
    clauses = [
        clause.strip()
        for clause in re.split(r"[\r\n]+|(?<=[。！？!?；;])", text)
        if clause.strip() and any(term in clause for term in ("洗衣机", "机洗"))
    ]
    return " ".join(dict.fromkeys(clauses)).strip()


_USAGE_INSTRUCTION_FIELD_MARKERS: dict[str, tuple[str, ...]] = {
    "cleaning": (
        "清洁", "清洗", "冲洗", "洗净", "擦洗", "擦拭", "刷洗",
        "去污", "污渍", "油污", "洗涤", "湿布", "温水", "洗洁精",
    ),
    "care": (
        "保养", "养护", "存放", "收纳", "晾干", "烘干", "擦干",
        "干燥", "防锈", "防霉", "通风", "长期不用", "避免潮湿",
        "定期检查",
    ),
}


def _liquid_temperature_capability_evidence(value: Any) -> str:
    """Keep only clauses that explicitly support liquid-temperature capability.

    A generic instruction such as "may contact hot food" does not establish
    whether a product can contain hot water.  This is evidence validation after
    the semantic FieldContract has selected ``usage_instruction``; it does not
    classify the user's wording or infer a capability from a product category.
    """
    text = str(value or "").strip()
    if not text or text in {"[]", "/"}:
        return ""
    markers = (
        "热水", "冷水", "开水", "沸水", "饮水", "补水",
        "保温", "热饮", "冷饮", "装水", "盛水", "液体",
        "装温水", "盛温水", "饮用温水",
    )
    clauses = [
        re.sub(r"\s+", " ", clause).strip()
        for clause in re.split(r"(?<=[。！？!?；;])\s*", text)
        if clause and clause.strip()
    ]
    return " ".join(
        clause for clause in clauses if any(marker in clause for marker in markers)
    ).strip()


def _usage_instruction_field_evidence(
    value: Any,
    canonical_field: str | None,
    *,
    requested_subtype: str | None = None,
) -> str:
    """Select only usage-instruction clauses compatible with the requested field.

    ``specs.usage_instruction`` is a shared storage column, not proof that every
    row contains cleaning and care guidance.  The central FieldContract may use
    it as a provider, but the provider must fail closed when no clause carries
    the requested semantics.
    """
    text = str(value or "").strip()
    field_type = str(canonical_field or "").strip()
    if not text or text in {"[]", "/"}:
        return ""

    def clean_segment(segment: str) -> str:
        cleaned = re.sub(r"\s+", " ", str(segment or "")).strip()
        # Imported instruction cells occasionally contain a stray terminal
        # ASCII token glued to Chinese prose.  It is not actionable evidence
        # and should not be repeated to customers.
        cleaned = re.sub(r"(?<=[\u4e00-\u9fff])[A-Za-z]{3,}\s*$", "", cleaned).strip()
        return cleaned

    text = re.sub(
        r"(?<=[\u4e00-\u9fff])[A-Za-z]{3,}(?=\s*(?:$|\r?\n))",
        "",
        text,
        flags=re.MULTILINE,
    ).strip()
    if field_type == "usage_instruction":
        return clean_segment(text)
    markers = _USAGE_INSTRUCTION_FIELD_MARKERS.get(field_type)
    if not markers:
        return text

    def has_field_marker(segment: str, target_field: str, target_markers: tuple[str, ...]) -> bool:
        matched = [marker for marker in target_markers if marker in segment]
        if not matched:
            return False
        if (
            target_field == "care"
            and set(matched) == {"收纳"}
            and re.search(r"(?:从.{0,8}收纳(?:包|袋).{0,8}取出|取出.{0,8}收纳(?:包|袋))", segment)
        ):
            return False
        return True

    selected: list[str] = []
    # Work with complete headings and numbered items. Splitting on commas or
    # line breaks produced fragments such as "1.使用后清洁泥土，" and could
    # join unrelated continuation lines into an unusable answer.
    sections = [
        section.strip()
        for section in re.split(r"(?=[【\[].*?[】\]])", text)
        if section and section.strip()
    ]
    for section in sections:
        heading_match = re.match(r"^([【\[].*?[】\]])", section)
        heading = heading_match.group(1) if heading_match else ""
        body = section[heading_match.end():] if heading_match else section
        heading_matches = bool(heading and any(marker in heading for marker in markers))
        items = [
            clean_segment(item)
            for item in re.split(r"(?m)(?=^\s*\d+\s*[.、)])", body)
            if clean_segment(item)
        ]
        if not items:
            items = [clean_segment(body)] if clean_segment(body) else []
        for item in items:
            if requested_subtype == "first_use" and not any(
                marker in item for marker in ("首次", "第一次", "第一次用", "开箱初洗")
            ):
                continue
            own_matches = has_field_marker(item, field_type, markers)
            competing_matches = any(
                has_field_marker(item, other_field, other_markers)
                for other_field, other_markers in _USAGE_INSTRUCTION_FIELD_MARKERS.items()
                if other_field != field_type
            )
            if own_matches and competing_matches:
                # A single imported sentence can join distinct instructions,
                # for example "用清水冲洗，使用后擦干并通风存放".  Keep
                # complete punctuation-delimited clauses for the requested
                # field instead of returning the other field's guidance too.
                clauses = [
                    clean_segment(clause)
                    for clause in re.split(r"(?<=[，,。！？!?；;])\s*", item)
                    if clean_segment(clause)
                ]
                keep_following = False
                for clause in clauses:
                    clause_matches_own = has_field_marker(clause, field_type, markers)
                    clause_matches_other = any(
                        has_field_marker(clause, other_field, other_markers)
                        for other_field, other_markers in _USAGE_INSTRUCTION_FIELD_MARKERS.items()
                        if other_field != field_type
                    )
                    if clause_matches_own:
                        selected.append(clause)
                        keep_following = True
                    elif clause_matches_other:
                        keep_following = False
                    elif keep_following:
                        # Unmarked continuation clauses often complete the
                        # preceding numbered instruction (for example the
                        # second half of an alternative drying method).
                        selected.append(clause)
            elif own_matches or (heading_matches and not competing_matches):
                selected.append(item)
    normalized_selected: list[str] = []
    for item in dict.fromkeys(selected):
        # Once clauses from different source sections are filtered into one
        # field answer, their original per-section numbering is no longer a
        # valid sequence.  Remove only the leading list marker; keep all
        # evidence text and any numbers that are part of the instruction.
        normalized = re.sub(r"^\d+\s*[.、)]\s*", "", item).strip()
        if normalized:
            normalized_selected.append(normalized)
    return " ".join(normalized_selected).strip().rstrip("，,；;：:")


def _usage_instruction_matches_product(product: Product, value: Any) -> bool:
    """Fail closed when an instruction cell clearly describes another domain."""
    return bool(product_vector_index_service.customer_visible_usage_instruction(
        product_name_cn=product.product_name_cn,
        product_name_en=product.product_name_en,
        category=product.category,
        sub_category=product.sub_category,
        value=value,
    ))


def _capacity_evidence_conflict(product_name: Any, structured_value: Any) -> tuple[str, str] | None:
    """Detect explicit capacity-unit contradictions without guessing a winner."""
    pattern = re.compile(r"(?<![\d.])(\d+(?:\.\d+)?)\s*(ml|毫升|l|升)", re.IGNORECASE)

    def values(text: Any) -> list[tuple[float, str]]:
        found: list[tuple[float, str]] = []
        for match in pattern.finditer(str(text or "")):
            number = float(match.group(1))
            unit = match.group(2).lower()
            milliliters = number if unit in {"ml", "毫升"} else number * 1000
            found.append((round(milliliters, 3), match.group(0).strip()))
        return found

    name_values = values(product_name)
    structured_values = values(structured_value)
    if not name_values or not structured_values:
        return None
    if {item[0] for item in name_values} & {item[0] for item in structured_values}:
        return None
    return name_values[0][1], structured_values[0][1]


_COLOR_FAMILY_CHARACTERS = frozenset("黑白红橙黄绿蓝紫粉灰银金棕褐咖锖")


def _color_evidence_conflict(product_name: Any, structured_value: Any) -> tuple[str, str] | None:
    """Detect an explicit color in a product name that conflicts with specs.

    Product names frequently carry the sellable variant in parentheses or
    after a dash.  Only those explicit variant spans are compared, so ordinary
    brand/name characters are not interpreted as colors.
    """
    name_text = str(product_name or "").strip()
    value_text = str(structured_value or "").strip()
    if not name_text or not value_text:
        return None
    name_spans = re.findall(r"[（(]([^（）()]{1,12})[）)]", name_text)
    name_spans.extend(re.findall(r"[-—]([^\s（）()]{1,12})$", name_text))
    name_colors = {
        char
        for span in name_spans
        for char in span
        if char in _COLOR_FAMILY_CHARACTERS
    }
    structured_colors = {char for char in value_text if char in _COLOR_FAMILY_CHARACTERS}
    if not name_colors or not structured_colors or name_colors & structured_colors:
        return None
    explicit_name_span = next(
        (span for span in name_spans if any(char in _COLOR_FAMILY_CHARACTERS for char in span)),
        "",
    )
    return explicit_name_span, value_text


def _resolve_single_product_field_evidence(
    db: Session,
    *,
    resolved_sku: str,
    requested_field: str,
    question: str,
) -> dict[str, Any]:
    product, specs, business, content = _phase1_product_bundle_by_ref(db, resolved_sku)
    if not product:
        return {
            "requested_field": requested_field,
            "evidence_field": None,
            "evidence_value": "",
            "evidence_source": None,
            "evidence_scope": None,
            "evidence_sku": None,
            "missing": True,
        }

    material_component = customer_field_contract.material_component_from_detail_label(requested_field)
    if material_component == "body":
        raw_material = str(getattr(specs, "body_material", "") or "").strip() if specs else ""
        body_material, _handle_material = customer_agent_intent_service._split_primary_and_handle_material(raw_material)
        value = _compound_display_value(body_material)
        return {
            "requested_field": requested_field,
            "evidence_field": "material" if value else None,
            "evidence_value": value,
            "evidence_source": "specs.body_material" if value else None,
            "evidence_scope": "body" if value else None,
            "evidence_sku": resolved_sku if value else None,
            "missing": not bool(value),
        }
    if material_component == "handle":
        raw_material = str(getattr(specs, "body_material", "") or "").strip() if specs else ""
        _body_material, handle_material = customer_agent_intent_service._split_primary_and_handle_material(raw_material)
        value = _compound_display_value(handle_material)
        return {
            "requested_field": requested_field,
            "evidence_field": "material" if value else None,
            "evidence_value": value,
            "evidence_source": "specs.body_material" if value else None,
            "evidence_scope": "handle" if value else None,
            "evidence_sku": resolved_sku if value else None,
            "missing": not bool(value),
        }
    if material_component == "lid":
        # General body-material cells do not evidence a lid.  Only a same-SKU
        # QA/knowledge statement that explicitly names both the lid and its
        # material is admissible; otherwise keep the missing-field boundary.
        value = customer_agent_intent_service._best_same_sku_evidence_text(
            db,
            sku=resolved_sku,
            supporting=None,
            term_groups=[("锅盖", "盖子", "杯盖"), ("材质", "材料")],
        )
        return {
            "requested_field": requested_field,
            "evidence_field": "material" if value else None,
            "evidence_value": _compound_display_value(value),
            "evidence_source": "product_qa:component_material" if value else None,
            "evidence_scope": "lid" if value else None,
            "evidence_sku": resolved_sku if value else None,
            "missing": not bool(value),
        }

    if requested_field == "适用场景":
        value = _compound_display_value(getattr(business, "usage_scenarios", "") if business else "")
        return {
            "requested_field": requested_field,
            "evidence_field": "usage_scene" if value else None,
            "evidence_value": value,
            "evidence_source": "business.usage_scenarios" if value else None,
            "evidence_scope": "subject" if value else None,
            "evidence_sku": resolved_sku if value else None,
            "missing": not bool(value),
        }

    field_contract = customer_field_contract.detect_field_contract(requested_field)
    canonical_field = (
        customer_field_contract.field_type_from_detail_label(requested_field)
        or (field_contract.field_type if field_contract else None)
    )
    detail_label = customer_field_contract.product_detail_field_label(canonical_field) if canonical_field else None
    if not canonical_field or not customer_field_contract.is_supported_detail_field(canonical_field) or not detail_label:
        return {
            "requested_field": requested_field,
            "evidence_field": canonical_field,
            "evidence_value": "",
            "evidence_source": None,
            "evidence_scope": None,
            "evidence_sku": None,
            "missing": True,
        }

    result = _product_field_followup_result(
        db,
        resolved_sku,
        detail_label,
        question,
        identity_source="phase2_resolved_entity",
        field_request_override={"field_type": canonical_field, "requested_field": detail_label, "source": "compound_field"},
    )
    metadata = result.get("answer_metadata") if isinstance(result, dict) and isinstance(result.get("answer_metadata"), dict) else {}
    evidence_status = str(metadata.get("evidence_status") or "").strip()
    missing = evidence_status in {"", "missing"}
    value = str(metadata.get("evidence_value") or "").strip()
    if not missing and not value:
        answer = str(result.get("answer") or "")
        marker = f"的{detail_label}："
        value = answer.split(marker, 1)[1].rstrip("。") if marker in answer else answer
    return {
        "requested_field": requested_field,
        "evidence_field": metadata.get("evidence_field") or (canonical_field if not missing else None),
        "evidence_value": _compound_display_value(value),
        "evidence_source": metadata.get("evidence_source"),
        "evidence_scope": metadata.get("evidence_scope"),
        "evidence_sku": metadata.get("evidence_sku") or (resolved_sku if not missing else None),
        "missing": missing,
    }


def _build_compound_product_detail_result(
    db: Session,
    *,
    resolved_sku: str,
    requested_fields: list[str],
    question: str,
    entity_contract: dict[str, Any] | None = None,
    compatibility_plan: dict[str, Any] | None = None,
) -> dict | None:
    product, specs, business, content = _phase1_product_bundle_by_ref(db, resolved_sku)
    if not product:
        return None
    # Compatibility extraction may emit product-component nouns (for example
    # "煎盘") alongside an actual field.  A component noun is not a second
    # FieldContract and must not preempt the same-SKU evidence route.  Keep
    # only labels that map to an existing canonical field contract.
    ordered_fields = list(dict.fromkeys(
        label
        for label in (str(field or "").strip() for field in requested_fields)
        if label and (
            customer_field_contract.field_type_from_detail_label(label)
            or (customer_field_contract.detect_field_contract(label) is not None)
        )
    ))
    if len(ordered_fields) < 2:
        return None
    field_results = [
        _resolve_single_product_field_evidence(
            db,
            resolved_sku=resolved_sku,
            requested_field=field,
            question=question,
        )
        for field in ordered_fields
    ]
    name = str(product.product_name_cn or product.product_name_en or resolved_sku).strip()
    lines = [f"{name}（{resolved_sku}）："]
    for field_result in field_results:
        label = field_result["requested_field"]
        value = str(field_result.get("evidence_value") or "").strip()
        if value:
            lines.append(f"- {label}：{value}")
        elif customer_field_contract.material_component_from_detail_label(label) == "lid":
            lines.append(f"- {label}：当前资料未单独提供锅盖材质。")
        else:
            lines.append(f"- {label}：当前资料未标注。")
    if _looks_like_portability_detail_question(question):
        lines.append(f"- {_same_sku_portability_detail_answer(db, resolved_sku)}")
    row = _product_row_from_model(product, specs, business, content)
    original_plan = compatibility_plan if isinstance(compatibility_plan, dict) else {}
    debug_plan = dict(original_plan)
    debug_plan.update({
        "primary_intent": str(original_plan.get("primary_intent") or "product_field"),
        "product_ref": resolved_sku,
        "sku": resolved_sku,
        "requested_fields": ordered_fields,
        "raw_question": question,
        "compound": True,
        "multi_field": True,
    })
    return {
        "intent": "product_detail",
        "answer_type": "product_detail",
        "answer": "\n".join(lines),
        "sku": resolved_sku,
        "results": [row],
        "result_skus": [resolved_sku],
        "candidate_skus": [resolved_sku],
        "answer_metadata": {
            "source": "resolved_entity_compound_detail",
            "answer_policy": "compound_field_evidence",
            "compound_fields": field_results,
        },
        "debug": {
            "agent_mode": "resolved_entity_compound_detail",
            "entity_resolution_contract": entity_contract or {},
            "requested_fields": ordered_fields,
            "compound": True,
            "multi_field": True,
            "plan": debug_plan,
        },
        "skip_polish": True,
    }


def _is_sealed_product_qa_safe_missing(result: dict | None) -> bool:
    """Whether a sealed QA attempt had identity but no direct evidence.

    This is a route-state check, not intent classification.  A safe-missing
    QA result remains the fallback for a compound supplement, but must not
    prevent the same sealed SKU from trying the RAG evidence provider.
    """
    return bool(
        isinstance(result, dict)
        and str((result.get("debug") or {}).get("agent_mode") or "")
        == "sealed_product_qa_safe_missing"
    )


async def _resolve_sealed_supplemental_product_evidence(
    db: Session,
    *,
    question: str,
    semantic_preplan: dict[str, Any] | None,
    base_plan: dict[str, Any] | None = None,
) -> tuple[dict | None, str]:
    """Use QA first, then sealed same-SKU RAG, for a semantic supplement."""
    effective_preplan = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    supplemental_query = str(effective_preplan.get("supplemental_qa_evidence_query") or "").strip()
    if not supplemental_query:
        return None, ""
    supplemental_preplan = dict(effective_preplan)
    supplemental_preplan.update({
        "canonical_fields": [], "field_type": "", "field_hint": None,
        "evidence_kind": "product_qa", "qa_evidence_query": supplemental_query,
        "compound": False,
    })
    supplemental_plan = dict(base_plan or {})
    supplemental_plan["semantic_preplan"] = supplemental_preplan
    supplemental_question = " ".join(
        item for item in (
            str(supplemental_preplan.get("subject_text") or "").strip(),
            supplemental_query,
        ) if item
    ) or question
    supplemental = await _try_product_qa_shortcut_with_semantic_selection(
        db, supplemental_question, phase1_plan=supplemental_plan,
    )
    qa_safe_missing = supplemental if _is_sealed_product_qa_safe_missing(supplemental) else None
    if qa_safe_missing:
        supplemental = None
    if not supplemental:
        for _supplemental_attempt in range(3):
            supplemental = await _try_sealed_same_sku_knowledge_answer(
                db, supplemental_question, supplemental_plan,
            )
            if supplemental:
                break
    if not supplemental and qa_safe_missing:
        # A formal-field turn can carry an independent suitability judgement.
        # If the QA/vector knowledge provider has no chunk, reuse the already
        # sealed SKU's structured evidence before exposing a missing-evidence
        # caveat.  This keeps capacity/people/usage facts available without
        # weakening the same-SKU grounding check or inventing a conclusion.
        supplemental = await _try_same_sku_structured_best_effort_answer(
            db,
            question=supplemental_question,
            safe_missing=qa_safe_missing,
            semantic_preplan=supplemental_preplan,
        )
    return supplemental or qa_safe_missing, supplemental_query


def _compose_alcohol_cause_boundary_answer(question: str) -> str | None:
    text = str(question or "").strip()
    if not (
        any(term in text for term in ("酒精", "燃料"))
        and any(term in text for term in ("问题", "原因", "导致", "是不是", "是否"))
    ):
        return None
    return "关于酒精/燃料是否导致你描述的问题：当前同 SKU 资料未标注该因果关系，不能仅凭材质判断。"


def _build_resolved_compound_evidence_result(
    db: Session,
    *,
    question: str,
    entity_contract: Any | None,
    field_request: dict[str, Any] | None,
    phase1_plan: dict[str, Any] | None = None,
) -> dict | None:
    """Execute a compound same-SKU evidence answer behind sealed contracts.

    The legacy compound formatter contains product-agnostic secondary evidence
    checks (for example a material question plus a durability question).  It
    is not permitted to resolve identity or choose the primary field here:
    both must already be sealed by Phase 2.  Returning ``None`` leaves normal
    one-field execution unchanged.
    """
    contract = entity_contract
    if not contract or not (
        contract.status == "resolved"
        and contract.resolved_sku
        and contract.is_unique
        and contract.confidence == "high"
        and contract.matched_by in _PHASE2_EXACT_ENTITY_MATCHES
        and contract.resolver_candidate_skus == [contract.resolved_sku]
    ):
        return None
    request = field_request if isinstance(field_request, dict) else {}
    canonical_fields = list(dict.fromkeys(
        str(field or "").strip()
        for field in (request.get("canonical_fields") or [])
        if str(field or "").strip() in customer_field_contract.FORMAL_DETAIL_FIELDS
    ))
    if not canonical_fields:
        return None
    product, specs, business, content = _phase1_product_bundle_by_ref(db, contract.resolved_sku)
    if not product:
        return None
    if len(canonical_fields) > 1:
        if str(contract.matched_by or "") == "recommendation_context_anchor":
            # This executor has already verified the anchor's resolved,
            # unique, high-confidence one-SKU contract above.  The context
            # provenance is not a raw-turn exact name, but it is a sealed
            # identity from the immediately preceding conversation state.
            resolution_decision = customer_entity_resolution_contract.SingleProductResolutionDecision(
                allowed=True,
                resolved_sku=str(contract.resolved_sku or "").strip().upper(),
                resolved_product_id=str(product.id),
                reason="resolved_context_anchor",
                match_level="recommendation_context_anchor",
            )
        else:
            resolution_decision = customer_entity_resolution_contract.can_resolve_single_product(contract, [product])
        if not resolution_decision.allowed:
            return None
        answers: list[str] = []
        evidence_items: list[dict[str, Any]] = []
        requested_labels_by_field: dict[str, list[str]] = {}
        for requested_label in request.get("requested_fields") or []:
            requested_type = customer_field_contract.field_type_from_detail_label(requested_label)
            if requested_type:
                requested_labels_by_field.setdefault(requested_type, []).append(str(requested_label))
        for field_type in canonical_fields:
            # A component qualifier refines the already-sealed canonical
            # material field.  Preserve that scope into the same-SKU evidence
            # provider instead of replacing it with the generic material
            # label in a compound answer.
            label = (requested_labels_by_field.get(field_type) or [
                customer_field_contract.product_detail_field_label(field_type)
            ])[0]
            if not label:
                return None
            supported = customer_field_contract.is_supported_detail_field(field_type)
            single_request = {
                "field_type": field_type,
                "requested_field": label,
                "requested_fields": [label],
                "canonical_fields": [field_type],
                "supported_fields": [field_type] if supported else [],
                "unsupported_fields": [] if supported else [field_type],
                "subject": str(request.get("subject") or ""),
                "requested_scope": "subject",
                "source": str(request.get("source") or "validated_semantic_preplan"),
                "confidence": float(request.get("confidence") or 0.0),
                "compound": False,
            }
            material_component = customer_field_contract.material_component_from_detail_label(label)
            if supported and material_component:
                # Component labels are evidence scopes for the already sealed
                # ``material`` contract.  The generic single-field formatter
                # would otherwise reread the whole body-material cell and
                # discard that scope in a compound answer.
                component_evidence = _resolve_single_product_field_evidence(
                    db,
                    resolved_sku=contract.resolved_sku,
                    requested_field=label,
                    question=question,
                )
                component_value = str(component_evidence.get("evidence_value") or "").strip()
                component_missing = bool(component_evidence.get("missing"))
                if component_value:
                    component_answer = f"{product.product_name_cn}（{contract.resolved_sku}）的{label}：{component_value}。"
                elif material_component == "lid":
                    component_answer = f"当前资料未单独提供{product.product_name_cn}（{contract.resolved_sku}）的锅盖材质。"
                else:
                    component_answer = f"当前资料未单独提供{product.product_name_cn}（{contract.resolved_sku}）的{label}。"
                field_result = {
                    "intent": "product_detail",
                    "answer_type": "product_detail",
                    "answer": component_answer,
                    "result_skus": [contract.resolved_sku],
                    "answer_metadata": {
                        "evidence_status": "missing" if component_missing else "structured",
                        "evidence_field": component_evidence.get("evidence_field"),
                        "evidence_source": component_evidence.get("evidence_source"),
                        "evidence_value": component_value,
                        "evidence_sku": component_evidence.get("evidence_sku"),
                    },
                }
            elif supported:
                field_result = _product_field_followup_result(
                    db,
                    contract.resolved_sku,
                    label,
                    question,
                    identity_source="phase2_resolved_entity",
                    field_request_override=single_request,
                )
            else:
                field_result = _build_resolved_product_unknown_field_result(
                    db,
                    product,
                    label=label,
                    source="resolved_entity_unknown_field_fallback",
                    resolution_decision=resolution_decision,
                )
            if not field_result or field_result.get("result_skus") != [contract.resolved_sku]:
                return None
            answer = str(field_result.get("answer") or "").strip()
            if not answer:
                return None
            answers.append(answer)
            field_metadata = field_result.get("answer_metadata") if isinstance(field_result.get("answer_metadata"), dict) else {}
            evidence_items.append({
                "field_type": field_type,
                "requested_field": label,
                "evidence_status": field_metadata.get("evidence_status"),
                "evidence_field": field_metadata.get("evidence_field"),
                "evidence_source": field_metadata.get("evidence_source"),
                "evidence_value": field_metadata.get("evidence_value"),
                "evidence_sku": field_metadata.get("evidence_sku"),
            })
        alcohol_cause_boundary = _compose_alcohol_cause_boundary_answer(question)
        if alcohol_cause_boundary:
            answers.insert(0, alcohol_cause_boundary)
        if _looks_like_portability_detail_question(question):
            answers.append(_same_sku_portability_detail_answer(db, contract.resolved_sku))
        row = _product_row_from_model(product, specs, business, content)
        plan = dict(phase1_plan or {})
        plan.update({
            "product_ref": contract.resolved_sku,
            "sku": contract.resolved_sku,
            "requested_fields": list(request.get("requested_fields") or []),
            "field_contract": dict(request),
            "compound": True,
            "raw_question": question,
        })
        evidence_skus = list(dict.fromkeys(
            str(item.get("evidence_sku") or "").strip().upper()
            for item in evidence_items
            if str(item.get("evidence_sku") or "").strip()
        ))
        return {
            "intent": "product_detail",
            "answer_type": "product_detail",
            "answer": "\n".join(answers),
            "sku": contract.resolved_sku,
            "results": [row],
            "result_skus": [contract.resolved_sku],
            "candidate_skus": [contract.resolved_sku],
            "answer_metadata": {
                "source": "resolved_entity_multi_field_contract",
                "answer_policy": "sealed_same_sku_multi_field_evidence",
                "contract_field_types": canonical_fields,
                "evidence_items": evidence_items,
                # Retain the established compound audit surface.  It is the
                # same per-field, sealed-SKU evidence list as ``evidence_items``
                # (not a second resolver or formatter path).
                "compound_fields": evidence_items,
                "evidence_skus": evidence_skus,
                "evidence_status": "structured" if any(item.get("evidence_value") for item in evidence_items) else "missing",
            },
            "debug": {
                "agent_mode": "resolved_entity_multi_field_contract",
                "binding_provenance": "resolved_entity_contract",
                "entity_resolution_contract": contract.to_dict(),
                "field_contract": dict(request),
                "plan": plan,
            },
            "skip_polish": True,
        }
    # This adapter is deliberately multi-field only. A single formal field
    # must continue to the ordinary Phase-2 provider, where field-specific
    # validation and same-SKU QA/RAG fallback are available.
    return None


_PHASE2_EXACT_ENTITY_MATCHES = {
    "sku_exact",
    "normalized_sku_exact",
    "canonical_name_exact",
    "normalized_alias_exact",
    # Identity was sealed by the immediately preceding single-product turn;
    # it is eligible for the same compound evidence executor as an exact name.
    "recommendation_context_anchor",
}


def _choose_effective_entity_contract(
    question: str,
    products: list[Product],
    *,
    resolver_candidates: list[Product] | None = None,
    override_subject: str | None = None,
) -> customer_entity_resolution_contract.EntityContractSelection:
    default_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
        question,
        products,
        resolver_candidates=resolver_candidates,
    )
    override_contract = None
    normalized_override = customer_agent_service.normalize_search_text(override_subject or "").strip()
    if normalized_override and normalized_override != default_contract.normalized_entity_text:
        override_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
            question,
            products,
            resolver_candidates=resolver_candidates,
            entity_text_override=override_subject,
        )
    return customer_entity_resolution_contract.choose_effective_entity_contract(
        default_contract,
        override_contract,
        products,
    )






def resolve_requested_field_contract(
    question: str,
    phase1_plan: dict | None = None,
    *,
    subject_override: str | None = None,
) -> dict[str, Any]:
    """Central Phase 2 adapter over the stable legacy field extractor."""
    compatibility_fields = customer_agent_intent_service._requested_fields_for_detail_question(question)
    selection = customer_field_contract.select_entity_subject_for_routing(raw_question=question)
    subject = str(subject_override or "").strip()
    if not subject:
        subject = selection.entity_subject if selection.source == "field_contract" else ""
    if not subject:
        subject = customer_agent_intent_service._detail_subject_from_question(question).strip()
    if not subject:
        # The broad SKU extractor intentionally emits a short compatibility
        # suffix as well as the full SKU for some forms (for example CW-C95
        # and C95).  A full token that contains every other extraction is one
        # unambiguous identity, not a multi-product request.
        explicit_skus = list(dict.fromkeys(
            str(item or "").strip().upper()
            for item in customer_agent_service._extract_skus(str(question or ""))
            if str(item or "").strip()
        ))
        longest = max(explicit_skus, key=len, default="")
        if longest and all(item in longest for item in explicit_skus):
            subject = longest
    if subject and compatibility_fields:
        # Legacy recognition may see a field-looking token inside the product
        # name itself (for example a product whose name contains "煎盘"). Only
        # retain compatibility fields that also occur outside the selected
        # subject; the formal FieldContract remains authoritative.
        predicate_text = customer_agent_intent_service._remove_subject_once(question, subject)
        predicate_fields = customer_agent_intent_service._requested_fields_for_detail_question(predicate_text)
        compatibility_fields = [field for field in compatibility_fields if field in predicate_fields]
        # The old extractor treats component nouns such as “手柄” and product
        # title text such as “10件套” as material/accessory hints.  They are not
        # field predicates by themselves.  Keep a legacy mapped field only
        # when the remaining predicate carries the formal field signal (or a
        # concrete material assertion); semantic planning remains the primary
        # route for broader natural-language meaning.
        predicate_types = set(customer_field_contract.detect_field_types(predicate_text))
        material_assertion = bool(re.search(
            r"材质|材料|304|不锈钢|铝合金|硬质氧化铝|钛|木质|白蜡木|胡桃木|榉木",
            predicate_text,
            flags=re.IGNORECASE,
        ))
        compatibility_fields = [
            field
            for field in compatibility_fields
            if not (field_type := customer_field_contract.field_type_from_detail_label(field))
            or field_type in predicate_types
            or (field_type == "material" and material_assertion)
        ]
    # When semantic planning is unavailable, a high-confidence field-only
    # planner task is the controlled fallback for natural wording that has no
    # literal alias (for example a size question phrased without “尺寸”).
    # Adapt that canonical planner label into the one FieldContract instead
    # of allowing an entity or QA shortcut to answer first.
    planned_label = str((phase1_plan or {}).get("requested_field") or "").strip()
    planned_field = customer_field_contract.field_type_from_detail_label(planned_label)
    if (
        not compatibility_fields
        and str((phase1_plan or {}).get("primary_intent") or "") == "product_field"
        and bool((phase1_plan or {}).get("field_only"))
        and customer_field_contract.is_supported_detail_field(planned_field)
    ):
        compatibility_fields = [planned_label]
    resolved_contract = customer_field_contract.resolve_requested_field_contract(
        question,
        phase1_plan,
        compatibility_fields=compatibility_fields,
        subject=subject,
        requested_scope=selection.requested_scope,
        subject_is_catalog_exact=bool(str(subject_override or "").strip()),
    )
    # The semantic planner may correctly classify a named-product
    # compatibility turn as product QA while leaving ``canonical_fields``
    # empty.  If the customer's wording contains an explicit heat-source
    # predicate, recover the existing deterministic FieldContract so Phase 2
    # can read the same-SKU heat evidence instead of falling into generic
    # safety prose.  This is a planner/provider arbitration fallback, not a
    # product- or SKU-specific answer rule.
    detected_contract = customer_field_contract.detect_field_contract(question)
    if (
        not str(resolved_contract.get("field_type") or "").strip()
        and detected_contract is not None
        and str(getattr(detected_contract, "field_type", "") or "").strip() == "heat_source"
        and _looks_like_compatibility_usage_question(question)
    ):
        resolved_contract = customer_field_contract.resolve_requested_field_contract(
            question,
            None,
            compatibility_fields=(customer_field_contract.product_detail_field_label("heat_source") or "适用热源",),
            subject=subject,
            requested_scope=selection.requested_scope,
            subject_is_catalog_exact=bool(str(subject_override or "").strip()),
        )
        resolved_contract["source"] = "deterministic_compatibility_field_recovery"
    return resolved_contract


def _build_phase2_entity_resolution_context(
    db: Session,
    question: str,
    field_request: dict[str, Any] | None = None,
    phase1_plan: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Build the deterministic Phase 2 entity snapshot once for this request."""
    try:
        products = db.query(Product).order_by(Product.sku.asc()).all()
        subject_selection = customer_field_contract.select_entity_subject_for_routing(
            raw_question=question,
        )
        canonical_subject = customer_entity_resolution_contract.unique_canonical_subject_in_question(
            question,
            products,
        )
        if canonical_subject:
            normalized_subject = customer_agent_service.normalize_search_text(canonical_subject)
            raw_canonical_owners = {
                str(product.sku or "").strip().upper()
                for product in products
                if any(
                    customer_agent_service.normalize_search_text(raw_name) == normalized_subject
                    for raw_name in (
                        str(product.product_name_cn or "").strip(),
                        str(product.product_name_en or "").strip(),
                    )
                    if raw_name
                )
            }
            subject_start = str(question or "").lower().find(str(canonical_subject).lower())
            suffix = (
                str(question or "")[subject_start + len(canonical_subject):]
                if subject_start >= 0
                else ""
            ).lstrip(" 的，,：:；;。.!！?？")
            explicit_variant_suffix = bool(re.match(
                r"^(?:(?:pro|plus)(?![A-Za-z0-9])|基础款|标准版|升级款|旗舰版|"
                r"\d+(?:\.\d+)?\s*(?:杯|寸|英寸|ml|毫升|l|升)|"
                r"(?:黑|白|红|橙|黄|绿|蓝|紫|粉|灰|银|金)(?:色)?)",
                suffix,
                flags=re.IGNORECASE,
            ))
            if len(raw_canonical_owners) != 1 or explicit_variant_suffix:
                canonical_subject = ""
        # A previously formed semantic FieldContract is authoritative here.
        # Re-running the legacy parser solely to obtain a canonical product
        # subject can otherwise replace that field with an incidental word in
        # the question (e.g. ``brand`` in a price-tier request).  The exact
        # catalogue subject remains an input to EntityResolution only; it does
        # not come from semantic classification.
        if (
            isinstance(field_request, dict)
            and field_request.get("source") in {
                "validated_semantic_preplan",
                "deterministic_explicit_multi_field",
            }
        ):
            resolved_field_request = dict(field_request)
            if canonical_subject:
                resolved_field_request["subject"] = canonical_subject
        else:
            resolved_field_request = dict(
                resolve_requested_field_contract(
                    question,
                    phase1_plan,
                    subject_override=canonical_subject,
                )
                if canonical_subject
                else (field_request or resolve_requested_field_contract(question, phase1_plan))
            )
        semantic_preplan = (
            (phase1_plan or {}).get("semantic_preplan")
            if isinstance((phase1_plan or {}).get("semantic_preplan"), dict)
            else {}
        )
        recovered_semantic_subject = str(semantic_preplan.get("subject_text") or "").strip()
        if (
            semantic_preplan.get("semantic_identity_recovery") == "catalog_unique_one_edit"
            and recovered_semantic_subject
        ):
            # The semantic layer established that this is a product-bound
            # field request; catalogue uniqueness then corrected one literal
            # character. Keep the already parsed fields, but replace the
            # polluted legacy subject before EntityResolutionContract runs.
            resolved_field_request["subject"] = recovered_semantic_subject
            resolved_field_request["subject_is_catalog_exact"] = True
        entity_subject = str(resolved_field_request.get("subject") or "").strip() or None
        if not entity_subject and resolved_field_request.get("source") == "validated_semantic_preplan":
            # The semantic preplan owns field meaning and may also identify a
            # subject span for natural wording whose predicate has no fixed
            # deterministic alias (for example an included-items question).
            # Accept it only when the exact normalized text occurs in this
            # turn; EntityResolutionContract still decides whether it binds a
            # unique catalogue SKU.
            semantic_subject = str(
                ((phase1_plan or {}).get("semantic_preplan") or {}).get("subject_text") or ""
            ).strip()
            normalized_question = customer_agent_service.normalize_search_text(question)
            normalized_semantic_subject = customer_agent_service.normalize_search_text(semantic_subject)
            if normalized_semantic_subject and normalized_semantic_subject in normalized_question:
                entity_subject = semantic_subject
                resolved_field_request["subject"] = entity_subject
        if not entity_subject and resolved_field_request.get("source") == "validated_semantic_preplan":
            # Reuse only the catalogue subject that already passed the raw
            # canonical-owner and explicit-variant-suffix checks above.  A
            # second unguarded lookup here would promote display aliases or a
            # base name followed by an unavailable variant (for example a
            # version suffix), bypassing the fail-closed entity contract.
            entity_subject = canonical_subject or None
            if entity_subject:
                resolved_field_request["subject"] = entity_subject
        contract = customer_entity_resolution_contract.build_entity_resolution_contract(
            question,
            products,
            entity_text_override=entity_subject,
            field_type_override=resolved_field_request.get("field_type"),
        )
        return {
            "products_snapshot": products,
            "contract": contract,
            "field_request": resolved_field_request,
            "entity_subject_selection": subject_selection,
            "error": None,
        }
    except Exception as exc:
        return {"products_snapshot": [], "contract": None, "error": f"{type(exc).__name__}: {exc}"}


def _phase2_single_field_arbitration_eligible(
    question: str,
    phase1_plan: dict | None,
    *,
    conversation_id: str | None,
    field_request_override: dict[str, Any] | None = None,
) -> bool:
    plan = phase1_plan if isinstance(phase1_plan, dict) else {}
    field_request = field_request_override or resolve_requested_field_contract(question, plan)
    current_subject = str(field_request.get("subject") or "").strip().strip("「」『』\"'“”")
    # A field predicate can describe a catalogue request ("哪种适合露营")
    # rather than a fact about one product.  Interrogative subjects never
    # establish single-product identity, so leave them to query/recommendation
    # routing instead of manufacturing an entity clarification.
    if re.match(r"^(?:哪种|哪款|哪些|什么|有哪|有没有)", current_subject):
        return False
    validated_semantic_subject = bool(
        current_subject
        and field_request.get("source") == "validated_semantic_preplan"
    )
    if (
        str(field_request.get("field_type") or "") in {"cleaning", "care", "usage_instruction"}
        and customer_agent_intent_service._looks_like_usage_care_question(question)
        and not _looks_like_product_like_scope_subject(current_subject)
        and not SKU_RE.fullmatch(current_subject)
        and not validated_semantic_subject
    ):
        # Generic care questions have no product identity to seal. Preserve
        # the established usage/care knowledge path; explicit products still
        # form EntityResolutionContract below.
        return False
    if conversation_id:
        # A conversation anchor is only a supplement to identity.  When the
        # current turn carries a formal field predicate and a concrete subject,
        # it must still enter EntityResolutionContract; otherwise an explicit
        # correction such as “我想问「…」的热源” falls through to generic tool
        # calling despite having a sealed current-turn identity.  Pure
        # pronouns retain the established anchor-specific follow-up path.
        if not current_subject or re.match(
            r"^(?:它|它的|这个|这个商品|这款|该商品|该产品|这件商品|本产品|那个|那款)",
            current_subject,
        ):
            return False
    # The legacy compatibility extractor can still label in-box wording as
    # "contents". Let the authoritative FieldContract keep those requests in
    # entity arbitration instead of falling through to a dedicated usage route.
    non_usage_field_request = _has_non_usage_care_field_contract(question)
    # A validated semantic field is the same central contract signal as a
    # deterministic alias.  It must be allowed into Phase 2 before legacy
    # usage/QA shortcuts can interpret the surrounding natural language.
    semantic_field_request = bool(
        field_request.get("source") == "validated_semantic_preplan"
        and field_request.get("canonical_fields")
    )
    primary_intent = str(plan.get("primary_intent") or "").strip()
    if primary_intent not in {"", "product_detail", "product_field"} and not non_usage_field_request and not semantic_field_request:
        return False
    if plan.get("routing_conflict") or plan.get("must_compare_both_products") or plan.get("must_make_choice"):
        return False
    # A planner may expose an exact product reference while still assigning a
    # broad compatibility intent.  That is not a competing product-list
    # request when a validated FieldContract has already identified one
    # supported detail field; Phase 2 must arbitrate identity instead of
    # handing the request back to the legacy executor.
    if (
        (plan.get("must_return_products") or plan.get("product_refs"))
        and not non_usage_field_request
        and not semantic_field_request
    ):
        return False
    tasks = [task for task in (plan.get("tasks") or []) if isinstance(task, dict)]
    if (
        len(tasks) > 1
        or any(str(task.get("type") or "") not in {"", "product_field"} for task in tasks)
    ) and not non_usage_field_request and not semantic_field_request:
        return False
    if len(field_request["requested_fields"]) > 1:
        return False
    return len(field_request["canonical_fields"]) == 1








def _looks_like_compound_contents_usage_question(question: str) -> bool:
    text = str(question or "").strip()
    if not customer_agent_intent_service._looks_like_contents_grounding_question(text):
        return False
    return any(
        term in text
        for term in ("直接用", "直接使用", "买回来", "到手", "收到货")
    )












def _classify_phase2_entity_state_action(
    question: str,
    phase1_plan: dict | None = None,
    *,
    conversation_id: str | None = None,
    signals: dict[str, bool] | None = None,
    entity_resolution_context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Classify Phase 2 entity handling without formatting a response."""
    field_request = (
        (entity_resolution_context or {}).get("field_request")
        or resolve_requested_field_contract(question, phase1_plan)
    )
    if not _phase2_single_field_arbitration_eligible(
        question,
        phase1_plan,
        conversation_id=conversation_id,
        field_request_override=field_request,
    ):
        return {"action": "pass_through", "reason": "ineligible"}
    if (signals or {}).get("scenario_recommendation"):
        return {"action": "pass_through", "reason": "scenario_recommendation"}
    if (signals or {}).get("realtime_weather"):
        return {"action": "pass_through", "reason": "realtime_weather"}
    if (signals or {}).get("generic_heat_source_selection"):
        return {"action": "pass_through", "reason": "generic_heat_source_selection"}
    if (signals or {}).get("generic_accessory_catalog"):
        return {"action": "pass_through", "reason": "generic_accessory_catalog"}
    field = customer_field_contract.field_contract_for_type(field_request.get("field_type"))
    requested_field = field_request.get("requested_field")
    if not field or not requested_field:
        return {"action": "pass_through", "reason": "no_detail_field"}
    subject_selection = (entity_resolution_context or {}).get("entity_subject_selection")
    if subject_selection and _is_generic_company_product_scope(
        str(getattr(subject_selection, "entity_subject", "") or "")
    ):
        return {"action": "pass_through", "reason": "generic_company_product_scope"}
    # Every formal customer field, including safely unsupported realtime and
    # service fields, must arbitrate entity identity here.  The distinction
    # between supported evidence execution and safe missing is applied only
    # after the canonical SKU has been sealed.

    context = entity_resolution_context or {}
    products = list(context.get("products_snapshot") or [])
    contract = context.get("contract")
    if contract is None:
        return {"action": "pass_through", "reason": "entity_contract_unavailable"}

    if subject_selection and _is_generic_field_subject(str(getattr(subject_selection, "entity_subject", "") or "")):
        if (signals or {}).get("category_general"):
            # A formally parsed category+field aggregation (for example a
            # category's available capacities) owns this generic subject.
            # It must run before the single-product fail-closed clarification,
            # while exact/ambiguous named products remain protected by the
            # category-general exclusion gate.
            return {"action": "pass_through", "reason": "category_field_general"}
        # A category label plus a product-bound field is not permission to
        # promote search results into a single-product answer.  Keep the
        # FieldContract and return the same explicit clarification used for
        # any other generic entity state.
        return {"action": "generic_clarification", "reason": "generic_field_subject", "contract": contract}

    plan_primary_intent = str((phase1_plan or {}).get("primary_intent") or "").strip()
    planner_confirms_detail = plan_primary_intent in {"product_detail", "product_field"}
    field_contract_confirms_detail = bool(
        contract.entity_text
        and requested_field
        and (
            field_request.get("source") == "validated_semantic_preplan"
            or
            customer_field_contract.is_field_contract_predicate_signal(
                context.get("entity_subject_selection")
            )
            or _has_non_usage_care_field_contract(question)
        )
    )
    rich_field_compatibility = not plan_primary_intent and field.field_type in {
        "model",
        "dimensions",
        "specification",
    }

    high_priority_signal = any(
        bool(value)
        for key, value in (signals or {}).items()
        if key != "dedicated_route"
        and not (
            key == "compound"
            and field.field_type == "accessories"
            and _looks_like_compound_contents_usage_question(question)
        )
    ) or bool(
        (signals or {}).get("dedicated_route")
        and not _has_non_usage_care_field_contract(question)
    )

    resolved_exact = bool(
        contract.status == "resolved"
        and contract.resolved_sku
        and contract.is_unique
        and contract.confidence == "high"
        and contract.matched_by in _PHASE2_EXACT_ENTITY_MATCHES
        and contract.resolver_candidate_skus == [contract.resolved_sku]
    )
    resolved_exact_blocked = bool(
        (signals or {}).get("recommendation")
        or (signals or {}).get("comparison")
        or (
            (signals or {}).get("compound")
            and not (
                field.field_type == "accessories"
                and _looks_like_compound_contents_usage_question(question)
            )
        )
        or (signals or {}).get("multi_product")
        or (signals or {}).get("multi_condition_recommendation")
    )

    if not resolved_exact or resolved_exact_blocked:
        if high_priority_signal:
            return {"action": "pass_through", "reason": "higher_priority_route"}

        displayable_candidate_skus = _displayable_phase2_clarification_candidate_skus(contract)
        if (
            contract.status == "ambiguous"
            and displayable_candidate_skus
            and (planner_confirms_detail or rich_field_compatibility or field_contract_confirms_detail)
        ):
            return {
                "action": "ambiguous_clarification",
                "reason": "formal_candidates_ambiguous",
                "contract": contract,
                "products": products,
                "displayable_candidate_skus": displayable_candidate_skus,
            }
        if (
            contract.status == "ambiguous"
            and contract.resolver_candidate_skus
            and (planner_confirms_detail or rich_field_compatibility or field_contract_confirms_detail)
        ):
            return {
                "action": "unresolved_clarification",
                "reason": "weak_single_candidate_not_displayable",
                "contract": contract,
            }
        if (
            contract.status == "ambiguous"
            and contract.diagnostic_candidate_skus
            and (planner_confirms_detail or rich_field_compatibility or field_contract_confirms_detail)
        ):
            return {
                "action": "ambiguous_clarification",
                "reason": "diagnostic_candidates_not_displayable",
                "contract": contract,
                "products": products,
                "displayable_candidate_skus": [],
            }

        generic_scope = contract.status == "generic" or (
            not contract.resolver_candidate_skus
            and _looks_like_generic_constraint_category_query(question)
        )
        if generic_scope and field_contract_confirms_detail:
            return {"action": "generic_clarification", "reason": "generic_field_subject", "contract": contract}
        if generic_scope and planner_confirms_detail and isinstance(phase1_plan, dict):
            product_ref = _semantic_catalog_product_ref(question) or "产品"
            phase1_plan.update(
                {
                    "primary_intent": "catalog_count",
                    "answer_type": "query_products",
                    "product_ref": product_ref,
                    "field_only": False,
                    "allow_search_top1_promotion": False,
                    "entity_resolution_contract": contract.to_dict(),
                }
            )
            return {"action": "pass_through", "reason": "generic_category_constraint", "contract": contract}

        if (
            contract.status == "unresolved"
            and contract.entity_text
            and (planner_confirms_detail or rich_field_compatibility or field_contract_confirms_detail)
        ):
            return {"action": "unresolved_clarification", "reason": "concrete_entity_unresolved", "contract": contract}
        return {"action": "pass_through", "reason": "no_entity_action", "contract": contract}

    return {
        "action": "resolved_detail",
        "reason": "resolved_exact_supported_field",
        "contract": contract,
        "products": products,
        "field": field,
        "requested_field": requested_field,
    }


def _displayable_phase2_clarification_candidate_skus(contract: Any) -> list[str]:
    if str(getattr(contract, "status", "") or "") != "ambiguous":
        return []
    unique_skus = list(dict.fromkeys(
        str(sku or "").strip().upper()
        for sku in (getattr(contract, "resolver_candidate_skus", None) or [])
        if str(sku or "").strip()
    ))
    return unique_skus if len(unique_skus) >= 2 else []


def _safe_customer_entity_text(entity_text: str | None, question: str | None = None) -> str | None:
    """Return an entity label only when it is safe to show to the customer.

    The semantic planner may emit a prefix of a sentence as ``entity_text``
    (for example ``“带炉子吗，炉子”``).  Echoing that prefix makes a
    clarification look like a product name and hides the real request.  Keep
    explicit SKU-like references and canonical product-like names, but fail
    closed for sentence fragments, interrogative wording, punctuation, and
    unmatched brackets.
    """
    value = str(entity_text or "").strip(" \t\r\n'\"“”‘’「」『』（）()，,。！？!?；;：:")
    if not value:
        return None

    # An explicit SKU is a stable customer-facing reference even when the
    # catalogue does not contain it; it is useful in the follow-up request.
    if re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._()（）/\-\u4e00-\u9fff]{2,}", value) and "-" in value:
        return value

    if any(mark in value for mark in (
        "，", ",", "。", "！", "!", "？", "?", "；", ";", "：", ":",
        "吗", "嘛", "呢", "怎么", "如何", "为什么", "是不是", "是否",
        "能不能", "能否", "可以", "带", "还是", "多大", "多少", "哪里",
        "什么", "有没有", "有无", "会不会", "买", "放进去", "之前",
        "因为", "我", "他", "这个", "那个", "最高", "火力",
    )):
        return None
    if len(value) > 24 or any(value.count(left) != value.count(right) for left, right in (("（", "）"), ("(", ")"))):
        return None
    if not _looks_like_product_like_scope_subject(value):
        return None

    # If the planner selected a prefix of this turn, only accept it when the
    # remaining text clearly starts a supported product-field question.
    raw_question = str(question or "").strip()
    if raw_question.startswith(value) and len(raw_question) > len(value):
        tail = raw_question[len(value):].lstrip(" \t，,：:")
        allowed_tail = re.compile(
            r"^(?:的)?(?:是什么|啥|哪种|型号|材质|主体材质|容量|重量|尺寸|功率|热源|燃料|配件|包装|内容|可以|能不能|能否|是否|是不是|适合|有多重|多大|多少|怎么|如何|有没有|有无|支持|能用|价格|多少钱|保修|售后|清洗|使用|安装|点火|调节|火力)",
        )
        if tail and not allowed_tail.match(tail):
            return None
    return value


def _build_phase2_entity_state_response(db: Session, question: str, decision: dict[str, Any]) -> dict | None:
    """Format a previously classified Phase 2 entity-state decision."""
    action = str(decision.get("action") or "pass_through")
    if action == "pass_through":
        return None
    contract = decision.get("contract")
    products = list(decision.get("products") or [])
    display_entity_text = _safe_customer_entity_text(
        getattr(contract, "entity_text", ""),
        question,
    )
    display_entity_label = display_entity_text or (
        "当前页面商品"
        if any(marker in str(question or "") for marker in ("当前商品", "当前页面", "页面商品"))
        else "这个商品"
    )
    if action == "ambiguous_clarification":
        displayable_candidate_skus = list(decision.get("displayable_candidate_skus") or [])
        product_by_sku = {
            str(product.sku or "").strip().upper(): product
            for product in products
        }
        options = [
            product_by_sku[sku]
            for sku in displayable_candidate_skus
            if sku in product_by_sku
        ]
        option_text = "；".join(
            f"{str(product.product_name_cn or product.product_name_en or product.sku).strip()}（{str(product.sku or '').strip().upper()}）"
            for product in options[:5]
        )
        route_source = (
            "named_product_unknown_field_clarification"
            if str(getattr(contract, "field_type", "") or "") in {"gift", "manual"}
            else "entity_state_detail_ambiguous"
        )
        compatibility_question = any(
            term in str(question or "")
            for term in ("能不能接", "能否接", "能不能用", "适配", "兼容", "通用气罐")
        )
        if compatibility_question:
            answer = (
                f"“{display_entity_label}”匹配到多个商品：{option_text}。"
                if option_text
                else f"“{display_entity_label}”对应多个相关商品。"
            ) + "由于具体款式未确定，当前无法确认通用气罐能否连接；请指定具体款式或 SKU 后再核对。"
        else:
            answer = (
                f"“{display_entity_label}”匹配到多个商品：{option_text}。请指定具体款式或 SKU。"
                if option_text
                else f"“{display_entity_label}”对应多个相关商品，请先指定具体款式或 SKU。"
            )
        return {
            "intent": "clarify", "answer_type": "clarification",
            "answer": answer,
            "results": [], "result_skus": [], "candidate_skus": displayable_candidate_skus,
            "needs_clarification": True,
            "answer_metadata": {"source": route_source, "evidence_status": "ambiguous_product"},
            "debug": {"agent_mode": route_source, "entity_resolution_contract": contract.to_dict()},
            "skip_polish": True,
        }
    if action == "unresolved_clarification":
        route_source = (
            "unresolved_product_like_contents_clarification"
            if str(getattr(contract, "field_type", "") or "") == "accessories"
            else (
                "unresolved_product_like_unknown_field_clarification"
                if str(getattr(contract, "field_type", "") or "") == "gift"
                else "entity_state_detail_unresolved"
            )
        )
        answer = (
            f"没有找到“{display_entity_text}”对应的商品资料，请确认商品名或提供 SKU。"
            if display_entity_text
            else "当前还无法锁定具体商品，暂时没有找到可核对的商品资料；请提供完整商品名或具体 SKU。"
        )
        return {
            "intent": "clarify", "answer_type": "clarification",
            "answer": answer,
            "results": [], "result_skus": [], "candidate_skus": [], "needs_clarification": True,
            "answer_metadata": {"source": route_source, "evidence_status": "product_not_found"},
            "debug": {"agent_mode": route_source, "entity_resolution_contract": contract.to_dict()},
            "skip_polish": True,
        }
    if action == "generic_clarification":
        # The subject-selection guard has concluded that the phrase is a
        # generic category-like scope.  An earlier resolver observation may
        # have found a coincidental canonical-name match, but that observation
        # must not leak as an exact identity alongside a fail-closed generic
        # clarification.  This is an output-contract correction only: it
        # neither promotes a SKU nor changes the field's semantic meaning.
        generic_contract = contract.to_dict()
        generic_contract.update({
            "status": "generic",
            "resolved_sku": None,
            "resolver_candidate_skus": [],
            "diagnostic_candidate_skus": [],
            "candidate_skus": [],
            "matched_by": "none",
            "confidence": "low",
            "is_unique": False,
            "matched_span": None,
            "status_reason": "generic_field_subject",
        })
        return {
            "intent": "clarify", "answer_type": "clarification",
            "answer": f"“{display_entity_label}”还不是明确的单个商品，请提供完整商品名或 SKU。",
            "results": [], "result_skus": [], "candidate_skus": [], "needs_clarification": True,
            "answer_metadata": {"source": "entity_state_detail_generic", "evidence_status": "generic_product"},
            "debug": {
                "agent_mode": "entity_state_detail_generic",
                # A generic subject is deliberately never promoted to a product.
                # Keep that binding decision observable just like resolved/ambiguous
                # detail contracts, so downstream diagnostics cannot mistake this
                # clarification for a missing contract.
                "binding_provenance": "none",
                "search_top1_promotion_blocked": True,
                "entity_resolution_contract": generic_contract,
            },
            "skip_polish": True,
        }

    field = decision["field"]
    requested_field = decision["requested_field"]
    product = next(
        (item for item in products if str(item.sku or "").strip().upper() == contract.resolved_sku),
        None,
    )
    shipping_qa_evidence_available = bool(
        str(field.field_type or "") == "shipping"
        and product is not None
        and _best_product_qa_match(
            db,
            product,
            question,
            requested_field_type="shipping",
        ) is not None
    )

    if not customer_field_contract.is_supported_detail_field(field.field_type) and not shipping_qa_evidence_available:
        if not product:
            return None
        resolution_decision = customer_entity_resolution_contract.can_resolve_single_product(
            contract,
            products,
        )
        result = _build_resolved_product_unknown_field_result(
            db,
            product,
            label=requested_field,
            source="resolved_entity_detail_contract",
            resolution_decision=resolution_decision,
            entity_contract=contract,
        )
    else:
        result = _product_field_followup_result(
            db,
            contract.resolved_sku,
            requested_field,
            question,
            identity_source="phase2_resolved_entity",
        )
        if not result:
            return None

    debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
    metadata = result.get("answer_metadata") if isinstance(result.get("answer_metadata"), dict) else {}
    if metadata.get("evidence_status") == "missing" and contract.resolved_sku not in str(result.get("answer") or ""):
        product = next(
            (item for item in products if str(item.sku or "").strip().upper() == contract.resolved_sku),
            None,
        )
        name = str(getattr(product, "product_name_cn", "") or getattr(product, "product_name_en", "") or "").strip()
        prefix = f"{name}（{contract.resolved_sku}）" if name else contract.resolved_sku
        result["answer"] = f"{prefix}：{str(result.get('answer') or '').strip()}"
    preserves_unknown_field_route = not customer_field_contract.is_supported_detail_field(field.field_type) and not shipping_qa_evidence_available
    route_source = (
        "resolved_entity_unknown_field_fallback"
        if preserves_unknown_field_route
        else "resolved_entity_detail_contract"
    )
    debug["agent_mode"] = route_source
    debug["binding_provenance"] = "resolved_entity_contract"
    debug["search_top1_promotion_blocked"] = False
    debug["entity_resolution_contract"] = contract.to_dict()
    metadata["source"] = route_source
    metadata["contract_field_type"] = field.field_type
    result["debug"] = debug
    result["answer_metadata"] = metadata
    return result


def _phase2_entity_state_arbitration_result(
    db: Session,
    question: str,
    phase1_plan: dict | None = None,
    *,
    conversation_id: str | None = None,
    signals: dict[str, bool] | None = None,
    entity_resolution_context: dict[str, Any] | None = None,
) -> dict | None:
    """Arbitrate one-field entity states before legacy product-field routing."""
    plan = phase1_plan if isinstance(phase1_plan, dict) else {}
    if (
        str(plan.get("primary_intent") or "") == "category_compatibility"
        and bool(plan.get("must_stay_within_category"))
        and str(plan.get("category_ref") or "").strip()
    ):
        return None
    # Every recognised formal field, including safely unsupported and
    # realtime-bound fields, must first seal identity here.  The formatter
    # below selects same-SKU evidence or the field-specific safe-missing
    # response; returning early here previously leaked such requests to
    # generic recommendation/tool routes without an entity contract.
    context = entity_resolution_context
    if context is None:
        predecision = _classify_phase2_entity_state_action(
            question,
            phase1_plan,
            conversation_id=conversation_id,
            signals=signals,
            entity_resolution_context={},
        )
        if predecision.get("reason") != "entity_contract_unavailable":
            predecision_result = _build_phase2_entity_state_response(db, question, predecision)
            if predecision_result:
                return predecision_result
        context = _build_phase2_entity_resolution_context(
            db,
            question,
            resolve_requested_field_contract(question, phase1_plan),
            phase1_plan,
        )
    # The semantic first-turn executor can arrive here before the larger ask
    # pipeline has built its compound-field branch. Once identity and the
    # complete FieldContract are sealed, execute all requested fields together;
    # do not let the single-field eligibility check turn a valid SKU question
    # into a generic QA clarification.
    effective_field_request = context.get("field_request") if isinstance(context, dict) else None
    compound_fields = [
        str(field or "").strip()
        for field in (effective_field_request or {}).get("canonical_fields") or []
        if str(field or "").strip() in customer_field_contract.FORMAL_DETAIL_FIELDS
    ] if isinstance(effective_field_request, dict) else []
    compound_fields = list(dict.fromkeys(compound_fields))
    if len(compound_fields) > 1:
        compound_result = _build_resolved_compound_evidence_result(
            db,
            question=question,
            entity_contract=(context or {}).get("contract"),
            field_request=effective_field_request,
            phase1_plan=plan,
        )
        if compound_result:
            return compound_result
    decision = _classify_phase2_entity_state_action(
        question,
        phase1_plan,
        conversation_id=conversation_id,
        signals=signals,
        entity_resolution_context=context,
    )
    result = _build_phase2_entity_state_response(db, question, decision)
    effective_field_request = context.get("field_request") if isinstance(context, dict) else None
    if isinstance(result, dict) and isinstance(effective_field_request, dict):
        debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
        debug["field_contract"] = dict(effective_field_request)
        debug_plan = debug.get("plan") if isinstance(debug.get("plan"), dict) else {}
        debug_plan["field_contract"] = dict(effective_field_request)
        debug["plan"] = debug_plan
        result["debug"] = debug
    return result




def _phase1_row_has_explicit_alcohol_stove_support(db: Session, row: dict[str, Any]) -> bool:
    if not isinstance(row, dict):
        return False
    heat_source = str(row.get("heat_source") or "").strip()
    if customer_agent_intent_service._alcohol_stove_support_verdict(heat_source) is True:
        return True
    field_values = row.get("field_values")
    if isinstance(field_values, dict):
        field_heat_source = str(field_values.get("热源") or field_values.get("适用热源") or "").strip()
        if customer_agent_intent_service._alcohol_stove_support_verdict(field_heat_source) is True:
            return True
    return False








def list_conversations(db: Session, user_id: str, skip: int = 0, limit: int = 30) -> dict:
    user_id = str(user_id)
    query = db.query(CustomerServiceConversation).filter(
        CustomerServiceConversation.user_id == user_id
    ).order_by(CustomerServiceConversation.updated_at.desc())
    total = query.count()
    items = query.offset(skip).limit(limit).all()
    previews = _conversation_previews(db, [item.id for item in items])
    return {
        "items": [_conversation_list_item(item, previews.get(item.id, {})) for item in items],
        "total": total,
    }


def _conversation_previews(db: Session, conversation_ids: list[str]) -> dict[str, dict]:
    if not conversation_ids:
        return {}
    previews: dict[str, dict] = {conversation_id: {} for conversation_id in conversation_ids}
    rows = (
        db.query(CustomerServiceMessage)
        .filter(CustomerServiceMessage.conversation_id.in_(conversation_ids))
        .order_by(CustomerServiceMessage.conversation_id.asc(), CustomerServiceMessage.created_at.desc())
        .all()
    )
    for message in rows:
        preview = previews.setdefault(message.conversation_id, {})
        preview.setdefault("last_any", message)
        if message.role == "assistant":
            preview.setdefault("last_assistant", message)
    return previews


def _conversation_list_item(item: CustomerServiceConversation, preview: dict) -> dict:
    preview_message = preview.get("last_assistant") or preview.get("last_any")
    preview = str(preview_message.content or "") if preview_message else ""
    return {
        "id": item.id,
        "title": item.title,
        "sku": item.sku,
        "last_message": preview[:120],
        "last_message_role": preview_message.role if preview_message else None,
        "last_message_at": str(preview_message.created_at) if preview_message and preview_message.created_at else None,
        "created_at": str(item.created_at),
        "updated_at": str(item.updated_at),
    }


def get_conversation(db: Session, conversation_id: str, user_id: str) -> dict:
    user_id = str(user_id)
    conversation = db.query(CustomerServiceConversation).filter(
        CustomerServiceConversation.id == conversation_id,
        CustomerServiceConversation.user_id == user_id,
    ).first()
    if not conversation:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="客服会话不存在")

    messages = db.query(CustomerServiceMessage).filter(
        CustomerServiceMessage.conversation_id == conversation_id
    ).order_by(CustomerServiceMessage.created_at.asc()).all()
    payload = []
    for item in messages:
        meta = _message_meta(item.sources_json)
        payload.append(
            {
                "id": item.id,
                "role": item.role,
                "content": item.content,
                "sku": item.sku,
                "sources": _safe_json(item.sources_json, []),
                "steps": _steps_from_sources(item.sources_json),
                "intent": meta.get("intent"),
                "answer_type": meta.get("answer_type"),
                "confidence": meta.get("confidence"),
                "uncertainty": meta.get("uncertainty"),
                "needs_clarification": meta.get("needs_clarification", False),
                "anomalies": meta.get("anomalies", []),
                "suggested_followups": meta.get("suggested_followups", meta.get("followups", [])),
                "followups": meta.get("followups", meta.get("suggested_followups", [])),
                "warnings": meta.get("warnings", []),
                "evidence": meta.get("evidence", []),
                "agent_quality": meta.get("agent_quality", {}),
                "debug": meta.get("debug", {}),
                "feedback": meta.get("feedback"),
                "created_at": str(item.created_at),
            }
        )
    return {
        "id": conversation.id,
        "title": conversation.title,
        "sku": conversation.sku,
        "created_at": str(conversation.created_at),
        "updated_at": str(conversation.updated_at),
        "messages": payload,
    }


def delete_conversation(db: Session, conversation_id: str, user_id: str) -> dict:
    user_id = str(user_id)
    conversation = db.query(CustomerServiceConversation).filter(
        CustomerServiceConversation.id == conversation_id,
        CustomerServiceConversation.user_id == user_id,
    ).first()
    if not conversation:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="客服会话不存在")

    # Do not rely solely on the database FK's ON DELETE CASCADE here.  Some
    # development/test SQLite connections do not enforce foreign keys, which
    # leaves orphaned turns behind and can make a deleted chat appear again in
    # later previews.  The ownership check above scopes both deletes to this
    # exact conversation.
    db.query(CustomerServiceMessage).filter(
        CustomerServiceMessage.conversation_id == conversation_id
    ).delete(synchronize_session=False)
    db.delete(conversation)
    db.commit()
    return {"deleted": True, "id": conversation_id}


def save_message_feedback(
    db: Session,
    *,
    user_id: str,
    message_id: str,
    rating: str,
    reason: str | None = None,
    comment: str | None = None,
) -> dict:
    allowed = {"helpful", "incorrect", "missing_data"}
    if rating not in allowed:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="反馈类型不支持")
    message = (
        db.query(CustomerServiceMessage)
        .join(CustomerServiceConversation, CustomerServiceConversation.id == CustomerServiceMessage.conversation_id)
        .filter(
            CustomerServiceMessage.id == message_id,
            CustomerServiceMessage.role == "assistant",
            CustomerServiceConversation.user_id == str(user_id),
        )
        .first()
    )
    if not message:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="客服消息不存在")

    sources = _safe_json(message.sources_json, [])
    meta = None
    for source in sources:
        if isinstance(source, dict) and source.get("type") == "agent_meta":
            meta = source
            break
    if meta is None:
        meta = {"type": "agent_meta", "label": "客服回复元数据"}
        sources.append(meta)
    feedback = {
        "rating": rating,
        "reason": reason or "",
        "comment": comment or "",
    }
    meta["feedback"] = feedback
    message.sources_json = json.dumps(sources, ensure_ascii=False, default=str)
    db.commit()
    return {"message_id": message.id, "feedback": feedback}


async def _try_explicit_customer_mutation_result(
    db: Session,
    *,
    user_id: str,
    question: str,
    sku: str | None,
    conversation_id: str | None,
) -> dict | None:
    """Create pending actions for a parseable write request before read-only guards.

    The normal agent/runtime path intentionally refuses catalogue mutations.
    Customer-service actions are a separate, confirmation-gated capability, so
    only the deterministic proposal intents may cross this boundary.
    """
    previous_result_skus = _previous_result_skus_for_pre_runtime(
        db,
        user_id=user_id,
        conversation_id=conversation_id,
        question=question,
    )
    intent = customer_agent_intent_service.parse_intent(
        question,
        sku=sku,
        previous_result_skus=previous_result_skus,
    )
    if not intent or intent.intent not in {"propose_update", "propose_delete"}:
        return None
    result = await customer_agent_intent_service.process_intent_request(
        db,
        user_id=user_id,
        question=question,
        sku=sku,
        previous_result_skus=previous_result_skus,
        allow_llm_fallback=False,
    )
    if not isinstance(result, dict) or result.get("intent") not in {"propose_update", "propose_delete"}:
        return None
    return result


def _customer_mutation_boundary_result(question: str) -> dict | None:
    """Keep customer support read-only when a turn explicitly asks to alter catalogue data."""
    text = str(question or "").strip()
    normalized = customer_agent_service.normalize_search_text(text)
    if not normalized:
        return None
    update_requested = bool(re.search(
        r"(?:把|将).{1,100}?(?:修改为|更改为|更新为|改成|改为|设为|设置为)"
        r"|(?:修改|更改|更新).{0,60}?(?:为|成|改成|改为|设为|设置为)",
        text,
    ))
    delete_requested = bool(re.search(r"(?:删除|清空).{0,80}(?:产品|商品|资料|字段|SKU|CW[-\s]?[A-Z0-9])", text, re.IGNORECASE))
    if not (update_requested or delete_requested):
        # Read-only questions about internal business fields still belong to
        # the enterprise guardrail; only an explicit write/delete request is
        # handled by the customer-service mutation boundary below.
        if (
            any(term in text for term in customer_enterprise_guardrail_service.INTERNAL_BUSINESS_TERMS)
            and not _is_internal_catalogue_filter_query(text)
        ):
            guarded = customer_enterprise_guardrail_service.evaluate_question(text)
            if guarded and guarded.get("intent") == "safety_refusal":
                return guarded
        return None
    # A pronoun-based write into an internal business field must retain the
    # enterprise safety refusal.  The customer-facing mutation boundary may
    # explain a direct, explicit catalogue edit, but it must not resolve “他 /
    # 前面那款” into an internal record or allow the runtime tool path to see
    # the request.
    if (
        any(term in text for term in customer_enterprise_guardrail_service.INTERNAL_BUSINESS_TERMS)
        and re.search(r"(?:他|她|它|这个|这款|前面|刚才|上一个|该商品|该产品)", text)
    ):
        guarded = customer_enterprise_guardrail_service.evaluate_question(text)
        if guarded and guarded.get("intent") == "safety_refusal":
            return guarded
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": "当前客服只提供商品查询、比较和推荐，不会代为修改或删除商品资料；本次请求没有写入任何数据。请通过商品管理功能由有权限的人员处理。",
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "sources": [],
        "answer_metadata": {"source": "customer_mutation_boundary", "evidence_status": "not_applicable"},
        "debug": {"agent_mode": "customer_mutation_boundary"},
        "skip_polish": True,
    }


def _is_internal_catalogue_filter_query(question: str) -> bool:
    """Allow allowlisted operational filters to resolve product context.

    Owner and lifecycle are searchable product metadata here.  They must not
    be exposed as general business advice, but an explicit catalogue filter is
    needed to identify products before a confirmation-gated update.
    """
    text = str(question or "").strip()
    if not text or any(term in text for term in ("修改", "更改", "更新", "改成", "改为", "删除", "清空")):
        return False
    intent = customer_agent_intent_service.parse_intent(text, previous_result_skus=[])
    if not intent or intent.intent != "query_products":
        return False
    if not any(
        intent.filters.get(field)
        for field in ("product.person_in_charge", "product.lifecycle_status")
    ):
        return False
    return any(term in text for term in ("哪些", "有哪些", "产品", "商品", "查询", "查一下", "列出"))


def _looks_like_portability_detail_question(question: str) -> bool:
    """Recognize an explicit portability/carrying-field supplement."""
    text = str(question or "").strip()
    if not text:
        return False
    if any(term in text for term in ("能装", "装在", "装进", "放进", "嵌套收纳")):
        return False
    return any(term in text for term in ("便携", "便携带", "轻便", "好带", "方便携带", "随身携带"))


def _same_sku_portability_detail_answer(db: Session, sku: str) -> str:
    """Compose a bounded portability line from same-SKU structured text."""
    product, specs, business, content = _phase1_product_bundle_by_ref(db, sku)
    if not product:
        return "便携/携带：当前资料未单独标注，无法确认。"
    row = _product_row_from_model(product, specs, business, content)
    evidence_text = " ".join(
        str(row.get(key) or "")
        for key in (
            "product_name_cn", "features", "usage_scenarios", "target_audience",
            "positioning", "long_description_cn", "bullet_points",
        )
    )
    if any(term in evidence_text for term in ("便携", "轻便", "轻量")):
        return "便携/携带：同 SKU 资料标注为便携或轻量使用。"
    if any(term in evidence_text for term in ("提手", "把手", "手柄")):
        return "便携/携带：同 SKU 资料标注有提手/把手设计；具体携带便利性仍需结合实际重量。"
    if "收纳" in evidence_text:
        return "便携/携带：同 SKU 资料提到收纳方式，但未单独量化携带便利性。"
    return "便携/携带：当前资料未单独标注，无法确认。"


def _build_bounded_clarification_result(*, answer: str, source: str) -> dict:
    """Build a no-catalogue clarification for an unbound product question."""
    return {
        "intent": "clarify",
        "answer_type": "clarification",
        "answer": answer,
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "sources": [],
        "evidence": [],
        "needs_clarification": True,
        "answer_metadata": {"source": source, "evidence_status": "missing"},
        "debug": {"agent_mode": source},
        "skip_polish": True,
    }




























def _looks_like_page_cookware_fit_question(question: str, request_sku_anchor: str | None) -> bool:
    """Recognize a page-bound vessel-fit question without inferring a SKU.

    A page SKU already seals the product identity.  Phrases about the largest
    vessel that can be placed on it are a fit/capability question, not a
    request to resolve the noun phrase before ``能放`` as a product name.
    The helper only describes the language contract; the caller still reads
    same-SKU evidence and falls back conservatively when the limit is absent.
    """
    text = str(question or "").strip()
    if not request_sku_anchor or not text:
        return False
    if _is_explicit_broad_catalogue_request(text) or _looks_like_recommendation_request(text):
        return False
    vessel_terms = ("锅", "锅具", "水壶", "烧水壶", "烤盘", "煎盘")
    fit_terms = (
        "能放", "放多大", "最大", "最小", "承载", "承重", "锅底", "底径", "口径",
        "直径", "适配", "匹配", "兼容",
    )
    return any(term in text for term in vessel_terms) and any(term in text for term in fit_terms)








def _is_explicit_broad_catalogue_request(question: str) -> bool:
    text = str(question or "").strip()
    if not text:
        return False
    if _looks_like_bundle_catalogue_request(text):
        return True
    if _looks_like_semantic_catalog_query(text):
        return True
    # Availability/listing wording with an explicit category is a catalogue
    # request, not a product-page identity question.  A named-but-unresolved
    # subject such as “激川锅” has no canonical category and therefore does
    # not enter this allowlist.
    target_category = _structured_target_category_from_question(text)
    if target_category and any(term in text for term in ("有没有", "有卖", "卖吗", "有哪些", "哪些", "多少款", "几款", "推荐", "帮我选", "帮我挑")):
        return True
    # Some category-selection wording puts the selection criterion between
    # the category noun and the recommendation predicate, e.g. “气罐品牌有
    # 推荐吗”.  Let the generic category recognizer establish scope instead
    # of treating the page product's formal field as the subject.
    if _looks_like_unconstrained_category_recommendation_question(text):
        return True
    if customer_agent_service.normalize_search_text(text).strip("？?!！。 ") in {
        "炉子", "炉具", "水壶", "水具", "锅", "锅具", "烤盘", "煎盘", "配件", "餐具"
    }:
        return True
    return any(term in text for term in ("看炉具", "看一下炉具", "单独卖炉具", "有哪些炉具", "有什么炉具", "列出炉具"))


def _looks_like_bundle_catalogue_request(question: str) -> bool:
    """Recognize a category-level bundle lookup without selecting a SKU."""
    text = str(question or "").strip()
    if not text or SKU_RE.search(text):
        return False
    if not any(term in text for term in ("套餐", "套装", "组合", "搭配")):
        return False
    if any(term in text for term in ("还有其他", "其他套装", "就这一套", "只有这一套", "哪套")):
        return any(term in text for term in ("推荐", "选择", "款式", "有没有", "有吗", "找"))
    scope_count = sum(
        1
        for term in ("水壶", "水具", "炉具", "炉子", "酒精炉", "锅", "餐具", "杯")
        if term in text
    )
    return scope_count >= 2 and any(term in text for term in ("有没有", "有哪些", "有吗", "推荐", "找", "想买"))


def _looks_like_material_catalogue_request(question: str) -> bool:
    """Recognize a material-filtered catalogue ask even with page context."""
    text = str(question or "").strip()
    if not text or not any(term in text for term in ("锅", "锅具", "套锅", "炊具")):
        return False
    if not any(term in text for term in ("304", "316", "不锈钢")):
        return False
    if not any(term in text for term in ("有没有", "有哪些", "有卖", "卖吗", "推荐", "找")):
        return False
    return not bool(customer_agent_service._extract_skus(text))




def _looks_like_material_or_surface_detail_question(question: str) -> bool:
    """Keep factual material/coating predicates out of the care shortcut.

    ``涂层`` is also a usage-care keyword (for example, how to protect a
    coating), but questions asking what the material/coating is are formal
    product-detail requests.  The distinction is semantic and deliberately
    independent of any SKU.
    """
    text = str(question or "").strip()
    if not text:
        return False
    field = customer_field_contract.detect_field_contract(text)
    if not field or field.field_type not in {"material", "surface_finish"}:
        return False
    if customer_agent_intent_service._looks_like_utensil_material_safety_question(text):
        return False
    operational_terms = (
        "怎么", "如何", "处理", "清洗", "清洁", "保养", "护理", "掉", "脱落",
        "剥落", "粘锅", "刮擦", "钢丝球", "泡水", "浸泡",
    )
    factual_predicate_terms = (
        "是什么", "哪种", "什么材质", "什么材料", "有没有", "有吗", "是否",
        "是不是", "采用", "用的", "吗", "吧",
    )
    operational_hit = any(term in text for term in operational_terms if term != "粘锅")
    # ``不粘锅/不沾锅`` is a surface-finish fact; the substring ``粘锅``
    # inside it must not turn a yes/no coating question into a cleaning ask.
    if "粘锅" in text and "不粘锅" not in text and "不沾锅" not in text:
        operational_hit = True
    return any(term in text for term in factual_predicate_terms) and not operational_hit










def _looks_like_missing_component_question(question: str) -> bool:
    """Recognize a missing-in-box complaint without choosing a product."""
    text = str(question or "").strip()
    if not text:
        return False
    has_missing = any(term in text for term in (
        "没收到", "没发", "没给", "怎么没", "少了", "缺少", "漏发", "没配",
        "不是一起到", "没有一起到", "没一起到", "未一起到", "未随货", "没随货",
    ))
    has_component = any(term in text for term in (
        "杯子", "水壶", "配件", "赠品", "套装", "炉具", "转接头", "转换头", "转向头", "转头",
        "连接管", "管线", "气管", "软管",
    ))
    return has_missing and has_component
















def _looks_like_page_bundle_inclusion_question(question: str) -> bool:
    text = str(question or "").strip()
    return bool(
        "带锅" in text
        and any(term in text for term in ("有没有", "有吗", "带锅的", "不带锅"))
    )


def _looks_like_bundle_heat_source_question(question: str) -> bool:
    """Recognize a bundle ask about whether a stove is included.

    A phrase such as “有没有带炉的套装” is neither a generic cookware
    browse nor a page-field question.  Treating it as an unconstrained search
    lets the catalogue formatter dump ordinary cookware sets that never claim
    to include a stove.  This semantic scope check deliberately uses bundle
    and inclusion language, not any SKU or product-name whitelist.
    """
    text = str(question or "").strip()
    if not text or SKU_RE.search(text):
        return False
    has_bundle = any(term in text for term in ("套装", "套锅", "套餐", "组合"))
    has_inclusion = any(term in text for term in ("带炉", "含炉", "有炉", "配炉", "炉具在里面"))
    return has_bundle and has_inclusion and any(term in text for term in ("有没有", "有吗", "哪些", "哪款", "推荐", "卖"))




def _looks_like_unconstrained_category_recommendation_question(question: str) -> bool:
    """Recognize a plain category recommendation with no personal criteria."""
    text = str(question or "").strip()
    if not text or SKU_RE.search(text):
        return False
    # Include natural category-selection wording such as “用什么样的炉头”
    # and “用哪种炉具”.  This is a language-level intent boundary; it does
    # not identify a particular SKU or promote a fixed product.
    if not any(term in text for term in (
        "推荐", "哪款", "哪个好", "哪个", "买哪个", "选哪个", "用什么样", "用哪种", "哪种",
    )):
        return False
    if any(term in text for term in (
        "适合", "徒步", "露营", "野餐", "自驾", "一个人", "一人", "两个人", "双人", "多人",
        "新手", "预算", "轻量", "便携", "容量", "重量", "收纳", "材质", "火力", "烧水", "煮饭",
        "能不能", "能否", "能用", "能配", "搭配", "配合", "适配", "兼容", "接口", "用什么燃料",
    )):
        return False
    return _semantic_catalog_product_ref(text) != "产品"
















def _answer_negates_requested_noun(question: str, answer: str) -> bool:
    """Detect an exact availability no-match before showing alternatives.

    A response may mention nearby products as explanatory examples while
    explicitly saying the requested item was not found.  Those examples are
    not customer-facing result cards for the requested item.  This helper
    extracts the noun after a generic availability prefix and checks that the
    same noun occurs near a negation in the answer; it never selects a SKU.
    """
    text = str(question or "").strip()
    response = str(answer or "").strip()
    if not text or not response:
        return False
    if not any(marker in response for marker in ("暂未查到", "未找到", "没有找到", "没有出现", "未出现", "暂无", "暂未")):
        return False
    noun = re.sub(r"^[\s，,：:、]*(?:有没有|有无|是否有|有吗|能否有|有卖)", "", text)
    noun = re.split(r"(?:推荐|能买吗|卖吗|有吗|吗|呢|吧|呀|啊|\?|？)", noun, maxsplit=1)[0]
    noun = noun.strip(" ，,。！？；;：:")
    if len(noun) < 2:
        return False
    for match in re.finditer(re.escape(noun), response):
        window = response[max(0, match.start() - 28): match.end() + 28]
        if any(marker in window for marker in ("暂未查到", "未找到", "没有找到", "没有出现", "未出现", "暂无", "暂未", "没有")):
            return True
    return False




def _clear_unrelated_catalogue_cards(question: str, agent_result: dict) -> dict:
    """Remove broad retrieval cards from a non-browse, uncertain answer.

    Retrieval may still be useful internally, but a customer-facing detail or
    safety answer must not display dozens of unrelated products.  Explicit
    browse/recommend/compare turns keep their candidate set.
    """
    if not isinstance(agent_result, dict):
        return agent_result
    def _filter_cards_to_answer_skus(answer_skus: list[str]) -> None:
        """Align visible cards with the SKU identities actually named in text."""
        allowed = {str(item or "").strip().upper() for item in answer_skus if str(item or "").strip()}
        if not allowed:
            return
        allowed_identity = {_sku_identity_key(item) for item in allowed if _sku_identity_key(item)}
        existing = {
            str(item or "").strip().upper()
            for item in (agent_result.get("result_skus") or [])
            if str(item or "").strip()
        }
        if not any(_sku_identity_key(item) in allowed_identity for item in existing):
            return
        for key in ("result_skus", "candidate_skus"):
            values = [
                str(item or "").strip().upper()
                for item in (agent_result.get(key) or [])
                if str(item or "").strip()
            ]
            agent_result[key] = [item for item in values if _sku_identity_key(item) in allowed_identity]
        rows = [row for row in (agent_result.get("results") or []) if isinstance(row, dict)]
        agent_result["results"] = [
            row
            for row in rows
            if _sku_identity_key(str(row.get("sku") or "").strip().upper()) in allowed_identity
        ]
        sources = agent_result.get("sources")
        if isinstance(sources, list):
            agent_result["sources"] = [
                source
                for source in sources
                if not isinstance(source, dict)
                or not str(source.get("sku") or "").strip()
                or _sku_identity_key(str(source.get("sku") or "").strip().upper()) in allowed_identity
            ]

    answer = str(agent_result.get("answer") or "")
    answer_skus = [
        str(item or "").strip().upper()
        for item in customer_agent_service._extract_skus(answer)
        if str(item or "").strip()
    ]
    result_skus = [
        str(item or "").strip().upper()
        for item in (agent_result.get("result_skus") or [])
        if str(item or "").strip()
    ]
    answer_metadata = agent_result.get("answer_metadata")
    metadata_source = str(
        answer_metadata.get("source") if isinstance(answer_metadata, dict) else ""
    ).strip()
    # A sealed semantic comparison may legitimately say that a criterion or
    # same-SKU evidence is missing.  Its participant rows are still the
    # conversation ledger for the next turn; the generic noun-negation cleaner
    # must not erase them just because the answer contains a boundary
    # disclosure.
    sealed_semantic_comparison = bool(
        str(agent_result.get("answer_type") or "").strip() == "comparison"
        and metadata_source.startswith("semantic_pairwise")
    )
    if _is_semantic_owned_result(agent_result):
        # The semantic executor has already sealed identity, evidence scope,
        # and customer prose. Legacy card cleanup is allowed to remove or
        # reinterpret results only for legacy-owned objects; it must not turn
        # a semantic answer into a category/no-match response after the fact.
        debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
        debug["catalogue_card_cleanup_skipped"] = "semantic_executor_provenance"
        agent_result["debug"] = debug
        return agent_result
    # The semantic recommendation executor has already sealed the selected
    # rows and rendered the customer prose from the same-SKU evidence packet.
    # Do not let this legacy catalogue-card cleaner reinterpret the request
    # by category or rebuild the answer from the first matching row.  That old
    # pass is precisely what turned a multi-candidate semantic answer into a
    # fixed "优先推荐 ..." fragment for griddle questions.
    if (
        metadata_source.startswith("validated_semantic_preplan")
        and isinstance(answer_metadata, dict)
        and isinstance(answer_metadata.get("recommendation_contract"), dict)
    ):
        debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
        debug["catalogue_card_cleanup_skipped"] = "sealed_semantic_recommendation"
        agent_result["debug"] = debug
        return agent_result
    # A structured recommendation may be useful even when no candidate proves
    # every requested dimension.  Its answer explicitly labels the rows as
    # reference-only; keep those evidence-bounded cards aligned with the text
    # instead of treating the uncertainty notice as a non-catalogue answer.
    if (
        metadata_source == "product_catalog_structured_recommendation"
        and str(answer_metadata.get("verification_level") or "").strip() == "partially_verified"
        and any(
            marker in answer
            for marker in ("仅供参考", "部分条件缺少资料", "未发现明确冲突")
        )
    ):
        debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
        debug["catalogue_cards_preserved"] = True
        debug["catalogue_cards_preserve_reason"] = "structured_partial_recommendation_reference_only"
        agent_result["debug"] = debug
        return agent_result
    if metadata_source == "mixed_stove_fuel_catalogue":
        if answer_skus:
            _filter_cards_to_answer_skus(answer_skus)
        return agent_result
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    sealed_single_product_safe_missing = bool(
        str(debug.get("agent_mode") or "") == "sealed_product_qa_safe_missing"
        and len(result_skus) == 1
        and any(
            _sku_identity_key(answer_sku) == _sku_identity_key(result_skus[0])
            for answer_sku in answer_skus
        )
    )
    if (
        not sealed_single_product_safe_missing
        and not sealed_semantic_comparison
        and _answer_negates_requested_noun(question, answer)
        and result_skus
    ):
        agent_result["results"] = []
        agent_result["result_skus"] = []
        agent_result["candidate_skus"] = []
        agent_result["sources"] = []
        debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
        debug["catalogue_cards_cleared"] = True
        debug["catalogue_cards_clear_reason"] = "exact_requested_noun_not_found"
        debug["catalogue_cards_cleared_count"] = len(result_skus)
        if isinstance(debug.get("raw_results"), list):
            debug["raw_results"] = []
        agent_result["debug"] = debug
        return agent_result
    if _looks_like_page_current_item_availability_question(question):
        page_match = re.search(r"当前商品\s*[：:]\s*(.+?)(?:）|\))\s*$", str(question or "").strip())
        page_subject = str(page_match.group(1) if page_match else "当前页面商品").strip()
        component = next(
            (
                term
                for term in ("炉头", "炉芯", "配件", "水壶", "锅", "炉具")
                if term in str(question or "")
            ),
            "该配件",
        )
        agent_result["intent"] = "clarify"
        agent_result["answer_type"] = "clarification"
        agent_result["answer"] = (
            f"{page_subject}：当前页面资料未标注是否包含或单独提供“{component}”，"
            "不能把其他炉具或目录中的配件当作这款商品的随附部件。请按该商品包装清单或配件说明核对。"
        )
        agent_result["needs_clarification"] = True
        agent_result["result_skus"] = []
        agent_result["candidate_skus"] = []
        agent_result["results"] = []
        agent_result["sources"] = []
        debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
        debug["agent_mode"] = "natural_page_current_item_availability_scope_guard"
        debug["catalogue_cards_cleared"] = True
        debug["catalogue_cards_clear_reason"] = "page_current_item_availability"
        agent_result["debug"] = debug
        return agent_result
    # Keep an explicit fuel subtype from degrading into the generic gas-stove
    # safety paragraph.  If one verified row is present, answer from that
    # row's heat-source evidence; otherwise state that the subtype is
    # unverified.  Recommendation turns are left to the recommendation
    # contract, which may return a verified no-match result.
    explicit_fuel_terms = ("固体酒精", "固态酒精", "酒精块", "固体燃料", "液体酒精", "木炭", "炭火", "柴火", "煤炭")
    requested_fuels = _requested_fuel_capabilities(question)
    answer_metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    same_sku_product_qa = bool(
        str(answer_metadata.get("evidence_field") or "").strip() == "product_qa"
        and str(answer_metadata.get("evidence_source") or "").strip().startswith("product_qa:")
        and len(result_skus) == 1
    )
    if (
        requested_fuels
        and not _is_unbound_environmental_fuel_safety_question(question)
        and not same_sku_product_qa
        and (
            not _looks_like_recommendation_request(question)
            or (_looks_like_fuel_choice_question(question) and ("当前商品：" in question or result_skus))
        )
        and not any(term in str(agent_result.get("answer") or "") for term in explicit_fuel_terms)
    ):
        rows = [row for row in (agent_result.get("results") or []) if isinstance(row, dict)]
        if len(rows) == 1:
            if len(requested_fuels) >= 2:
                fuel_answer, _fuel_status = _phase1_multi_fuel_capability_answer(
                    rows[0],
                    question,
                    asked_fuels=requested_fuels,
                )
            else:
                fuel_answer, _fuel_status = _phase1_fuel_capability_answer(
                    rows[0],
                    question,
                    asked_fuel=requested_fuels[0],
                )
        else:
            fuel_label = "、".join(requested_fuels)
            conclusion_label = "热源结论" if any(
                fuel in {"电磁炉", "电陶炉", "电热炉", "电炉"} for fuel in requested_fuels
            ) else "燃料结论"
            fuel_answer = (
                f"{conclusion_label}：当前资料未标注具体商品是否支持{fuel_label}，不能把明火、气罐或其他酒精标注直接当作适配依据。"
                "请提供具体商品名或 SKU，我再按同款热源和说明书核对。"
            )
        agent_result["answer"] = fuel_answer
        if len(rows) != 1:
            agent_result["results"] = []
            agent_result["result_skus"] = []
            agent_result["candidate_skus"] = []
            agent_result["sources"] = []
        debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
        debug["agent_mode"] = "explicit_fuel_subtype_evidence_scope_guard"
        agent_result["debug"] = debug
        return agent_result

    # An accessory-combination ask must be grounded in an accessory row that
    # actually mentions the requested capability.  A broad “配件” retrieval
    # can otherwise turn a missing ignition/regulator match into an unrelated
    # water bag or bowl recommendation.  This is a semantic evidence-scope
    # check and intentionally does not name or allowlist any SKU.
    if (
        _is_unbound_accessory_availability_question(question)
        and not SKU_RE.search(question)
        and "当前商品：" not in question
        and (
            result_skus
            or str(agent_result.get("answer_type") or "").strip() == "recommendation"
        )
    ):
        requested_groups: list[tuple[str, ...]] = []
        if any(term in question for term in ("点火器", "点火装置", "点火")):
            requested_groups.append(("点火器", "点火装置", "点火", "电子点火"))
        if any(term in question for term in ("调节开关", "火力调节", "调节旋钮")):
            requested_groups.append(("调节开关", "火力调节", "调节旋钮", "火力阀"))
        if any(term in question for term in ("转接头", "转换头", "适配头")):
            requested_groups.append(("转接头", "转换头", "适配头", "转接器"))
        if any(term in question for term in ("管线", "连接管", "连接软管", "气管", "软管")):
            requested_groups.append(("管线", "连接管", "连接软管", "气管", "软管"))
        rows = [row for row in (agent_result.get("results") or []) if isinstance(row, dict)]
        row_texts = [
            " ".join(
                str(row.get(key) or "").strip()
                for key in (
                    "product_name_cn", "product_name_en", "category", "sub_category",
                    "features", "long_description_cn", "usage_instruction",
                )
            )
            for row in rows
        ]
        if requested_groups:
            has_single_row_combo = any(
                all(any(term in text for term in group) for group in requested_groups)
                for text in row_texts
            )
            has_verified_requested_scope = has_single_row_combo
        else:
            has_verified_requested_scope = bool(row_texts)
        if not has_verified_requested_scope:
            agent_result["answer"] = (
                "当前资料未找到同时明确标注你所说配件组合的商品，不能把其他配件当作替代推荐。"
                "请提供具体商品名或 SKU，并说明炉头/接口型号，我再按包装清单和同款配件资料核对。"
            )
            agent_result["results"] = []
            agent_result["result_skus"] = []
            agent_result["candidate_skus"] = []
            agent_result["sources"] = []
            debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
            debug["agent_mode"] = "accessory_combination_evidence_scope_guard"
            debug["catalogue_cards_cleared"] = True
            debug["catalogue_cards_clear_reason"] = "requested_accessory_capability_not_verified"
            agent_result["debug"] = debug
            return agent_result

    if (
        _looks_like_unbound_canister_compatibility_question(question)
        and not SKU_RE.search(question)
        and "当前商品：" not in question
        and (
            result_skus
            or str(agent_result.get("answer_type") or "").strip() == "recommendation"
        )
    ):
        answer_text = str(agent_result.get("answer") or "")
        direct_terms = (
            "兼容性", "接口", "转接头", "转换头", "适配", "兼容", "连接",
            "无法确认", "未标注", "请提供",
        )
        if not any(term in answer_text for term in direct_terms):
            agent_result["answer"] = (
                "兼容性结论：当前没有锁定具体炉具型号，无法确认你提到的气罐是否能直接连接。"
                "如果涉及转接头或转换头，也不能仅凭接口外观判断适配；请提供炉具商品名或 SKU，"
                "以及气罐型号，我再按同款接口和说明书核对。"
            )
            agent_result["results"] = []
            agent_result["result_skus"] = []
            agent_result["candidate_skus"] = []
            agent_result["sources"] = []
            debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
            debug["agent_mode"] = "canister_compatibility_answer_scope_guard"
            debug["catalogue_cards_cleared"] = True
            debug["catalogue_cards_clear_reason"] = "compatibility_conclusion_missing"
            agent_result["debug"] = debug
            return agent_result

    explicit_browse = _is_explicit_broad_catalogue_request(question) or _looks_like_recommendation_request(question)
    if _looks_like_category_availability_question(question) and len(result_skus) >= 5 and not answer_skus:
        # Availability prose often names products but not their SKUs.  Keep
        # only rows whose verified product name is actually present in that
        # prose; otherwise broad retrieval can show unrelated kettles, bags or
        # cookware beside a simple “有没有杯子” answer.
        normalized_answer = customer_agent_service.normalize_search_text(answer)
        rows = [row for row in (agent_result.get("results") or []) if isinstance(row, dict)]
        named_rows = []
        for row in rows:
            names = [
                customer_agent_service.normalize_search_text(str(row.get(key) or "")).strip()
                for key in ("product_name_cn", "product_name_en")
            ]
            if any(name and name in normalized_answer for name in names):
                named_rows.append(row)
        named_skus = [
            str(row.get("sku") or "").strip().upper()
            for row in named_rows
            if str(row.get("sku") or "").strip()
        ]
        allowed = set(named_skus)
        for key in ("result_skus", "candidate_skus"):
            agent_result[key] = [
                str(item or "").strip().upper()
                for item in (agent_result.get(key) or [])
                if str(item or "").strip().upper() in allowed
            ]
        agent_result["results"] = named_rows
        sources = agent_result.get("sources")
        if isinstance(sources, list):
            agent_result["sources"] = [
                source
                for source in sources
                if not isinstance(source, dict)
                or not str(source.get("sku") or "").strip()
                or str(source.get("sku") or "").strip().upper() in allowed
            ]
        debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
        debug["catalogue_cards_scoped_to_answer_names"] = True
        debug["catalogue_cards_scoped_count"] = len(named_rows)
        if isinstance(debug.get("raw_results"), list):
            debug["raw_results"] = named_rows
        agent_result["debug"] = debug
        return agent_result
    answer_is_catalogue_listing = bool(
        len(answer_skus) >= 3
        and any(term in question for term in ("单独一个", "套装", "有哪些", "哪几款", "一共", "几款"))
        and any(term in answer for term in ("SKU", "分别", "单独", "套装", "列表", "包括"))
    )
    # A recommendation may explicitly list a bounded, verified candidate set
    # while also explaining that the available preference fields are
    # incomplete.  Treat those named rows as catalogue output; otherwise the
    # generic uncertainty guard removes the very candidates the answer just
    # presented.  Require multiple answer/result SKU matches and catalogue
    # wording so a speculative single-product mention cannot bypass the guard.
    named_result_sku_count = len({
        _sku_identity_key(sku)
        for sku in answer_skus
        if _sku_identity_key(sku)
        and any(
            _sku_identity_key(result_sku) == _sku_identity_key(sku)
            for result_sku in result_skus
        )
    })
    answer_has_bounded_catalogue_candidates = bool(
        (explicit_browse or answer_is_catalogue_listing)
        and named_result_sku_count >= 2
        and any(
            marker in answer
            for marker in ("候选", "核验通过", "已核验", "共找到", "展示", "列表")
        )
    )
    if (explicit_browse or answer_is_catalogue_listing) and answer_skus:
        # Category/recommendation routes may retrieve a large candidate set,
        # but the customer should only see the products named in the final
        # answer.  This also fixes a partial category listing (for example,
        # “列前 10 款”) without constraining candidate generation itself.
        _filter_cards_to_answer_skus(answer_skus)

    if _looks_like_bundle_catalogue_request(question):
        # A bundle answer may be composed from a broad semantic retrieval set,
        # while the customer-visible text names only the verified bundle(s).
        # Keep result cards aligned with those named SKUs instead of exposing
        # unrelated cookware or kettle rows alongside a single conclusion.
        answer_skus = [
            str(item or "").strip().upper()
            for item in customer_agent_service._extract_skus(str(agent_result.get("answer") or ""))
            if str(item or "").strip()
        ]
        if answer_skus:
            answer_sku_set = set(answer_skus)
            agent_result["result_skus"] = [
                sku for sku in [
                    str(item or "").strip().upper()
                    for item in (agent_result.get("result_skus") or [])
                    if str(item or "").strip()
                ] if sku in answer_sku_set
            ]
            agent_result["candidate_skus"] = [
                sku for sku in [
                    str(item or "").strip().upper()
                    for item in (agent_result.get("candidate_skus") or [])
                    if str(item or "").strip()
                ] if sku in answer_sku_set
            ]
            rows = [row for row in (agent_result.get("results") or []) if isinstance(row, dict)]
            agent_result["results"] = [
                row for row in rows
                if str(row.get("sku") or "").strip().upper() in answer_sku_set
            ]
            sources = agent_result.get("sources")
            if isinstance(sources, list):
                agent_result["sources"] = [
                    source for source in sources
                    if not isinstance(source, dict)
                    or not str(source.get("sku") or "").strip()
                    or str(source.get("sku") or "").strip().upper() in answer_sku_set
                ]
        return agent_result
    result_skus = [
        str(item or "").strip().upper()
        for item in (agent_result.get("result_skus") or [])
        if str(item or "").strip()
    ]
    # Keep a small, explicitly named answer/result set aligned before the
    # broad-card uncertainty cleanup. This is an identity-consistency step,
    # not product selection or a question-specific route.
    if len(result_skus) >= 5 and answer_skus and not explicit_browse:
        _filter_cards_to_answer_skus(answer_skus)
        result_skus = [
            str(item or "").strip().upper()
            for item in (agent_result.get("result_skus") or [])
            if str(item or "").strip()
        ]
        if len(result_skus) < 5:
            return agent_result
    if len(result_skus) < 5:
        return agent_result

    uncertainty_markers_early = (
        "无法确认", "未标注", "暂未找到", "资料不足", "请提供", "不能确认", "不能把",
        "没有提到", "无法判断", "无法直接判断", "未出现", "暂未提供", "不建议尝试", "不能直接判断",
        "并未提供", "未维护", "没有找到", "可能是", "只是推测", "建议核对", "核对具体",
    )
    answer_has_uncertainty_early = any(marker in answer for marker in uncertainty_markers_early)
    answer_has_global_uncertainty = bool(re.search(
        r"(?:当前|目前|现有|产品资料|产品清单|产品库|知识库|文档|资料|检索到的产品资料|检索结果).{0,48}(?:没有找到|暂未找到|暂未提供|未维护|并未提供|无法确认|无法直接判断|不能确认|没有|未标注)",
        answer,
    )) or ("可能是" in answer and "请提供" in answer) or "只是推测" in answer
    # Some catalogue/no-match answers omit the word “找到” and only say
    # “没有‘某类商品’可推荐”.  Treat that as a no-match conclusion so stale
    # retrieval cards cannot remain visible beside it.  The pattern is generic
    # and does not mention any product or SKU.
    answer_indicates_no_match = bool(re.search(
        r"(?:没有|未找到|未检索到|暂无|暂未|无).{0,24}(?:匹配|符合|相关|可推荐|可核验|商品|产品|款式|候选|[“\"].{1,40}[”\"])",
        answer,
    ))
    answer_has_global_uncertainty = answer_has_global_uncertainty or answer_indicates_no_match
    if (
        _is_explicit_broad_catalogue_request(question)
        or _looks_like_recommendation_request(question)
        or answer_is_catalogue_listing
    ) and (
        not answer_has_global_uncertainty
        or answer_is_catalogue_listing
        or answer_has_bounded_catalogue_candidates
    ):
        return agent_result
    if _is_contextual_candidate_comparison_question(question) or _is_contextual_power_followup_question(question):
        return agent_result
    answer_type = str(agent_result.get("answer_type") or "").strip()
    uncertainty_markers = (
        "无法确认", "未标注", "暂未找到", "资料不足", "请提供", "不能确认", "不能把",
        "没有提到", "无法判断", "无法直接判断", "未出现", "暂未提供", "不建议尝试", "不能直接判断",
        "并未提供", "未维护", "没有找到", "可能是", "只是推测", "建议核对", "核对具体",
    )
    answer = str(agent_result.get("answer") or "")
    direct_non_catalogue_terms = (
        "单拍", "是否包含", "是否配", "随附", "替代", "代替", "换一个", "能不能放", "能否放",
        "不规则", "放在炉子", "放到", "兼容", "适配", "不适合", "不能放", "电池炉", "电磁炉",
    )
    answer_has_uncertainty = any(marker in answer for marker in uncertainty_markers)
    if (
        answer_type not in {"product_usage_care", "product_detail", "clarification"}
        and not answer_has_uncertainty
        and not answer_has_global_uncertainty
        and not any(term in question for term in direct_non_catalogue_terms)
    ):
        return agent_result
    # A non-browse clarification or speculative identity answer must never
    # carry a broad retrieval set.  Explicit category/recommendation answers
    # were aligned above, so this branch only clears unresolved turns.
    if answer_has_uncertainty or answer_has_global_uncertainty or any(term in question for term in direct_non_catalogue_terms):
        agent_result["results"] = []
        agent_result["result_skus"] = []
        agent_result["candidate_skus"] = []
        agent_result["sources"] = []
        debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
        debug["catalogue_cards_cleared"] = True
        debug["catalogue_cards_cleared_count"] = len(result_skus)
        debug["catalogue_cards_clear_reason"] = "uncertain_or_non_catalogue_answer"
        if isinstance(debug.get("raw_results"), list):
            debug["raw_results"] = []
        agent_result["debug"] = debug
        return agent_result
    agent_result["results"] = []
    agent_result["result_skus"] = []
    agent_result["candidate_skus"] = []
    agent_result["sources"] = []
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    debug["catalogue_cards_cleared"] = True
    debug["catalogue_cards_cleared_count"] = len(result_skus)
    debug["catalogue_cards_clear_reason"] = "non_browse_uncertain_answer"
    if isinstance(debug.get("raw_results"), list):
        debug["raw_results"] = []
    agent_result["debug"] = debug
    return agent_result
_KNOWLEDGE_META_PRODUCT_SOURCES = {"product", "product_qa", "sku_manual"}


def _knowledge_meta_rows(rows: list[dict[str, Any]] | None) -> list[dict[str, Any]]:
    """Keep document evidence for an explicit knowledge-base turn.

    Retrieval is deliberately source-agnostic.  This small projection only
    removes product-index chunks, which belong to the SKU-bound executors and
    must not silently become a general knowledge answer.  It does not inspect
    the customer's wording or classify a product category.
    """
    selected: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    for raw in rows or []:
        if not isinstance(raw, dict):
            continue
        content = str(raw.get("content") or "").strip()
        if not content:
            continue
        source_type = str(raw.get("source_type") or "").strip().lower()
        if source_type in _KNOWLEDGE_META_PRODUCT_SOURCES:
            continue
        metadata = raw.get("metadata") if isinstance(raw.get("metadata"), dict) else {}
        source_id = str(
            metadata.get("source_id")
            or metadata.get("source_id_hash")
            or raw.get("source_id")
            or ""
        ).strip()
        key = (source_type, source_id, content)
        if key in seen:
            continue
        seen.add(key)
        selected.append({
            "source_type": source_type or "knowledge_base",
            "source_id": source_id,
            "title": str(metadata.get("title") or raw.get("title") or "").strip(),
            "content": content,
            "score": raw.get("score"),
            "metadata": metadata,
        })
    return selected


async def _semantic_knowledge_base_meta_result(
    db: Session,
    question: str,
    semantic_preplan: dict[str, Any] | None,
) -> dict | None:
    """Answer an explicit knowledge-base question from retrieved documents.

    Flash owns the meaning of the turn and the wording.  Retrieval supplies
    only document excerpts; this executor never turns a chunk into a product
    candidate and never asks a lexical route to reinterpret the question.
    """
    if db is None:
        return None
    plan = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    query = str(plan.get("qa_evidence_query") or question or "").strip()
    if not query:
        return None
    try:
        retrieved = await knowledge_service.semantic_retrieve(
            db,
            query,
            limit=10,
            prefer_product_sources=False,
        )
    except TypeError:
        # Keep simple test doubles compatible with the retrieval contract.
        try:
            retrieved = await knowledge_service.semantic_retrieve(db, query, limit=10)
        except Exception:
            retrieved = []
    except Exception:
        retrieved = []
    evidence_rows = _knowledge_meta_rows(retrieved)
    if not evidence_rows:
        return None

    packet = [
        {
            "source_index": index,
            "source_type": row["source_type"],
            "source_id": row["source_id"],
            "title": row["title"],
            "content": row["content"][:1800],
        }
        for index, row in enumerate(evidence_rows[:8])
    ]
    runtime = customer_agent_planner_service._semantic_preplan_runtime_settings()
    try:
        raw = await customer_llm_service.chat_completion(
            db,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Return only JSON: {answer:string,used_sources:[integer]}. "
                        "Answer the customer's original question in natural, concise Chinese using only the supplied knowledge-base excerpts. "
                        "The excerpts are the source of truth: do not add general knowledge, product facts, prices, stock, or guarantees. "
                        "Explain the relevant rule or procedure directly, combine related excerpts when useful, and say plainly which point the documents do not establish if the question goes beyond them. "
                        "Do not turn the reply into a retrieval report, a source dump, a fixed no-match sentence, or a follow-up question when the excerpts already answer it. "
                        "Do not mention models, prompts, routing, chunks, indexes, validation, or internal fields. "
                        "used_sources may contain only source_index values from the supplied excerpts."
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps(
                        {
                            "question": str(question or "").strip(),
                            "knowledge_query": query,
                            "excerpts": packet,
                        },
                        ensure_ascii=False,
                    ),
                },
            ],
            temperature=0.3,
            max_tokens=min(int(runtime["max_tokens"]), 600),
            purpose="semantic_knowledge_base_answer",
            api_model_override=runtime["model"],
            response_format=runtime["response_format"],
            thinking=runtime["thinking"],
        )
    except Exception:
        return None
    parsed = _parse_semantic_json_object(str(raw or "")) or {}
    answer = str(parsed.get("answer") or "").strip()
    if not answer:
        return None
    selected_indexes = [
        value
        for value in (parsed.get("used_sources") or [])
        if type(value) is int and 0 <= value < len(packet)
    ]
    selected_indexes = list(dict.fromkeys(selected_indexes)) or list(range(len(packet)))
    evidence = []
    for index in selected_indexes:
        row = evidence_rows[index]
        item = {
            "type": "knowledge_base",
            "source_type": row["source_type"],
            "source": row["source_type"],
            "content": row["content"],
        }
        if row["source_id"]:
            item["source_id"] = row["source_id"]
        if row["title"]:
            item["title"] = row["title"]
        evidence.append(item)
    return {
        "intent": "knowledge_base_answer",
        "answer_type": "knowledge_base_answer",
        "answer": answer,
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "evidence": evidence,
        "answer_metadata": {
            "source": "semantic_knowledge_base_rag",
            "information_scope": "knowledge_base_meta",
            "evidence_status": "matched",
            "knowledge_query": query,
            "used_source_indexes": selected_indexes,
        },
        "debug": {
            "agent_mode": "semantic_knowledge_base_rag",
            "knowledge_query": query,
            "retrieved_document_count": len(evidence_rows),
            "used_source_indexes": selected_indexes,
        },
        "skip_polish": True,
    }


def _semantic_first_turn_is_owned(preplan: dict | None) -> bool:
    """Return whether a healthy semantic plan owns the complete read turn.

    This is deliberately a route-family check, not another intent classifier.
    Once the model has produced a usable plan, the legacy parser must not get a
    second vote and reinterpret the same sentence.  Identity, permissions,
    writes, and safety guards still run before this boundary.
    """
    if not isinstance(preplan, dict) or not preplan.get("called"):
        return False
    if preplan.get("error"):
        return False
    if str(preplan.get("fallback_reason") or "").strip():
        return False
    route = _semantic_preplan_route_family(preplan)
    # Flash can mark a recommendation or a named-product comparison as
    # ambiguous while still preserving the product scope and requested work.
    # That flag is a diagnostic about wording, not product identity or
    # evidence. Let the corresponding RAG executor inspect the catalogue; its
    # same-SKU verifier decides whether the identity is actually sealable. A
    # comparison with two literal participants is safe to enter for the same
    # reason: an unsealable participant still fails closed in the comparison
    # entity contract, while a sealable pair must not be discarded here.
    if preplan.get("ambiguity") and route not in {"recommendation", "comparison"}:
        # Ambiguity is a model diagnostic, not an evidence decision.  A
        # product-bound plan that still carries a formal field, a QA retrieval
        # query, an entity, or a prior-result handle has executable meaning;
        # let entity resolution/RAG decide whether it can be sealed.  Keep the
        # empty malformed shape out of the live executor so an incomplete
        # provider packet cannot become arbitrary catalogue work.
        has_product_work = bool(
            preplan.get("canonical_fields")
            or str(preplan.get("field_type") or "").strip()
            or str(preplan.get("qa_evidence_query") or "").strip()
            or preplan.get("entities")
            or preplan.get("context_result_indexes")
            or (route == "general_chat" and bool(preplan.get("qa_or_usage_care")))
        )
        if not (
            has_product_work
            and route in {"product_bound_qa", "general_chat"}
        ):
            return False
    return bool(route and _semantic_preplan_confident(preplan, minimum=0.65))


def _semantic_owned_missing_result(
    question: str,
    preplan: dict,
    *,
    reason: str,
) -> dict:
    """Fail closed without handing a healthy semantic turn to legacy routes."""
    route = _semantic_preplan_route_family(preplan) or "semantic"
    requirements = [
        str(item or "").strip()
        for item in (
            list(preplan.get("recommendation_evidence_requirements") or [])
            + list(preplan.get("unrepresented_recommendation_requirements") or [])
        )
        if str(item or "").strip()
    ]
    # This is only the provider-outage fallback.  When Flash is available the
    # companion writer above supplies the customer-facing wording.  Keep the
    # local fallback short and non-prescriptive so it cannot turn one missing
    # retrieval result into a hard-coded request for a specific field.
    answer = "这次我还没能核对到足够明确的资料，先不替你猜结论；如果你愿意，可以再试一次，我会继续按原问题查。"
    return {
        "intent": "recommendation" if route == "recommendation" else "clarification",
        "answer_type": "clarification",
        "answer": answer,
        "results": [],
        "result_skus": [],
        "candidate_skus": [],
        "evidence": [],
        "needs_clarification": True,
        "answer_metadata": {
            "source": "semantic_first_turn_owned_missing",
            "semantic_route": route,
            "evidence_status": "missing",
        },
        "debug": {
            "agent_mode": "semantic_first_turn_owned_missing",
            "semantic_route": route,
            "reason": reason,
            "question": question,
        },
        "skip_polish": True,
    }


def _remove_redundant_identity_request(agent_result: dict) -> dict:
    """Remove a late product-name/SKU re-ask after identity is sealed.

    Several legacy presentation boundaries and the recovery writer can each
    produce a reasonable clarification in isolation.  Once the result carries
    exactly one verified product identity, asking for that identity again is
    contradictory and makes the answer look like a canned failure.  This
    shared cleanup preserves the unresolved product point and never removes a
    request for a genuinely missing non-identity detail.
    """
    if not isinstance(agent_result, dict):
        return agent_result
    result_skus = list(dict.fromkeys(
        str(item or "").strip().upper()
        for item in (agent_result.get("result_skus") or [])
        if str(item or "").strip()
    ))
    if len(result_skus) != 1:
        return agent_result
    metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    semantic_product_qa = (
        str(metadata.get("source") or "") == "semantic_clarification"
        or str(metadata.get("source") or "").startswith("semantic_outage_")
        or str(debug.get("semantic_route") or "") == "product_bound_qa"
        or str(debug.get("agent_mode") or "").startswith("semantic_first_product_qa")
        or str(debug.get("agent_mode") or "").startswith("semantic_outage_named_product")
    )
    if not semantic_product_qa:
        return agent_result
    answer = str(agent_result.get("answer") or "").strip()
    if not answer:
        return agent_result
    identity_request = re.compile(
        r"(?:请提供|提供|把).{0,48}(?:商品名|SKU).{0,36}(?:再|继续|核对|确认|查)",
        flags=re.IGNORECASE | re.DOTALL,
    )
    if not identity_request.search(answer):
        return agent_result
    cleaned = re.sub(
        r"(?:请提供|提供|把).{0,48}(?:商品名|SKU).{0,36}(?:再|继续|核对|确认|查)[^。！？!?]*[。！？!?]?",
        "",
        answer,
        flags=re.IGNORECASE | re.DOTALL,
    ).strip(" \t\r\n，,；;。！？!?.")
    if not cleaned:
        rows = [row for row in (agent_result.get("results") or []) if isinstance(row, dict)]
        name = str((rows[0] if rows else {}).get("product_name_cn") or result_skus[0]).strip()
        cleaned = f"{name}（{result_skus[0]}）这次还没核实到你问的那一点；可以补充具体使用场景或参数，我再继续核对"
    agent_result["answer"] = cleaned.rstrip("。！？!?.") + "。"
    debug = dict(debug)
    debug["redundant_identity_request_removed"] = True
    agent_result["debug"] = debug
    return agent_result


async def _semantic_owned_missing_result_with_llm(
    db: Session,
    question: str,
    preplan: dict,
    *,
    reason: str,
    resolved_sku: str | None = None,
    catalogue_context: dict[str, Any] | None = None,
) -> dict:
    """Recover a useful customer turn when a semantic executor has no result.

    This is deliberately a prose recovery pass, not another route or evidence
    gate.  A failed executor must not expose one identical internal failure
    sentence for every question.  The model may only acknowledge the request,
    explain what remains unresolved, and ask for the single most useful next
    detail; it cannot invent a product fact or silently select a SKU.
    """
    resolved_sku = str(resolved_sku or "").strip().upper()
    base = _semantic_owned_missing_result(question, preplan, reason=reason)
    product_name = ""
    product_category = ""
    if resolved_sku and db is not None:
        try:
            product = db.query(Product).filter(Product.sku == resolved_sku).first()
        except Exception:
            product = None
        if product is not None:
            product_name = str(
                getattr(product, "product_name_cn", None)
                or getattr(product, "product_name_en", None)
                or resolved_sku
            ).strip()
            row = {
                "sku": resolved_sku,
                "product_name_cn": product_name,
            }
            category = str(getattr(product, "category", None) or "").strip()
            if category:
                product_category = category
                row["category"] = category
            base.update({
                "results": [row],
                "result_skus": [resolved_sku],
                "candidate_skus": [resolved_sku],
                "sku": resolved_sku,
            })
            metadata = base.setdefault("answer_metadata", {})
            metadata.update({
                "resolved_identity": True,
                "resolved_sku": resolved_sku,
                "identity_source": "semantic_missing_recovery",
            })
    runtime = customer_agent_planner_service._semantic_preplan_runtime_settings()
    semantic_value = preplan if isinstance(preplan, dict) else {}
    route_family = str(semantic_value.get("route_family") or "").strip()
    requested_condition_label = _semantic_missing_condition_label(
        question,
        semantic_value,
        resolved_sku=resolved_sku,
        product_name=product_name,
    )
    prompt_payload = {
        "question": str(question or "").strip(),
        "route_family": route_family,
        "subject_text": str(semantic_value.get("subject_text") or "").strip(),
        "meaningful_requirements": [
            str(item or "").strip()
            for item in (
                list(semantic_value.get("recommendation_evidence_requirements") or [])
                + list(semantic_value.get("unrepresented_recommendation_requirements") or [])
                + list(semantic_value.get("recommendation_soft_preferences") or [])
            )
            if str(item or "").strip()
        ][:5],
        "semantic_ambiguity": str(semantic_value.get("ambiguity") or "").strip(),
        "requested_condition": requested_condition_label,
        "resolved_identity": {
            "sku": resolved_sku,
            "product_name": product_name,
            "category": product_category,
        } if resolved_sku else None,
        "catalogue_context": catalogue_context if isinstance(catalogue_context, dict) else {},
    }
    no_verified_recommendation_instruction = ""
    if route_family == "recommendation" and not resolved_sku:
        # A missing recommendation has no customer-visible product identity.
        # Preserve only the semantic state needed to explain a known direct
        # match gap; do not expose an unranked recall list as an unsolicited
        # recommendation. This lets a genuine missing product form be
        # explained plainly without turning every provider failure into the
        # same opaque no-result sentence.
        catalogue_state = prompt_payload.get("catalogue_context")
        catalogue_state = catalogue_state if isinstance(catalogue_state, dict) else {}
        prompt_payload["catalogue_context"] = {
            key: catalogue_state[key]
            for key in ("direct_match_found", "unmet_conditions", "related_items")
            if key in catalogue_state
        }
        prompt_payload["no_verified_recommendation_candidate"] = True
        if catalogue_state.get("direct_match_found") is False:
            no_verified_recommendation_instruction = (
                "The supplied catalogue state explicitly says direct_match_found=false for the requested product form or capability. "
                "State that limitation plainly in natural Chinese. You may briefly name one or two supplied related_items as adjacent records, but explicitly say they are not substitutes for the requested form or capability. "
                "Do not ask for a brand, model, SKU, more detail, or a later retry, and do not end with a question or a promise to search again. "
                "Do not recommend the adjacent records as alternatives. End after the self-contained explanation. "
            )
        else:
            no_verified_recommendation_instruction = (
                "No verified recommendation candidate was selected for this turn. Do not name, list, or recommend any product, SKU, or alternative. "
                "Do not turn a related catalogue record into a suggestion. Explain the unresolved request in natural Chinese; ask at most one useful follow-up only if the customer's own request leaves a meaningful search choice, otherwise end with the explanation. "
            )
    care_recovery_instruction = ""
    knowledge_scope_recovery_instruction = ""
    if route_family == "knowledge_base_meta" or str(
        semantic_value.get("information_scope") or ""
    ).strip() == "knowledge_base_meta":
        # A knowledge-base-bounded turn must not fall through to the generic
        # care writer when retrieval is empty. The honest answer is a scoped
        # gap, not uncited procedural advice from model memory.
        prompt_payload["knowledge_base_evidence_missing"] = True
        knowledge_scope_recovery_instruction = (
            "The customer explicitly bounded this request to the knowledge base. No matching knowledge-base excerpt was supplied. "
            "State that the current knowledge base does not provide a directly matching cleaning/maintenance instruction. Do not give general advice, a safety recipe, or a product-specific procedure from memory; do not claim that any step is required or safe. "
            "Do not ask the customer to restate the question or choose an alternative. End with the scoped limitation. "
        )
    # ``qa_or_usage_care`` is only a semantic side signal.  It can coexist
    # with a recommendation (for example, a request for a pot that should work
    # with an alcohol stove), so it must never authorize an unrelated cleaning
    # recipe in a no-match recommendation recovery.  Only an explicitly
    # usage/safety-shaped plan may use the conservative care guidance below.
    care_signal = (
        str(semantic_value.get("subtype") or "").strip() in {"usage_care", "safety_procedure"}
        or str(semantic_value.get("question_type") or "").strip() in {"usage", "safety"}
    )
    if (
        not knowledge_scope_recovery_instruction
        and (
            route_family == "general_chat"
            or (
                not resolved_sku
                and care_signal
                and not customer_agent_service._extract_skus(question)
            )
        )
    ):
        care_recovery_instruction = (
            "This is an unbound cleaning/usage/safety question, not a product lookup. "
            "Give a short, directly usable conservative answer even when the catalogue executor has no result: stop heating and let the cookware cool, "
            "then use warm water and a soft cloth or sponge; avoid metal or hard scraping, abrasive pads, strong chemicals, and another high-heat attempt. "
            "Do not add a soaking duration, detergent type, baking soda, boiling, cold-water warning, or product-specific procedure unless the supplied evidence explicitly states it. Do not claim the method will definitely avoid damage, is completely safe, or will remove the stain; use Chinese wording only. "
            "Do not turn this into a generic '资料未找到' reply. "
        )
    try:
        raw = await customer_llm_service.chat_completion(
            db,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Return only JSON: {answer:string}. Write a natural, concise Chinese reply to the customer's original question. "
                        "The catalogue executor did not produce a complete verified answer for this turn. Do not invent a product, SKU, price, stock, material, capacity, compatibility, or other product fact. "
                        "Acknowledge the customer's actual purpose and explain only what remains unresolved in plain language. "
                        + no_verified_recommendation_instruction
                        + knowledge_scope_recovery_instruction
                        + care_recovery_instruction
                        + (
                                "If a resolved identity is supplied, keep that product identity and never ask the customer to repeat its name or SKU. You may use the supplied product name and category only to clarify what item was actually resolved; they are identity context, not proof of an unlisted capability. If the customer's requested capability belongs to a different product form than the resolved item, say that the catalogue identifies the item as the recorded product type and that the requested capability is not recorded for this SKU. Do not turn that distinction into an absolute technical impossibility, and do not silently substitute another SKU. If the original turn already contains a concrete SKU or product name but the catalogue could not resolve it, state that the supplied identifier has no confirmed record; do not ask the customer to repeat it, replace it, or provide a different identifier. For an unbound recommendation, do not ask for a product name, model, or SKU merely because no direct candidate was found; request identity only when the customer is clearly asking about a particular item. If the customer wants a recommendation, ask one concrete detail only when it would genuinely improve the next search. "
                            "Do not silently replace a requested condition with an easier alternative, and do not ask the customer to choose an alternative unless they asked for one. "
                            "When catalogue_context says direct_match_found is false, do not ask the customer to choose among product forms or alternatives that are absent from related_items. State the missing direct match plainly; related_items may be named only as adjacent, non-equivalent records. If you name one, preserve its supplied catalogue name exactly and explicitly say it is not a substitute for the requested form or capability. Do not reinterpret a title, keyword, broad category, or neighboring workflow as proof of the requested form, and do not add a parenthetical label that changes what the catalogue item is. When the missing point is the requested product form or capability itself and the supplied context shows no direct match, do not ask for budget, scenario, a more specific subcategory, or any other new detail as though that could create the missing catalogue item; give a self-contained limitation instead. In this direct_match_found=false case, end with the explanation rather than a question or a promise to search again. Prefer a self-contained explanation when no additional customer detail would materially change the search. "
                            "Do not mention routing, retrieval, evidence gates, models, databases, internal failures, executor branches, or the phrase 'semantic'. "
                            "Avoid canned system-error wording and keep the reply specific to the customer's question. "
                                "Do not make the answer sound like a generic system error. Keep it to one or two helpful sentences and do not ask more than one question. Do not claim that the method will definitely avoid damage, is completely safe, or will remove the stain. Use Chinese wording only."
                        )
                    ),
                },
                {"role": "user", "content": json.dumps(prompt_payload, ensure_ascii=False)},
            ],
            temperature=0.1,
            max_tokens=min(int(runtime["max_tokens"]), 280),
            purpose="semantic_customer_natural_recovery",
            api_model_override=runtime["model"],
            response_format=runtime["response_format"],
            thinking=runtime["thinking"],
        )
        payload = customer_agent_planner_service._extract_json_object(str(raw or "")) or {}
        answer = str(payload.get("answer") or "").strip()
    except Exception:
        answer = ""
    if answer:
        base["answer"] = answer
        base["debug"]["recovery_writer"] = "flash_natural_recovery"
    return base


def _semantic_care_fields_to_product_qa_preplan(
    semantic_preplan: dict[str, Any] | None,
) -> dict[str, Any] | None:
    """Reuse same-SKU RAG for semantic care fields without a QA keyword route.

    Cleaning, maintenance, and usage instructions are often stored in the
    product profile rather than authored as a standalone ProductQa row.  The
    planner may represent that meaning with formal care fields, so adapt that
    already validated field set into the existing product-QA/RAG executor.
    This does not infer a field from question text and does not widen product
    identity or evidence scope.
    """
    value = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    fields = {
        customer_field_contract.semantic_preplan_field_type(item)
        for item in [
            value.get("field_type"),
            value.get("field_hint"),
            *(value.get("canonical_fields") or []),
        ]
        if customer_field_contract.semantic_preplan_field_type(item)
    }
    if not (
        str(value.get("route_family") or "").strip() == "product_bound_qa"
        and str(value.get("evidence_kind") or "").strip() == "structured_field"
        and fields
        and fields.issubset({"cleaning", "care", "usage_instruction"})
        and str(value.get("subject_text") or "").strip()
    ):
        return None
    adapted = dict(value)
    adapted.update({
        "route_family": "product_bound_qa",
        "route_hint": "product_detail",
        "question_type": "field",
        "canonical_fields": [],
        "field_type": "",
        "field_hint": None,
        "evidence_kind": "product_qa",
        # Keep the original customer turn as the retrieval fallback.  A
        # product name alone is not a care/usage query and makes RAG retrieve
        # the whole profile instead of the operative instruction.
        "qa_evidence_query": str(
            value.get("qa_evidence_query")
            or value.get("supplemental_qa_evidence_query")
            or ""
        ).strip(),
        "qa_evidence_queries": [],
        "accepted_or_overridden": "overridden",
        "override_reason": "semantic_care_fields_use_same_sku_rag",
        "semantic_adapter_source": "semantic_care_fields_to_same_sku_rag",
        # Ambiguity here describes the provider's wording diagnosis.  The
        # actual product identity is still sealed by the same-SKU entity
        # contract below; keeping it as a route veto would send a named care
        # question back to the structured field dumper.
        "semantic_original_ambiguity": bool(value.get("ambiguity")),
        "ambiguity": False,
    })
    return adapted


def _semantic_subfield_to_product_qa_preplan(
    semantic_preplan: dict[str, Any] | None,
) -> dict[str, Any] | None:
    """Adapt a semantic sub-capability hidden under a broad formal field.

    Providers sometimes place a natural capability such as grind adjustment
    under ``specification`` because the catalogue has no dedicated column.
    Reopening a lexical field route loses the actual question.  The adapter
    preserves the model's subfield decision and sends it through the existing
    same-SKU QA/RAG executor; it supplies no identity, value, or answer.
    """
    value = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    fields = {
        customer_field_contract.semantic_preplan_field_type(item)
        for item in [
            value.get("field_type"),
            value.get("field_hint"),
            *(value.get("canonical_fields") or []),
        ]
        if customer_field_contract.semantic_preplan_field_type(item)
    }
    hint = str(value.get("field_hint") or "").strip()
    if not (
        str(value.get("route_family") or "").strip() == "product_bound_qa"
        and str(value.get("evidence_kind") or "").strip() == "structured_field"
        and fields
        and str(value.get("subject_text") or "").strip()
        and hint
        and hint not in customer_field_contract.FORMAL_DETAIL_FIELDS
        and hint != str(value.get("field_type") or "").strip()
    ):
        return None
    adapted = dict(value)
    adapted.update({
        "route_family": "product_bound_qa",
        "route_hint": "product_detail",
        "question_type": "field",
        "canonical_fields": [],
        "field_type": "",
        "field_hint": None,
        "evidence_kind": "product_qa",
        "qa_evidence_query": str(
            value.get("qa_evidence_query")
            or value.get("supplemental_qa_evidence_query")
            or ""
        ).strip(),
        "qa_evidence_queries": [],
        "accepted_or_overridden": "overridden",
        "override_reason": "semantic_subfield_uses_same_sku_rag",
        "semantic_adapter_source": "semantic_subfield_to_same_sku_rag",
        "semantic_original_ambiguity": bool(value.get("ambiguity")),
        "ambiguity": False,
    })
    return adapted


def _normalize_unanchored_product_qa_to_general_chat(
    db: Session,
    question: str,
    semantic_preplan: dict[str, Any] | None,
    *,
    context_result_skus: list[str] | None = None,
    phase1_plan: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    """Keep an identity-free product-QA shape out of the product executor.

    This is a schema invariant, not a wording classifier: a product-bound
    executor needs either a named/current product or a conversation result
    anchor.  If neither exists, the turn is general guidance and the LLM may
    answer it without pretending a catalogue product was identified.
    """
    value = semantic_preplan if isinstance(semantic_preplan, dict) else {}
    if str(value.get("route_family") or "").strip() != "product_bound_qa":
        return value if isinstance(semantic_preplan, dict) else None
    subject_text = str(value.get("subject_text") or "").strip()
    if value.get("context_result_indexes") or context_result_skus:
        return value
    if isinstance(phase1_plan, dict) and phase1_plan.get("request_sku_anchor"):
        return value
    context_usage = str(value.get("context_usage") or "").strip()
    if context_usage in {"entity_anchor", "active_product_anchor", "anchor", "result_context"}:
        return value
    # Catalogue identity resolution is the only source allowed to decide
    # whether a current-turn name is a real product.  A generic noun such as
    # “锅” therefore remains general guidance, while an exact named product
    # continues through same-SKU QA even if Flash omitted its entity span.
    if db is not None and (
        _explicit_product_from_question(db, question) is not None
        or bool(_products_named_in_question(db, question))
    ):
        return value
    # Flash can preserve the product meaning while a shopper shortens or
    # mistypes one character of the catalogue name (for example, omitting the
    # leading ``天`` in ``天鹅壶4杯-黑色``).  Do not throw that semantically
    # product-bound turn into free-form chat: a unique, catalogue-validated
    # near-name recovery can hand the canonical display name to the existing
    # entity contract, which then seals the SKU before RAG sees any evidence.
    # This is identity recovery only; it does not classify the question,
    # select a field, or accept a product fact from the model.
    if db is not None:
        try:
            products = db.query(Product).order_by(Product.sku.asc()).all()
            recovered_subject = _semantic_unique_typo_near_catalog_subject(
                subject_text,
                products,
            )
        except Exception:
            recovered_subject = ""
        if recovered_subject:
            normalized = dict(value)
            normalized["subject_text"] = recovered_subject
            normalized["entities"] = [
                recovered_subject
                if customer_agent_service.normalize_search_text(str(entity or "")).strip()
                == customer_agent_service.normalize_search_text(subject_text).strip()
                else entity
                for entity in (value.get("entities") or [])
            ] or [recovered_subject]
            normalized["semantic_adapter_source"] = (
                "semantic_catalogue_unique_near_name_identity_recovery"
            )
            normalized["identity_recovery"] = {
                "source": "catalogue_unique_near_name",
                "recovered_subject": recovered_subject,
            }
            return normalized
    # A generic product form (for example, a liquid-alcohol stove in a
    # closed tent) is not a sealed catalogue identity. Let the semantic
    # general-guidance/RAG path answer the safety question instead of sending
    # it to a product-QA executor that can only return a missing-SKU result.
    # An explicit but unknown SKU stays product-bound so the customer receives
    # an identity-specific "not found" answer rather than generic advice.
    if _has_explicit_sku_text(question):
        return value
    normalized = dict(value)
    normalized.update({
        "route_family": "general_chat",
        "route_hint": "general_chat",
        "question_type": "general_guidance",
        "entities": [],
        "subject_text": "",
        "canonical_fields": [],
        "field_type": "",
        "field_hint": None,
        "evidence_required": False,
        "evidence_kind": "structured_field",
        "qa_evidence_query": str(value.get("qa_evidence_query") or question or "").strip(),
        "context_usage": "none",
        "context_result_indexes": [],
        "accepted_or_overridden": "overridden",
        "override_reason": "unanchored_product_qa_to_general_guidance",
        "semantic_adapter_source": "unanchored_product_qa_to_general_chat",
        "ambiguity": False,
    })
    return normalized


def _normalize_semantic_catalogue_continuation(
    db: Session,
    semantic_preplan: dict | None,
    recommendation_context: dict | None,
) -> dict | None:
    """Keep a category continuation in the catalogue executor.

    Flash sometimes treats a bare category follow-up as a choice among the
    previous opaque result handles.  That is a discourse interpretation
    error: a customer saying only a real catalogue category is usually
    narrowing the search scope, not selecting one of the previous products.
    Resolve the subject against live category membership and normalize only
    this internally inconsistent plan.  No Chinese phrase list, product fact,
    or candidate identity is introduced here.
    """
    if not isinstance(semantic_preplan, dict) or db is None:
        return semantic_preplan
    route_family = str(semantic_preplan.get("route_family") or "").strip()
    if route_family not in {"product_navigation", "recommendation"}:
        return semantic_preplan
    subject = str(semantic_preplan.get("subject_text") or "").strip()
    if not subject:
        return semantic_preplan
    try:
        catalogue_rows = _phase1_catalog_rows(db, "产品")
        category_ref = _database_category_scope_ref(catalogue_rows, subject)
    except Exception:
        return semantic_preplan
    if not category_ref:
        return semantic_preplan

    predicate_constraints = [
        item
        for item in (
            semantic_preplan.get("predicate_constraints")
            or semantic_preplan.get("structured_query_constraints")
            or []
        )
        if isinstance(item, dict)
        and str(item.get("field") or "").strip()
        not in {"", "category"}
    ]
    canonical_fields = [
        str(item or "").strip()
        for item in (semantic_preplan.get("canonical_fields") or [])
        if str(item or "").strip() not in {"", "category"}
    ]
    normalized_subject = customer_agent_service.normalize_search_text(subject).strip()
    non_subject_entities = [
        str(entity or "").strip()
        for entity in (semantic_preplan.get("entities") or [])
        if str(entity or "").strip()
        and customer_agent_service.normalize_search_text(str(entity or "")).strip()
        != normalized_subject
    ]
    has_selection_detail = bool(
        predicate_constraints
        or canonical_fields
        # ``decision_requested`` is itself a semantic selection contract.
        # A recommendation can have no formal predicate when Flash preserves
        # the scenario in its typed semantic context; the live category-scope
        # adapter must not downgrade that explicit choice request to a browse.
        or semantic_preplan.get("decision_requested") is True
        or semantic_preplan.get("recommendation_evidence_requirements")
        or semantic_preplan.get("recommendation_soft_preferences")
        or semantic_preplan.get("unrepresented_recommendation_requirements")
        or non_subject_entities
    )
    if has_selection_detail:
        return semantic_preplan

    normalized = dict(semantic_preplan)
    has_prior_recommendation = bool(
        isinstance(recommendation_context, dict)
        and (
            recommendation_context.get("recommended_skus")
            or recommendation_context.get("previous_result_skus")
        )
    )
    if has_prior_recommendation:
        # This is a category narrowing inside the existing recommendation
        # conversation.  Preserve the prior purpose as context, but do not
        # bind the new turn to opaque result positions or an alternative
        # action that the customer did not ask for.
        normalized["route_family"] = "recommendation"
        normalized["route_hint"] = "recommendation"
        normalized["question_type"] = "recommendation"
        normalized["context_usage"] = "recommendation_context"
        normalized["context_result_indexes"] = []
        normalized["decision_requested"] = False
        normalized["recommendation_followup_action"] = ""
        normalized["fallback_reason"] = ""
        normalized["ambiguity"] = False
        normalized["accepted_or_overridden"] = "catalogue_category_continuation"
        normalized["override_reason"] = "live_category_scope_overrode_opaque_result_choice"
        normalized["catalogue_category_ref"] = category_ref
    else:
        # Without a recommendation context, a bare category is a catalogue
        # browse.  Let the structured catalogue executor display its actual
        # members instead of trying to resolve the category as one product.
        normalized["route_family"] = "structured_query"
        normalized["route_hint"] = "query_products"
        normalized["question_type"] = "filter"
        normalized["subtype"] = "category_browse"
        normalized["context_usage"] = "none"
        normalized["context_result_indexes"] = []
        normalized["decision_requested"] = False
        normalized["canonical_fields"] = ["category"]
        normalized["recommendation_constraints"] = {}
        normalized["recommendation_followup_action"] = ""
        normalized["fallback_reason"] = ""
        normalized["ambiguity"] = False
        normalized["accepted_or_overridden"] = "catalogue_category_continuation"
        normalized["override_reason"] = "live_category_scope_overrode_product_navigation"
        normalized["catalogue_category_ref"] = category_ref
    return normalized


def _normalize_semantic_recommendation_scope_from_context(
    db: Session,
    semantic_preplan: dict | None,
    recommendation_context: dict | None,
) -> dict | None:
    """Carry a prior catalogue scope into an underspecified recommendation.

    A later turn may supply the decision variables (for example, group size
    and scene) without repeating the product kind selected one turn earlier.
    Flash is free to describe that turn broadly, so the executor uses the
    persisted live catalogue scope as discourse context when the current
    subject resolves to neither a category nor a product family.  This is a
    database-backed context normalization, not a phrase route or a second
    interpretation of the customer's wording.
    """
    if (
        not isinstance(semantic_preplan, dict)
        or not isinstance(recommendation_context, dict)
        or db is None
        or str(semantic_preplan.get("route_family") or "").strip() != "recommendation"
    ):
        return semantic_preplan
    prior_scope = str(recommendation_context.get("product_scope") or "").strip()
    if not prior_scope:
        prior_contract = (
            recommendation_context.get("effective_recommendation_contract")
            or recommendation_context.get("recommendation_request_contract")
        )
        if isinstance(prior_contract, dict):
            prior_scope = str(prior_contract.get("subject_category") or "").strip()
    if not prior_scope:
        return semantic_preplan
    try:
        catalogue_rows = _phase1_catalog_rows(db, "产品")
        prior_category = _database_category_scope_ref(catalogue_rows, prior_scope)
        current_subject = str(semantic_preplan.get("subject_text") or "").strip()
        current_category = _database_category_scope_ref(catalogue_rows, current_subject) if current_subject else ""
        current_family_rows = (
            _database_product_family_scope_rows(catalogue_rows, current_subject)
            if current_subject and not current_category
            else []
        )
    except Exception:
        return semantic_preplan
    if not prior_category or current_category or current_family_rows:
        return semantic_preplan

    normalized = dict(semantic_preplan)
    normalized["subject_text"] = prior_category
    normalized["entity_scope"] = "category_scope"
    normalized["context_usage"] = "recommendation_context"
    normalized["context_result_indexes"] = []
    normalized["catalogue_category_ref"] = prior_category
    normalized["context_scope_inherited"] = {
        "source": "persisted_recommendation_catalogue_scope",
        "category": prior_category,
    }
    # Keep the small schema's product-kind value aligned with the live scope;
    # otherwise a broad model label such as accessories can reopen an unrelated
    # category after the scope has already been resolved from the catalogue.
    kind_by_category = {
        "锅具": "cookware",
        "水具": "waterware",
        "炉具": "stove",
        "咖啡器具": "coffee_gear",
        "配件": "accessories",
    }
    constraints = dict(normalized.get("recommendation_constraints") or {})
    prior_kind = kind_by_category.get(prior_category)
    if prior_kind:
        constraints["subject_kind"] = prior_kind
        normalized["recommendation_constraints"] = constraints
    normalized["accepted_or_overridden"] = "recommendation_context_scope"
    normalized["override_reason"] = "current_subject_has_no_live_catalogue_scope"
    normalized["semantic_adapter_source"] = "persisted_catalogue_scope_context"
    return normalized


async def _semantic_first_turn_result(
    db: Session,
    *,
    question: str,
    phase1_plan: dict,
    semantic_preplan: dict,
    conversation_id: str | None,
    user_id: str,
) -> tuple[dict | None, str | None]:
    """Execute one healthy Flash plan through the central RAG executors.

    A successful semantic plan owns the turn.  This function only chooses the
    executor that matches that plan and binds any returned facts to the
    executor's existing same-SKU contracts; it never re-parses the question
    with the historical keyword router.
    """
    if not _semantic_first_turn_is_owned(semantic_preplan):
        return None, None

    phase1_plan["semantic_preplan"] = semantic_preplan
    recommendation_context = (
        _latest_recommendation_context_for_sources(db, conversation_id)
        if conversation_id else None
    )
    candidate_context = (
        _latest_candidate_context_for_sources(db, conversation_id)
        if conversation_id else None
    )
    semantic_preplan = (
        _normalize_semantic_catalogue_continuation(
            db,
            semantic_preplan,
            recommendation_context,
        )
        or semantic_preplan
    )
    semantic_preplan = (
        _normalize_semantic_recommendation_scope_from_context(
            db,
            semantic_preplan,
            recommendation_context,
        )
        or semantic_preplan
    )
    phase1_plan["semantic_preplan"] = semantic_preplan
    context_result_skus = _semantic_prior_result_context_skus(
        recommendation_context,
        candidate_context,
    )
    semantic_preplan = _normalize_unanchored_product_qa_to_general_chat(
        db,
        question,
        semantic_preplan,
        context_result_skus=context_result_skus,
        phase1_plan=phase1_plan,
    ) or semantic_preplan
    phase1_plan["semantic_preplan"] = semantic_preplan
    route = _semantic_preplan_route_family(semantic_preplan)

    # Run this check after all context normalizers have settled the current
    # discourse shape.  In particular, Flash can first describe a replacement
    # as a choice from opaque result handles; the classifier decides whether it
    # is actually a fresh alternative search before the recommendation branch
    # locks that handle set.
    if (
        str(semantic_preplan.get("recommendation_followup_action") or "").strip()
        == "alternative"
        and isinstance(recommendation_context, dict)
    ):
        semantic_preplan = _apply_semantic_recommendation_followup_action(
            semantic_preplan,
            recommendation_context,
            {
                "recommendation_followup_action": "alternative",
                "relative_fields": semantic_preplan.get("canonical_fields") or [],
            },
        ) or semantic_preplan
        phase1_plan["semantic_preplan"] = semantic_preplan
    followup_review_needed = _semantic_recommendation_followup_review_needed(
        semantic_preplan,
        recommendation_context,
    )
    if followup_review_needed:
        followup_decision = await customer_agent_planner_service.classify_semantic_recommendation_followup(
            db,
            question=question,
            semantic_preplan=semantic_preplan,
            context={
                "has_recommendation_context": True,
                "prior_result_context_semantics": _semantic_prior_result_context_semantics(
                    recommendation_context,
                    candidate_context,
                ),
            },
        )
        if isinstance(semantic_preplan, dict):
            semantic_preplan["semantic_recommendation_followup_review"] = dict(followup_decision)
        semantic_preplan = (
            _apply_semantic_recommendation_followup_action(
                semantic_preplan,
                recommendation_context,
                followup_decision,
            )
            or semantic_preplan
        )
        phase1_plan["semantic_preplan"] = semantic_preplan
        route = _semantic_preplan_route_family(semantic_preplan)

    if route == "comparison" and not bool(semantic_preplan.get("decision_requested")):
        comparison_decision_review = (
            await customer_agent_planner_service.classify_semantic_comparison_decision(
                db,
                question=question,
                semantic_preplan=semantic_preplan,
            )
        )
        semantic_preplan = dict(semantic_preplan)
        semantic_preplan["semantic_comparison_decision_review"] = dict(
            comparison_decision_review
        )
        if comparison_decision_review.get("decision_requested") is True:
            semantic_preplan["decision_requested"] = True
            semantic_preplan["accepted_or_overridden"] = "overridden"
            semantic_preplan["override_reason"] = (
                "flash_semantic_comparison_decision_review"
            )
        phase1_plan["semantic_preplan"] = semantic_preplan

    if route == "knowledge_base_meta":
        result = await _semantic_knowledge_base_meta_result(
            db,
            question,
            semantic_preplan,
        )
        return (
            result
            or await _semantic_owned_missing_result_with_llm(
                db,
                question,
                semantic_preplan,
                reason="knowledge_base_meta_executor_no_result",
            ),
            "semantic_first_knowledge_base_meta"
            if result
            else "semantic_first_knowledge_base_meta_missing",
        )

    if route == "recommendation":
        context_choice_requested = bool(
            semantic_preplan.get("context_result_indexes")
            and str(semantic_preplan.get("context_usage") or "").strip()
            == "result_context"
            and bool(semantic_preplan.get("decision_requested"))
            and str(semantic_preplan.get("recommendation_followup_action") or "").strip()
            != "alternative"
            and context_result_skus
        )
        prior_context_is_comparison = any(
            str(context.get("source") or "").strip().lower() == "comparison"
            or str(context.get("answer_type") or "").strip().lower() == "comparison"
            for context in (candidate_context, recommendation_context)
            if isinstance(context, dict)
        )
        if context_choice_requested and not prior_context_is_comparison:
            fresh_plan = dict(semantic_preplan)
            fresh_plan["context_usage"] = "recommendation_context"
            fresh_plan["context_result_indexes"] = []
            fresh_plan["recommendation_followup_action"] = ""
            fresh_plan["context_reset_reason"] = (
                "fresh_recommendation_search_after_prior_recommendation"
            )
            phase1_plan["semantic_preplan"] = fresh_plan
            result = await _semantic_recommendation_contract_result(
                db,
                question,
                phase1_plan,
                _fresh_recommendation_context_for_semantic_search(
                    recommendation_context,
                ),
            )
            if result:
                return result, "semantic_first_recommendation_context_selection"
            semantic_preplan = fresh_plan
        elif context_choice_requested and prior_context_is_comparison:
            prior_question = str(
                (candidate_context or {}).get("user_question")
                or (recommendation_context or {}).get("user_question")
                or ""
            ).strip()
            if prior_question:
                phase1_plan["comparison_context_question"] = prior_question
            contracts = _apply_semantic_comparison_plan(
                question,
                phase1_plan,
                semantic_preplan,
                db.query(Product).order_by(Product.sku.asc()).all(),
                context_result_skus=context_result_skus,
            )
            if contracts:
                result = await _phase1_compare_choice_result(db, phase1_plan)
                if result:
                    return result, "semantic_first_context_choice"

        result = await _semantic_recommendation_contract_result(
            db,
            question,
            phase1_plan,
            _fresh_recommendation_context_for_semantic_search(
                recommendation_context,
            ),
        )
        return (
            result
            or await _semantic_owned_missing_result_with_llm(
                db,
                question,
                semantic_preplan,
                reason="recommendation_executor_no_result",
            ),
            "semantic_first_recommendation"
            if result
            else "semantic_first_recommendation_missing",
        )

    if route in {"structured_query", "generic_query"}:
        result = _semantic_structured_query_result(
            db,
            question,
            candidate_context=candidate_context,
            semantic_preplan=semantic_preplan,
        )
        return (
            result
            or await _semantic_owned_missing_result_with_llm(
                db,
                question,
                semantic_preplan,
                reason="structured_executor_no_result",
            ),
            "semantic_first_structured_query"
            if result
            else "semantic_first_structured_missing",
        )

    if route == "comparison":
        if (
            semantic_preplan.get("context_result_indexes")
            and str(semantic_preplan.get("context_usage") or "").strip()
            == "result_context"
        ):
            prior_question = str(
                (candidate_context or {}).get("user_question")
                or (recommendation_context or {}).get("user_question")
                or ""
            ).strip()
            if prior_question:
                phase1_plan["comparison_context_question"] = prior_question
        contracts = _apply_semantic_comparison_plan(
            question,
            phase1_plan,
            semantic_preplan,
            db.query(Product).order_by(Product.sku.asc()).all(),
            context_result_skus=context_result_skus,
        )
        if contracts:
            result = await _phase1_compare_choice_result(db, phase1_plan)
            if result:
                return result, "semantic_first_comparison"
        result = _semantic_comparison_fail_closed_result(semantic_preplan)
        return (
            result
            or await _semantic_owned_missing_result_with_llm(
                db,
                question,
                semantic_preplan,
                reason="comparison_not_sealed",
            ),
            "semantic_first_comparison_missing",
        )

    if route == "product_navigation":
        contextual_recommendation = bool(
            recommendation_context
            and str(semantic_preplan.get("context_usage") or "").strip()
            in {"entity_anchor", "recommendation_context"}
            and (
                recommendation_context.get("recommended_skus")
                or recommendation_context.get("previous_result_skus")
            )
        )
        if contextual_recommendation:
            result = await _semantic_recommendation_contract_result(
                db,
                question,
                phase1_plan,
                _fresh_recommendation_context_for_semantic_search(
                    recommendation_context,
                ),
            )
            if result:
                return result, "semantic_first_contextual_recommendation"
        result = _semantic_product_navigation_contract_result(
            db,
            question,
            semantic_preplan,
        )
        return (
            result
            or await _semantic_owned_missing_result_with_llm(
                db,
                question,
                semantic_preplan,
                reason="navigation_executor_no_result",
            ),
            "semantic_first_navigation"
            if result
            else "semantic_first_navigation_missing",
        )

    if route == "general_chat":
        # Category-level care/safety has no SKU to seal.  Give the knowledge
        # retriever the first chance to provide a document-backed answer, then
        # let the ordinary semantic writer handle the request if the corpus has
        # no usable document.  This keeps generic guidance out of the product
        # field executor without turning it into a phrase-specific route.
        if semantic_preplan.get("qa_or_usage_care"):
            knowledge_plan = dict(semantic_preplan)
            knowledge_plan["qa_evidence_query"] = str(
                knowledge_plan.get("qa_evidence_query") or question or ""
            ).strip()
            knowledge_result = await _semantic_knowledge_base_meta_result(
                db,
                question,
                knowledge_plan,
            )
            if knowledge_result:
                # A general-care document may establish only a boundary and
                # still omit the actual household steps.  Give Flash one
                # natural synthesis pass with that retrieved context so the
                # customer receives a cautious, usable answer instead of a
                # document-status dump.  This branch has no product identity,
                # so the writer may give general guidance but may not claim a
                # catalogue-specific coating or procedure.
                evidence_text = "\n\n".join(
                    str(item.get("content") or "").strip()
                    for item in (knowledge_result.get("evidence") or [])[:4]
                    if isinstance(item, dict) and str(item.get("content") or "").strip()
                )
                try:
                    guidance_raw = await customer_llm_service.chat_completion(
                        db,
                        messages=[
                            {
                                "role": "system",
                                "content": (
                                    "Return only JSON: {answer:string}. Answer this category-level cleaning or safety question in natural, concise Chinese. "
                                    "Use the retrieved context only where it directly bears on the customer's question; retrieved titles, sales guidance, unrelated scenarios, and wording-policy notes are not cleaning procedures. Do not pretend the excerpts contain a product-specific instruction when they do not. "
                                    "For combustion or fire safety, especially a stove in a tent, room, vehicle, or other enclosed space, state the prohibition clearly: do not use it there because ventilation does not remove the fire and carbon-monoxide risk. Never offer 'if you must use it indoors, ventilate and supervise' as an acceptable workaround; tell the customer to stop, extinguish if safe, leave for fresh air, and use an open safe environment instead. "
                                    "If the coating or material is unknown, give a conservative and executable first step: stop heating and let the cookware cool, avoid metal tools, hard scraping, abrasive pads, strong chemicals, or another high-heat attempt until the material is identified. For this burnt-pot question, answer in only two or three sentences and keep the procedure to cooling, warm-water softening, and a soft cloth or sponge; do not add a soak duration, detergent type, baking soda, boiling, cold-water thermal-shock claim, or other detailed procedure unless that exact procedure is directly stated in the retrieved context. "
                                    "Do not promise that the stain will come off or that the method will not damage the pot, and do not invent a product, SKU, coating, or official procedure. Use Chinese wording only. "
                                    "Do not answer with only '资料没有说明' when a safe general first step can still be given."
                                ),
                            },
                            {
                                "role": "user",
                                "content": json.dumps(
                                    {"question": question, "retrieved_context": evidence_text},
                                    ensure_ascii=False,
                                ),
                            },
                        ],
                        temperature=0.1,
                        max_tokens=260,
                        purpose="semantic_general_care_guidance_with_rag_context",
                        api_model_override=customer_agent_planner_service._semantic_preplan_runtime_settings()["model"],
                        thinking=customer_agent_planner_service._semantic_preplan_runtime_settings()["thinking"],
                    )
                    guidance_payload = customer_agent_planner_service._extract_json_object(
                        str(guidance_raw or "")
                    ) or {}
                    guidance_answer = str(guidance_payload.get("answer") or "").strip()
                except Exception:
                    guidance_answer = ""
                if guidance_answer:
                    knowledge_result["answer"] = guidance_answer
                    metadata = knowledge_result.get("answer_metadata")
                    metadata = dict(metadata) if isinstance(metadata, dict) else {}
                    metadata["source"] = "semantic_general_guidance_rag"
                    metadata["writer"] = "flash_general_guidance"
                    knowledge_result["answer_metadata"] = metadata
                    debug = knowledge_result.get("debug")
                    debug = dict(debug) if isinstance(debug, dict) else {}
                    debug["agent_mode"] = "semantic_general_guidance_rag"
                    debug["guidance_writer"] = "flash_general_guidance"
                    knowledge_result["debug"] = debug
                    return knowledge_result, "semantic_first_general_chat_rag"
                # If the guidance writer cannot produce a usable answer from
                # the retrieved packet, do not return its retrieval-status
                # prose. Fall through to the conservative general writer,
                # which can still give a reversible first step without
                # pretending the noisy documents contain a procedure.
        runtime = customer_agent_planner_service._semantic_preplan_runtime_settings()
        answer = ""
        try:
            answer = str(
                await customer_llm_service.chat_completion(
                    db,
                    [
                        {
                            "role": "system",
                            "content": (
                                "根据客户整句话自然回答，不要把对话改写成商品筛选。"
                                "没有明确商品身份时，不要编造 SKU、价格、库存、政策或商品事实。"
                                "如果是没有具体商品身份的清洁、使用或安全问题，请给出保守、可执行的通用处理建议；不确定材质时不要假定具体涂层或说明书。涉及燃烧型炉具在帐篷、室内、车内或其他密闭空间使用时，必须明确说不要使用，通风不能消除火灾和一氧化碳风险；不要把‘如果必须使用就通风并看管’写成可接受的替代方案，应建议停止、在安全前提下熄火并到新鲜空气处，改在开放且安全的环境使用。此类烧糊锅问题只写两到三句：先停热并完全冷却；再用温水软化后以软布或海绵轻擦；避开金属、硬刮、研磨垫、强酸强碱和再次高温。不要自行增加浸泡时长、洗剂种类、小苏打煮沸、冷水冲洗等其他具体步骤，也不要保证污渍一定能去掉。"
                                "如果问题确实需要更多信息，只追问一个最有帮助的问题。"
                                "输出中文客户答复，不要解释内部流程。"
                            ),
                        },
                        {"role": "user", "content": question},
                    ],
                    temperature=0.15,
                    max_tokens=260,
                    purpose="semantic_first_general_chat",
                    api_model_override=runtime["model"],
                    thinking=runtime["thinking"],
                )
                or ""
            ).strip()
        except Exception:
            answer = ""
        if answer:
            return {
                "answer": answer,
                "intent": "general_chat",
                "answer_type": "chat",
                "confidence": "high",
                "uncertainty": "resolved",
                "needs_clarification": False,
                "anomalies": [],
                "suggested_followups": [],
                "followups": [],
                "warnings": [],
                "evidence": [],
                "sources": [{"type": "semantic_chat", "label": "语义客服对话"}],
                "actions": [],
                "results": [],
                "result_skus": [],
                "candidate_skus": [],
                "answer_metadata": {
                    "source": "semantic_first_general_chat",
                    "evidence_status": "not_applicable",
                },
                "debug": {"agent_mode": "semantic_first_general_chat"},
                "skip_polish": True,
            }, "semantic_first_general_chat"
        return (
            await _semantic_owned_missing_result_with_llm(
                db,
                question,
                semantic_preplan,
                reason="general_chat_empty",
            ),
            "semantic_first_general_chat_missing",
        )

    if route == "product_bound_qa":
        qa_plan = dict(phase1_plan)
        care_preplan = _semantic_care_fields_to_product_qa_preplan(
            semantic_preplan,
        )
        subfield_preplan = (
            None
            if care_preplan is not None
            else _semantic_subfield_to_product_qa_preplan(semantic_preplan)
        )
        qa_rag_preplan = care_preplan or subfield_preplan
        if qa_rag_preplan is not None:
            qa_plan["semantic_preplan"] = qa_rag_preplan
            # Expose the actual execution contract to the outer trace as well:
            # the original planner may have called this a formal field, but
            # the answer was deliberately sent through same-SKU QA/RAG.
            phase1_plan["semantic_preplan"] = qa_rag_preplan
        formal_fields = [
            str(field or "").strip()
            for field in (
                list(semantic_preplan.get("canonical_fields") or [])
                + [semantic_preplan.get("field_type")]
            )
            if str(field or "").strip()
            in customer_field_contract.FORMAL_DETAIL_FIELDS
        ]
        if qa_rag_preplan is not None:
            # Usage/care fields and semantic sub-capabilities are not raw
            # catalogue display requests.  Let the same-SKU QA/RAG executor
            # select the relevant evidence and write only the answer to the
            # customer's current condition.
            formal_fields = []
        selected_context_skus = _semantic_context_result_skus(
            semantic_preplan,
            context_result_skus,
        )
        context_usage = str(semantic_preplan.get("context_usage") or "").strip()
        # An explicit SKU in the current utterance is a fresh identity
        # assertion.  It must outrank the previous conversation anchor even
        # when Flash also marks the turn as context-bound.  This is identity
        # precedence, not a question-specific route: the current SKU is
        # resolved against the catalogue and then handed to the same RAG
        # field executor as every other product-bound turn.
        explicit_current_skus = [
            resolved
            for token in customer_agent_service._extract_skus(question)
            if (resolved := _resolve_exact_sku_variant(db, token))
        ]
        explicit_current_skus = list(dict.fromkeys(explicit_current_skus))
        active_anchor_sku = str(
            (recommendation_context or {}).get("active_single_product_anchor") or ""
        ).strip().upper()
        if not active_anchor_sku and isinstance(candidate_context, dict):
            active_anchor_sku = str(
                candidate_context.get("final_choice_sku") or ""
            ).strip().upper()
        context_bound_sku = str(
            (explicit_current_skus[0] if len(explicit_current_skus) == 1 else "")
            or semantic_preplan.get("semantic_context_result_sku")
            or (selected_context_skus[0] if len(selected_context_skus) == 1 else "")
            or (
                active_anchor_sku
                if context_usage in {"entity_anchor", "active_product_anchor", "anchor"}
                else ""
            )
            or ""
        ).strip().upper()
        if formal_fields and context_bound_sku:
            field_request = resolve_requested_field_contract(
                question,
                qa_plan,
            )
            field_request = {
                **field_request,
                "field_type": formal_fields[0] if len(formal_fields) == 1 else "",
                "canonical_fields": formal_fields,
                "requested_fields": [
                    customer_field_contract.product_detail_field_label(field)
                    for field in formal_fields
                    if customer_field_contract.product_detail_field_label(field)
                ],
                "source": "validated_semantic_preplan",
            }
            requested_fields = list(field_request.get("requested_fields") or [])
            result = _product_field_followup_result(
                db,
                context_bound_sku,
                requested_fields[0] if requested_fields else formal_fields[0],
                question,
                identity_source="recommendation_context_result_index",
                field_request_override=field_request,
            )
            if result:
                return result, "semantic_first_context_product_field"
        if formal_fields:
            _apply_semantic_single_field_route_precedence(
                qa_plan,
                semantic_preplan,
            )
            result = _phase2_entity_state_arbitration_result(
                db,
                question,
                qa_plan,
                conversation_id=conversation_id,
            )
            if result:
                return result, "semantic_first_product_field"
        # Same-SKU RAG is the primary product-QA executor.  The former
        # ProductQa shortcut could return a stored answer before the current
        # question had been semantically aligned with the retrieved evidence,
        # which made natural safety/capability paraphrases look like a legacy
        # field route.  Keep the shortcut only as a compatibility fallback
        # when RAG cannot establish a product-bound result at all.
        result = await _try_sealed_same_sku_knowledge_answer(
            db,
            question,
            qa_plan,
        )
        if result:
            result_debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
            if str(result_debug.get("agent_mode") or "").strip() == "sealed_same_sku_knowledge_missing":
                # Identity and the failed same-SKU retrieval are already
                # sealed.  Give the semantic recovery writer one chance to
                # explain the missing capability naturally, rather than
                # exposing the legacy safe-missing sentence.  It cannot add a
                # product fact or change the resolved SKU; if it fails, keep
                # the original safe result unchanged.
                resolved_missing_sku = str(
                    result.get("sku")
                    or (result.get("answer_metadata") or {}).get("evidence_sku")
                    or ""
                ).strip().upper()
                natural_missing = await _semantic_owned_missing_result_with_llm(
                    db,
                    question,
                    semantic_preplan,
                    reason="product_qa_evidence_missing",
                    resolved_sku=resolved_missing_sku,
                    catalogue_context={
                        "direct_match_found": False,
                        "unmet_conditions": [
                            _semantic_missing_condition_label(
                                question,
                                semantic_preplan,
                                resolved_sku=resolved_missing_sku,
                            )
                        ],
                    },
                )
                if isinstance(natural_missing, dict) and str(natural_missing.get("answer") or "").strip():
                    merged_metadata = dict(result.get("answer_metadata") or {})
                    merged_metadata.update(natural_missing.get("answer_metadata") or {})
                    merged_metadata.update({
                        "source": "same_sku_knowledge_missing",
                        "evidence_source": "same_sku_knowledge",
                        "evidence_status": "missing",
                    })
                    merged_debug = dict(result_debug)
                    merged_debug.update(natural_missing.get("debug") or {})
                    merged_debug.update({
                        "agent_mode": "sealed_same_sku_knowledge_missing",
                        "recovery_writer": "flash_natural_recovery",
                        "knowledge_evidence_missing_reason": result_debug.get(
                            "knowledge_evidence_missing_reason"
                        ),
                    })
                    natural_missing.update({
                        "intent": "product_detail",
                        "answer_type": "product_detail",
                        "confidence": result.get("confidence", "medium"),
                        "uncertainty": "missing_data",
                        "needs_clarification": False,
                        "results": result.get("results") or natural_missing.get("results") or [],
                        "result_skus": result.get("result_skus") or natural_missing.get("result_skus") or [],
                        "candidate_skus": result.get("candidate_skus") or natural_missing.get("candidate_skus") or [],
                        "sku": result.get("sku") or natural_missing.get("sku"),
                        "evidence": result.get("evidence") or [],
                        "answer_metadata": merged_metadata,
                        "debug": merged_debug,
                        "skip_polish": True,
                    })
                    result = natural_missing
            return result, "semantic_first_product_qa_rag"
        result = await _try_product_qa_shortcut_with_semantic_selection(
            db,
            question,
            phase1_plan=qa_plan,
        )
        if result:
            return result, "semantic_first_product_qa_compatibility_fallback"
        return (
            await _semantic_owned_missing_result_with_llm(
                db,
                question,
                semantic_preplan,
                reason="product_qa_evidence_missing",
            ),
            "semantic_first_product_qa_missing",
        )

    if route in {
        "unknown_realtime",
        "contents_accessories",
        "clarification",
        "unresolved_product_like",
        "negative_product_like",
    }:
        return (
            await _semantic_owned_missing_result_with_llm(
                db,
                question,
                semantic_preplan,
                reason=f"semantic_route_{route}",
            ),
            "semantic_first_clarification_missing",
        )

    return (
        await _semantic_owned_missing_result_with_llm(
            db,
            question,
            semantic_preplan,
            reason="semantic_route_unresolved",
        ),
        "semantic_first_unresolved",
    )


async def ask_customer_service(
    db: Session,
    *,
    user_id: str,
    question: str,
    sku: str | None = None,
    conversation_id: str | None = None,
    answer_delta_callback: Callable[[str], Awaitable[None]] | None = None,
) -> dict:
    user_id = str(user_id)
    question = question.strip()
    if not question:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail="问题不能为空")
    original_question = question
    question, inline_page_subject = _extract_inline_page_context(question)
    page_context_sku = _resolve_exact_sku_variant(db, sku) or _resolve_exact_page_subject_sku(
        db,
        inline_page_subject,
    )
    explicit_question_sku = _resolve_explicit_question_sku(db, question)
    request_sku_anchor = page_context_sku or explicit_question_sku
    if not customer_perf_service.get_trace_id():
        customer_perf_service.start_trace()
    request_start = perf_counter()
    planner_start = perf_counter()
    # Ordinary read turns do not go through the historical keyword planner.
    # This object is only a request envelope for page scope, timing and the
    # later semantic plan; Flash owns interpretation of the complete question.
    phase1_plan = {
        "raw_question": question,
        "original_question": original_question,
        "inline_page_subject": inline_page_subject or "",
        "primary_intent": "",
        "answer_type": "",
        "semantic_owner": "flash",
    }
    # Semantic preplanning is intentionally deferred until the identity and
    # page-scope guards have run.  Early page-bound adapters may still need to
    # persist a result before that deferred call, so keep an explicit empty
    # value in scope rather than reading an unassigned local.
    semantic_preplan: dict | None = None
    if request_sku_anchor and isinstance(phase1_plan, dict):
        # This is product-page identity only. The planner and semantic layer
        # still own the meaning of the customer's wording.
        phase1_plan["request_sku_anchor"] = request_sku_anchor
    planner_duration_ms = round((perf_counter() - planner_start) * 1000, 2)
    if page_context_sku and explicit_question_sku != page_context_sku:
        page_product = db.query(Product).filter(Product.sku == request_sku_anchor).first()
        page_product_name = str(
            getattr(page_product, "product_name_cn", "")
            or getattr(page_product, "product_name_en", "")
            or request_sku_anchor
        ).strip()
        explicit_page_subject = _explicit_page_subject_from_question(question)
        if _explicit_page_subject_conflicts_with_anchor(
            question,
            page_product_name=page_product_name,
        ):
            conflict_result = _build_bounded_clarification_result(
                answer=(
                    f"你当前问题提到的是“{explicit_page_subject}”，而当前页面商品是“{page_product_name}（{request_sku_anchor}）”。"
                    "两者身份未确认一致，不能把页面资料直接套用；请提供前者的 SKU 或完整商品名，我再按对应商品核对。"
                ),
                source="page_context_explicit_subject_conflict",
            )
            conflict_result["sku"] = request_sku_anchor
            conflict_result = _attach_phase1_plan_and_timing(
                conflict_result,
                phase1_plan,
                _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
            )
            conflict_debug = conflict_result.get("debug") if isinstance(conflict_result.get("debug"), dict) else {}
            conflict_debug.update({
                "agent_mode": "page_context_explicit_subject_conflict",
                "request_sku_anchor": request_sku_anchor,
                "explicit_subject": explicit_page_subject,
            })
            conflict_result["debug"] = conflict_debug
            return await _save_agent_result_and_return(
                db,
                user_id=user_id,
                question=question,
                conversation_id=conversation_id,
                agent_result=conflict_result,
                request_start=request_start,
                branch="page_context_explicit_subject_conflict",
                semantic_preplan=None,
            )
    # Product identity and write permissions are the only hard boundaries that
    # precede semantic interpretation. Once they are settled, Flash owns the
    # meaning of the complete read turn and the central executor retrieves
    # structured/same-SKU evidence. The historical route tree below is
    # unreachable and is not an outage fallback.
    explicit_mutation_result = await _try_explicit_customer_mutation_result(
        db,
        user_id=user_id,
        question=question,
        sku=sku,
        conversation_id=conversation_id,
    )
    if explicit_mutation_result:
        explicit_mutation_result = _attach_phase1_plan_and_timing(
            explicit_mutation_result,
            phase1_plan,
            _phase1_timing(
                request_start=request_start,
                planner_duration_ms=planner_duration_ms,
            ),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=explicit_mutation_result,
            request_start=request_start,
            branch="explicit_mutation_action_proposal",
            semantic_preplan=None,
        )

    mutation_boundary_result = _customer_mutation_boundary_result(question)
    if mutation_boundary_result:
        mutation_boundary_result = _attach_phase1_plan_and_timing(
            mutation_boundary_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=mutation_boundary_result,
            request_start=request_start,
            branch="customer_mutation_boundary",
            semantic_preplan=None,
        )

    semantic_preplan = await _maybe_run_semantic_preplan(
        db,
        question,
        phase1_plan,
        conversation_id=conversation_id,
        request_sku_anchor=request_sku_anchor,
    )
    if request_sku_anchor and isinstance(semantic_preplan, dict):
        semantic_preplan["request_sku_anchor"] = request_sku_anchor

    high_risk_contract_result = _pre_route_high_risk_contract_result(
        db,
        question,
        semantic_preplan,
    )
    if high_risk_contract_result:
        high_risk_contract_result = _attach_formal_field_contract(
            high_risk_contract_result,
            question,
            phase1_plan,
        )
        high_risk_contract_result = _attach_phase1_plan_and_timing(
            high_risk_contract_result,
            phase1_plan,
            _phase1_timing(
                request_start=request_start,
                planner_duration_ms=planner_duration_ms,
            ),
        )
        high_risk_contract_result = _attach_semantic_preplan_debug(
            high_risk_contract_result,
            semantic_preplan,
            final_route=str(
                high_risk_contract_result.get("answer_type")
                or high_risk_contract_result.get("intent")
                or ""
            ),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=high_risk_contract_result,
            request_start=request_start,
            branch="pre_route_high_risk_contract",
            semantic_preplan=semantic_preplan,
        )

    # Flash owns the meaning of an ordinary read turn.  Do this outage check
    # before any catalogue shortcut, legacy intent handler, or fixed scenario
    # composer can reinterpret the same sentence after semantic planning has
    # failed.  A healthy semantic plan continues below; a provider outage gets
    # the bounded outage response (or a deterministic identity/safety
    # contract) and never silently becomes a rule-based recommendation.
    semantic_preplan_unavailable_result = _semantic_preplan_unavailable_clarification_result(
        semantic_preplan,
        db=db,
        question=question,
        phase1_plan=phase1_plan,
        request_sku_anchor=request_sku_anchor,
    )
    if semantic_preplan_unavailable_result:
        semantic_preplan_unavailable_result = _attach_phase1_plan_and_timing(
            semantic_preplan_unavailable_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=semantic_preplan_unavailable_result,
            request_start=request_start,
            branch="semantic_preplan_unavailable_clarification",
            semantic_preplan=semantic_preplan,
        )

    semantic_first_result = None
    semantic_first_branch = None
    if isinstance(semantic_preplan, dict) and semantic_preplan.get("called"):
        semantic_first_result, semantic_first_branch = await _semantic_first_turn_result(
            db,
            question=question,
            phase1_plan=phase1_plan,
            semantic_preplan=semantic_preplan,
            conversation_id=conversation_id,
            user_id=user_id,
        )
    if semantic_first_result:
        effective_semantic_preplan = phase1_plan.get("semantic_preplan") if isinstance(phase1_plan, dict) else None
        if isinstance(effective_semantic_preplan, dict) and effective_semantic_preplan.get("called"):
            semantic_preplan = effective_semantic_preplan
        semantic_first_result = _mark_semantic_executor_result(
            semantic_first_result,
            branch=semantic_first_branch or "semantic_first_turn",
            semantic_preplan=semantic_preplan,
        )
        semantic_first_result = _attach_phase1_plan_and_timing(
            semantic_first_result,
            phase1_plan,
            _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
        )
        semantic_first_result = _attach_semantic_preplan_debug(
            semantic_first_result,
            semantic_preplan,
            final_route=str(
                semantic_first_result.get("answer_type")
                or semantic_first_result.get("intent")
                or "clarification"
            ),
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=semantic_first_result,
            request_start=request_start,
            branch=semantic_first_branch or "semantic_first_turn",
            semantic_preplan=semantic_preplan,
        )
    if isinstance(semantic_preplan, dict) and semantic_preplan.get("called"):
        # A successful semantic envelope owns the turn even when an executor
        # unexpectedly returns no result. Do not give the legacy catalogue,
        # FAQ, or lexical context branches a second interpretation vote; keep
        # the unresolved turn in the natural semantic recovery writer.
        semantic_executor_missing_result = await _semantic_owned_missing_result_with_llm(
            db,
            question,
            semantic_preplan,
            reason="semantic_executor_returned_no_result",
        )
        semantic_executor_missing_result = _mark_semantic_executor_result(
            semantic_executor_missing_result,
            branch="semantic_executor_missing_recovery",
            semantic_preplan=semantic_preplan,
        )
        semantic_executor_missing_result = _attach_phase1_plan_and_timing(
            semantic_executor_missing_result,
            phase1_plan,
            _phase1_timing(
                request_start=request_start,
                planner_duration_ms=planner_duration_ms,
            ),
        )
        semantic_executor_missing_result = _attach_semantic_preplan_debug(
            semantic_executor_missing_result,
            semantic_preplan,
            final_route="clarification",
        )
        return await _save_agent_result_and_return(
            db,
            user_id=user_id,
            question=question,
            conversation_id=conversation_id,
            agent_result=semantic_executor_missing_result,
            request_start=request_start,
            branch="semantic_executor_missing_recovery",
            semantic_preplan=semantic_preplan,
        )

    # No ordinary read turn is allowed to reach the historical route tree
    # below this point.  A missing semantic envelope is already handled above;
    # this last boundary covers an unexpected executor/adapter state and keeps
    # the whole utterance owned by semantic recovery instead of giving legacy
    # keyword branches a second interpretation vote.
    semantic_terminal_recovery = await _semantic_owned_missing_result_with_llm(
        db,
        question,
        semantic_preplan if isinstance(semantic_preplan, dict) else {},
        reason="semantic_ownership_unresolved",
    )
    semantic_terminal_recovery = _mark_semantic_executor_result(
        semantic_terminal_recovery,
        branch="semantic_terminal_recovery",
        semantic_preplan=semantic_preplan if isinstance(semantic_preplan, dict) else {},
    )
    semantic_terminal_recovery = _attach_phase1_plan_and_timing(
        semantic_terminal_recovery,
        phase1_plan,
        _phase1_timing(request_start=request_start, planner_duration_ms=planner_duration_ms),
    )
    semantic_terminal_recovery = _attach_semantic_preplan_debug(
        semantic_terminal_recovery,
        semantic_preplan,
        final_route="clarification",
    )
    return await _save_agent_result_and_return(
        db,
        user_id=user_id,
        question=question,
        conversation_id=conversation_id,
        agent_result=semantic_terminal_recovery,
        request_start=request_start,
        branch="semantic_terminal_recovery",
        semantic_preplan=semantic_preplan,
    )
def _finalize_answer(agent_result: dict) -> dict:
    result = _normalize_agent_result(agent_result)
    primary = _pick_primary_answer_source(result)
    sources = _tag_and_order_sources(result.get("sources") or [], primary)
    result["sources"] = sources
    result["answer"] = _sanitize_final_answer_text(str(result.get("answer") or ""), primary)
    answer_metadata = result.get("answer_metadata") if isinstance(result.get("answer_metadata"), dict) else {}
    answer_metadata["final_decision"] = {
        "primary_source": primary.get("type"),
        "priority": primary.get("priority"),
        "single_source_of_truth": True,
        "llm_allowed": _llm_allowed_for_final_answer(result, primary),
    }
    result["answer_metadata"] = answer_metadata
    debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
    debug["final_answer"] = answer_metadata["final_decision"]
    result["debug"] = debug
    if not answer_metadata["final_decision"]["llm_allowed"]:
        result["skip_polish"] = True
    return result




def review_samples(db: Session, user_id: str, limit: int = 100) -> dict:
    user_id = str(user_id)
    messages = (
        db.query(CustomerServiceMessage, CustomerServiceConversation)
        .join(CustomerServiceConversation, CustomerServiceConversation.id == CustomerServiceMessage.conversation_id)
        .filter(
            CustomerServiceConversation.user_id == user_id,
            CustomerServiceMessage.role == "assistant",
        )
        .order_by(CustomerServiceMessage.created_at.desc())
        .limit(limit)
        .all()
    )
    items = []
    frequent_questions: dict[str, int] = {}
    clarification_samples = 0
    anomaly_samples = 0
    for assistant_message, conversation in messages:
        meta = _message_meta(assistant_message.sources_json)
        user_message = (
            db.query(CustomerServiceMessage)
            .filter(
                CustomerServiceMessage.conversation_id == conversation.id,
                CustomerServiceMessage.role == "user",
                CustomerServiceMessage.created_at <= assistant_message.created_at,
            )
            .order_by(CustomerServiceMessage.created_at.desc())
            .first()
        )
        question = (user_message.content if user_message else "").strip()
        if question:
            frequent_questions[question] = frequent_questions.get(question, 0) + 1
        if meta.get("needs_clarification"):
            clarification_samples += 1
        if meta.get("anomalies"):
            anomaly_samples += 1
        items.append({
            "conversation_id": conversation.id,
            "message_id": assistant_message.id,
            "question": question,
            "answer": assistant_message.content,
            "intent": meta.get("intent"),
            "confidence": meta.get("confidence"),
            "agent_quality": meta.get("agent_quality", {}),
            "needs_clarification": meta.get("needs_clarification", False),
            "anomalies": meta.get("anomalies", []),
            "warnings": meta.get("warnings", []),
            "suggested_followups": meta.get("suggested_followups", []),
            "created_at": str(assistant_message.created_at),
        })

    top_questions = sorted(frequent_questions.items(), key=lambda item: item[1], reverse=True)[:20]
    quality_summary = _review_quality_summary(items)
    return {
        "items": items,
        "summary": {
            "total_samples": len(items),
            "clarification_samples": clarification_samples,
            "anomaly_samples": anomaly_samples,
            "quality": quality_summary,
            "top_questions": [{"question": question, "count": count} for question, count in top_questions],
        },
    }


def _resolve_sku(db: Session, question: str, sku: str | None) -> str | None:
    if sku:
        resolved = _resolve_exact_sku_variant(db, sku)
        return resolved or sku.strip()
    return _resolve_explicit_question_sku(db, question)


def _resolve_explicit_question_sku(db: Session, question: str) -> str | None:
    """Resolve an explicitly written SKU without deciding the question route."""
    candidates = customer_agent_service._extract_skus(question)
    for candidate in candidates:
        resolved = _resolve_exact_sku_variant(db, candidate)
        if resolved:
            return resolved
    return None


def _sku_lookup_variants(value: str | None) -> list[str]:
    raw = str(value or "").strip()
    if not raw:
        return []
    variants: list[str] = []
    compact_raw = raw.upper().replace("_", "-")
    parenthetical_variants: list[str] = []
    paren_match = re.match(r"^(?P<prefix>[A-Z0-9]+(?:-[A-Z0-9]+)+)[-](?P<suffix>[A-Z0-9]{2,8})$", compact_raw)
    if paren_match:
        parenthetical_variants.extend(
            [
                f"{paren_match.group('prefix')}({paren_match.group('suffix')})",
                f"{paren_match.group('prefix')}（{paren_match.group('suffix')}）",
            ]
        )
    suffix_match = re.match(r"^(?P<prefix>[A-Z0-9]+(?:-[A-Z0-9]+)+)[(（](?P<suffix>[A-Z0-9]{2,8})[)）]$", compact_raw)
    if suffix_match:
        parenthetical_variants.append(f"{suffix_match.group('prefix')}-{suffix_match.group('suffix')}")
    candidates = [
        raw,
        compact_raw,
        raw.replace("(", "（").replace(")", "）"),
        raw.replace("（", "(").replace("）", ")"),
        customer_agent_service.normalize_search_text(raw).upper().replace("_", "-"),
        *parenthetical_variants,
    ]
    for candidate in candidates:
        normalized = str(candidate or "").strip()
        if normalized and normalized not in variants:
            variants.append(normalized)
    return variants


def _resolve_exact_sku_variant(db: Session, sku: str | None) -> str | None:
    variants = _sku_lookup_variants(sku)
    if not variants:
        return None
    for candidate in variants:
        product = db.query(Product).filter(Product.sku == candidate).first()
        if product:
            return product.sku
    normalized_targets = {
        customer_agent_service.normalize_search_text(candidate).upper().replace("_", "-")
        for candidate in variants
    }
    for product in db.query(Product).all():
        product_sku = str(getattr(product, "sku", "") or "").strip()
        if not product_sku:
            continue
        normalized_product = customer_agent_service.normalize_search_text(product_sku).upper().replace("_", "-")
        if normalized_product in normalized_targets:
            return product_sku
    for candidate in variants:
        product = db.query(Product).filter(Product.sku.ilike(candidate)).first()
        if product:
            return product.sku
    return None










def _pending_clarification_context_for_result(agent_result: dict, user_question: str | None = None) -> dict | None:
    if agent_result.get("answer_type") != "clarification" or not agent_result.get("needs_clarification"):
        return None
    text = str(user_question or "").strip()
    if not text:
        return None
    normalized = customer_agent_service.normalize_search_text(text)
    product_scope = customer_dialogue_state.product_scope_from_text(text)
    price_terms = ("多少钱", "价格", "售价", "什么价", "几块", "几元")
    if any(term in text for term in price_terms):
        return {
            "intent": "product_detail",
            "requested_field": "price",
            "product_scope": product_scope,
            "original_question": text,
        }
    if "酒精炉" in text and any(term in text for term in ("能不能", "能否", "是否", "可不可以", "支持", "适用")):
        return {
            "intent": "product_detail",
            "requested_field": "heat_source",
            "capability_question": "能不能用酒精炉",
            "product_scope": product_scope,
            "original_question": text,
        }
    if normalized in {"这个锅", "那个锅", "这个水壶", "那个水壶"}:
        return {
            "intent": "product_detail",
            "requested_field": "",
            "product_scope": product_scope,
            "original_question": text,
        }
    return {
        "intent": "product_context_required",
        "requested_field": "",
        "product_scope": product_scope,
        "original_question": text,
    }




def _bound_gifting_qa_answer_to_evidence(
    question: str,
    answer: str,
    *,
    trusted_recorded_qa: bool = False,
) -> str:
    # An approved ProductQa answer is already a same-SKU customer-facing
    # record.  Do not reinterpret its wording as an unsupported model claim;
    # the boundary below is for generated answers assembled from ordinary
    # product/profile evidence.
    if trusted_recorded_qa:
        return str(answer or "").strip()
    value = str(answer or "").strip()
    question_text = str(question or "")
    unsupported_markers = (
        "包装精美",
        "品质出众",
        "绝佳礼物",
        "非常适合",
        "送给户外露营爱好者",
    )
    if not any(marker in value for marker in unsupported_markers):
        return value
    question_requests_marketing_judgement = any(
        term in question_text
        for term in ("送人", "送礼", "礼物", "赠送", "品质", "质量", "做工", "包装")
    )
    answer_makes_gifting_claim = any(term in value for term in ("礼物", "送给"))
    if not question_requests_marketing_judgement and not answer_makes_gifting_claim:
        return value
    requested_dimensions: list[str] = []
    if any(term in question_text for term in ("品质", "质量", "做工")):
        requested_dimensions.append("品质")
    if "包装" in question_text:
        requested_dimensions.append("包装")
    if any(term in question_text for term in ("送人", "送礼", "礼物", "赠送")):
        requested_dimensions.append("礼赠适配")
    if not requested_dimensions:
        if "品质出众" in value:
            requested_dimensions.append("品质")
        if "包装精美" in value:
            requested_dimensions.append("包装")
        if answer_makes_gifting_claim:
            requested_dimensions.append("礼赠适配")
    dimension_text = "、".join(dict.fromkeys(requested_dimensions)) or "品质、包装或礼赠适配"
    return f"当前同 SKU 资料不足以直接支持上述{dimension_text}判断，暂时无法确认。"


async def _rewrite_suitability_boundary_from_same_sku_evidence(
    db: Session,
    *,
    question: str,
    draft: str,
    evidence: str,
    evidence_quotes: list[str] | None = None,
    recorded_qa_selected: bool = False,
) -> tuple[str, list[str]] | None:
    """Turn relevant same-SKU facts into a useful bounded decision answer.

    Stored QA can contain a strong marketing conclusion while the surrounding
    profile only supports the underlying traits.  Keep the RAG path useful by
    asking Flash to separate those two layers: explain the recorded traits and
    leave only the unsupported final suitability judgement open.  The result
    is still checked by the normal quote and entailment audits by the caller.
    """
    runtime = customer_agent_planner_service._semantic_preplan_runtime_settings()
    payload = {
        "question": str(question or ""),
        "draft": str(draft or ""),
        "evidence": str(evidence or ""),
        "draft_quotes": list(evidence_quotes or []),
    }
    try:
        raw = await customer_llm_service.chat_completion(
            db,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Return only JSON: {answer:string,evidence_quotes:string[]}. Rewrite the draft into a natural, helpful Chinese answer for the customer's exact question. "
                        "Use only the supplied same-SKU evidence. Separate concrete recorded traits from the final suitability judgement: you may describe traits such as design, durability, non-slip, easy cleaning, stated scenes, target audience, or packaging only when the evidence says them; "
                        "if the evidence does not directly establish whether this is a good gift or suitable for the requested recipient, say that plainly after giving the useful recorded factors. "
                        + (
                             "A selected Q/A record is customer-facing evidence: when its question and answer directly address the customer's question, report the recorded answer naturally, but keep subjective marketing language attributed to the record instead of presenting it as an independently verified fact. For any subjective suitability, quality, or gifting conclusion, the answer must explicitly say that the product Q/A, product资料, or记录 describes it that way; a direct sentence such as '很适合作为礼物' without that attribution is invalid even when the stored answer contains those words. Then distinguish concrete recorded traits from that description. Paraphrase persuasive wording into neutral Chinese: do not repeat or amplify promotional intensifiers, superlatives, or praise adjectives from the record as the assistant's own wording. When the selected Q/A question directly matches the customer's question, answer only that recorded conclusion and its concrete supporting traits in exactly one or two sentences; do not add a caveat about other recipient types, hypothetical conditions, or what the customer might decide unless the customer asked for those distinctions. "
                            if recorded_qa_selected else
                            "Do not repeat unsupported marketing conclusions such as '绝佳礼物', '非常适合', '品质出众', or '包装精美' unless the customer-facing evidence independently supports that exact conclusion. "
                        )
                        + "Do not say the product is unsuitable merely because the recipient is not listed. "
                        "Do not use boilerplate such as '当前同 SKU 资料不足' as the whole answer, and do not mention routing, gates, models, candidates, or internal review. "
                        "Include one to three exact uninterrupted evidence_quotes copied from evidence, each at most 60 characters. Do not invent facts."
                    ),
                },
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
            temperature=0,
            max_tokens=min(int(runtime["max_tokens"]), 320),
            purpose="sealed_same_sku_suitability_boundary_rewrite",
            api_model_override=runtime["model"],
            response_format=runtime["response_format"],
            thinking=runtime["thinking"],
        )
    except Exception:
        return None
    parsed = customer_agent_planner_service._extract_json_object(str(raw or "")) or {}
    answer = str(parsed.get("answer") or "").strip()
    quotes = [str(item or "").strip() for item in (parsed.get("evidence_quotes") or []) if str(item or "").strip()]
    valid_quotes = _same_sku_rag_validated_quotes({"evidence_quotes": quotes}, evidence)
    if not answer or not valid_quotes:
        return None
    return answer, valid_quotes


def _suitability_boundary_fallback_answer(
    question: str,
    evidence_quotes: list[str],
) -> str:
    """Give a turn-specific fallback when the evidence writer is unavailable."""
    question_text = str(question or "")
    quotes = [str(item or "").strip() for item in evidence_quotes if str(item or "").strip()]
    unsupported_markers = (
        "包装精美",
        "品质出众",
        "绝佳礼物",
        "非常适合",
        "送给户外露营爱好者",
    )
    usable_quotes = [
        quote for quote in quotes
        if not any(marker in quote for marker in unsupported_markers)
    ][:3]
    if usable_quotes:
        if any(term in question_text for term in ("送人", "送礼", "礼物", "赠送")):
            return (
                f"这款资料里能先核对到的是：{'；'.join(usable_quotes)}。"
                "这些信息可以作为送礼时的参考，但记录没有直接给出‘是否适合作为礼物’的结论，我不替你把相关特点直接等同于适合送人。"
            )
        return (
            f"这款资料里能先核对到的是：{'；'.join(usable_quotes)}。"
            "它们能帮助你判断，但记录没有直接给出你问的最终适配结论。"
        )
    if any(term in question_text for term in ("送人", "送礼", "礼物", "赠送")):
        return "这条资料目前更像宣传描述，缺少能独立核对礼赠适配的具体依据；我不把宣传语直接当成是否适合送人的结论。"
    return "这条资料目前缺少能独立核对你所问判断的具体依据，我不把相近描述直接当成结论。"


def _sealed_product_qa_safe_missing_result(
    product: Product,
    answer: str,
    *,
    field_contract: dict[str, Any],
    debug: dict[str, Any] | None = None,
) -> dict[str, Any]:
    sku = str(product.sku or "").strip().upper()
    result_debug = {
        "agent_mode": "sealed_product_qa_safe_missing",
        "field_contract": dict(field_contract),
    }
    if isinstance(debug, dict):
        result_debug.update(debug)
    return {
        "answer": str(answer or "").strip(),
        "intent": "product_detail",
        "answer_type": "product_detail",
        "confidence": "medium",
        "uncertainty": "missing_data",
        "needs_clarification": False,
        "results": [{
            "sku": sku,
            "product_name_cn": product.product_name_cn,
            "product_name_en": product.product_name_en,
            "category": product.category,
        }],
        "result_skus": [sku],
        "candidate_skus": [sku],
        "sku": sku,
        "evidence": [],
        "sources": [],
        "answer_metadata": {
            "contract_field_type": "product_qa",
            "requested_field": "产品问答",
            "evidence_status": "missing",
            "field_evidence_missing": True,
            "evidence_sku": sku,
            "evidence_skus": [],
            "answer_policy": "insufficient_evidence",
        },
        "debug": result_debug,
        "skip_polish": True,
    }


def _try_product_qa_shortcut(
    db: Session,
    question: str,
    *,
    phase1_plan: dict[str, Any] | None = None,
    selected_qa: ProductQa | None = None,
) -> dict | None:
    # Exact stored QA is a database fact, not a lexical shortcut.  It still
    # must pass entity arbitration and same-SKU evidence below, but it must
    # not be discarded merely because its natural wording resembles an
    # unknown detail or a contents question.
    exact_qa_records = (
        db.query(ProductQa)
        .filter(
            ProductQa.question == str(question or "").strip(),
            ProductQa.integrity_status == "approved",
        )
        .all()
    )
    exact_qa_product_ids = {record.product_id for record in exact_qa_records if record.product_id}
    exact_qa_record = exact_qa_records[0] if len(exact_qa_product_ids) == 1 else None
    exact_qa_product = (
        db.query(Product).filter(Product.id == exact_qa_record.product_id).first()
        if exact_qa_record else None
    )
    has_exact_stored_qa = bool(exact_qa_product)
    named_products = _products_named_in_question(db, question)
    if exact_qa_product:
        # A unique database QA identity is stronger than fuzzy alias expansion.
        named_products = [exact_qa_product]
    if len(named_products) >= 2:
        return None
    if customer_agent_intent_service._is_compare_question(question):
        return None
    if any(term in str(question or "") for term in ("哪个", "哪款")):
        normalized_question = customer_agent_service.normalize_search_text(question)
        explicit_canonical_skus = {
            str(product.sku or "").strip().upper()
            for product in db.query(Product).all()
            if str(product.sku or "").strip()
            and any(
                normalized_name and normalized_name in normalized_question
                for normalized_name in (
                    customer_agent_service.normalize_search_text(product.product_name_cn or ""),
                    customer_agent_service.normalize_search_text(product.product_name_en or ""),
                )
            )
        }
        if len(explicit_canonical_skus) >= 2:
            return None
    if customer_agent_intent_service._looks_like_multi_product_relation_question(question):
        return None
    if (
        customer_agent_intent_service._looks_like_usage_care_question(question)
        and not _semantic_prefers_sealed_product_qa(phase1_plan or {})
        and not has_exact_stored_qa
    ):
        return None
    if customer_agent_intent_service._looks_like_contents_grounding_question(question) and not has_exact_stored_qa:
        return None
    if (
        _is_generic_named_product_question(question)
        and any(term in str(question or "") for term in ("再看", "改看", "看看", "看一下"))
        and not customer_field_contract.detect_field_contract(question)
    ):
        return None
    # A selected QA record may come from the semantic supplemental-intent
    # contract after a separate realtime/commercial field has already been
    # safely handled. Its same-SKU identity and evidence were sealed before
    # this formatter, so the broad unknown-field guard must not erase that
    # independent supported answer.
    if _detect_resolved_entity_unknown_fact_label(question) and not has_exact_stored_qa and selected_qa is None:
        return None
    product = _explicit_product_from_question(db, question)
    if not product:
        return None
    fallback_field_contract = customer_field_contract.detect_field_contract(question)
    subject_selection = customer_field_contract.select_entity_subject_for_routing(
        raw_question=question,
        fallback_product_like_subject=_product_like_scope_subject(question),
        fallback_named_subject=customer_agent_intent_service._detail_subject_from_question(question).strip() or question,
    )
    entity_subject = subject_selection.entity_subject
    # An exact stored QA identifies its product record before natural-language
    # subject extraction. Use that product's canonical name as the resolver
    # subject whenever it is literally present, so trailing predicates such
    # as “正常能用多久” cannot turn a colour/variant name into ambiguity.
    if product:
        normalized_question = customer_agent_service.normalize_search_text(question)
        canonical_names = [
            str(product.product_name_cn or "").strip(),
            str(product.product_name_en or "").strip(),
        ]
        canonical_subject = next(
            (
                name
                for name in canonical_names
                if name and customer_agent_service.normalize_search_text(name) in normalized_question
            ),
            "",
        )
        if canonical_subject:
            entity_subject = canonical_subject
    # A high-confidence semantic QA decision with no formal field is sealed
    # before this shortcut reaches deterministic entity/evidence validation.
    # Do not derive a different field again from text inside the product name.
    sealed_product_qa = _semantic_prefers_sealed_product_qa(phase1_plan or {})
    semantic_field_request = (
        {}
        if sealed_product_qa
        else customer_field_contract.resolve_requested_field_contract(
            question,
            phase1_plan,
            subject=entity_subject,
            subject_is_catalog_exact=bool(entity_subject),
        )
    )
    semantic_preplan = phase1_plan.get("semantic_preplan") if isinstance(phase1_plan, dict) else {}
    semantic_field_type = str((semantic_preplan or {}).get("field_type") or "").strip()
    semantic_field_allowed = bool(
        _semantic_preplan_confident(semantic_preplan, minimum=0.9)
        and str((semantic_preplan or {}).get("route_family") or "").strip() == "product_bound_qa"
        and str((semantic_preplan or {}).get("route_hint") or "").strip() == "product_detail"
        and semantic_field_type in customer_field_contract.FORMAL_DETAIL_FIELDS
    )
    field_type = None if sealed_product_qa else semantic_field_type if semantic_field_allowed else str(semantic_field_request.get("field_type") or "").strip() or (
        fallback_field_contract.field_type if fallback_field_contract else None
    )
    all_products = db.query(Product).order_by(Product.sku.asc()).all()
    entity_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
        question,
        all_products,
        resolver_candidates=named_products or [product],
        entity_text_override=entity_subject or None,
        field_type_override=field_type,
    )
    identity_decision = customer_entity_resolution_contract.can_resolve_single_product(
        entity_contract,
        all_products,
    )
    product_sku = str(product.sku or "").strip().upper()
    if not identity_decision.allowed or identity_decision.resolved_sku != product_sku:
        if field_type:
            displayable_candidate_skus = _displayable_phase2_clarification_candidate_skus(entity_contract)
            if displayable_candidate_skus:
                return _build_phase2_entity_state_response(
                    db,
                    question,
                    {
                        "action": "ambiguous_clarification",
                        "contract": entity_contract,
                        "products": all_products,
                        "displayable_candidate_skus": displayable_candidate_skus,
                    },
                )
            if entity_contract.status in {"ambiguous", "unresolved"}:
                return _build_phase2_entity_state_response(
                    db,
                    question,
                    {"action": "unresolved_clarification", "contract": entity_contract},
                )
        return None
    if selected_qa is not None and str(selected_qa.product_id or "") != str(product.id):
        # A semantic selector receives only same-SKU candidates, but keep the
        # identity boundary local to the evidence formatter as well.
        return None
    if field_type:
        qa = selected_qa or _best_product_qa_match(
            db,
            product,
            question,
            requested_field_type=field_type,
        )
        if not qa:
            return None
    elif not sealed_product_qa and _looks_like_product_detail_field_question(question):
        return None
    else:
        semantic_qa_query = (
            str((semantic_preplan or {}).get("qa_evidence_query") or "").strip()
            if sealed_product_qa and isinstance(semantic_preplan, dict)
            else ""
        )
        qa = selected_qa or _best_product_qa_match(
            db,
            product,
            question,
            semantic_query=semantic_qa_query or None,
        )
    if not qa:
        return None
    exact_qa_match = _is_exact_product_qa_question_match(qa, question)
    if not exact_qa_match and selected_qa is None:
        # Lexical overlap is retrieval evidence, not authorization to publish
        # an old answer. A non-identical question must pass the semantic
        # full-coverage selection contract below.
        return None
    # An exact QA can prove a product fact that is outside the formal field
    # ontology.  A semantic field label is not allowed to relabel that fact
    # when its own evidence policy rejects the matched QA record (for example
    # durability is not lifecycle status).  Keep formal-field QA untouched.
    if (
        field_type
        and exact_qa_match
        and not customer_field_contract.qa_evidence_matches_field(
            str(qa.question or ""),
            str(getattr(qa, "tags", "") or ""),
            field_type,
        )
    ):
        field_type = None
        entity_contract = customer_entity_resolution_contract.build_entity_resolution_contract(
            question,
            all_products,
            resolver_candidates=named_products or [product],
            entity_text_override=entity_subject or None,
            field_type_override=None,
        )
    if (
        _has_direct_structured_detail_answer(db, product, question)
        and not exact_qa_match
        and selected_qa is None
    ):
        return None
    answer = str(qa.answer or "").strip()
    if not answer:
        return None
    sku = product_sku
    bounded_gifting_answer = _bound_gifting_qa_answer_to_evidence(
        question,
        answer,
        trusted_recorded_qa=bool(exact_qa_match or selected_qa is not None),
    )
    if bounded_gifting_answer != answer:
        field_contract = {
            "field_type": "product_qa",
            "requested_field": "产品问答",
            "requested_fields": ["产品问答"],
            "canonical_fields": ["product_qa"],
            "supported_fields": ["product_qa"],
            "unsupported_fields": [],
            "subject": entity_subject,
            "requested_scope": "subject",
            "source": "gifting_evidence_boundary",
            "confidence": 1.0,
            "compound": False,
        }
        return _sealed_product_qa_safe_missing_result(
            product,
            bounded_gifting_answer,
            field_contract=field_contract,
            debug={"gifting_evidence_boundary": True},
        )
    qa_bundle = customer_evidence_bundle.build_customer_evidence_bundle(
        sku=sku,
        product_name=product.product_name_cn or product.product_name_en or sku,
        evidence_items=[{
            "evidence_id": f"product_qa:{qa.id}",
            "sku": sku,
            "source_type": "product_qa",
            "source": "product_qa",
            "field": field_type or "product_qa",
            "value": answer,
            "visibility": customer_evidence_bundle.CUSTOMER_VISIBLE,
        }],
    )
    if len(qa_bundle.items) != 1:
        return None
    qa_evidence = qa_bundle.items[0]
    steps = [{"type": "product_qa_shortcut", "label": "产品 QA 快速命中", "detail": sku, "ok": True}]
    qa_field_contract = {
        "field_type": field_type,
        "requested_field": customer_field_contract.product_detail_field_label(field_type),
        "requested_fields": [customer_field_contract.product_detail_field_label(field_type)],
        "canonical_fields": [field_type],
        "supported_fields": [field_type],
        "unsupported_fields": [],
        "subject": entity_subject,
        "requested_scope": "subject",
        "source": "deterministic_field_contract",
        "confidence": 1.0,
        "compound": False,
    } if field_type else {
        # This generic contract is intentionally created only after both an
        # exact entity contract and a same-SKU QA record have been sealed.
        # It has no aliases and cannot become a keyword route.
        "field_type": "product_qa",
        "requested_field": "产品问答",
        "requested_fields": ["产品问答"],
        "canonical_fields": ["product_qa"],
        "supported_fields": ["product_qa"],
        "unsupported_fields": [],
        "subject": entity_subject,
        "requested_scope": "subject",
        "source": "sealed_same_sku_product_qa",
        "confidence": 1.0,
        "compound": False,
    }
    result = {
        "answer": answer,
        "intent": "product_detail",
        "answer_type": "product_detail",
        "confidence": "high",
        "uncertainty": "resolved",
        "needs_clarification": False,
        "anomalies": [],
        "suggested_followups": [],
        "followups": [],
        "evidence": [{
            "evidence_id": qa_evidence.evidence_id,
            "sku": sku,
            "product_name": product.product_name_cn or product.product_name_en or "",
            "field_label": "产品 QA",
            "value": qa_evidence.value,
            "source_layer": "QA",
            "matched_by": "product_qa",
            "source_type": "product_qa",
            "source_label": "产品 QA",
            "evidence_text": answer,
        }],
        "sources": [{"type": "product_qa", "label": "产品 QA", "sku": sku, "qa_id": qa.id}],
        "actions": [],
        "results": [{
            "sku": sku,
            "product_name_cn": product.product_name_cn,
            "product_name_en": product.product_name_en,
            "category": product.category,
        }],
        "steps": steps,
        "warnings": [],
        "sku": sku,
        "result_skus": [sku],
        "answer_metadata": {
            "qa_match_type": "exact" if exact_qa_match else "semantic",
            "contract_field_type": qa_field_contract["field_type"],
            "requested_field": qa_field_contract["requested_field"],
            "evidence_status": "matched",
            "evidence_field": "product_qa",
            "evidence_source": f"product_qa:{qa.id}",
            "evidence_value": answer,
            "evidence_sku": sku,
            "evidence_skus": [sku],
            "evidence_bundle_skus": [qa_bundle.sku],
            "evidence_ids": [qa_evidence.evidence_id],
            "field_evidence_match": True,
            "field_evidence_missing": False,
        },
        "debug": {
            "agent_mode": "product_qa_fast_path",
            "field_contract": qa_field_contract,
            "entity_resolution_contract": entity_contract.to_dict(),
            "intent": "product_detail",
            "steps": steps,
            "warnings": [],
            "anomalies": [],
            "raw_results": [],
        },
        "skip_polish": False,
    }
    return result


async def _try_product_qa_shortcut_with_semantic_selection(
    db: Session,
    question: str,
    *,
    phase1_plan: dict[str, Any] | None = None,
) -> dict | None:
    """Resolve sealed QA with a bounded same-SKU candidate selector.

    The preplan decides that a customer asks product QA; this helper never
    lets the model select a product, a database value, or an answer.  It is
    only used when normal same-SKU retrieval cannot align a natural paraphrase
    to a stored QA question.  The selected QA id is revalidated by the normal
    entity/evidence contract before its stored answer is returned.
    """
    direct = _try_product_qa_shortcut(db, question, phase1_plan=phase1_plan)
    # A sealed safe-missing has identity but no validated QA evidence. It is a
    # fail-closed fallback, not a positive QA match, so it must not prevent
    # the semantic selector from checking the same SKU. This matters for a
    # compound turn after semantic splitting: each narrow child can have a
    # valid QA match even though the original combined turn does not.
    direct_safe_missing = _is_sealed_product_qa_safe_missing(direct)
    semantic_preplan = (phase1_plan or {}).get("semantic_preplan") if isinstance(phase1_plan, dict) else {}
    strict_compound_child_qa = bool((semantic_preplan or {}).get("strict_compound_child_qa"))
    if (
        (direct is not None and not direct_safe_missing and not strict_compound_child_qa)
        or not _semantic_prefers_sealed_product_qa(phase1_plan or {})
    ):
        return direct

    subject_text = str((semantic_preplan or {}).get("subject_text") or "").strip()
    product = _explicit_product_from_question(db, question)
    named_products = _products_named_in_question(db, question)
    if not product or (named_products and len(named_products) != 1):
        return direct
    if named_products and str(named_products[0].id) != str(product.id):
        return direct
    normalized_question = customer_agent_service.normalize_search_text(question)
    canonical_names = (
        customer_agent_service.normalize_search_text(product.product_name_cn or ""),
        customer_agent_service.normalize_search_text(product.product_name_en or ""),
    )
    explicit_sku_tokens = {
        str(item or "").strip().upper()
        for item in customer_agent_service._extract_skus(question)
        if str(item or "").strip()
    }
    if not any(name and name in normalized_question for name in canonical_names) and str(product.sku or "").strip().upper() not in explicit_sku_tokens:
        # An unresolved shorthand is not permitted to ask the selector to bind
        # an identity. The normal entity clarification path owns it instead.
        return direct

    selected = await _select_same_sku_product_qa_with_semantic_selection(
        db,
        product,
        question,
        semantic_query=str((semantic_preplan or {}).get("qa_evidence_query") or "").strip(),
        subject_text=subject_text,
        strict_entailment=strict_compound_child_qa,
    )
    if selected is None:
        # A compound child question is already an independently scoped
        # semantic intent. Do not let a broad lexical QA match answer a
        # different sibling property; the caller renders this child safely
        # missing when no same-SKU selector can cover it.
        return direct if not strict_compound_child_qa or direct_safe_missing else None

    # The selector has already chosen a high-confidence QA id from this sealed
    # SKU. Pass that immutable record into the normal contract/evidence
    # formatter; do not make legacy lexical retrieval choose it a second time.
    result = _try_product_qa_shortcut(
        db,
        question,
        phase1_plan=phase1_plan,
        selected_qa=selected,
    )
    if result is not None:
        debug = result.setdefault("debug", {})
        debug["qa_evidence_selector"] = {
            "selected_qa_id": str(selected.id),
            "confidence": "high",
            "selection_scope": "same_sku_only",
        }
    return result


async def _select_same_sku_product_qa_with_semantic_selection(
    db: Session,
    product: Product,
    question: str,
    *,
    semantic_query: str = "",
    subject_text: str = "",
    comparison_criterion: str = "",
    strict_entailment: bool = False,
) -> ProductQa | None:
    """Let the semantic model choose one QA record from an already sealed SKU."""
    qas = product_service.customer_visible_product_qas(db, product.id)[:20]
    candidates = [
        {
            "id": str(qa.id),
            "question": str(qa.question or "").strip(),
            "tags": str(getattr(qa, "tags", "") or "").strip(),
        }
        for qa in qas
        if str(qa.id or "").strip() and str(qa.question or "").strip() and str(qa.answer or "").strip()
    ]
    if not candidates:
        return None
    target_question = str(semantic_query or question).strip()
    payload = {
        "customer_question": target_question,
        "original_customer_question": question,
        "semantic_query": semantic_query,
        "subject_text": subject_text,
        "comparison_criterion": comparison_criterion,
        "sealed_product_name": str(product.product_name_cn or product.product_name_en or "").strip(),
        "qa_candidates": candidates,
    }
    selection_instruction = (
        "The customer is comparing already sealed products. For this one sealed participant, select a candidate only when its QUESTION "
        "directly supplies evidence relevant to comparison_criterion or a concrete enabling capability materially related to that criterion. "
        "The QA does not need to answer which participant is better, and related evidence alone never proves the participant wins. "
        "Do not infer a comparison result or a product identity. "
        if comparison_criterion else
                        "Select at most one candidate whose QUESTION directly answers the customer's current question. "
    )
    semantic_runtime = customer_agent_planner_service._semantic_preplan_runtime_settings()
    try:
        raw = await customer_llm_service.chat_completion(
            db,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Return only JSON: {qa_id:string|null,coverage:full|partial|none,confidence:high|medium|low,reasoning_summary:string}. "
                        + selection_instruction +
                        "You may select only an id listed in qa_candidates. customer_question is the sole evidence-selection target; "
                        "original_customer_question is identity context only and must not add a second condition. Do not infer a product, write an answer, use external knowledge, "
                        "or select a merely related question. The selected candidate must address the same operative property as the customer's "
                        "question: a specification such as fuel, heat source, material, size, weight, capacity, or a generic product description "
                        "does not prove a separate performance, weather/environment, durability, procedure, safety, or compatibility question. "
                        "Set coverage=full only when the selected QA completely answers every operative part of the current customer question. "
                        "For an overview or decision-support question asking for useful information, key points, or considerations about the product as a whole, "
                        "a single-property QA cannot have full coverage unless that QA question itself explicitly covers multiple product traits. "
                        "For a narrow single-property candidate in that situation, return qa_id null and coverage=none so complementary same-SKU evidence can be selected. "
                        "Use partial when it is relevant but leaves any requested condition, comparison, procedure, compatibility, limitation, or second question unanswered. "
                        "Return qa_id null and coverage=none when no candidate directly matches."
                    ),
                },
                {"role": "user", "content": json.dumps(payload, ensure_ascii=False)},
            ],
            temperature=0,
            max_tokens=min(int(semantic_runtime["max_tokens"]), 240),
            purpose="semantic_product_qa_evidence_selection",
            api_model_override=semantic_runtime["model"],
            response_format=semantic_runtime["response_format"],
            thinking=semantic_runtime["thinking"],
        )
    except Exception:
        return None
    selected = customer_agent_planner_service._extract_json_object(str(raw or "")) or {}
    selected_id = str(selected.get("qa_id") or "").strip()
    if (
        str(selected.get("confidence") or "").strip().lower() != "high"
        or str(selected.get("coverage") or "").strip().lower() != "full"
        or not selected_id
    ):
        return None
    candidate = next((qa for qa in qas if str(qa.id) == selected_id), None)
    if candidate is None:
        return None
    if not strict_entailment:
        return candidate
    # The first selector chooses from a sealed same-SKU set. A second narrow
    # entailment check prevents a broadly related QA (for example durability)
    # from being reused as a different capability, safety, temperature,
    # compatibility, procedure, or limitation answer in a compound turn.
    try:
        verification_raw = await customer_llm_service.chat_completion(
            db,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Return only JSON: {direct:boolean}. direct is true only when candidate_question and candidate_answer "
                        "directly determine the narrow customer_question without inference. A generic selling point, material, "
                        "durability, size, capacity, or usage statement does not determine a separate safety, temperature, "
                        "compatibility, cleaning, procedure, limitation, or performance question."
                    ),
                },
                {
                    "role": "user",
                    "content": json.dumps(
                        {
                            "customer_question": target_question,
                            "candidate_question": str(candidate.question or "").strip(),
                            "candidate_answer": str(candidate.answer or "").strip(),
                        },
                        ensure_ascii=False,
                    ),
                },
            ],
            temperature=0,
            max_tokens=40,
            purpose="semantic_product_qa_direct_entailment",
            api_model_override=semantic_runtime["model"],
            response_format=semantic_runtime["response_format"],
            thinking=semantic_runtime["thinking"],
        )
    except Exception:
        return None
    verification = customer_agent_planner_service._extract_json_object(str(verification_raw or "")) or {}
    return candidate if verification.get("direct") is True else None


async def _select_same_sku_comparison_knowledge_answer(
    db: Session,
    product: Product,
    *,
    comparison_criterion: str,
    participant_identity_tokens: list[str] | None = None,
) -> dict | None:
    """Use the sealed product knowledge packet when a comparison concept is not a QA column.

    Comparison participants are already resolved by the pairwise contract. The
    supplemental concept (for example storage or packing) is therefore sent
    through the same-SKU RAG executor with a synthetic, validated product-QA
    preplan. This is a source-class adapter, not a new wording route: the
    semantic query still decides what the retriever and selector should look
    for, while the RAG selector binds every chosen fact to this one SKU.
    """
    sku = str(product.sku or "").strip().upper()
    query = str(comparison_criterion or "").strip()
    if not sku or not query:
        return None
    # The participant identities are already sealed by the comparison
    # contract.  Do not send the whole pairwise sentence to the one-SKU
    # relevance selector: the other SKU and the words asking for a winner can
    # make Flash treat a directly relevant profile fact as a comparison claim
    # and return low coverage.  Remove only those server-resolved identity
    # spans; the customer's actual criterion remains untouched and semantic
    # selection still owns relevance.
    local_query = query
    for token in sorted(
        {
            str(item or "").strip()
            for item in (participant_identity_tokens or [])
            if str(item or "").strip()
        },
        key=len,
        reverse=True,
    ):
        local_query = re.sub(re.escape(token), " ", local_query, flags=re.IGNORECASE)
    local_query = re.sub(r"\s+", " ", local_query).strip(" \t\r\n、，,和与及以及/")
    local_query = local_query or query
    preplan = {
        "called": True,
        "route_family": "product_bound_qa",
        "route_hint": "product_detail",
        "question_type": "field",
        "entities": [sku],
        "subject_text": sku,
        "canonical_fields": [],
        "field_type": "",
        "field_hint": None,
        "ambiguity": False,
        "evidence_required": True,
        "evidence_kind": "product_qa",
        "qa_evidence_query": local_query,
        "qa_evidence_queries": [],
        "supplemental_qa_evidence_query": "",
        "compound": False,
        "intent_coverage": "full",
        "context_usage": "none",
        "decision_requested": False,
        "information_scope": "",
        "recommendation_constraints": {},
        "structured_query_constraints": [],
        "unrepresented_recommendation_requirements": [],
        "recommendation_evidence_requirements": [],
        "recommendation_soft_preferences": [],
        "confidence": 0.9,
        "confidence_label": "high",
        "subtype": "comparison_supplemental_knowledge",
    }
    result = await _try_sealed_same_sku_knowledge_answer(
        db,
        f"{sku} {local_query}",
        {"semantic_preplan": preplan},
    )
    if not isinstance(result, dict):
        return None
    if str(result.get("answer") or "").strip():
        return result
    # A comparison needs the selected same-SKU facts, not necessarily a
    # standalone prose answer for each participant.  If the per-participant
    # writer/grounding pass fails after semantic selection, retain the already
    # identity-checked selected units for the aggregate comparison writer.
    # This prevents a presentation failure for one SKU from erasing valid RAG
    # evidence and turning the whole pair into a no-match response.
    result_debug = result.get("debug") if isinstance(result.get("debug"), dict) else {}
    selected_units = [
        str(item or "").strip()
        for item in (result_debug.get("knowledge_selected_evidence") or [])
        if str(item or "").strip()
    ]
    selected_meta = result_debug.get("knowledge_evidence_selection")
    if (
        not selected_units
        or not isinstance(selected_meta, dict)
        or selected_meta.get("identity_consistent") is not True
    ):
        return None
    evidence = [
        {
            "evidence_id": customer_evidence_bundle.stable_customer_evidence_id(
                namespace="knowledge",
                sku=sku,
                value=value,
            ),
            "sku": sku,
            "source_type": "knowledge_base",
            "source": "same_sku_knowledge",
            "field": "product_qa",
            "value": value,
        }
        for value in selected_units
    ]
    return {
        "answer": "",
        "evidence": evidence,
        "answer_metadata": {
            "contract_field_type": "product_qa",
            "evidence_status": "selected",
            "evidence_source": "same_sku_knowledge",
            "evidence_sku": sku,
            "evidence_skus": [sku],
        },
        "debug": {
            "agent_mode": "sealed_same_sku_knowledge_selected_for_comparison",
            "knowledge_evidence_selection": selected_meta,
        },
    }
    return result


def _same_sku_knowledge_evidence_selection_messages(
    question: str,
    sku: str,
    candidates: list[dict[str, Any]],
    *,
    product_identity: dict[str, Any] | None = None,
    allow_partial_compound: bool = False,
) -> list[dict[str, str]]:
    """Build the semantic-only relevance contract for sealed product RAG.

    Identity has already been verified by the entity contract before this
    selector runs.  The model must therefore judge relevance from the complete
    customer question, rather than treating every same-SKU chunk as an answer.
    """
    compound_instruction = (
        "The semantic plan has confirmed that this turn asks several independently requested product facts. "
        "Select an item when it directly supports one independently requested part, but never treat that item as support for another part; "
        "a later sealed answer will state any separately unsupported part safely. "
        if allow_partial_compound
        else ""
    )
    return [
        {
            "role": "system",
            "content": (
                "Return only JSON: {indexes:number[],confidence:high|medium|low,identity_consistent:boolean,coverage:full|partial|none}. "
                "Select only directly relevant same-product evidence. Same-SKU identity alone is insufficient: "
                "every selected item must directly respond to the customer's intended question. "
                "coverage describes the selected evidence against the whole customer question: full means it directly answers the operative request, partial means it answers only one independently requested part, and none means it is merely related. "
                "For a single-intent question, return coverage=none unless the selected evidence directly answers that intent. A capacity, material, scene, or generic selling-point paragraph is not full evidence for a separate compatibility, heat-source, safety, cleaning, or operating question. Conversely, do not reject a natural semantic paraphrase when the evidence states the same capability. "
                "Treat product_identity (canonical product name and catalogue category) as the authority for what physical product is being discussed. "
                "A stored SKU tag, the customer's wording, and a candidate that repeats the question do not prove that a capability belongs to that product. "
                "Set identity_consistent=false and indexes=[] when any evidence needed for the answer describes an operation or capability that plainly belongs to a different device, component, or product function not identified by product_identity, "
                "even when that candidate is tagged with this SKU. Missing identity detail is not itself a conflict, but evidence may never override a clear product identity. "
                "For a broad overview or decision question, select only complementary product-specific traits, "
                "capabilities, applicable scenes, compatibility, stated limitations, or trade-offs that help answer it. "
                "When the customer asks what a set, package, box, or unboxing includes, an evidence item that explicitly says the set includes, "
                "contains, or is composed of named main components directly answers that contents question. Do not treat generic selling points, "
                "usage instructions, or a product title alone as package-contents evidence. "
                "A selected same-SKU record in the form 'Q: ... A: ...' is direct evidence when its stored question semantically addresses the "
                "customer's question: its A text may then support the answer. Do not reject it merely because the customer used a natural paraphrase. "
                "An explicit numeric operating boundary is directly relevant when the customer's named condition can be transparently and conservatively "
                "checked against that boundary. Select the boundary evidence, but do not invent a hidden tolerance, failure mode, or safety guarantee. "
                "Do not select a comparison claim unless the customer explicitly asks for a comparison or names a comparison target. "
                "Do not include merely related material such as purchase, authenticity, delivery, returns, warranty, "
                "gifting, first-use, cleaning, maintenance, or other after-sales information unless the customer directly asks about it. "
                + compound_instruction
                + "Do not infer facts. Return indexes [] with low confidence when no candidate directly matches."
            ),
        },
        {
            "role": "user",
            "content": json.dumps(
                {
                    "question": question,
                    "sku": sku,
                    "product_identity": product_identity or {"sku": sku},
                    "candidates": candidates,
                },
                ensure_ascii=False,
            ),
        },
    ]


def _knowledge_rows_with_approved_qa_provenance(
    db: Session,
    rows: list[dict[str, Any]] | None,
    *,
    sku: str,
) -> list[dict[str, Any]]:
    """Exclude stale product-QA chunks unless their live source is approved.

    The vector index is a cache of customer evidence, not the authority for QA
    eligibility. A rejected, pending-review, or deleted ProductQa row must stop
    being usable immediately even if an older chunk has not been reindexed yet.
    """
    normalized_sku = str(sku or "").strip().upper()
    prefix = f"product:{normalized_sku}:qa:"
    qa_ids: set[str] = set()
    prepared: list[tuple[dict[str, Any], str]] = []
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        metadata = row.get("metadata") if isinstance(row.get("metadata"), dict) else {}
        source_id = str(metadata.get("source_id") or "").strip()
        qa_id = source_id[len(prefix):].strip() if source_id.startswith(prefix) else ""
        if qa_id:
            qa_ids.add(qa_id)
        prepared.append((row, qa_id))
    if not qa_ids:
        return [row for row, _qa_id in prepared]
    approved_ids = {
        str(qa_id)
        for (qa_id,) in db.query(ProductQa.id).join(
            Product,
            Product.id == ProductQa.product_id,
        ).filter(
            ProductQa.id.in_(qa_ids),
            ProductQa.integrity_status == "approved",
            Product.sku == normalized_sku,
        ).all()
    }
    return [row for row, qa_id in prepared if not qa_id or qa_id in approved_ids]


def _is_complete_package_contents_evidence(text: str) -> bool:
    """Whether one source explicitly supports a complete in-box list.

    A marketing claim that a cookware set "contains" its main pot and pan
    describes product composition, but cannot establish the complete package
    because it says nothing about handles, bags, manuals, or other standard
    items.  This guard only bounds the claim made for package-list questions;
    it does not infer products or select evidence.
    """
    value = re.sub(r"\s+", "", str(text or "")).casefold()
    if not value:
        return False
    return bool(re.search(
        r"(?:包装(?:清单|内|里|盒里|盒内)|开箱(?:清单|内容)|标配|随附|附带|随箱|"
        r"标准配置|盒内清单|package(?:contents|includes)|whatcomesinthebox)",
        value,
    ))


def _semantic_plan_requests_accessories(phase1_plan: dict[str, Any] | None) -> bool:
    """Honor a sealed accessories field contract in RAG evidence validation."""
    plan = phase1_plan if isinstance(phase1_plan, dict) else {}
    semantic = plan.get("semantic_preplan") if isinstance(plan.get("semantic_preplan"), dict) else {}
    fields = semantic.get("canonical_fields")
    return isinstance(fields, list) and "accessories" in fields


_UNSUPPORTED_SAFETY_GUARANTEE_RE = re.compile(
    r"(?:放心(?:使用)?|完全没问题|没有问题|绝对安全|安全可靠|无风险|零风险|保证安全|risk[- ]free|completely safe|no problem)",
    re.IGNORECASE,
)


def _bound_unsupported_rag_safety_guarantee(
    answer: str,
    answer_payload: dict[str, Any],
    evidence_content: str,
) -> tuple[str, bool]:
    """Fail closed when a RAG draft turns compatibility into a guarantee.

    This is output safety validation only. It neither detects intent nor
    selects a field, entity, or source; the replacement quotes the already
    selected same-SKU evidence and retains its limited scope.
    """
    if not _UNSUPPORTED_SAFETY_GUARANTEE_RE.search(str(answer or "")):
        return answer, False
    if _UNSUPPORTED_SAFETY_GUARANTEE_RE.search(str(evidence_content or "")):
        return answer, False
    quotes = answer_payload.get("evidence_quotes") if isinstance(answer_payload, dict) else []
    quote = next((str(item).strip() for item in (quotes or []) if str(item).strip() in str(evidence_content or "")), "")
    if not quote:
        return "", True
    return f"当前同 SKU 资料显示：{quote}。这说明该场景的适配信息，不能据此作出安全或无风险保证。", True


async def _try_sealed_same_sku_knowledge_answer(
    db: Session,
    question: str,
    phase1_plan: dict[str, Any] | None,
) -> dict | None:
    """Answer a sealed product-QA turn from directly selected same-SKU RAG evidence."""
    safe_missing = _sealed_semantic_product_qa_entity_guard(db, question, phase1_plan)
    if not isinstance(safe_missing, dict):
        return None
    if str((safe_missing.get("debug") or {}).get("agent_mode") or "") != "sealed_product_qa_safe_missing":
        return None
    sku = str(safe_missing.get("sku") or "").strip().upper()
    if not sku:
        return None
    # These are populated only after semantic evidence selection succeeds.
    # Missing-result paths can run before those assignments, so initialise
    # them before the nested diagnostic helper closes over them.
    selected: dict[str, Any] = {}
    selected_evidence: list[dict[str, Any]] = []
    def _return_same_sku_missing(reason: str) -> dict[str, Any]:
        """Preserve the sealed product when RAG finds no usable evidence."""
        metadata = safe_missing.get("answer_metadata")
        metadata = dict(metadata) if isinstance(metadata, dict) else {}
        metadata.update({
            "source": "same_sku_knowledge_missing",
            "evidence_source": "same_sku_knowledge",
            "retrieval_attempted": True,
            "retrieval_missing_reason": reason,
        })
        safe_missing["answer_metadata"] = metadata
        missing_debug = safe_missing.get("debug")
        missing_debug = dict(missing_debug) if isinstance(missing_debug, dict) else {}
        missing_debug.update({
            "agent_mode": "sealed_same_sku_knowledge_missing",
            "knowledge_evidence_attempted": True,
            "knowledge_evidence_missing_reason": reason,
        })
        # Keep the failed semantic decision inspectable in debug responses.
        # This is diagnostic provenance only; it is never copied into the
        # customer answer and makes a grounding rejection distinguishable from
        # an actual retrieval miss during HTTP acceptance.
        if selected:
            missing_debug["knowledge_evidence_selection"] = {
                "indexes": selected.get("indexes"),
                "confidence": selected.get("confidence"),
                "coverage": selected.get("coverage"),
                "identity_consistent": selected.get("identity_consistent"),
            }
        if selected_evidence:
            missing_debug["knowledge_selected_evidence"] = [
                str(item.get("content") or "")[:240]
                for item in selected_evidence
                if isinstance(item, dict)
            ]
        safe_missing["debug"] = missing_debug
        safe_missing["skip_polish"] = True
        return safe_missing

    semantic_value = (phase1_plan or {}).get("semantic_preplan") if isinstance(phase1_plan, dict) else {}
    semantic_query = str(
        semantic_value.get("supplemental_qa_evidence_query")
        or semantic_value.get("qa_evidence_query")
        or question
    ).strip() or question
    # The planner's query is a retrieval hint, not a license to change the
    # customer's language. A Chinese turn can occasionally receive an
    # English-heavy hint with only the product name left in Chinese; preserve
    # the original turn so Chinese usage instructions remain retrievable.
    original_cjk_count = len(re.findall(r"[\u3400-\u9fff]", str(question or "")))
    semantic_cjk_count = len(re.findall(r"[\u3400-\u9fff]", semantic_query))
    semantic_latin_words = len(re.findall(r"[A-Za-z]{2,}", semantic_query))
    retrieval_question = (
        str(question or "").strip()
        if original_cjk_count >= 4
        and (
            semantic_cjk_count < 4
            or (
                semantic_latin_words >= 3
                and semantic_cjk_count < original_cjk_count * 0.5
            )
        )
        else semantic_query
    ) or str(question or "").strip()
    try:
        # Same-SKU sealing has already removed the principal precision risk.
        # Keep a wider retriever pool so natural paraphrases and multilingual
        # file chunks are not discarded before the semantic evidence selector
        # can judge them. The downstream prompt remains bounded to 24 atomic
        # evidence units and still fails closed on low confidence.
        retrieved = await knowledge_service.semantic_retrieve(db, retrieval_question, sku=sku, limit=12)
    except Exception:
        return _return_same_sku_missing("retrieval_error")
    retrieved = _knowledge_rows_with_approved_qa_provenance(db, retrieved, sku=sku)
    # Semantic vector results are strongest for narrow QA, but may omit the
    # product's Listing/profile on broad product questions.  Add one bounded,
    # customer-facing same-SKU context; the semantic selector below still
    # decides whether it directly answers this particular question.
    try:
        # Keep both customer-facing Listing and profile/specification context
        # available.  A product can have no standalone QA row for a procedure
        # while its usage_instruction is still the authoritative same-SKU
        # answer (for example cleaning and storage).  The semantic selector
        # still chooses the relevant units; this only prevents the profile
        # from disappearing before RAG sees it.
        authoritative_context = knowledge_service.same_sku_customer_context(db, sku, limit=2)
    except Exception:
        authoritative_context = []
    # ProductQa is a customer-facing source, but its rows may not have a
    # synced vector chunk (or the vector query may return no hit for a natural
    # paraphrase).  Feed approved same-SKU Q/A into the same semantic packet
    # instead of letting the legacy exact-QA formatter answer first.  The
    # selector and writer still decide relevance and wording; the historical
    # answer is never returned merely because its question is similar.
    approved_qa_context: list[dict[str, Any]] = []
    try:
        product = db.query(Product).filter(Product.sku == sku).first()
        for qa in product_service.customer_visible_product_qas(db, product.id) if product else []:
            qa_question = str(qa.question or "").strip()
            qa_answer = str(qa.answer or "").strip()
            if not qa_question or not qa_answer:
                continue
            approved_qa_context.append({
                "source_type": "product_qa",
                "sku": sku,
                "content": f"Q: {qa_question}\nA: {qa_answer}",
                "metadata": {
                    "section": "qa",
                    "source_id": f"product:{sku}:qa:{qa.id}",
                },
                "score": None,
            })
    except Exception:
        approved_qa_context = []
    seen_contents = {
        str(item.get("content") or "").strip()
        for item in (retrieved or [])
        if isinstance(item, dict) and str(item.get("content") or "").strip()
    }
    retrieved = [
        *(retrieved or []),
        *approved_qa_context,
        *[
            item
            for item in authoritative_context
            if isinstance(item, dict) and str(item.get("content") or "").strip() not in seen_contents
        ],
    ]
    # Knowledge chunks are ingestion units, not necessarily atomic evidence.
    # A product Listing can contain several unrelated paragraphs (for example
    # material, heat source, care, and package composition).  Presenting the
    # entire Listing as one candidate lets a semantic selector correctly find
    # the chunk but leaves the answer writer free to cite a different sentence
    # from that same chunk. Split only after SKU sealing and customer-safe
    # filtering; DeepSeek still decides relevance.
    candidates: list[dict[str, Any]] = []
    candidate_evidence_items: dict[int, dict[str, Any]] = {}
    seen_candidate_content: set[str] = set()
    # The old 24-unit ceiling was applied after the profile had been split into
    # atomic lines.  That made the packet depend on storage order: the first
    # few specification/care lines survived, while later customer-facing
    # business context (target audience, positioning, usage scenes) was
    # silently removed before Flash could judge it.  This is a context-budget
    # bound, not an intent rule, so keep a wider same-SKU packet and let the
    # semantic selector choose the relevant units.  The source is already
    # sealed to one SKU and internal labels are removed above.
    evidence_unit_limit = 64
    for row in retrieved or []:
        if not isinstance(row, dict) or str(row.get("sku") or "").strip().upper() != sku:
            continue
        safe_content = _customer_safe_same_sku_knowledge_content(str(row.get("content") or ""))
        for evidence_unit in _same_sku_knowledge_evidence_units(safe_content):
            normalized_unit = "".join(evidence_unit.casefold().split())
            if not normalized_unit or normalized_unit in seen_candidate_content:
                continue
            seen_candidate_content.add(normalized_unit)
            candidate_index = len(candidates)
            candidates.append({"index": candidate_index, "content": evidence_unit})
            metadata = row.get("metadata") if isinstance(row.get("metadata"), dict) else {}
            section = str(metadata.get("section") or "").strip().casefold()
            source_type = (
                "product_qa"
                if section in {"qa", "product_qa"} or section.startswith("qa:")
                else "knowledge_chunk"
            )
            candidate_evidence_items[candidate_index] = {
                "evidence_id": customer_evidence_bundle.stable_customer_evidence_id(
                    namespace="knowledge",
                    sku=sku,
                    value=evidence_unit,
                ),
                "sku": sku,
                "source_type": source_type,
                "source": source_type,
                "field": "product_qa",
                "value": evidence_unit,
                "visibility": customer_evidence_bundle.CUSTOMER_VISIBLE,
            }
            # Bound the semantic prompt while retaining a diverse set of
            # retriever-ranked, independently auditable facts.
            if len(candidates) >= evidence_unit_limit:
                break
        if len(candidates) >= evidence_unit_limit:
            break
    if not candidates:
        return _return_same_sku_missing("no_same_sku_evidence")
    result_rows = safe_missing.get("results") if isinstance(safe_missing.get("results"), list) else []
    identity_row = next(
        (
            item
            for item in result_rows
            if isinstance(item, dict) and str(item.get("sku") or "").strip().upper() == sku
        ),
        {},
    )
    product_identity = {
        "sku": sku,
        "canonical_name": str(
            identity_row.get("product_name_cn")
            or identity_row.get("product_name_en")
            or ""
        ).strip(),
        "category": str(identity_row.get("category") or "").strip(),
    }
    explicit_missing_clause_allowed = _semantic_product_qa_allows_explicit_missing_clause(phase1_plan)
    missing_capability_instruction = (
        "The semantic plan identifies multiple independently requested capabilities. Answer only the parts directly supported by the selected evidence. "
        "Do not append a missing-data or cannot-confirm clause here; the compound coverage orchestrator owns unsupported child requests after each child "
        "has been independently retrieved and grounded. Never use a related fact to imply support for a separate unsupported condition. "
        if explicit_missing_clause_allowed
        else "The semantic plan identifies one broad product request, not separate capability checks. Do not add an absence, missing-data, unsupported, "
        "or cannot-confirm sentence, and do not invent a second use case, criterion, or example scenario. "
    )
    runtime = customer_agent_planner_service._semantic_preplan_runtime_settings()
    try:
        selected: dict[str, Any] = {}
        selected_indexes: Any = None
        selection_coverage = ""
        # Even a single same-SKU candidate must pass the semantic identity and
        # relevance contract. Same-SKU ingestion mistakes are precisely the
        # case where automatic one-item selection would be unsafe.
        for _selection_attempt in range(2):
            selected = customer_agent_planner_service._extract_json_object(str(
                await customer_llm_service.chat_completion(
                    db,
                    messages=_same_sku_knowledge_evidence_selection_messages(
                        question,
                        sku,
                        candidates,
                        product_identity=product_identity,
                        allow_partial_compound=explicit_missing_clause_allowed,
                    ),
                    temperature=0,
                    max_tokens=min(int(runtime["max_tokens"]), 120),
                    purpose="semantic_product_knowledge_evidence_selection",
                    api_model_override=runtime["model"],
                    response_format=runtime["response_format"],
                    thinking=runtime["thinking"],
                ) or ""
            )) or {}
            selected_indexes = selected.get("indexes")
            selection_coverage = str(selected.get("coverage") or "").strip().lower()
            if (
                selected.get("identity_consistent") is True
                and str(selected.get("confidence") or "").lower() in {"high", "medium"}
                and isinstance(selected_indexes, list)
                and selected_indexes
                and all(isinstance(index, int) for index in selected_indexes)
                and (
                    not selection_coverage
                    or (
                        selection_coverage in {"full", "partial"}
                        and (explicit_missing_clause_allowed or selection_coverage == "full")
                    )
                )
            ):
                break
        # Evidence selection is semantic, not an authorization to state a
        # product fact.  A nonempty medium-confidence selection remains
        # cautiously useful for broad product questions because generation is
        # followed by the independent same-SKU grounding gate below.  Low
        # confidence still fails closed before any answer is drafted.
        if (
            selected.get("identity_consistent") is not True
            or str(selected.get("confidence") or "").lower() not in {"high", "medium"}
            or not isinstance(selected_indexes, list)
            or not selected_indexes
            or not all(isinstance(index, int) for index in selected_indexes)
            or (
                bool(selection_coverage)
                and (
                    selection_coverage not in {"full", "partial"}
                    or (not explicit_missing_clause_allowed and selection_coverage != "full")
                )
            )
        ):
            return _return_same_sku_missing("evidence_selection_not_usable")
        selected_index_set = set(selected_indexes)
        selected_evidence = [item for item in candidates if item["index"] in selected_index_set]
        if len(selected_evidence) != len(selected_index_set):
            return _return_same_sku_missing("evidence_selection_index_mismatch")
        # The semantic evidence selector has already judged identity and
        # relevance against the canonical product identity, while every row
        # in this packet was filtered to the resolved SKU before selection.
        # A second independent identity LLM used to re-audit the same packet
        # here.  Its stochastic verdict could reject a valid paraphrase (for
        # example, a safety instruction about refuelling a named alcohol
        # burner) and turn a retrieved answer into a false missing-data reply.
        # Keep one semantic selection decision and the deterministic same-SKU
        # evidence/quote contracts; do not make duplicate identity review a
        # delivery gate.
        missing_debug = safe_missing.get("debug")
        missing_debug = dict(missing_debug) if isinstance(missing_debug, dict) else {}
        missing_debug["knowledge_identity_validation"] = "semantic_selector_same_sku"
        safe_missing["debug"] = missing_debug
        if (
            (
                customer_agent_intent_service._looks_like_contents_grounding_question(question)
                or _semantic_plan_requests_accessories(phase1_plan)
            )
            and not any(_is_complete_package_contents_evidence(item["content"]) for item in selected_evidence)
        ):
            return _return_same_sku_missing("package_evidence_incomplete")
        selected_bundle = customer_evidence_bundle.build_customer_evidence_bundle(
            sku=sku,
            product_name=sku,
            evidence_items=[
                candidate_evidence_items[item["index"]]
                for item in selected_evidence
            ],
        )
        if len(selected_bundle.items) != len(selected_evidence):
            return _return_same_sku_missing("evidence_bundle_invalid")
        evidence_content = "\n\n".join(item["content"] for item in selected_evidence)
        selected_has_approved_product_qa = any(
            str((candidate_evidence_items.get(item["index"]) or {}).get("source_type") or "").strip() == "product_qa"
            and str(item.get("content") or "").lstrip().startswith("Q:")
            for item in selected_evidence
        )
        answer = await customer_llm_service.chat_completion(
            db,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "Return only JSON: {answer:string,evidence_quotes:string[]}. Answer in concise, direct, friendly Chinese using only the supplied same-product evidence. "
                        "Start with the customer's actual conclusion, not boilerplate such as '请查看以下说明' or a description of evidence. "
                        "For a safety or operating question, clearly state the permitted action and the prohibited action supported by the evidence so the customer knows what to do next. When the evidence supports a safe sequence, name the customer's immediate condition, the action that must stop first, and the next permitted step instead of collapsing the reply into one short clause. "
                        "The upstream semantic selector has already accepted each supplied evidence item as directly relevant to the customer's complete question. "
                        "For a broad product overview or decision question, synthesize the concrete traits, stated capabilities, applicable scenes, "
                        "limitations, or trade-offs in that selected evidence; do not set answer to NO_EVIDENCE merely because no item repeats the customer's wording. "
                        "For a suitability or decision question, when the evidence supplies relevant decision-support factors but does not explicitly state the "
                        "requested final suitability judgement, present those concrete factors and say the records do not directly establish that final judgement. "
                        "Do not claim suitable or unsuitable merely from adjacent traits. "
                        "A listed target audience never excludes an unlisted audience and never proves that the product was not designed for them. "
                        "For an unlisted audience, state the recorded audience and useful traits, then keep the final suitability judgement explicitly unconfirmed. "
                        "You may make transparent conservative reasoning from an explicit numeric boundary in the evidence when the customer's stated condition "
                        "unambiguously falls outside that boundary. State the recorded boundary and phrase the result as outside the recorded range or not recommended; "
                        "never answer with cannot, impossible, or unsafe unless the evidence explicitly states that stronger conclusion. "
                        "Do not turn boundary reasoning into an unrecorded product failure, safety guarantee, or hidden tolerance. "
                        "Never both resolve a condition from accepted evidence and then say that same condition is unconfirmed or missing. "
                        "Only state that evidence does not directly confirm something when the customer explicitly asks a separate capability or condition. "
                        "For a broad overview or decision request, do not invent a missing use case, accessory, performance criterion, or example scenario. "
                        "Evidence that says suitable, adapted, or compatible with a condition supports only that attributed compatibility statement, never a safety, risk-free, certification, or 'no problem' guarantee without explicit evidence. "
                        "For a question about what a set, package, box, or unboxing includes, state only components explicitly introduced by an includes, contains, or composition statement in the evidence. "
                        "Do not infer included components from a title, dimensions, capacity, material, or a compatibility specification; each evidence quote for such an answer must itself support the stated component. "
                        "For selected evidence written as 'Q: ... A: ...', use the stored A as the direct answer evidence when the stored Q addresses "
                        "the customer's paraphrased question; quote the A text rather than treating the absence of identical wording as missing information. If the stored A is subjective marketing or a suitability opinion, attribute it to the product Q/A or product资料 in the answer instead of presenting it as an independently verified product fact. "
                        "For example, a stored same-SKU QA statement that the product has official warranty supports saying that the record states official warranty; "
                        "it does not support inventing a warranty duration, coverage term, or policy detail not present in that A. "
                        + missing_capability_instruction
                        + "Do not add facts, assumptions, or external knowledge. Include one to at most 3 evidence_quotes copied verbatim from the supplied evidence that support the answer; "
                        "each quote must be 60 characters or shorter. "
                        "do not return an answer when no such quote exists. Set answer to NO_EVIDENCE only when the selected evidence contains no customer-facing fact that can answer the question."
                    ),
                },
                {"role": "user", "content": json.dumps({"question": question, "evidence": evidence_content}, ensure_ascii=False)},
            ],
            temperature=0,
            max_tokens=min(int(runtime["max_tokens"]), 360),
            purpose="sealed_same_sku_knowledge_answer",
            api_model_override=runtime["model"],
            response_format=runtime["response_format"],
            thinking=runtime["thinking"],
        )
    except Exception:
        return _return_same_sku_missing("answer_writer_error")
    answer_payload = customer_agent_planner_service._extract_json_object(str(answer or "")) or {}
    answer = str(answer_payload.get("answer") or "").strip()
    if not answer or answer == "NO_EVIDENCE":
        return _return_same_sku_missing("answer_writer_no_evidence")
    answer, safety_bounded = _bound_unsupported_rag_safety_guarantee(answer, answer_payload, evidence_content)
    if not answer:
        return _return_same_sku_missing("answer_safety_boundary")
    quote_contract_failed = not _same_sku_rag_answer_has_selected_quotes(
        answer_payload,
        evidence_content,
    )
    initial_grounded = (
        not quote_contract_failed
        if safety_bounded
        else await _same_sku_rag_answer_is_grounded_after_quote_validation(
            db,
            question,
            answer,
            answer_payload,
            evidence_content,
        )
    )
    # Factual grounding alone is insufficient for a compound customer turn:
    # an answer can faithfully state one evidence fact while silently omitting
    # a second independently asked capability.  Keep semantic ownership of
    # that completeness judgement in a separate bounded LLM audit; the
    # deterministic layer only requires its boolean result before delivery.
    initial_complete = (
        initial_grounded
        if safety_bounded
        else initial_grounded and await _same_sku_rag_answer_covers_question(
            db,
            question,
            answer,
            evidence_content,
        )
    )
    semantic_answer_coverage_complete = bool(initial_complete)
    if not initial_grounded or not initial_complete:
        quote_repair_instruction = (
            "The prior evidence_quotes failed the provenance contract: every replacement quote must be a literal uninterrupted substring "
            "copied from the supplied evidence. Do not paraphrase, abbreviate, or replace part of a source list with ‘etc.’ or ‘and so on’. "
            if quote_contract_failed else ""
        )
        try:
            repaired = await customer_llm_service.chat_completion(
                db,
                messages=[
                    {
                        "role": "system",
                        "content": (
                            "Return only JSON: {answer:string,evidence_quotes:string[]}. Rewrite the answer in concise, direct, friendly Chinese using only the supplied same-product evidence. "
                            "Start with the customer's actual conclusion, not boilerplate such as '请查看以下说明' or a description of evidence. "
                            "For a safety or operating question, clearly state the permitted action and the prohibited action supported by the evidence so the customer knows what to do next. When the evidence supports a safe sequence, name the customer's immediate condition, the action that must stop first, and the next permitted step instead of collapsing the reply into one short clause. "
                            "Correct the previous draft when it says information is missing even though the evidence contains it. "
                            "Complete every independently requested part of the customer question; do not silently omit a part. "
                            "For a suitability or decision question, when the evidence supplies relevant decision-support factors but does not explicitly state the "
                            "requested final suitability judgement, present those concrete factors and say the records do not directly establish that final judgement. "
                            "If the previous draft claimed suitable or unsuitable merely from adjacent traits, replace it with this bounded decision-support answer. "
                            "A listed target audience never excludes an unlisted audience and never proves the product was not designed for them. "
                            "Remove any such exclusion; state the recorded audience and traits, then keep the final suitability judgement explicitly unconfirmed. "
                            "You may make transparent conservative reasoning from an explicit numeric boundary in the evidence when the customer's stated condition "
                            "unambiguously falls outside that boundary. State the recorded boundary and phrase the result as outside the recorded range or not recommended; "
                            "never answer with cannot, impossible, or unsafe unless the evidence explicitly states that stronger conclusion. "
                            "If the prior draft used such a stronger word, replace it with the recorded range plus a bounded not-recommended conclusion. "
                            "Do not turn boundary reasoning into an unrecorded product failure, safety guarantee, or hidden tolerance. "
                            "Never both resolve a condition from accepted evidence and then say that same condition is unconfirmed or missing; remove the contradictory missing clause. "
                            "Only state that evidence does not directly confirm something when the customer explicitly asks a separate capability or condition; "
                            "for a broad overview or decision request, do not invent a missing use case, accessory, performance criterion, or example scenario. "
                            "For a question about what a set, package, box, or unboxing includes, state only components explicitly introduced by an includes, contains, or composition statement in the evidence. "
                            "Do not infer included components from a title, dimensions, capacity, material, or a compatibility specification; each evidence quote for such an answer must itself support the stated component. "
                            "For selected evidence written as 'Q: ... A: ...', use the stored A as direct answer evidence when the stored Q addresses "
                            "the customer's paraphrased question; quote the A text rather than treating non-identical wording as missing information. "
                            "A stored same-SKU QA statement that the product has official warranty supports stating that recorded warranty fact, but never an unrecorded duration or policy term. "
                            "Evidence that says suitable, adapted, or compatible with a condition supports only that attributed compatibility statement, never a safety, risk-free, certification, or 'no problem' guarantee without explicit evidence. "
                            + missing_capability_instruction
                            + quote_repair_instruction
                            + "Do not add facts, make assumptions, or use external knowledge. Include one to at most 3 evidence_quotes copied verbatim from the supplied evidence that support the answer; "
                            "each quote must be 60 characters or shorter. "
                            "do not return an answer when no such quote exists. Set answer to NO_EVIDENCE if the evidence cannot answer."
                        ),
                    },
                    {
                        "role": "user",
                        "content": json.dumps(
                            {"question": question, "evidence": evidence_content, "previous_draft": answer},
                            ensure_ascii=False,
                        ),
                    },
                ],
                temperature=0,
                max_tokens=min(int(runtime["max_tokens"]), 360),
                purpose="sealed_same_sku_knowledge_answer_repair",
                api_model_override=runtime["model"],
                response_format=runtime["response_format"],
                thinking=runtime["thinking"],
            )
        except Exception:
            return _return_same_sku_missing("answer_repair_error")
        repaired_payload = customer_agent_planner_service._extract_json_object(str(repaired or "")) or {}
        answer = str(repaired_payload.get("answer") or "").strip()
        answer, repaired_safety_bounded = _bound_unsupported_rag_safety_guarantee(answer, repaired_payload, evidence_content)
        safety_bounded = safety_bounded or repaired_safety_bounded
        repaired_grounded = bool(
            answer
            and answer != "NO_EVIDENCE"
            and await _same_sku_rag_answer_is_grounded_after_quote_validation(
                db,
                question,
                answer,
                repaired_payload,
                evidence_content,
            )
        )
        repaired_complete = bool(
            repaired_grounded
            and await _same_sku_rag_answer_covers_question(
                db,
                question,
                answer,
                evidence_content,
            )
        )
        semantic_answer_coverage_complete = bool(repaired_complete)
        if not repaired_grounded or not repaired_complete:
            return _return_same_sku_missing("answer_grounding_failed")
    # A live, approved ProductQa record is evidence, not a license to dump its
    # historical marketing prose verbatim. Always run the same natural
    # suitability boundary for a marketing-shaped answer; a passed rewrite
    # may retain the recorded conclusion only as an attributed statement.
    # Product-QA answers may be customer-facing evidence without being
    # objective product facts. Always let the semantic suitability pass see a
    # marketing-shaped draft, including when the source is an approved Q/A;
    # the rewrite can preserve the record while attributing its judgement.
    bounded_marketing_answer = _bound_gifting_qa_answer_to_evidence(question, answer)
    if bounded_marketing_answer != answer:
        boundary_rewrite = await _rewrite_suitability_boundary_from_same_sku_evidence(
            db,
            question=question,
            draft=answer,
            evidence=evidence_content,
            evidence_quotes=_same_sku_rag_validated_quotes(answer_payload, evidence_content),
            recorded_qa_selected=selected_has_approved_product_qa,
        )
        if boundary_rewrite is not None:
            rewritten_answer, rewritten_quotes = boundary_rewrite
            if recorded_qa_selected and not any(
                marker in rewritten_answer
                for marker in ("产品问答", "产品资料", "资料描述", "记录中", "问答中", "资料中")
            ):
                # The source is a subjective customer-facing Q/A record.  If
                # Flash omitted the attribution despite the semantic rewrite
                # contract, add only the provenance frame; do not change the
                # recorded conclusion or introduce a product fact.
                rewritten_answer = f"产品问答中将它描述为：{rewritten_answer}"
            rewritten_payload = {"evidence_quotes": rewritten_quotes}
            # The rewrite is checked against the selected same-SKU quotes. Do
            # not send an accepted answer through a second source-type-dependent
            # keyword boundary; that used to turn a valid attributed answer
            # back into the old missing-data template when RAG returned a QA row.
            rewritten_bounded = rewritten_answer
            rewritten_is_natural = (
                "".join(rewritten_answer.split()).rstrip("。！？!?；;，,")
                != "".join(answer.split()).rstrip("。！？!?；;，,")
            )
            rewritten_grounded = await _same_sku_rag_answer_is_grounded_after_quote_validation(
                db,
                question,
                rewritten_answer,
                rewritten_payload,
                evidence_content,
            )
            rewritten_complete = (
                rewritten_grounded
                and await _same_sku_rag_answer_covers_question(
                    db,
                    question,
                    rewritten_answer,
                    evidence_content,
                )
            )
            if rewritten_complete and rewritten_bounded == rewritten_answer and rewritten_is_natural:
                answer = rewritten_answer
                answer_payload = rewritten_payload
                semantic_answer_coverage_complete = True
                bounded_marketing_answer = answer
        if bounded_marketing_answer != answer:
            # The selected packet did contain useful same-SKU facts, but the
            # writer could not turn them into a grounded bounded answer. Keep
            # the customer-facing response specific to this turn rather than
            # returning the old one-line evidence-gate template.
            safe_missing["answer"] = _suitability_boundary_fallback_answer(
                question,
                _same_sku_rag_validated_quotes(answer_payload, evidence_content),
            )
            safe_missing["confidence"] = "medium"
            safe_missing["uncertainty"] = "missing_data"
            safe_missing["evidence"] = []
            safe_missing["sources"] = []
            safe_missing["answer_metadata"] = {
                "contract_field_type": "product_qa",
                "requested_field": "产品问答",
                "evidence_status": "missing",
                "field_evidence_missing": True,
                "evidence_sku": sku,
                "evidence_skus": [],
                "answer_policy": "insufficient_evidence",
            }
            safe_missing_debug = (
                safe_missing.get("debug")
                if isinstance(safe_missing.get("debug"), dict)
                else {}
            )
            safe_missing_debug["agent_mode"] = "sealed_product_qa_safe_missing"
            safe_missing_debug["gifting_evidence_boundary"] = True
            safe_missing["debug"] = safe_missing_debug
            safe_missing["skip_polish"] = True
            return safe_missing
    safe_missing["answer"] = answer
    safe_missing["confidence"] = "high"
    safe_missing["uncertainty"] = "resolved"
    safe_missing["evidence"] = [
        {
            "evidence_id": item.evidence_id,
            "sku": item.sku,
            "field_label": "产品知识库",
            "value": item.value,
            "source_type": item.source_type,
            "source_layer": "RAG",
            "matched_by": "semantic_same_sku_evidence",
        }
        for item in selected_bundle.items
    ]
    safe_missing["sources"] = [{"type": "knowledge_base", "label": "同 SKU 文件知识库", "sku": sku}]
    safe_missing["answer_metadata"] = {
        "contract_field_type": "product_qa",
        "evidence_status": "matched",
        "evidence_sku": sku,
        "evidence_skus": [sku],
        "evidence_bundle_skus": [selected_bundle.sku],
        "evidence_ids": [item.evidence_id for item in selected_bundle.items],
        "evidence_source": "same_sku_knowledge",
        "semantic_answer_coverage_complete": semantic_answer_coverage_complete,
    }
    safe_missing["debug"]["agent_mode"] = "sealed_same_sku_knowledge_rag"
    safe_missing["debug"]["knowledge_evidence_selector"] = {
        "confidence": "high",
        "selection_scope": "same_sku_only",
        "selected_count": len(selected_evidence),
        "coverage": selection_coverage or "legacy_unspecified",
        "selected_evidence": [str(item.get("content") or "")[:240] for item in selected_evidence],
    }
    # This answer has already been written by the customer-facing semantic
    # writer and independently checked against the sealed same-SKU evidence.
    # A second generic polish pass only adds a boilerplate preface and another
    # model call; it cannot improve or expand the permitted evidence.
    safe_missing["skip_polish"] = True
    return safe_missing


def _semantic_product_qa_allows_explicit_missing_clause(phase1_plan: dict[str, Any] | None) -> bool:
    """Use the semantic plan's multi-intent signal before drafting a safe gap.

    This does not infer a product field or capability from wording.  It merely
    keeps a one-intent product overview from being rewritten as if it contained
    a second, unasked customer requirement.
    """
    plan = phase1_plan if isinstance(phase1_plan, dict) else {}
    preplan = plan.get("semantic_preplan") if isinstance(plan.get("semantic_preplan"), dict) else {}
    return bool(
        preplan.get("compound")
        or preplan.get("additional_user_intent")
        or plan.get("compound")
        or plan.get("additional_user_intent")
        # Pairwise comparisons often have one participant with direct
        # supporting evidence and another with only a partial or unverified
        # dimension.  That is a normal comparison result, not a reason to
        # discard the supported participant before the comparison writer can
        # disclose the gap.
        or str(preplan.get("route_family") or "").strip() == "comparison"
    )


def _same_sku_rag_answer_has_selected_quotes(payload: dict[str, Any], evidence: str) -> bool:
    """Require model-supplied provenance snippets to come from selected evidence.

    The semantic selector owns relevance. This deterministic gate only checks
    that the answer generator did not silently rely on a different retrieval
    hit or model memory while turning selected same-SKU evidence into a reply.
    """
    return bool(_same_sku_rag_validated_quotes(payload, evidence))


def _same_sku_rag_validated_quotes(payload: dict[str, Any], evidence: str) -> list[str]:
    """Return only exact, nontrivial provenance quotes from selected evidence."""
    quotes = payload.get("evidence_quotes") if isinstance(payload, dict) else None
    if not isinstance(quotes, list) or not quotes:
        return []
    normalized_evidence = "".join(str(evidence or "").casefold().split())
    if not normalized_evidence:
        return []
    cleaned_quotes = [str(quote or "").strip() for quote in quotes]
    normalized_quotes = ["".join(quote.casefold().split()) for quote in cleaned_quotes]
    if not all(len(quote) >= 4 and quote in normalized_evidence for quote in normalized_quotes):
        return []
    return cleaned_quotes




async def _same_sku_rag_answer_is_grounded_after_quote_validation(
    db: Session,
    question: str,
    answer: str,
    payload: dict[str, Any],
    evidence: str,
) -> bool:
    """Cross-check a cited RAG draft and fail closed on unsupported claims.

    Exact quotes first bind the draft to the semantic selector's same-SKU
    evidence. A grounding rejection cannot be retried into an approval: that
    would make a stochastic verifier a fail-open path for unsupported facts.
    """
    quotes = _same_sku_rag_validated_quotes(payload, evidence)
    if not quotes:
        return False
    # Quotes remain a mandatory provenance receipt, but they are intentionally
    # capped at three short spans.  A concise overview can contain more than
    # three directly selected same-SKU facts, so strict entailment must audit
    # the complete sealed selection rather than mistake uncited selected facts
    # for hallucinations.
    # The strict claim-entailment audit is the delivery gate.  A second,
    # broader relevance-style vote made a directly evidenced compound answer
    # fail merely because another separately requested condition was safely
    # marked as absent from the record.  Coverage remains independently
    # checked below; this gate stays fail-closed on every positive claim.
    return await _same_sku_evidence_answer_is_grounded(
        db,
        question,
        answer,
        evidence,
        strict_entailment=True,
    )


def _customer_safe_same_sku_knowledge_content(content: str) -> str:
    """Remove internal-only catalog fields before any RAG model sees a chunk.

    Product knowledge chunks are assembled from mixed database layers.  The
    product identity and customer-facing fields are valid same-SKU evidence,
    while owner, lifecycle planning status, search terms, and quality/remarks
    are not customer facts.  Filter by the chunk's labelled field boundary,
    rather than by SKU, product name, or customer wording.
    """
    internal_labels = {"负责人", "生命周期", "关键词", "品质情况", "备注"}
    kept: list[str] = []
    for line in str(content or "").splitlines():
        stripped = line.strip()
        label, separator, _ = stripped.lstrip("- ").partition(":")
        if separator and any(internal_label in label.strip() for internal_label in internal_labels):
            continue
        kept.append(line)
    return "\n".join(kept).strip()


def _customer_facing_knowledge_unit(content: str) -> str:
    """Remove import labels from one already selected knowledge unit.

    The unit has already passed same-SKU semantic selection. This adapter does
    not change relevance or facts; it only prevents source-schema labels such
    as ``技术优势`` or ``规格信息`` from becoming customer prose when the
    selected unit is a single structured record.
    """
    value = str(content or "").strip()
    if not value:
        return ""
    lines = [line.strip() for line in value.splitlines() if line.strip()]
    source_field_labels = (
        "技术优势", "使用说明", "核心卖点", "目标人群", "定位", "价格定位",
        "情绪价值", "使用场景", "竞品信息", "尺寸", "容量", "毛重g",
        "材质", "颜色", "表面工艺", "适用热源", "功率", "中文标题",
        "英文标题", "中文描述", "英文描述", "Amazon 标题", "官网标题",
        "五点描述", "中文 Listing", "英文 Listing",
    )
    cleaned: list[str] = []
    for line in lines:
        line = re.sub(
            r"^(?:规格信息|业务信息|内容信息|关联信息|产品\s*QA|差评/负面问题应答)\s*[:：]\s*",
            "",
            line,
            flags=re.IGNORECASE,
        ).strip()
        line = re.sub(r"^[-•]\s*", "", line).strip()
        for label in source_field_labels:
            for prefix in (f"{label}：", f"{label}:"):
                if line.startswith(prefix):
                    line = line[len(prefix):].strip()
                    break
            else:
                continue
            break
        if line:
            cleaned.append(line)
    return "；".join(cleaned).strip("； ")


def _same_sku_knowledge_evidence_units(content: str) -> list[str]:
    """Expose independently auditable paragraphs from a sealed knowledge chunk.

    This is source-agnostic: it does not identify a field, infer a fact, or
    select an answer. It only prevents unrelated facts in one imported document
    from being treated as one evidence claim. Imported product profiles are
    often newline-delimited rather than blank-line-delimited, so a whole
    profile must not remain one retrieval unit: otherwise a selector can find
    the right product while the writer still receives every field and may
    reproduce the raw record.
    """
    text = str(content or "").strip()
    if not text:
        return []
    lines = [line.strip() for line in text.splitlines()]
    section_or_field = re.compile(
        r"^(?:(?:SKU|Q|A|中文名|英文名|品牌|系列|类目|等级|生命周期|负责人|规格信息|业务信息|"
        r"内容信息|关联信息|产品\s*QA|差评/负面问题应答)\s*[:：]|"
        r"[-•]\s*[^:：\n]{1,32}\s*[:：])",
        flags=re.IGNORECASE,
    )
    units: list[str] = []
    current: list[str] = []
    current_is_qa = False

    def flush() -> None:
        nonlocal current, current_is_qa
        value = "\n".join(item for item in current if item).strip()
        if value:
            units.append(value)
        current = []
        current_is_qa = False

    for line in lines:
        if not line:
            flush()
            continue
        is_q = bool(re.match(r"^Q\s*[:：]", line, flags=re.IGNORECASE))
        is_structured_boundary = bool(section_or_field.match(line))
        # Keep a stored Q and its A together. Other labelled lines are
        # independently auditable source units; numbered continuation lines
        # stay attached to the preceding usage/instruction field.
        if is_q:
            flush()
            current = [line]
            current_is_qa = True
            continue
        if current_is_qa:
            current.append(line)
            continue
        if is_structured_boundary and current:
            flush()
        current.append(line)
    flush()

    if not units:
        units = [text]
    atomic: list[str] = []
    for unit in units:
        if re.match(r"^Q\s*[:：]", unit, flags=re.IGNORECASE):
            atomic.append(unit)
            continue
        pieces = [
            piece.strip()
            for piece in re.split(r"(?<=[。！？!?])\s*", unit)
            if piece.strip()
        ]
        for piece in pieces or [unit]:
            # Some imported profiles arrive as one semicolon-delimited record
            # rather than labelled lines. Keep natural prose intact, but
            # split a record when several source-field labels prove that the
            # delimiters separate independent catalogue values. This keeps
            # the semantic selector from citing an entire raw profile for a
            # single comparison dimension.
            record_labels = re.findall(
                r"(?:SKU|Q|A|中文名|英文名|品牌|系列|类目|等级|生命周期|负责人|"
                r"规格信息|业务信息|内容信息|关联信息|产品\s*QA|差评/负面问题应答|"
                r"label|value)\s*[:：]",
                piece,
                flags=re.IGNORECASE,
            )
            if len(record_labels) >= 2 and re.search(r"[；;]", piece):
                atomic.extend(
                    fragment.strip()
                    for fragment in re.split(r"[；;]\s*", piece)
                    if fragment.strip()
                )
            else:
                atomic.append(piece)
    return list(dict.fromkeys(atomic))


async def _same_sku_evidence_answer_is_grounded(
    db: Session,
    question: str,
    answer: str,
    evidence: str,
    *,
    strict_entailment: bool = False,
) -> bool:
    """Verify a generated RAG answer before it becomes a customer fact."""
    runtime = customer_agent_planner_service._semantic_preplan_runtime_settings()
    try:
        raw = await customer_llm_service.chat_completion(
            db,
            messages=(
                _same_sku_knowledge_strict_entailment_messages(question, answer, evidence)
                if strict_entailment
                else _same_sku_knowledge_grounding_messages(question, answer, evidence)
            ),
            temperature=0,
            max_tokens=min(int(runtime["max_tokens"]), 80),
            purpose=(
                "sealed_same_sku_knowledge_strict_entailment"
                if strict_entailment
                else "sealed_same_sku_knowledge_grounding"
            ),
            api_model_override=runtime["model"],
            response_format=runtime["response_format"],
            thinking=runtime["thinking"],
        )
    except Exception:
        return False
    verdict = customer_agent_planner_service._extract_json_object(str(raw or "")) or {}
    return verdict.get("grounded") is True


async def _same_sku_rag_answer_covers_question(
    db: Session,
    question: str,
    answer: str,
    evidence: str,
) -> bool:
    """Ask the semantic layer whether a sealed draft covers every customer ask.

    This is deliberately separate from factual grounding.  It cannot select a
    route, field, SKU, or evidence; it only catches a generated reply that
    leaves an independent part of a compound customer question unanswered.
    """
    runtime = customer_agent_planner_service._semantic_preplan_runtime_settings()
    try:
        raw = await customer_llm_service.chat_completion(
            db,
            messages=_same_sku_knowledge_coverage_messages(question, answer, evidence),
            temperature=0,
            max_tokens=min(int(runtime["max_tokens"]), 80),
            purpose="sealed_same_sku_knowledge_coverage",
            api_model_override=runtime["model"],
            response_format=runtime["response_format"],
            thinking=runtime["thinking"],
        )
    except Exception:
        return False
    verdict = customer_agent_planner_service._extract_json_object(str(raw or "")) or {}
    return (
        verdict.get("complete") is True
        and verdict.get("internally_consistent", True) is True
    )


def _same_sku_knowledge_grounding_messages(
    question: str,
    answer: str,
    evidence: str,
) -> list[dict[str, str]]:
    """Build the evidence-faithfulness check for a sealed product RAG answer."""
    return [
        {
            "role": "system",
            "content": (
                "Return only JSON: {grounded:boolean}. The upstream semantic evidence selector has already decided that the supplied same-product evidence is relevant to the current request. "
                "Do not override the upstream semantic evidence selection by demanding a separate source that repeats the request's scenario wording. "
                "grounded is true when the answer faithfully states one or more supplied evidence facts without adding a fact, limitation, promise, comparison, or inference not in evidence. "
                "Use the supplied customer question only to identify the conditions that the draft claims to answer; it must not change the route, identity, or evidence selection. "
                "Approve a claimed condition only when the evidence directly supports that condition or conclusion. For a recommendation answer, a natural same-SKU paraphrase is allowed when it preserves the recorded meaning (for example, 水性不沾 can answer a request for 不粘涂层), and several recorded fields may be combined into a bounded practical suggestion (for example, a people range plus capacity and scene can support a conditional group-size reference). Do not turn that synthesis into an appetite guarantee, unusual-environment capability, safety claim, compatibility promise, or different specification. A related property, specification, range, or general benefit does not by itself support a distinct duration, environment, causal guarantee, compatibility, or safety conclusion. For an operation-simplicity or ease-of-use request, high-efficiency heating, fast boiling, even heat distribution, capacity, light weight, non-stick finish, or easy cleaning does not entail that operation is simple or easy to learn; the evidence must explicitly describe operation or learning ease, and a draft that adds that claim before a caveat is not grounded. "
                "Evidence that says suitable, adapted, or compatible with a condition supports only that attributed compatibility statement; it does not prove safety, no risk, certification, or that there will be no problem unless those stronger claims are explicitly present. "
                "Absence of evidence never proves a negative claim: a product being manual, unpowered, or described for one capability does not by itself prove "
                "that it cannot perform a different capability. Require an explicit supporting fact before approving any no, cannot, does-not, unsupported, "
                "or other negative product assertion. "
                "For a compound question, it is allowed to keep a directly supported part and state that the supplied evidence does not directly confirm another requested capability, "
                "provided this is not presented as a negative product fact. "
                "The same boundary applies when the customer names an unusual environment or capability that the supplied product record does not cover: a plain statement that the catalogue does not verify that requested condition is allowed, even when the record contains no matching phrase. Do not add a physical explanation or turn the boundary into 'cannot' or 'unsafe'. "
                "Treat product-title, model, version, compatibility, or configuration descriptors embedded in the question as identity context, "
                "not independent unanswered customer conditions, unless the customer separately asks to verify that descriptor. "
                "For a broad preparation, overview, or decision question, directly selected product traits may answer the question without a separate travel, preparation, or scenario guide. "
                "Do not require the answer to exhaust every possible product consideration or every detail absent from the selected evidence; "
                "a concise answer that directly addresses the question using verified evidence is grounded. "
                "Return false when the answer says a recorded fact is missing or adds unsupported content."
            ),
        },
        {
            "role": "user",
            # Relevance remains sealed by semantic selection. The raw question
            # is supplied only so this verifier can distinguish a direct
            # evidence-backed fact from a newly inferred customer condition;
            # it has no authority to choose route, field, identity, or evidence.
            "content": json.dumps({"question": question, "answer": answer, "evidence": evidence}, ensure_ascii=False),
        },
    ]


def _same_sku_knowledge_strict_entailment_messages(
    question: str,
    answer: str,
    evidence: str,
) -> list[dict[str, str]]:
    """Build an adversarial claim-entailment audit for a sealed RAG draft."""
    return [
        {
            "role": "system",
            "content": (
                "Return only JSON: {grounded:boolean}. Audit strict evidence entailment, not route selection. "
                "The product, route, and same-SKU evidence are already sealed and cannot be changed. "
                "Use the customer question only to identify which conditions the draft purports to answer. "
                "Return true only if every factual conclusion, promise, condition, duration, environment, causal implication, compatibility, or safety statement in the draft is directly stated by the supplied evidence. "
                "A faithful concise synthesis of several directly stated same-product traits is allowed, including ordinary same-language paraphrase or grouping; "
                "do not reject it merely because no one source sentence repeats the combined wording. "
                "Customer-facing framing such as what to know before taking a product out, whether it fits a plan, or what to consider is not itself a new product claim; "
                "when the selected evidence directly states traits or applicable scenes, summarizing those facts for that framing is allowed. "
                "For a suitability or decision request, a draft may present directly stated decision-support factors and explicitly say the records do not directly "
                "establish the requested final suitability judgement. That evidence-boundary sentence is allowed; a definitive suitable/unsuitable conclusion still "
                "requires direct evidence. "
                "A related property, specification, numeric range, or general benefit is not enough to prove a distinct condition or conclusion. "
                "A statement about how many physical items are included in a package requires evidence that directly states the included quantity or package composition. "
                "Never infer included quantity from a product title, serving or user count, capacity descriptor, model number, or a statement that the product meets a number of users' needs. "
                "One narrow exception is transparent conservative boundary reasoning: when the evidence explicitly states a numeric operating range and the customer's "
                "named condition unambiguously falls outside it, the draft may state the recorded range and say that condition is outside the recorded range or is not recommended. "
                "When the named condition is a universally defined physical threshold (for example freshly boiling water), normalizing that threshold to the standard measurement needed for that boundary comparison is allowed. "
                "This permits only the arithmetic comparison against the recorded range; it does not add a product fact, hidden tolerance, failure mode, or safety guarantee. "
                "Example that must return grounded=true: evidence records 32°F to 140°F, the customer asks about freshly boiling water, and the draft says the recorded upper limit is 140°F (60°C), freshly boiling water exceeds it, so direct filling is not recommended. "
                "This exception does not permit an unrecorded failure mode, hidden tolerance, safety guarantee, or stronger cannot/unsafe claim. "
                "A supplied same-SKU QA statement that the product has official warranty directly entails the bounded claim that the record states official warranty. "
                "It never entails a warranty duration, coverage term, or any policy detail absent from that statement. "
                "For a semantic compound question, a statement that the supplied evidence does not directly confirm a separately requested condition is allowed "
                "when it is plainly an evidence boundary, not a negative product fact or product conclusion. Such a bounded record-coverage statement "
                "does not need separate product evidence and must not be rejected merely because the record is silent on that separate condition. "
                "Do not rely on common knowledge or plausible inference beyond this narrow threshold normalization. If any other claim needs an inference beyond the evidence, return false."
            ),
        },
        {
            "role": "user",
            "content": json.dumps(
                {"question": question, "answer": answer, "evidence": evidence},
                ensure_ascii=False,
            ),
        },
    ]


def _same_sku_knowledge_coverage_messages(
    question: str,
    answer: str,
    evidence: str,
) -> list[dict[str, str]]:
    """Build a semantic answer-coverage audit without granting new evidence."""
    return [
        {
            "role": "system",
            "content": (
                "Return only JSON: {complete:boolean,internally_consistent:boolean}. You are a coverage auditor and internal-consistency auditor, not a route planner or answer writer. "
                "Decide whether the draft addresses every independently requested product fact in the complete customer question. "
                "A compound question is complete only when every part is either answered from the supplied same-product evidence "
                "or explicitly and safely stated as not directly confirmed by that evidence. "
                "Return false when a draft both resolves a condition and says that same condition is not confirmed or missing; that contradiction must be rewritten. "
                "Return true when the draft both gives a directly evidenced part and names the other separately requested condition as not directly confirmed by the supplied evidence; "
                "that is a complete evidence-boundary answer, not an unsupported negative product claim. "
                "A factually grounded answer that silently omits an independent requested capability is incomplete. "
                "A draft that only acknowledges the request, offers to list information, or gives a generic lead without stating at least one "
                "concrete fact from the supplied evidence is incomplete, even when its evidence_quotes are valid. "
                "A broad overview or decision question (for example asking what to notice, consider, or weigh) is one request for a useful synthesis, "
                "not a list of hidden capabilities. Do not invent an independent requested condition, use case, accessory, or performance criterion "
                "from that broad wording, from a product name, or from an illustrative phrase in the draft. "
                "Only state that evidence does not directly confirm something when the question explicitly asks a separate capability or condition; "
                "do not return false merely because the evidence cannot resolve that named separate condition. "
                "Do not require an answer to introduce facts absent from the evidence, and do not treat evidence absence as a negative product fact."
            ),
        },
        {
            "role": "user",
            "content": json.dumps(
                {"question": question, "answer": answer, "evidence": evidence},
                ensure_ascii=False,
            ),
        },
    ]


def _safe_missing_product_qa_answer(name: str, sku: str, question: str) -> str:
    """Keep a safe missing answer specific enough to be useful to a shopper."""
    # Do not quote proposed values from the question.  A safe-missing answer
    # that repeats an unverified rating, certification, or number can look as
    # though the catalogue supports it and also leaks unsupported values into
    # downstream evidence checks.
    return (
        f"{name}（{sku}）在目录中有记录，但现有同 SKU 资料没有直接说明你问到的这项能力，暂时不能确认。"
        "不能把相近商品的资料套到这款上；如它会影响购买或使用，请以官方规格或人工核验为准。"
    )


def _sealed_semantic_product_qa_entity_guard(
    db: Session,
    question: str,
    phase1_plan: dict[str, Any] | None,
) -> dict | None:
    """Fail closed before legacy retrieval can answer an unsealed QA turn."""
    if not _semantic_prefers_sealed_product_qa(phase1_plan or {}):
        return None
    preplan = (phase1_plan or {}).get("semantic_preplan") if isinstance(phase1_plan, dict) else {}
    subject = str((preplan or {}).get("subject_text") or "").strip()
    if not subject:
        return None
    versioned_subject = customer_entity_resolution_contract.recover_explicit_versioned_subject(
        question,
        subject,
    )
    if versioned_subject:
        subject = versioned_subject
    products = db.query(Product).order_by(Product.sku.asc()).all()
    resolver_candidates = _products_named_in_question(db, question)
    # The semantic planner decides the QA meaning, while the catalogue owns
    # identity. A unique canonical name explicitly present in this turn is
    # therefore stronger than a semantic subject that either absorbs predicate
    # words or drops a meaning-bearing name prefix. This supplies only the
    # validated display span, never an SKU, field, or answer; ambiguity still
    # fails closed in the entity contract below.
    canonical_subject = customer_entity_resolution_contract.unique_canonical_subject_in_question(
        question,
        products,
    )
    if canonical_subject:
        subject = canonical_subject
    contract = customer_entity_resolution_contract.build_entity_resolution_contract(
        question,
        products,
        resolver_candidates=resolver_candidates or None,
        entity_text_override=subject,
        field_type_override="product_qa",
    )
    resolution = customer_entity_resolution_contract.can_resolve_single_product(contract, products)
    field_contract = {
        "field_type": "product_qa",
        "requested_field": "产品问答",
        "requested_fields": ["产品问答"],
        "canonical_fields": ["product_qa"],
        "supported_fields": ["product_qa"],
        "unsupported_fields": [],
        "subject": subject,
        "requested_scope": "subject",
        "source": "validated_semantic_product_qa",
        "confidence": float((preplan or {}).get("confidence") or 0),
        "compound": False,
    }
    if not resolution.allowed:
        action = "ambiguous_clarification" if contract.status == "ambiguous" else "unresolved_clarification"
        result = _build_phase2_entity_state_response(
            db,
            question,
            {
                "action": action,
                "contract": contract,
                "products": products,
                "displayable_candidate_skus": _displayable_phase2_clarification_candidate_skus(contract),
            },
        )
        if isinstance(result, dict):
            debug = result.setdefault("debug", {})
            debug["field_contract"] = field_contract
            debug["agent_mode"] = "sealed_product_qa_entity_clarification"
        return result

    product = next((item for item in products if str(item.sku or "").strip().upper() == resolution.resolved_sku), None)
    if product is None:
        return None
    sku = str(product.sku or "").strip().upper()
    name = str(product.product_name_cn or product.product_name_en or sku).strip()
    answer = _safe_missing_product_qa_answer(name, sku, question)
    return _sealed_product_qa_safe_missing_result(
        product,
        answer,
        field_contract=field_contract,
        debug={
            "entity_resolution_contract": contract.to_dict(),
            "binding_provenance": "resolved_entity_contract",
        },
    )


def _is_exact_product_qa_question_match(qa: ProductQa, question: str) -> bool:
    qa_question = _normalize_qa_question_text(qa.question or "")
    user_question = _normalize_qa_question_text(question or "")
    # Substring containment would let an old QA consume an added condition or
    # a second question. Natural rewrites are handled by semantic selection.
    return bool(qa_question and qa_question == user_question)


def _normalize_qa_question_text(question: str) -> str:
    text = re.sub(r"[（(]\s*[A-Za-z0-9]+(?:[-_][A-Za-z0-9]+)+\s*[）)]", "", str(question or ""))
    text = text.translate(str.maketrans("", "", "「」『』“”"))
    text = customer_agent_service.normalize_search_text(text)
    return re.sub(r"[?？。!！]+$", "", text).rstrip()


def _has_direct_structured_detail_answer(db: Session, product: Product, question: str) -> bool:
    """Keep exact field reads on the deterministic product_detail path."""
    text = str(question or "")
    if not text:
        return False
    field_groups = (
        (("热源", "适用热源", "燃料", "适用燃料"), ("heat_source",)),
        (("材质", "材料", "主体材质"), ("body_material",)),
        (("容量", "规格"), ("capacity",)),
        (("重量", "净重", "毛重"), ("gross_weight_g", "net_weight_g")),
        (("尺寸", "大小"), ("dimensions", "package_size")),
        (("颜色",), ("color",)),
        (("功率",), ("power",)),
        (("表面处理", "表面工艺"), ("surface_finish",)),
        (("适用人群", "适合哪些人群", "适合几人", "适合几个人"), ("target_audience",)),
    )
    matched_fields: tuple[str, ...] = ()
    for terms, fields in field_groups:
        if any(term in text for term in terms):
            matched_fields = fields
            break
    if not matched_fields:
        if "洗碗机" in text:
            detail = product_service.get_product_detail(db, product.sku)
            specs = detail.get("specs") or {}
            return bool(_dishwasher_specific_evidence(specs.get("usage_instruction")))
        return False
    detail = product_service.get_product_detail(db, product.sku)
    specs = detail.get("specs") or {}
    for field in matched_fields:
        if _display_value(specs.get(field)):
            return True
    return False


def _explicit_product_from_question(db: Session, question: str) -> Product | None:
    sku = _resolve_sku(db, question, None)
    if sku:
        product = db.query(Product).filter(Product.sku == sku).first()
        if product:
            return product
    normalized_question = customer_agent_service.normalize_search_text(question)
    if not normalized_question:
        return None
    matches: list[tuple[int, int, Product]] = []
    for product in db.query(Product).all():
        names = [
            customer_agent_service.normalize_search_text(product.product_name_cn or ""),
            customer_agent_service.normalize_search_text(product.product_name_en or ""),
        ]
        for name in names:
            if not name or name not in normalized_question:
                continue
            matches.append((normalized_question.index(name), -len(name), product))
            break
    if not matches:
        return _product_from_exact_qa_question(db, question)
    matches.sort(key=lambda item: (item[0], item[1]))
    return matches[0][2]


def _product_from_exact_qa_question(db: Session, question: str) -> Product | None:
    normalized_question = _normalize_qa_question_text(question)
    if not normalized_question:
        return None
    exact_qa = db.query(ProductQa).filter(
        ProductQa.question == str(question or "").strip(),
        ProductQa.integrity_status == "approved",
    ).first()
    if exact_qa and exact_qa.product_id:
        product = db.query(Product).filter(Product.id == exact_qa.product_id).first()
        if product:
            return product
    qa_matches: list[tuple[int, ProductQa]] = []
    for qa in db.query(ProductQa).filter(
        ProductQa.integrity_status == "approved",
    ).order_by(ProductQa.priority.desc().nullslast(), ProductQa.updated_at.desc()).all():
        qa_question = _normalize_qa_question_text(qa.question or "")
        if qa_question and qa_question in normalized_question:
            qa_matches.append((len(qa_question), qa))
    if not qa_matches:
        return None
    qa_matches.sort(key=lambda item: item[0], reverse=True)
    product_id = qa_matches[0][1].product_id
    if not product_id:
        return None
    return db.query(Product).filter(Product.id == product_id).first()


def _best_product_qa_match(
    db: Session,
    product: Product,
    question: str,
    *,
    requested_field_type: str | None = None,
    semantic_query: str | None = None,
) -> ProductQa | None:
    qas = product_service.customer_visible_product_qas(db, product.id)[:20]
    if not qas:
        return None
    question_terms = _qa_match_terms(question)
    semantic_terms = _qa_semantic_similarity_terms(semantic_query) if semantic_query else set()
    requested_qa_type = requested_field_type or customer_field_contract.classify_product_qa_request_type(question)
    best: tuple[int, ProductQa] | None = None
    for qa in qas:
        exact_question_match = _is_exact_product_qa_question_match(qa, question)
        field_compatible_qa = bool(requested_field_type and customer_field_contract.qa_evidence_matches_field(
            str(qa.question or ""),
            str(getattr(qa, "tags", "") or ""),
            requested_field_type,
        ))
        if requested_field_type and not field_compatible_qa and not exact_question_match:
            continue
        qa_text = f"{qa.question or ''} {qa.answer or ''}"
        qa_terms = _qa_match_terms(qa_text)
        overlap = question_terms & qa_terms
        # The semantic retrieval phrase represents the requested QA intent.
        # Match it only to the stored QA's request-side metadata, never to an
        # answer body.  Generic prose such as “正常使用” or “适合” in an answer
        # must not cause an unrelated same-SKU QA to win retrieval.
        qa_retrieval_text = f"{qa.question or ''} {getattr(qa, 'tags', '') or ''}"
        semantic_overlap = semantic_terms & _qa_semantic_similarity_terms(qa_retrieval_text)
        if semantic_query and not semantic_overlap and not exact_question_match:
            # Once semantic preplanning has sealed product-QA intent, an
            # unaligned candidate is not evidence. Fail closed rather than
            # falling back to legacy QA priority or answer-word matching.
            continue
        evidence_type = customer_field_contract.classify_product_qa_evidence_type(
            str(qa.question or ""),
            str(getattr(qa, "tags", "") or ""),
        )
        if not customer_field_contract.is_qa_evidence_compatible(
            requested_qa_type,
            evidence_type,
            has_semantic_overlap=bool(overlap or semantic_overlap),
        ) and not exact_question_match and not field_compatible_qa:
            continue
        score = len(overlap) + (2 * len(semantic_overlap))
        if exact_question_match:
            score += 8
        if requested_qa_type != "unknown" and requested_qa_type == evidence_type:
            score += 1
        elif field_compatible_qa:
            score += 1
        if score <= 0:
            continue
        if best is None or score > best[0]:
            best = (score, qa)
    return best[1] if best else None


def _qa_match_terms(text: str) -> set[str]:
    value = str(text or "")
    terms = set()
    for term in (
        "燃料", "热源", "气罐", "高山气罐", "卡式气罐", "酒精",
        "核心卖点", "卖点", "棋盘格", "材质", "耐用", "不易打滑", "易清洁",
        "正常使用", "正确保养", "使用多年", "越用越顺手", "用多久",
    ):
        if term in value:
            terms.add(term)
    for token in re.findall(r"[A-Za-z0-9]+", value.lower()):
        if len(token) >= 2:
            terms.add(token)
    return terms


def _qa_semantic_similarity_terms(text: str | None) -> set[str]:
    """Build language-agnostic retrieval tokens for an LLM-provided QA intent.

    This is evidence retrieval, not a route classifier: it never chooses a
    SKU, changes the semantic field, or authorizes an answer.  The caller has
    already required a high-confidence semantic ``product_qa`` decision and a
    sealed same-SKU entity contract.  CJK character n-grams make normal
    paraphrases comparable without maintaining a phrase whitelist.
    """
    normalized = customer_agent_service.normalize_search_text(str(text or "")).lower()
    terms: set[str] = set()
    for span in re.findall(r"[\u4e00-\u9fff]{2,}", normalized):
        for size in (2, 3):
            terms.update(span[index:index + size] for index in range(max(0, len(span) - size + 1)))
    for token in re.findall(r"[a-z0-9]{2,}", normalized):
        terms.add(token)
    return terms


def _get_or_create_conversation(
    db: Session,
    user_id: str,
    question: str,
    sku: str | None,
    conversation_id: str | None,
) -> CustomerServiceConversation:
    user_id = str(user_id)
    if conversation_id:
        conversation = db.query(CustomerServiceConversation).filter(
            CustomerServiceConversation.id == conversation_id,
            CustomerServiceConversation.user_id == user_id,
        ).first()
        if not conversation:
            raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="客服会话不存在")
        return conversation

    # SQLite permits one writer at a time.  A short, bounded retry makes
    # independent customer sessions robust under concurrent first messages
    # without conflating users, swallowing other persistence failures, or
    # changing any product/field answer contract.
    for attempt in range(5):
        conversation = CustomerServiceConversation(
            user_id=user_id,
            title=_make_title(question, sku),
            sku=sku,
        )
        db.add(conversation)
        try:
            db.flush()
            return conversation
        except OperationalError as exc:
            message = str(exc).casefold()
            transient_sqlite_lock = "sqlite" in message and "locked" in message
            if not transient_sqlite_lock or attempt == 4:
                raise
            db.rollback()
            sleep(0.01 * (2 ** attempt))

    raise RuntimeError("unreachable conversation creation retry state")


def _touch_conversation(conversation: CustomerServiceConversation, sku: str | None = None) -> None:
    if sku:
        conversation.sku = sku
    conversation.updated_at = datetime.now(timezone.utc)


def update_active_product_anchor(
    *,
    previous_anchor: str | None,
    current_result_skus: list[str],
    answer_type: str,
    user_question: str,
    replacement_recommendation: bool = False,
) -> tuple[str | None, str]:
    previous = str(previous_anchor or "").strip().upper() or None
    if any(term in str(user_question or "") for term in ("不说这个了", "换个话题", "重新开始", "清空上下文")):
        return None, "explicit_reset"
    confirmed = [str(sku or "").strip().upper() for sku in current_result_skus if str(sku or "").strip()]
    if answer_type == "product_detail" and len(confirmed) == 1:
        return confirmed[0], "confirmed_single_product"
    if answer_type in {"comparison", "recommendation"} and len(confirmed) == 1:
        if answer_type == "recommendation" and replacement_recommendation and previous:
            return previous, "preserved_for_replacement_recommendation"
        return confirmed[0], "single_selected_product"
    if previous:
        return previous, "preserved_without_new_single_product"
    return None, "no_active_single_product"


def _sources_with_result_context(
    agent_result: dict,
    turn_index: int | None = None,
    user_question: str | None = None,
    inherited_recommendation_context: dict | None = None,
    inherited_candidate_context: dict | None = None,
) -> list[dict]:
    sources = list(agent_result.get("sources") or [])
    existing_meta_entry = next(
        (
            item
            for item in sources
            if isinstance(item, dict)
            and item.get("type") == "agent_meta"
        ),
        None,
    )
    entities = _entities_from_agent_result(agent_result)
    if "result_skus" in agent_result:
        result_skus = [
            str(sku or "").strip().upper()
            for sku in (agent_result.get("result_skus") or [])
            if str(sku or "").strip()
        ]
        allowed_skus = set(result_skus)
        entities = [item for item in entities if item.get("sku") in allowed_skus]
    else:
        result_skus = [item["sku"] for item in entities]
    answer_ordered_skus = _order_skus_by_answer(result_skus, str(agent_result.get("answer") or ""))
    if answer_ordered_skus:
        result_skus = answer_ordered_skus
    recommendation_context = None
    candidate_context = None
    existing_candidate_context = next(
        (
            item.get("candidate_context")
            for item in sources
            if isinstance(item, dict)
            and item.get("type") == "agent_meta"
            and isinstance(item.get("candidate_context"), dict)
        ),
        {},
    )
    product_scope = customer_dialogue_state.product_scope_from_text(str(user_question or ""))
    if not product_scope and isinstance(inherited_recommendation_context, dict):
        product_scope = str(inherited_recommendation_context.get("product_scope") or "").strip()
    if not product_scope and isinstance(inherited_candidate_context, dict):
        product_scope = str(inherited_candidate_context.get("product_scope") or "").strip()
    inherited_candidate_skus = [
        str(sku).strip().upper()
        for sku in ((inherited_candidate_context or {}).get("candidate_skus") or [])
        if str(sku or "").strip()
    ]
    inherited_ordered_skus = [
        str(sku).strip().upper()
        for sku in (
            (inherited_candidate_context or {}).get("ordered_result_skus")
            or inherited_candidate_skus
            or []
        )
        if str(sku or "").strip()
    ]
    inherited_original_candidate_skus = [
        str(sku).strip().upper()
        for sku in (
            (existing_candidate_context or {}).get("original_candidate_skus")
            or (existing_candidate_context or {}).get("parent_candidate_skus")
            or (inherited_candidate_context or {}).get("original_candidate_skus")
            or (inherited_candidate_context or {}).get("parent_candidate_skus")
            or inherited_ordered_skus
            or inherited_candidate_skus
            or []
        )
        if str(sku or "").strip()
    ]
    current_ordered_skus = [
        str(sku).strip().upper()
        for sku in result_skus
        if str(sku or "").strip()
    ]
    result_metadata = agent_result.get("answer_metadata") if isinstance(agent_result.get("answer_metadata"), dict) else {}
    current_scope_skus = _normalized_recommendation_scope_skus(
        result_metadata.get("recommendation_scope_skus")
    )
    inherited_scope_skus = (
        _normalized_recommendation_scope_skus(
            (inherited_recommendation_context or {}).get("result_reference_scope_skus")
        )
        or _normalized_recommendation_scope_skus(
            (inherited_candidate_context or {}).get("result_reference_scope_skus")
        )
        or _normalized_recommendation_scope_skus(
            (existing_candidate_context or {}).get("result_reference_scope_skus")
        )
    )
    debug_metadata = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    answer_type = str(agent_result.get("answer_type") or "").strip()
    metadata_source = str(result_metadata.get("source") or "").strip()
    debug_agent_mode = str(debug_metadata.get("agent_mode") or "").strip()
    recommendation_like = bool(
        answer_type == "recommendation"
        or (
            answer_type in {"product_query", "query_products"}
            and (
                str(agent_result.get("intent") or "").strip() in {"recommendation", "recommend_products"}
                or metadata_source in {
                    "product_catalog_structured_recommendation",
                    "validated_semantic_preplan_then_same_sku_verification",
                }
                or debug_agent_mode == "semantic_recommendation_contract"
            )
        )
    )
    context_detail_from_inherited_candidate_domain = bool(
        answer_type == "product_detail"
        and inherited_candidate_skus
        and current_ordered_skus
        and set(current_ordered_skus).issubset(set(inherited_candidate_skus))
        and bool(
            (debug_metadata.get("semantic_preplan") or {}).get("context_result_indexes")
            if isinstance(debug_metadata.get("semantic_preplan"), dict)
            else False
        )
    )
    result_debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    verified_candidate_skus = [
        str(sku).strip().upper()
        for sku in (agent_result.get("candidate_skus") or [])
        if str(sku or "").strip()
    ]
    if len(verified_candidate_skus) < 2:
        for key in ("all_verified_candidate_skus", "verified_candidate_skus"):
            verified_candidate_skus = [
                str(sku).strip().upper()
                for sku in result_debug.get(key) or []
                if str(sku or "").strip()
            ]
            if len(verified_candidate_skus) >= 2:
                break
    verified_candidate_skus = list(dict.fromkeys(verified_candidate_skus))[:10]
    final_choice_sku = str(result_metadata.get("final_choice_sku") or "").strip().upper()
    if final_choice_sku not in set(current_ordered_skus):
        final_choice_sku = ""
    context_choice_participant_skus = [
        str(sku or "").strip().upper()
        for sku in (result_metadata.get("context_result_skus") or [])
        if str(sku or "").strip()
    ] if result_metadata.get("source") == "semantic_pairwise_context_choice_contract" else []
    replacement_recommendation = (
        str(result_debug.get("agent_mode") or "") == "recommendation_context_alternative_followup"
        or str(result_metadata.get("source") or "") == "recommendation_context_alternative_followup"
    )
    result_reference_skus = (
        inherited_ordered_skus
        or inherited_original_candidate_skus
        or current_ordered_skus
    ) if replacement_recommendation else current_ordered_skus
    active_anchor, anchor_update_reason = update_active_product_anchor(
        previous_anchor=(inherited_recommendation_context or {}).get("active_single_product_anchor"),
        current_result_skus=current_ordered_skus,
        answer_type=str(agent_result.get("answer_type") or ""),
        user_question=str(user_question or ""),
        replacement_recommendation=replacement_recommendation,
    )
    # A comparison/recommendation may return several ordered rows while also
    # recording one evidence-backed decision.  That explicit final choice is
    # the singular discourse target for “the one just selected”; list order
    # must not silently replace it with the first participant.
    if final_choice_sku:
        active_anchor = final_choice_sku
        anchor_update_reason = "explicit_final_choice"
    preserve_inherited_candidate_domain = bool(
        (recommendation_like or context_detail_from_inherited_candidate_domain)
        and inherited_candidate_skus
        and result_skus
        and set(result_skus).issubset(set(inherited_candidate_skus))
    )
    if result_skus and (
        agent_result.get("answer_type") in {"query_products", "product_query", "recommendation", "comparison"}
        or context_detail_from_inherited_candidate_domain
    ):
        comparison_like = agent_result.get("answer_type") == "comparison"
        # Participant order remains available for result-context follow-ups. When
        # the answer records a final choice, that choice is the singular
        # discourse referent for phrases such as "the one just selected".
        last_referenced_sku = final_choice_sku or (
            current_ordered_skus[0] if current_ordered_skus else None
        )
        candidate_domain_skus = (
            context_choice_participant_skus
            if context_choice_participant_skus
            else inherited_candidate_skus
            if preserve_inherited_candidate_domain
            else verified_candidate_skus
            if recommendation_like and len(verified_candidate_skus) >= 2
            else current_ordered_skus
        )
        candidate_context = {
            "candidate_skus": candidate_domain_skus,
            "result_reference_scope_skus": current_scope_skus or inherited_scope_skus,
            "ordered_result_skus": (
                context_choice_participant_skus
                if context_choice_participant_skus
                else inherited_ordered_skus
                if preserve_inherited_candidate_domain
                else candidate_domain_skus
            ),
            "recommended_skus": result_skus if recommendation_like else [],
            "final_choice_sku": final_choice_sku or None,
            "pair_skus": (
                context_choice_participant_skus[:2]
                if context_choice_participant_skus and len(context_choice_participant_skus) >= 2
                else current_ordered_skus[:2]
                if comparison_like and len(current_ordered_skus) >= 2
                else []
            ),
            "user_question": str(user_question or "").strip(),
            "product_scope": product_scope,
            "last_referenced_sku": last_referenced_sku,
            "source": (
                "recommendation"
                if recommendation_like or agent_result.get("intent") == "recommend_products"
                else "comparison"
                if agent_result.get("answer_type") == "comparison"
                else "result"
            ),
        }
    elif _is_empty_candidate_subset_result(agent_result, inherited_candidate_skus):
        candidate_context = {
            "candidate_skus": [],
            "result_reference_scope_skus": inherited_scope_skus,
            "ordered_result_skus": [],
            "filtered_skus": [],
            "original_candidate_skus": inherited_original_candidate_skus,
            "parent_candidate_skus": inherited_original_candidate_skus,
            "recommended_skus": [],
            "user_question": str(user_question or "").strip(),
            "product_scope": product_scope,
            "empty_subset": True,
            "applied_filter": (
                (existing_candidate_context or {}).get("applied_filter")
                if isinstance((existing_candidate_context or {}).get("applied_filter"), dict)
                else None
            ),
        }
    elif (
        not result_skus
        and isinstance(existing_candidate_context, dict)
        and existing_candidate_context.get("empty_subset")
        and inherited_original_candidate_skus
    ):
        candidate_context = {
            "candidate_skus": [],
            "result_reference_scope_skus": inherited_scope_skus,
            "ordered_result_skus": [],
            "filtered_skus": [
                str(sku).strip().upper()
                for sku in (existing_candidate_context.get("filtered_skus") or [])
                if str(sku or "").strip()
            ],
            "original_candidate_skus": inherited_original_candidate_skus,
            "parent_candidate_skus": inherited_original_candidate_skus,
            "recommended_skus": [],
            "user_question": str(user_question or "").strip(),
            "product_scope": product_scope,
            "empty_subset": True,
            "applied_filter": (
                (existing_candidate_context or {}).get("applied_filter")
                if isinstance((existing_candidate_context or {}).get("applied_filter"), dict)
                else None
            ),
        }
    answer_metadata = result_metadata
    current_contract = answer_metadata.get("recommendation_contract") or answer_metadata.get("current_recommendation_contract")
    effective_contract = answer_metadata.get("effective_recommendation_contract") or current_contract
    merge_provenance = answer_metadata.get("contract_merge_provenance") or (
        effective_contract.get("field_provenance") if isinstance(effective_contract, dict) else {}
    )
    verification_by_sku = {
        str(item.get("sku") or "").strip().upper(): dict(item)
        for item in (debug_metadata.get("candidate_verifications") or [])
        if isinstance(item, dict) and str(item.get("sku") or "").strip()
    }
    if recommendation_like and result_skus:
        recommendation_context = {
            "recommended_skus": result_skus,
            "ordered_result_skus": current_ordered_skus,
            "candidate_skus": current_ordered_skus,
            "result_reference_scope_skus": current_scope_skus or inherited_scope_skus,
            "user_question": str(user_question or "").strip(),
            "product_scope": product_scope,
            "answer_type": "recommendation",
            "top_recommended_sku": current_ordered_skus[0] if current_ordered_skus else None,
            "last_referenced_sku": current_ordered_skus[0] if current_ordered_skus else None,
            "result_reference_skus": result_reference_skus,
            "active_single_product_anchor": active_anchor,
            "anchor_update_reason": anchor_update_reason,
            "replacement_top_sku": current_ordered_skus[0] if replacement_recommendation and current_ordered_skus else None,
            "recommendation_request_contract": dict(current_contract) if isinstance(current_contract, dict) else {},
            "effective_recommendation_contract": dict(effective_contract) if isinstance(effective_contract, dict) else {},
            "verification_by_sku": verification_by_sku,
            "semantic_recommendation_requirements": [
                str(item or "").strip()
                for item in result_metadata.get("semantic_recommendation_requirements") or []
                if str(item or "").strip()
            ],
            "semantic_recommendation_preferences": [
                str(item or "").strip()
                for item in result_metadata.get("semantic_recommendation_preferences") or []
                if str(item or "").strip()
            ],
            "previous_result_skus": result_skus,
            "excluded_skus": list((effective_contract or {}).get("exclusions") or []) if isinstance(effective_contract, dict) else [],
            "contract_merge_provenance": dict(merge_provenance) if isinstance(merge_provenance, dict) else {},
        }
    elif isinstance(inherited_recommendation_context, dict) and inherited_recommendation_context.get("recommended_skus"):
        recommendation_context = {
            "recommended_skus": [
                str(sku).strip().upper()
                for sku in inherited_recommendation_context.get("recommended_skus") or []
                if str(sku or "").strip()
            ],
            "ordered_result_skus": [
                str(sku).strip().upper()
                for sku in (
                    inherited_recommendation_context.get("ordered_result_skus")
                    or inherited_recommendation_context.get("recommended_skus")
                    or []
                )
                if str(sku or "").strip()
            ],
            "candidate_skus": [
                str(sku).strip().upper()
                for sku in (
                    inherited_recommendation_context.get("candidate_skus")
                    or inherited_recommendation_context.get("ordered_result_skus")
                    or inherited_recommendation_context.get("recommended_skus")
                    or []
                )
                if str(sku or "").strip()
            ],
            "user_question": str(inherited_recommendation_context.get("user_question") or "").strip(),
            "product_scope": str(inherited_recommendation_context.get("product_scope") or "").strip(),
            "answer_type": str(inherited_recommendation_context.get("answer_type") or "recommendation"),
            "top_recommended_sku": str(
                inherited_recommendation_context.get("top_recommended_sku")
                or (
                    (inherited_recommendation_context.get("ordered_result_skus") or inherited_recommendation_context.get("recommended_skus") or [None])[0]
                )
                or ""
            ).strip().upper() or None,
            "last_referenced_sku": str(inherited_recommendation_context.get("last_referenced_sku") or "").strip().upper() or None,
            "result_reference_skus": [
                str(sku).strip().upper()
                for sku in (
                    inherited_recommendation_context.get("result_reference_skus")
                    or inherited_recommendation_context.get("ordered_result_skus")
                    or inherited_recommendation_context.get("recommended_skus")
                    or []
                )
                if str(sku or "").strip()
            ],
            "result_reference_scope_skus": (
                current_scope_skus
                or inherited_scope_skus
            ),
            "active_single_product_anchor": active_anchor,
            "anchor_update_reason": anchor_update_reason,
            "replacement_top_sku": str(inherited_recommendation_context.get("replacement_top_sku") or "").strip().upper() or None,
            "recommendation_request_contract": dict(inherited_recommendation_context.get("recommendation_request_contract") or {}),
            "effective_recommendation_contract": dict(
                answer_metadata.get("effective_recommendation_contract")
                or inherited_recommendation_context.get("effective_recommendation_contract")
                or inherited_recommendation_context.get("recommendation_request_contract")
                or {}
            ),
            "verification_by_sku": dict(inherited_recommendation_context.get("verification_by_sku") or {}),
            "semantic_recommendation_requirements": [
                str(item or "").strip()
                for item in inherited_recommendation_context.get("semantic_recommendation_requirements") or []
                if str(item or "").strip()
            ],
            "semantic_recommendation_preferences": [
                str(item or "").strip()
                for item in inherited_recommendation_context.get("semantic_recommendation_preferences") or []
                if str(item or "").strip()
            ],
            "previous_result_skus": list(inherited_recommendation_context.get("previous_result_skus") or inherited_recommendation_context.get("recommended_skus") or []),
            "excluded_skus": list(
                (answer_metadata.get("effective_recommendation_contract") or {}).get("exclusions")
                or inherited_recommendation_context.get("excluded_skus")
                or []
            ),
            "contract_merge_provenance": dict(
                answer_metadata.get("contract_merge_provenance")
                or inherited_recommendation_context.get("contract_merge_provenance")
                or {}
            ),
        }
    elif agent_result.get("answer_type") == "clarification":
        clarification_skus = [
            str(sku or "").strip().upper()
            for sku in (agent_result.get("candidate_skus") or [])
            if str(sku or "").strip()
        ]
        debug_contract = (
            (agent_result.get("debug") or {}).get("entity_resolution_contract")
            if isinstance(agent_result.get("debug"), dict)
            else {}
        ) or {}
        if len(clarification_skus) >= 2 and debug_contract.get("status") == "ambiguous":
            candidate_context = {
                "candidate_skus": clarification_skus,
                "ordered_result_skus": clarification_skus,
                "recommended_skus": [],
                "user_question": str(user_question or "").strip(),
                "product_scope": product_scope,
                "source": "entity_ambiguity",
                "entity_text": str(debug_contract.get("entity_text") or "").strip(),
                "field_type": str(debug_contract.get("field_type") or "").strip(),
            }
        if agent_result.get("answer_type") == "product_detail" and len(result_skus) == 1:
            recommendation_context["last_referenced_sku"] = result_skus[0]
    if candidate_context and candidate_context.get("empty_subset") and isinstance(existing_candidate_context, dict):
        if not candidate_context.get("candidate_skus"):
            candidate_context["candidate_skus"] = [
                str(sku).strip().upper()
                for sku in existing_candidate_context.get("candidate_skus") or []
                if str(sku or "").strip()
            ]
        if not candidate_context.get("original_candidate_skus"):
            candidate_context["original_candidate_skus"] = [
                str(sku).strip().upper()
                for sku in (
                    existing_candidate_context.get("original_candidate_skus")
                    or existing_candidate_context.get("parent_candidate_skus")
                    or []
                )
                if str(sku or "").strip()
            ]
        if not candidate_context.get("parent_candidate_skus"):
            candidate_context["parent_candidate_skus"] = [
                str(sku).strip().upper()
                for sku in (
                    existing_candidate_context.get("parent_candidate_skus")
                    or existing_candidate_context.get("original_candidate_skus")
                    or candidate_context.get("original_candidate_skus")
                    or []
                )
                if str(sku or "").strip()
            ]
        if not candidate_context.get("applied_filter") and isinstance(existing_candidate_context.get("applied_filter"), dict):
            candidate_context["applied_filter"] = existing_candidate_context.get("applied_filter")
    if candidate_context and isinstance(existing_meta_entry, dict):
        existing_meta_entry["candidate_context"] = dict(candidate_context)
    if recommendation_context and isinstance(existing_meta_entry, dict):
        existing_meta_entry["recommendation_context"] = dict(recommendation_context)
    meta_entry = {
        "type": "agent_meta",
        "label": "客服回复元数据",
        "intent": agent_result.get("intent"),
        "answer_type": agent_result.get("answer_type"),
        "confidence": agent_result.get("confidence"),
        "uncertainty": agent_result.get("uncertainty"),
        "needs_clarification": agent_result.get("needs_clarification", False),
        "anomalies": agent_result.get("anomalies") or [],
        "suggested_followups": agent_result.get("suggested_followups") or agent_result.get("followups") or [],
        "followups": agent_result.get("followups") or agent_result.get("suggested_followups") or [],
        "warnings": agent_result.get("warnings") or [],
        "evidence": agent_result.get("evidence") or [],
        "agent_quality": agent_result.get("agent_quality") or {},
        "debug": agent_result.get("debug") or {},
        "feedback": agent_result.get("feedback") or None,
    }
    pending_clarification_context = _pending_clarification_context_for_result(agent_result, user_question)
    if pending_clarification_context:
        meta_entry["pending_clarification_context"] = pending_clarification_context
    if recommendation_context:
        meta_entry["recommendation_context"] = recommendation_context
    if candidate_context:
        meta_entry["candidate_context"] = candidate_context
    sources.append(meta_entry)
    if agent_result.get("steps"):
        sources.append({"type": "agent_steps", "label": "Agent执行过程", "steps": agent_result.get("steps")})
    if result_skus:
        context_entry = {
            "type": "agent_context",
            "label": "上下文结果",
            "result_skus": result_skus,
            "current_sku": agent_result.get("sku") if agent_result.get("sku") in result_skus else (result_skus[0] if len(result_skus) == 1 else None),
            "entities": entities,
            "count": len(result_skus),
        }
        if turn_index is not None:
            context_entry["turn_index"] = turn_index
        sources.append(context_entry)
    return sources


def _latest_recommendation_context_for_sources(db: Session, conversation_id: str | None) -> dict:
    if not conversation_id:
        return {}
    messages = (
        db.query(CustomerServiceMessage)
        .filter(
            CustomerServiceMessage.conversation_id == conversation_id,
            CustomerServiceMessage.role == "assistant",
        )
        .order_by(CustomerServiceMessage.created_at.desc(), CustomerServiceMessage.id.desc())
        .limit(5)
        .all()
    )
    anchor_fallback: dict[str, Any] = {}
    context_fallback: dict[str, Any] = {}
    for message in messages:
        sources = _safe_json(message.sources_json, [])
        for source in sources:
            if not isinstance(source, dict) or source.get("type") != "agent_meta":
                continue
            context = source.get("recommendation_context")
            if isinstance(context, dict) and context.get("recommended_skus"):
                # Explanation and context-bound detail turns may preserve the prior
                # SKU list but intentionally carry no recommendation contract.
                # Keep scanning for the last decision-bearing recommendation
                # so an alternative can inherit its real category/constraints
                # instead of treating the explanation as a new recommendation.
                if not context_fallback:
                    context_fallback = context
                if isinstance(context.get("effective_recommendation_contract"), dict) and context.get("effective_recommendation_contract"):
                    return context
                if isinstance(context.get("recommendation_request_contract"), dict) and context.get("recommendation_request_contract"):
                    return context
    for message in messages:
        sources = _safe_json(message.sources_json, [])
        for source in sources:
            if not isinstance(source, dict) or source.get("type") != "agent_context":
                continue
            current_sku = str(source.get("current_sku") or "").strip().upper()
            result_skus = [
                str(sku or "").strip().upper()
                for sku in (source.get("result_skus") or [])
                if str(sku or "").strip()
            ]
            if current_sku and result_skus == [current_sku] and not anchor_fallback:
                anchor_fallback = {
                    "active_single_product_anchor": current_sku,
                    "anchor_update_reason": "confirmed_single_product_context",
                }
    return context_fallback or anchor_fallback


def _is_empty_candidate_subset_result(agent_result: dict, inherited_candidate_skus: list[str]) -> bool:
    if not inherited_candidate_skus:
        return False
    if agent_result.get("answer_type") != "product_query":
        return False
    if agent_result.get("results"):
        return False
    debug = agent_result.get("debug") if isinstance(agent_result.get("debug"), dict) else {}
    parsed = debug.get("parsed_intent") if isinstance(debug.get("parsed_intent"), dict) else {}
    if parsed.get("source_context") == "previous_results":
        return True
    for step in agent_result.get("steps") or []:
        if isinstance(step, dict) and "filter_previous_results" in str(step.get("type") or ""):
            return True
    return False


def _latest_candidate_context_for_sources(db: Session, conversation_id: str | None) -> dict:
    if not conversation_id:
        return {}
    messages = (
        db.query(CustomerServiceMessage)
        .filter(
            CustomerServiceMessage.conversation_id == conversation_id,
            CustomerServiceMessage.role == "assistant",
        )
        .order_by(CustomerServiceMessage.created_at.desc(), CustomerServiceMessage.id.desc())
        .limit(5)
        .all()
    )
    comparison_fallback: dict[str, Any] = {}
    for message in messages:
        for source in _safe_json(message.sources_json, []):
            if not isinstance(source, dict) or source.get("type") != "agent_meta":
                continue
            context = source.get("candidate_context")
            if isinstance(context, dict) and (context.get("candidate_skus") or context.get("empty_subset")):
                ordered_context = _ordered_context_skus(context)
                if (
                    len(ordered_context) >= 2
                    and str(context.get("source") or "").strip().lower() == "comparison"
                ):
                    # A complete comparison result is the correct discourse
                    # context for the next multi-product follow-up.  Do not
                    # let a later single-item anchor supersede it.  Keep the
                    # first one encountered because messages are newest-first;
                    # replacing it while scanning older messages can erase a
                    # newer final_choice_sku with the original unchosen pair.
                    if not comparison_fallback:
                        comparison_fallback = context
                    continue
                return {
                    "candidate_skus": [
                        str(sku).strip().upper()
                        for sku in context.get("candidate_skus") or []
                        if str(sku or "").strip()
                    ],
                    "ordered_result_skus": [
                        str(sku).strip().upper()
                        for sku in context.get("ordered_result_skus") or context.get("candidate_skus") or []
                        if str(sku or "").strip()
                    ],
                    "recommended_skus": [
                        str(sku).strip().upper()
                        for sku in context.get("recommended_skus") or []
                        if str(sku or "").strip()
                    ],
                    "pair_skus": [
                        str(sku).strip().upper()
                        for sku in (
                            context.get("pair_skus")
                            or context.get("ordered_result_skus")
                            or context.get("candidate_skus")
                            or []
                        )
                        if str(sku or "").strip()
                    ][:2],
                    "original_candidate_skus": [
                        str(sku).strip().upper()
                        for sku in (
                            context.get("original_candidate_skus")
                            or context.get("parent_candidate_skus")
                            or []
                        )
                        if str(sku or "").strip()
                    ],
                    "parent_candidate_skus": [
                        str(sku).strip().upper()
                        for sku in (
                            context.get("parent_candidate_skus")
                            or context.get("original_candidate_skus")
                            or []
                        )
                        if str(sku or "").strip()
                    ],
                    "filtered_skus": [
                        str(sku).strip().upper()
                        for sku in context.get("filtered_skus") or []
                        if str(sku or "").strip()
                    ],
                    "user_question": str(context.get("user_question") or "").strip(),
                    "product_scope": str(context.get("product_scope") or "").strip(),
                    "source": str(context.get("source") or "").strip(),
                    "entity_text": str(context.get("entity_text") or "").strip(),
                    "field_type": str(context.get("field_type") or "").strip(),
                    "empty_subset": bool(context.get("empty_subset")),
                    "applied_filter": context.get("applied_filter") if isinstance(context.get("applied_filter"), dict) else None,
                    "last_referenced_sku": str(context.get("last_referenced_sku") or "").strip().upper() or None,
                    "final_choice_sku": str(context.get("final_choice_sku") or "").strip().upper() or None,
                }
    if comparison_fallback:
        return {
            "candidate_skus": [
                str(sku).strip().upper()
                for sku in comparison_fallback.get("candidate_skus") or []
                if str(sku or "").strip()
            ],
            "ordered_result_skus": [
                str(sku).strip().upper()
                for sku in comparison_fallback.get("ordered_result_skus")
                or comparison_fallback.get("candidate_skus")
                or []
                if str(sku or "").strip()
            ],
            "recommended_skus": [],
            "pair_skus": [
                str(sku).strip().upper()
                for sku in comparison_fallback.get("pair_skus")
                or comparison_fallback.get("ordered_result_skus")
                or comparison_fallback.get("candidate_skus")
                or []
                if str(sku or "").strip()
            ][:2],
            "user_question": str(comparison_fallback.get("user_question") or "").strip(),
            "product_scope": str(comparison_fallback.get("product_scope") or "").strip(),
            "source": "comparison",
            "final_choice_sku": str(comparison_fallback.get("final_choice_sku") or "").strip().upper() or None,
        }
    return {}






















def _previous_result_skus_for_pre_runtime(
    db: Session,
    *,
    user_id: str,
    conversation_id: str | None,
    question: str,
) -> list[str]:
    candidate_context = _latest_candidate_context_for_sources(db, conversation_id)
    if not candidate_context:
        candidate_context = _latest_recommendation_context_for_sources(db, conversation_id)
    if candidate_context and _is_plural_heat_source_followup(question):
        scoped_skus = (
            candidate_context.get("ordered_result_skus")
            or candidate_context.get("candidate_skus")
            or candidate_context.get("recommended_skus")
            or candidate_context.get("original_candidate_skus")
            or candidate_context.get("parent_candidate_skus")
            or []
        )
        scoped_skus = [
            str(sku).strip().upper()
            for sku in scoped_skus
            if str(sku or "").strip()
        ]
        if len(scoped_skus) >= 2:
            return scoped_skus[:2]
    if candidate_context and (
        _is_recommendation_followup_question(question)
        or _is_contextual_power_followup_question(question)
        or customer_dialogue_state.needs_previous_context(question)
    ):
        scoped_skus = (
            candidate_context.get("candidate_skus")
            or candidate_context.get("ordered_result_skus")
            or candidate_context.get("recommended_skus")
            or candidate_context.get("original_candidate_skus")
            or candidate_context.get("parent_candidate_skus")
            or []
        )
        scoped_skus = [
            str(sku).strip().upper()
            for sku in scoped_skus
            if str(sku or "").strip()
        ]
        if scoped_skus:
            return scoped_skus[:10]
    if conversation_id and customer_dialogue_state.needs_previous_context(question):
        ordered_skus = _latest_ordered_result_skus_for_followup(db, conversation_id, user_id)
        if ordered_skus:
            return ordered_skus[:10]
    return _latest_active_product_skus(db, conversation_id, user_id)






def _asks_for_alternative_recommendation(question: str) -> bool:
    text = str(question or "")
    terms = (
        "\u6362\u4e00\u4e2a",
        "\u6362\u4e00\u6b3e",
        "\u6362\u4e2a",
        "\u518d\u63a8\u8350",
        "\u518d\u6765\u4e00\u4e2a",
        "\u53e6\u5916\u63a8\u8350",
        "\u8fd8\u6709\u5176\u4ed6\u63a8\u8350",
        "\u53e6\u4e00\u4e2a",
        "\u6709\u6ca1\u6709\u522b\u7684",
        "\u8fd8\u6709\u522b\u7684",
        "\u8fd8\u6709\u522b\u7684\u5417",
        "\u8fd8\u6709\u522b\u7684\u4e48",
        "\u522b\u7684\u5417",
        "\u522b\u7684\u4e48",
        "\u4e0d\u8981\u521a\u624d",
        "\u522b\u8981\u521a\u624d",
        "\u66ff\u4ee3",
        "\u66f4\u4fbf\u5b9c",
        "\u4fbf\u5b9c\u70b9",
        "\u7a0d\u5fae\u4fbf\u5b9c",
        "\u66f4\u8f7b",
        "\u66f4\u5408\u9002",
        "\u66f4\u9002\u5408",
    )
    return any(term in text for term in terms)


def _explicit_single_recommendation_request(question: str) -> bool:
    """Whether the customer has explicitly requested one recommendation."""
    return bool(re.search(
        r"(?:推荐|选|挑)\s*(?:一(?:个|款|口|套)|1(?:个|款|口|套))",
        str(question or ""),
    ))


def _asks_for_recommendation_explanation(question: str) -> bool:
    text = str(question or "")
    terms = (
        "\u4e3a\u4ec0\u4e48\u63a8\u8350",
        "\u63a8\u8350\u7406\u7531",
        "\u7406\u7531",
        "\u89e3\u91ca",
        "\u4f9d\u636e",
        "\u7b2c\u4e00\u4e2a",
        "\u7b2c\u4e00\u6b3e",
        "\u9996\u4e2a",
        "\u9996\u6b3e",
        "\u524d\u9762\u63a8\u8350\u7684",
        "\u521a\u624d\u63a8\u8350\u7684",
    )
    return any(term in text for term in terms)


def _is_recommendation_followup_question(question: str) -> bool:
    text = str(question or "")
    candidate_scope_terms = (
        "这些里",
        "这些里面",
        "里面哪些",
        "里面哪个",
        "上面这些",
        "其中哪个",
        "哪个更适合",
        "哪些支持",
    )
    budget_refinement = (
        any(term in text for term in ("预算不高", "预算有限", "预算低", "便宜点", "别太贵", "性价比"))
        and any(term in text for term in ("推荐", "来一个", "一款", "一个"))
    )
    return (
        _asks_for_alternative_recommendation(question)
        or _asks_for_recommendation_explanation(question)
        or any(term in text for term in candidate_scope_terms)
        or budget_refinement
    )


def _is_contextual_candidate_comparison_question(question: str) -> bool:
    text = str(question or "")
    if not any(term in text for term in ("对比", "比较", "区别")):
        return False
    return any(term in text for term in ("这几款", "这些", "上面", "前面", "其中", "容量", "人群", "重量", "材质", "适合"))






def _entities_from_agent_result(agent_result: dict, limit: int = 20) -> list[dict]:
    entities: list[dict] = []
    seen: set[str] = set()

    def add_entity(raw: dict, role: str, source: str) -> None:
        sku = str(raw.get("sku") or "").strip().upper()
        if not sku or "," in sku or sku in seen or len(entities) >= limit:
            return
        seen.add(sku)
        entities.append({
            "sku": sku,
            "name": raw.get("product_name_cn") or raw.get("product_name_en") or raw.get("name") or "",
            "turn": None,
            "role": role,
            "source": source,
        })

    primary_sku = str(agent_result.get("sku") or "").strip().upper()
    for item in agent_result.get("results") or []:
        if isinstance(item, dict):
            role = "current" if primary_sku and str(item.get("sku") or "").strip().upper() == primary_sku else "result"
            add_entity(item, role, "results")
    for action in agent_result.get("actions") or []:
        if isinstance(action, dict):
            add_entity(action, "current" if len(entities) == 0 else "result", "actions")
    if primary_sku and primary_sku not in seen:
        add_entity({"sku": primary_sku}, "current", "sku")
    return entities


def _order_skus_by_answer(skus: list[str], answer: str) -> list[str]:
    normalized = [
        str(sku or "").strip().upper()
        for sku in skus
        if str(sku or "").strip()
    ]
    if not normalized:
        return []
    positions: list[tuple[int, int, str]] = []
    for index, sku in enumerate(normalized):
        pos = str(answer or "").upper().find(sku)
        if pos >= 0:
            positions.append((pos, index, sku))
    if not positions:
        return normalized
    seen = {sku for _, _, sku in positions}
    ordered = [sku for _, _, sku in sorted(positions)]
    ordered.extend(sku for sku in normalized if sku not in seen)
    return ordered


def _steps_from_sources(sources_json: str | None) -> list[dict]:
    for source in _safe_json(sources_json, []):
        if isinstance(source, dict) and source.get("type") == "agent_steps":
            return source.get("steps") or []
    return []


def _message_meta(sources_json: str | None) -> dict:
    for source in _safe_json(sources_json, []):
        if isinstance(source, dict) and source.get("type") == "agent_meta":
            return source
    return {}




def _normalize_agent_result(agent_result: dict) -> dict:
    result = dict(agent_result)
    results = result.get("results") or []
    warnings = result.get("warnings") or []
    debug = dict(result.get("debug") or {})
    debug_intent = debug.get("intent")
    parsed_intent = debug.get("parsed_intent") if isinstance(debug.get("parsed_intent"), dict) else None
    result.setdefault("answer_type", _answer_type_from_intent(result.get("intent")))
    result.setdefault("uncertainty", _uncertainty_from_answer(result.get("answer") or "", results, warnings, result.get("needs_clarification", False)))
    result.setdefault("evidence", _evidence_from_results(results))
    result.setdefault("followups", result.get("suggested_followups") or [])
    result.setdefault("suggested_followups", result.get("followups") or [])
    result.setdefault("agent_quality", {})
    if not isinstance(debug_intent, dict):
        debug["intent"] = dict(parsed_intent or {"intent": result.get("intent")})
    debug.setdefault("steps", result.get("steps") or [])
    debug.setdefault("warnings", warnings)
    debug.setdefault("anomalies", result.get("anomalies") or [])
    debug.setdefault("raw_results", results)
    result["debug"] = debug
    return result








